INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$e51350e8-8bac-54d9-a78a-31c1a8012303$ml$::uuid, $ml$neuroscience$ml$, 1, 1, $ml${"id": "neuroscience-d1-c1", "title": "A stroke treated through the cerebellum", "lessonTitle": "The brain in four regions", "slot": 1, "type": "apply", "brief": {"headline": "In 2023, a Cleveland Clinic trial put stimulating electrodes in the cerebellum of 12 stroke survivors with weak arms. Nine of the 12 improved, alongside physical therapy.", "kicker": "Apply the map: why treat a stroke through the cerebellum?", "fullText": "The 12 volunteers had chronic, moderate to severe weakness in one arm after a stroke 12 to 36 months earlier. Surgeons implanted deep brain stimulation electrodes in the dentate nucleus, part of the cerebellum, and stimulation ran for four to eight months alongside physical therapy.\n\nNine of the 12 improved, and the gains held after the device was switched off. People who still had some hand function gained the most, with scores almost tripling; those with little hand function gained little. The NIH BRAIN Initiative funded the phase 1 trial, published in Nature Medicine in August 2023, and said larger, randomized trials are needed.\n\nWhy the cerebellum? It coordinates movement, and decades of animal work pointed to a circuit linking the dentate nucleus to the motor cortex. Know the map, and you know where to aim.", "sources": [{"url": "https://www.nih.gov/news-events/news-releases/cerebellar-post-stroke-deep-brain-stimulation-appears-safe-feasible-small-trial", "label": "NIH, Cerebellar post-stroke deep brain stimulation appears safe and feasible, Aug 2023"}, {"url": "https://newsroom.clevelandclinic.org/2023/08/14/cleveland-clinic-study-shows-deep-brain-stimulation-encouraging-for-stroke-patients/", "label": "Cleveland Clinic, Deep brain stimulation encouraging for stroke patients, Aug 2023"}, {"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}]}, "evidence": {"kind": "multipleChoice", "prompt": "The trial aimed at the cerebellum to help weak arms. Which of its jobs made it the target?", "options": ["Coordinating movement", "Running heart rate and breathing", "Storing and retrieving memories"], "correctIndex": 0, "explanation": "The cerebellum coordinates movement, and its dentate nucleus links to the motor cortex. Breathing belongs to the brainstem, memory to the hippocampus."}, "numbers": {"kind": "numberSense", "prompt": "Nine of the 12 participants improved. What share is that?", "min": 0, "max": 100, "value": 75, "unit": "%", "explanation": "Nine of 12 is 75%, a promising start from a small trial that still needs larger, randomized follow-up."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a company that wants to treat stroke through the cerebellum.", "prompt": "Which question shows you get the science?", "options": ["How many patents does the company hold so far?", "Why not aim the electrodes at the brainstem?", "How is the target wired to the motor cortex?"], "correctIndex": 2, "consequences": ["Patents matter later; first show you know why the target fits.", "The brainstem runs heart rate and breathing, not arm coordination.", "The dentate nucleus to motor cortex circuit is why the target makes sense."], "explanation": "The trial aimed at the dentate nucleus because of its circuit to the motor cortex. Asking about the circuit shows you think from the map."}, "proReasoning": "Strong candidates ask what a device targets and why that region fits the lost function. Here, the cerebellum coordinates movement and connects to the motor cortex.", "commonMistake": "Assuming a stroke must be treated exactly where it struck.", "mentalModel": "Aim at the circuit, not just the damage."}, "invest": {"call": {"kind": "theCall", "situation": "The trial reports 9 of 12 patients improved. A friend wants to buy into the company commercializing it.", "prompt": "What should temper the excitement?", "options": ["A 12-person trial still needs larger ones", "Gains vanished once the device was off", "The cerebellum holds few neurons"], "correctIndex": 0, "consequences": ["The NIH called the results preliminary and asked for larger, randomized trials.", "The gains persisted after stimulation was turned off.", "It holds about 80% of the brain's neurons."], "explanation": "Nine of 12 is promising, but small early trials often look better than larger ones. The NIH itself called for randomized trials."}, "proReasoning": "Investors read a phase 1 result as a reason to watch, not as proof. Trial size, controls and who benefits most all matter.", "commonMistake": "Treating 9 of 12 as a proven success rate.", "mentalModel": "Small trial, early signal."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building rehab software to pair with cerebellar stimulation. The trial showed who gained most.", "prompt": "Who should your first users be?", "options": ["Everyone who has ever had a stroke", "Survivors who kept some hand function", "Survivors with no hand movement at all"], "correctIndex": 1, "consequences": ["Too broad, and many would not respond.", "They gained the most, with scores almost tripling.", "Those with little hand function showed minimal benefit."], "explanation": "In the trial, people with some remaining hand function made the biggest gains. Start where the therapy works best."}, "proReasoning": "Founders start with the group the evidence favors. A narrow first user, chosen from data, beats a broad one chosen from hope.", "commonMistake": "Picking the users with the most need instead of the most benefit.", "mentalModel": "Start where the evidence is strongest."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend is puzzled: why put electrodes in the cerebellum to help a stroke survivor move an arm?", "prompt": "What's the best answer?", "options": ["Every stroke starts in the cerebellum", "It controls breathing during therapy", "It coordinates movement"], "correctIndex": 2, "consequences": ["Strokes strike many places; this trial chose its target by function.", "The brainstem, not the cerebellum, runs breathing.", "And a circuit links its dentate nucleus to the motor cortex."], "explanation": "The cerebellum coordinates movement, and its dentate nucleus connects to the motor cortex. Stimulating it aims to help the movement system relearn."}, "proReasoning": "Explain a treatment by the job of the region it targets. The cerebellum's job is coordination, which is what a weak arm needs.", "commonMistake": "Thinking treatment must go exactly where the damage is.", "mentalModel": "Regions work in circuits."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:83df87c1b25a$ml$]::text[]),
($ml$9cac9c8a-6d28-5475-be64-38c046644a9a$ml$::uuid, $ml$neuroscience$ml$, 1, 2, $ml${"id": "neuroscience-d1-c2", "title": "Biggest region, fewer neurons", "lessonTitle": "The brain in four regions", "slot": 2, "type": "connect", "brief": {"headline": "The cerebrum is the brain's largest part, yet its outer cortex holds about 16 billion neurons. The smaller cerebellum holds about 69 billion, or 80%.", "kicker": "Connect two day 1 ideas: the map of jobs and the count of neurons.", "fullText": "Day 1 gave you two ways to look at the brain. The first is the map: the cerebrum handles thinking and planning, the limbic system emotion and memory, the brainstem vital functions, and the cerebellum coordination. The second is the count: of about 86 billion neurons, about 69 billion sit in the cerebellum and about 16 billion in the cerebral cortex.\n\nPut them together and size stops being a guide. The region that looks biggest is not the one with the most neurons, and neither size nor count tells you a region's job. You need the map for that.", "sources": [{"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}, {"url": "https://Gwern.net/doc/psychology/neuroscience/2009-azevedo.pdf", "label": "Azevedo et al. 2009, neuron counts in the human brain"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The cerebellum holds about 80% of the brain's neurons.", "The largest region holds the most neurons.", "The brainstem links the brain to the spinal cord."], "fakeIndex": 1, "explanation": "The cerebrum is the largest part, but the smaller cerebellum holds about 80% of the neurons."}, "numbers": {"kind": "numberSense", "prompt": "What share of the brain's neurons sit in the cerebral cortex?", "min": 0, "max": 100, "value": 19, "unit": "%", "explanation": "About 16 of 86 billion, or 19%. The largest part of the brain holds under a fifth of its neurons."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a neurotech interview, you're asked which brain region holds the most neurons.", "prompt": "Which answer lands best?", "options": ["The cerebellum, about 80% of them", "The cerebral cortex, since it is largest", "The brainstem, since it runs vital signs"], "correctIndex": 0, "consequences": ["Azevedo and colleagues counted about 69 of 86 billion there.", "The cortex is large but holds about 19%.", "The brainstem runs vital functions; it is not where most neurons sit."], "explanation": "The cerebellum holds about 80% of neurons. Knowing the counterintuitive fact, with a number, stands out."}, "proReasoning": "A precise number with its source beats a guess from size. Interviewers notice when you know the surprising fact.", "commonMistake": "Assuming the biggest region holds the most cells.", "mentalModel": "Count, don't eyeball."}, "invest": {"call": {"kind": "theCall", "situation": "A startup says its device reaches most of the brain's neurons because it covers the cortex.", "prompt": "How do you read the claim?", "options": ["Unclear, since nobody has counted neurons", "Wrong, since the cortex holds about 19%", "Right, since the cortex is the largest part"], "correctIndex": 1, "consequences": ["Azevedo and colleagues counted them in 2009.", "The cerebellum holds about 80%, so the claim fails a basic check.", "Largest in size, but not in neuron count."], "explanation": "The cortex holds about 16 of 86 billion neurons. A pitch that gets this wrong has a rigor problem."}, "proReasoning": "Investors check a pitch's basic science first. A wrong anatomy claim says something about the team's rigor.", "commonMistake": "Letting a confident claim pass because it sounds plausible.", "mentalModel": "Check the claim against the count."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're picking a first target for a brain device. A cofounder wants the region with the most neurons.", "prompt": "What should decide the target?", "options": ["The region with the most neurons", "The largest region by size", "The job you want to restore"], "correctIndex": 2, "consequences": ["Most neurons sit in the cerebellum, which only helps if you need coordination.", "Size says little about a region's job.", "Each region runs different jobs, so the lost function picks the target."], "explanation": "Each region runs different jobs. Start from the function patients lose, then find the region that runs it."}, "proReasoning": "Founders start from the function patients lose, then find the region that runs it. Neuron counts and size are trivia without that.", "commonMistake": "Choosing a target for its size or cell count.", "mentalModel": "Function first, then the region."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says the cortex must hold most of the brain's neurons, since it's the biggest part.", "prompt": "What's a fair reply?", "options": ["Most neurons are in the small cerebellum", "Yes, the cortex holds nearly all neurons", "The brainstem holds most of the neurons"], "correctIndex": 0, "consequences": ["About 69 of 86 billion neurons sit there, so size misleads.", "It holds about 16 billion, or 19%.", "The brainstem runs vital signs; the cerebellum holds most neurons."], "explanation": "The cerebellum, below and behind the rest of the brain, holds about 80% of its neurons."}, "proReasoning": "Use one surprising number to reframe a belief. The cerebellum's 80% shows that size and cell count are different questions.", "commonMistake": "Equating the biggest part with the most neurons.", "mentalModel": "Size misleads."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:23988654e26e$ml$]::text[]),
($ml$20ec0c3a-0369-5017-9068-a29052c338e9$ml$::uuid, $ml$neuroscience$ml$, 1, 3, $ml${"id": "neuroscience-d1-c3", "title": "Pick the region, pick the patients", "lessonTitle": "The brain in four regions", "slot": 3, "type": "decide", "brief": {"headline": "You run a small fund choosing among three brain device startups. One targets memory, one movement and one breathing control. Each region means different patients.", "kicker": "Decide which region each pitch really targets.", "fullText": "You run a small fund that backs early brain device companies. Three pitches arrive. One wants to help people who lose memories, one people whose movements are clumsy and uncoordinated, and one people whose breathing and heart rate are unstable.\n\nDay 1's map tells you where each must work. Deep structures in the limbic system govern emotion and memory, and the hippocampus sends memories to storage and retrieves them. The cerebellum coordinates movement. The brainstem, which links the brain to the spinal cord, runs heart rate, breathing and blood pressure. The region tells you the job, and the job tells you the patients.", "sources": [{"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}, {"url": "https://Gwern.net/doc/psychology/neuroscience/2009-azevedo.pdf", "label": "Azevedo et al. 2009, neuron counts in the human brain"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which region would each product need to act on?", "buckets": ["Limbic system", "Cerebellum", "Brainstem"], "items": [{"text": "A device to help recall new memories", "bucket": 0}, {"text": "A therapy for emotional regulation", "bucket": 0}, {"text": "A device to steady a clumsy walk", "bucket": 1}, {"text": "A tool that merges input from eyes and ears", "bucket": 1}, {"text": "A device to stabilize breathing", "bucket": 2}, {"text": "A device to steady heart rate", "bucket": 2}], "explanation": "Memory and emotion sit in the limbic system, coordination in the cerebellum, and vital functions in the brainstem."}, "numbers": {"kind": "numberSense", "prompt": "The cerebellum holds about 69 billion neurons and the cortex about 16 billion. About how many times as many is that?", "min": 0, "max": 10, "value": 4.3, "unit": "times", "explanation": "69 divided by 16 is a little over 4. The smaller region holds more than four times the neurons."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at the memory startup. The founder asks where in the brain its device must act.", "prompt": "What do you answer?", "options": ["The brainstem, near the spinal cord", "The hippocampus, in the limbic system", "The cerebellum, which holds most neurons"], "correctIndex": 1, "consequences": ["The brainstem runs vital functions like breathing.", "The hippocampus sends memories to storage and retrieves them later.", "The cerebellum coordinates movement, not memory."], "explanation": "Memory runs through the hippocampus, a deep structure in the limbic system."}, "proReasoning": "Name the structure and its job in one breath. It shows you can connect a product to the anatomy.", "commonMistake": "Picking the region with the most neurons instead of the right job.", "mentalModel": "Job first, then structure."}, "invest": {"call": {"kind": "theCall", "situation": "You can back only one of the three. You want the clearest link from region to patients to market.", "prompt": "What should you ask each founder first?", "options": ["How many neurons the region holds", "How big the region looks on a scan", "Which lost function, and in whom?"], "correctIndex": 2, "consequences": ["Neuron count does not tell you who the patients are.", "Size on a scan says little about a market.", "The region's job defines the patients, and the patients define the market."], "explanation": "Movement, memory and vital functions each mean different people. The lost function tells you the market."}, "proReasoning": "Investors trace a brain product from region to job to patients. Movement, memory and vital functions each mean very different people.", "commonMistake": "Judging a pitch by the anatomy's size rather than the patients.", "mentalModel": "Region, job, patients, market."}, "build_startup": {"call": {"kind": "theCall", "situation": "You founded the breathing control startup. A partner suggests also claiming memory benefits to widen the market.", "prompt": "What's the sound call?", "options": ["Stay with the brainstem job you can show", "Add memory claims to look bigger", "Switch to the cerebellum for more neurons"], "correctIndex": 0, "consequences": ["A device acting on vital functions has no basis for memory claims.", "Memory runs through the limbic system, not the brainstem.", "More neurons does not make it the right target."], "explanation": "Your device works on brainstem jobs. Claims should stay inside what that region runs."}, "proReasoning": "Founders keep claims inside the function their target region runs. Stretching to other jobs invites doubt.", "commonMistake": "Widening claims beyond what the region does.", "mentalModel": "Claim what your region runs."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why doctors check breathing and heart rate after an injury to the brainstem.", "prompt": "What's the reason?", "options": ["The cortex controls every breath", "The brainstem runs those vital functions", "The cerebellum stores the heartbeat rhythm"], "correctIndex": 1, "consequences": ["The cortex runs thinking and planning; breathing sits in the brainstem.", "It links the brain to the spinal cord and runs heart rate and breathing.", "The cerebellum coordinates movement."], "explanation": "Heart rate, breathing and blood pressure run through the brainstem, so damage there threatens them."}, "proReasoning": "Each region runs different jobs, so damage shows up as lost functions. That is why doctors test the jobs a region runs.", "commonMistake": "Thinking the whole brain does everything together.", "mentalModel": "Damage shows the region's job."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ed6a3b919a59$ml$]::text[]),
($ml$115321e0-d186-56e1-9d7b-6cce0c119de8$ml$::uuid, $ml$neuroscience$ml$, 2, 1, $ml${"id": "neuroscience-d2-c1", "title": "Synchron's $200 million", "lessonTitle": "Three streams of brain money", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, Synchron raised $200 million to move its brain implant toward market. It had implanted 10 people with paralysis and was still preparing a commercial launch.", "kicker": "Apply the three streams: which one pays for an implant before sales?", "fullText": "Synchron's Stentrode reaches the motor cortex through blood vessels, placed with a catheter instead of open brain surgery. By November 2025 it had been implanted in 10 people with paralysis, in trials in the US and Australia.\n\nOn November 6, 2025, the company closed a $200 million Series D led by Double Point Ventures, bringing its total raised to $345 million. The money is for pivotal trials, preparing a commercial launch and building a next-generation interface with more channels.\n\nOf day 2's three streams, investors, drug sales and public grants, investors are the one carrying Synchron toward market.", "sources": [{"url": "https://www.mddionline.com/neurological/synchron-snags-200m-to-move-its-bci-tech-closer-to-market", "label": "MD+DI, Synchron snags $200M to move its BCI tech closer to market, Nov 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put Synchron's path to market in order.", "steps": ["The implant reaches the motor cortex through a vessel", "Early trials implant 10 people with paralysis", "Investors put in a $200 million round", "Pivotal trials test the implant at scale", "A commercial launch follows, if approved"], "explanation": "Investor money pays for the trials that come before any sales. Revenue is the last link in the chain."}, "numbers": {"kind": "numberSense", "prompt": "Synchron had raised $345 million and implanted 10 people. About how much is that per patient, in millions?", "min": 0, "max": 100, "value": 34.5, "unit": "M", "explanation": "About $34.5 million per patient so far. Investors are paying for the future, not for today's ten implants."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Synchron offers you a job in late 2025, right after its $200 million round.", "prompt": "What does its funding tell you about the role?", "options": ["Pay depends on investors until sales begin", "Product sales already cover salaries", "Grants guarantee the job for a decade"], "correctIndex": 0, "consequences": ["It is still preparing a launch, so investor money funds the work.", "It was still preparing its commercial launch.", "Its new money came from investors, not a grant."], "explanation": "A pre-launch device company lives on investor rounds. That money is plentiful after a raise but tied to hitting milestones."}, "proReasoning": "Before joining a neurotech startup, ask how long the last round lasts and which milestone earns the next one.", "commonMistake": "Assuming a big round means the company pays its own way.", "mentalModel": "Know who pays your salary."}, "invest": {"call": {"kind": "theCall", "situation": "You're offered shares in Synchron's next round. It has 10 patients implanted and no sales yet.", "prompt": "What are you really paying for?", "options": ["A guaranteed FDA approval", "The chance pivotal trials succeed", "Revenue from its current implants"], "correctIndex": 1, "consequences": ["No trial result or approval is guaranteed.", "With 10 patients, value rests on what trials still have to show.", "There is no product revenue before approval and launch."], "explanation": "Before sales, a device company is a bet on its trials. The price reflects odds, not cash flow."}, "proReasoning": "Investors in pre-revenue neurotech price a probability, not a cash flow. Ask what each milestone proves and what is still a bet.", "commonMistake": "Valuing a pre-launch company as if sales were coming in.", "mentalModel": "Pre-revenue means pricing the odds."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your BCI startup has 2 patients implanted. You hear Synchron raised $200 million with 10.", "prompt": "Which funding stream fits your stage?", "options": ["Product sales, starting next quarter", "Wait for NIH to fund a pivotal trial", "Investors, matched to clear milestones"], "correctIndex": 2, "consequences": ["An implant still in trials has no product to sell.", "BRAIN Initiative funding fell from $680 million to $321 million.", "Like Synchron, you raise on milestones until you can sell."], "explanation": "Device startups raise from investors against milestones. Sales come last, and public grants are shrinking."}, "proReasoning": "Founders match the money to the stage. Implant startups raise from investors against milestones, since grants are shrinking and sales come last.", "commonMistake": "Planning on revenue before the device is approved.", "mentalModel": "Match the money to the stage.", "sources": [{"url": "https://braininitiative.nih.gov/funding/understanding-brain-initiative-budget", "label": "NIH BRAIN Initiative, Understanding the budget"}]}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a company with nothing on sale can raise $200 million.", "prompt": "What's the best explanation?", "options": ["Investors bet on future sales", "The government paid for the round", "Patients prepaid for their implants"], "correctIndex": 0, "consequences": ["Investors buy a share of what the implant might earn later.", "The round was led by Double Point Ventures, an investor.", "The implants so far went to people in trials."], "explanation": "Investors fund years of trials in exchange for a share of a possible large market later."}, "proReasoning": "Explain startup funding as a bet on the future. Investors pay for years of trials hoping for a large market later.", "commonMistake": "Assuming money only follows existing sales.", "mentalModel": "Investors buy the future."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9cb491e7f105$ml$]::text[]),
($ml$0c8177e8-e820-5da1-8bad-2a48f0c6a8fd$ml$::uuid, $ml$neuroscience$ml$, 2, 2, $ml${"id": "neuroscience-d2-c2", "title": "Memory sells, movement raises", "lessonTitle": "Three streams of brain money", "slot": 2, "type": "connect", "brief": {"headline": "Leqembi, an Alzheimer's drug, launched at $26,500 a year. Neuralink, helping people with paralysis, raised $650 million with five people implanted. Different jobs, different money.", "kicker": "Connect day 1 and day 2: the job a product targets shapes its money.", "fullText": "On day 1 you learned that each region runs different jobs: memory through the limbic system and hippocampus, coordination through the cerebellum, vital functions through the brainstem. On day 2 you met three streams of money.\n\nLeqembi treats Alzheimer's disease, where memory fails, and earns through drug sales at $26,500 a year per patient. Neuralink's implant lets people with severe paralysis control devices with their minds; with five people implanted, it ran on investor money, $650 million in June 2025. Public grants fund much of the research behind both, and NIH BRAIN Initiative funding fell from $680 million in fiscal 2023 to $321 million in fiscal 2025.", "sources": [{"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}, {"url": "https://biopharma-reporter.com/Article/2023/01/10/Next-steps-for-lecanemab-Eisai-reveals-pricing-US-and-global-rollout-plans", "label": "BioPharma Reporter, Eisai reveals Leqembi pricing"}, {"url": "https://techcrunch.com/2025/06/02/elon-musks-neuralink-closes-a-650m-series-e", "label": "TechCrunch, Neuralink closes a $650M Series E"}, {"url": "https://braininitiative.nih.gov/funding/understanding-brain-initiative-budget", "label": "NIH BRAIN Initiative, Understanding the budget"}]}, "evidence": {"kind": "faceOff", "prompt": "Which one earns from sales to patients today?", "left": {"name": "Leqembi", "note": "Alzheimer's drug, $26,500 a year"}, "right": {"name": "Neuralink", "note": "Brain implant, five people by June 2025"}, "correctIndex": 0, "explanation": "Leqembi is a launched drug that earns from patients. Neuralink was still in trials, funded by investors."}, "numbers": {"kind": "numberSense", "prompt": "NIH BRAIN Initiative funding fell from $680 million to $321 million. By about what percent?", "min": 0, "max": 80, "value": 53, "unit": "%", "explanation": "A drop of $359 million, about 53%. The public stream shrank while the investor stream grew."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You have offers from Eisai's Leqembi team and from a BCI startup like Neuralink.", "prompt": "What's the key difference in who pays you?", "options": ["There is no real difference", "Drug sales versus investor rounds", "Grants versus drug sales"], "correctIndex": 1, "consequences": ["Their money comes from different streams with different risks.", "A launched drug earns from patients; a startup lives on its next raise.", "Neither offer rests mainly on grants."], "explanation": "Leqembi earns from patients. A BCI startup lives on investor rounds until it can sell."}, "proReasoning": "Know which stream pays your salary. Sales depend on patients and payers; rounds depend on investors' confidence and milestones.", "commonMistake": "Treating every brain company as the same kind of employer.", "mentalModel": "Different streams, different risks."}, "invest": {"call": {"kind": "theCall", "situation": "You compare Leqembi's maker with a BCI startup. Both serve people with brain disease.", "prompt": "What drives each one's value most?", "options": ["NIH grants pay for both of them", "The size of the region each one targets", "Patients for one, trials for the other"], "correctIndex": 2, "consequences": ["Neither company's value rests on grants, which are shrinking anyway.", "Region size says nothing about value.", "Drug revenue scales with patients; the startup's value with trial progress."], "explanation": "A launched drug is valued on patients and price. A pre-revenue implant is valued on its trials."}, "proReasoning": "Investors map each company to its stream. For a launched drug, track patients and price; for an implant, track trials and runway.", "commonMistake": "Valuing a pre-revenue implant on the same terms as a selling drug.", "mentalModel": "Know the stream before the valuation."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup targets movement, like Neuralink. A mentor says to plan revenue like Leqembi from day one.", "prompt": "What's wrong with that plan?", "options": ["You need investors long before sales", "Implants always cost less than drugs", "The NIH sets prices for devices"], "correctIndex": 0, "consequences": ["Neuralink raised $650 million while still in trials.", "Price depends on the product and the payer, not the category.", "The NIH funds research; it does not set prices."], "explanation": "An implant earns nothing until it is approved and sold. Until then, investors are the stream."}, "proReasoning": "Founders of implant companies plan years of investor funding before any sales. Pricing matters later; runway matters now.", "commonMistake": "Planning revenue like a launched drug before the device is approved.", "mentalModel": "Runway first, price later."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Alzheimer's drugs and brain implants seem funded so differently.", "prompt": "What's the short answer?", "options": ["Insurance already pays for brain implants", "One earns from sales, the other from investors", "Both are mostly paid for by the NIH"], "correctIndex": 1, "consequences": ["Neuralink's implant was still in trials with five people.", "Leqembi sells at $26,500 a year; Neuralink raised $650 million.", "NIH BRAIN funding fell to $321 million in fiscal 2025."], "explanation": "A launched drug earns from patients. An implant in trials runs on investor money."}, "proReasoning": "Follow the money stream to explain how a field behaves. Drug sales reward patients treated; investor money rewards progress.", "commonMistake": "Assuming all medical research is funded the same way.", "mentalModel": "Each stream rewards something different."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3b62ac735946$ml$]::text[]),
($ml$8faab938-7e4c-526a-8f65-dc68cab99c65$ml$::uuid, $ml$neuroscience$ml$, 2, 3, $ml${"id": "neuroscience-d2-c3", "title": "Grant, spinout or both", "lessonTitle": "Three streams of brain money", "slot": 3, "type": "decide", "brief": {"headline": "You run a university lab building a brain implant. Your NIH grant ends next year, BRAIN Initiative funding has more than halved, and a venture firm offers seed money for a spinout.", "kicker": "Decide how to fund the next stage of your lab's work.", "fullText": "You run a university lab developing a brain implant. Your NIH grant ends next year. Across the BRAIN Initiative, funding fell from $680 million in fiscal 2023 to $402 million in fiscal 2024 and $321 million in fiscal 2025.\n\nA venture firm offers seed money to spin the implant out as a company. Neuralink shows how big that stream can get: $650 million in June 2025, with five people implanted. Investors expect milestones in return, and drug-style sales only come after approval.", "sources": [{"url": "https://braininitiative.nih.gov/funding/understanding-brain-initiative-budget", "label": "NIH BRAIN Initiative, Understanding the budget"}, {"url": "https://techcrunch.com/2025/06/02/elon-musks-neuralink-closes-a-650m-series-e", "label": "TechCrunch, Neuralink closes a $650M Series E"}, {"url": "https://www.fiercebiotech.com/medtech/neuralink-secures-650m-series-e-funding-expand-patient-access-brain-chip-technology", "label": "FierceBiotech, Neuralink secures $650M Series E"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which plan spreads your lab's funding risk best?", "options": ["Take seed money and drop all grant work", "Keep applying for grants and test the spinout", "Bet everything on one more NIH grant"], "correctIndex": 1, "explanation": "With grants shrinking, a second stream lowers risk. Keeping grant work protects the science while investors test the business."}, "numbers": {"kind": "numberSense", "prompt": "From fiscal 2024 to 2025, BRAIN Initiative funding fell from $402 million to $321 million. How big a drop, in millions?", "min": 0, "max": 200, "value": 81, "unit": "M", "explanation": "$81 million less in one year, on top of a $278 million drop the year before."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a postdoc in the lab. The spinout offers you a job; the lab can fund you one more year.", "prompt": "What should you weigh most?", "options": ["Which job has the bigger title", "Whether grants will bounce back", "How long the seed money lasts"], "correctIndex": 2, "consequences": ["Titles matter less than how long the money lasts.", "BRAIN funding fell two years running, so a rebound is a guess.", "Investor money runs out unless milestones bring the next round."], "explanation": "A seed round buys a fixed amount of time. Your job depends on hitting the milestone before it runs out."}, "proReasoning": "Researchers moving to startups ask about runway and milestones. A seed round buys time, not certainty.", "commonMistake": "Choosing on title or salary without asking how long the money lasts.", "mentalModel": "Ask how long the money lasts."}, "invest": {"call": {"kind": "theCall", "situation": "You're the venture firm. The lab's implant has worked in early tests, and its grant ends next year.", "prompt": "What makes this a good time to invest?", "options": ["Shrinking grants leave a funding gap", "The NIH guarantees follow-on funding", "Product sales will start within a year"], "correctIndex": 0, "consequences": ["With grants falling, your seed money fills a real gap.", "The NIH guarantees nothing, and its BRAIN budget fell.", "An implant in early tests is years from any sales."], "explanation": "When public money pulls back, good science looks for new funders. That is when early investors get in."}, "proReasoning": "Investors watch where public money pulls back. Good science losing its main funder can be a chance to back it early.", "commonMistake": "Assuming public funding will carry a project to market.", "mentalModel": "Watch where grants pull back."}, "build_startup": {"call": {"kind": "theCall", "situation": "You take the seed money and found the spinout. Investors want a milestone within 18 months.", "prompt": "Which milestone best earns the next round?", "options": ["A press tour about the technology", "Safety results in more patients", "A bigger office near the university"], "correctIndex": 1, "consequences": ["Attention without data rarely earns a bigger round.", "Neuralink raised after implanting five people; evidence drives rounds.", "Space costs money and proves nothing."], "explanation": "The next round pays for proof. For an implant, that means patients and safety data."}, "proReasoning": "Founders pick milestones that reduce the main risk. For an implant, that means more patients and safety data.", "commonMistake": "Spending seed money on things that do not answer investors' questions.", "mentalModel": "Each round buys one answer."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why so many university brain projects are turning into startups.", "prompt": "What's one big reason?", "options": ["Universities must sell their labs", "Drug sales pay for lab research", "Public grants are shrinking"], "correctIndex": 2, "consequences": ["No rule forces universities to sell labs.", "Labs mostly run on grants, not drug sales.", "BRAIN Initiative funding fell by more than half from 2023 to 2025."], "explanation": "When one stream shrinks, researchers turn to the others. A spinout is how lab science reaches investor money."}, "proReasoning": "When one money stream shrinks, work moves toward the others. Spinouts are how lab science reaches investor money.", "commonMistake": "Thinking startups appear only because founders want to get rich.", "mentalModel": "Work follows the money."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8434fecbc53e$ml$]::text[]),
($ml$8be384c0-a10b-52d7-8221-4fdb0a698213$ml$::uuid, $ml$neuroscience$ml$, 3, 1, $ml${"id": "neuroscience-d3-c1", "title": "Paradromics gets its yes", "lessonTitle": "The brain's two gatekeepers", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, the FDA let Paradromics start a study of its fully implanted brain-computer interface, beginning with two people. The first implant came in June 2026.", "kicker": "Apply the regulator gate: what the FDA's yes did and did not allow.", "fullText": "Paradromics' Connexus implant records brain signals through a high-density microelectrode array and sends them to a receiver in the chest, which transmits them wirelessly through the skin. The goal is to restore speech and computer control for people with severe motor impairment.\n\nOn November 20, 2025, the FDA granted an investigational device exemption, or IDE, for the Connect-One early feasibility study: initially two participants, at UC Davis, Massachusetts General Hospital and the University of Michigan. On June 17, 2026, the company announced the first implant, in a Michigan woman with motor neuron disease, who will be followed for six years.\n\nThe yes allowed a study, not sales. The device stays limited by US law to investigational use.", "sources": [{"url": "https://www.businesswire.com/news/home/20251120141086/en/Paradromics-Receives-FDA-Approval-for-the-Connect-One-Clinical-Study-with-the-Connexus%C2%AE-Brain-Computer-Interface/", "label": "Paradromics via Business Wire, FDA approval for the Connect-One study, Nov 2025"}, {"url": "https://www.businesswire.com/news/home/20260617963732/en/Paradromics-and-University-of-Michigan-Complete-First-Connexus-BCI-Implantation-for-the-FDA-Approved-Connect-One-Clinical-Study", "label": "Paradromics via Business Wire, First Connexus implant in Connect-One, Jun 2026"}, {"url": "https://www.hhs.gov/guidance/sites/default/files/hhs-guidance-documents/FDA/Brain-Computer-Interface-Guidance.pdf", "label": "FDA guidance, Implanted brain-computer interface devices (2021)"}]}, "evidence": {"kind": "buildChain", "prompt": "Put Paradromics' path to its first implant in order.", "steps": ["Years of animal tests show stable recordings", "The FDA grants an IDE for a small study", "Three sites screen possible participants", "The first participant is implanted", "Six years of follow-up build the safety record"], "explanation": "The FDA's yes came before any long-term implant in a person. Follow-up then runs for years."}, "numbers": {"kind": "numberSense", "prompt": "From the IDE in November 2025 to the first implant in June 2026, about how many months passed?", "min": 0, "max": 24, "value": 7, "unit": "months", "explanation": "About seven months from the regulator's yes to the first person, with six years of follow-up still ahead."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Paradromics' clinical team in 2026. A friend congratulates you on the FDA approval.", "prompt": "How do you describe it accurately?", "options": ["No FDA role, since it is still research", "FDA approval to run a study, not to sell", "Full approval to market the implant"], "correctIndex": 1, "consequences": ["The FDA had to approve the study before any implant.", "An IDE lets the study go ahead; the device stays investigational.", "The device is limited by US law to investigational use."], "explanation": "An IDE allows a clinical study. Selling the device would need a separate, later approval."}, "proReasoning": "In device regulation, say which approval you mean. An IDE allows a study; clearance or approval allows sales.", "commonMistake": "Calling a study approval a market approval.", "mentalModel": "Name the approval precisely."}, "invest": {"call": {"kind": "theCall", "situation": "A headline says Paradromics is FDA approved. You hold a small stake.", "prompt": "What does the news really change?", "options": ["The device can now earn revenue", "The regulatory risk is fully over", "Human data can now start to build"], "correctIndex": 2, "consequences": ["It stays limited by US law to investigational use.", "A feasibility study is an early step on a long path.", "Two participants and six years of follow-up are the next proof points."], "explanation": "An IDE starts the clock on human data. It does not allow sales or end the regulatory risk."}, "proReasoning": "Investors translate regulatory headlines into the next proof point. A study approval starts the clock on human data; it does not end the risk.", "commonMistake": "Reading 'FDA approves study' as 'FDA approves product'.", "mentalModel": "A study yes is a start, not a finish."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your BCI startup has strong animal data and wants its first long-term human implant in the US.", "prompt": "What must come first?", "options": ["FDA approval of a study, like an IDE", "A first patient willing to try it", "A sales deal with a hospital"], "correctIndex": 0, "consequences": ["The FDA classes implanted BCIs as significant risk, so it must approve the study.", "A willing patient cannot replace the FDA's approval.", "You cannot sell an implant that has not been tested in people."], "explanation": "Implanted BCIs are significant risk devices. The FDA must approve the study before the first implant."}, "proReasoning": "Founders plan the regulator into the timeline. Paradromics went from IDE to first implant in about seven months, and follow-up runs for years.", "commonMistake": "Setting a first implant date before the FDA has approved the study.", "mentalModel": "The regulator sets the first date."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a brain implant study starts with only two people.", "prompt": "What's a sound answer?", "options": ["Nobody else wanted to get the implant", "Risky devices are tried on a few first", "The FDA caps every study at two people"], "correctIndex": 1, "consequences": ["Screening was underway at three sites.", "It is an early feasibility study, set to begin with two people.", "There is no fixed cap of two; this study starts with two."], "explanation": "The FDA classes implanted BCIs as significant risk devices. An early feasibility study starts small and follows people for years."}, "proReasoning": "Explain small first studies as risk control. With a significant risk device, you learn from a few people before many.", "commonMistake": "Reading a small study as a sign of weak demand.", "mentalModel": "Few people first, many later."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a6e4bf7d3d67$ml$]::text[]),
($ml$6b6140a1-8a0a-5a6a-971f-ed921b36fc82$ml$::uuid, $ml$neuroscience$ml$, 3, 2, $ml${"id": "neuroscience-d3-c2", "title": "The gate before the round", "lessonTitle": "The brain's two gatekeepers", "slot": 2, "type": "connect", "brief": {"headline": "The FDA turned down Neuralink's requests for human testing several times before saying yes in May 2023. Two years later, with five people implanted, it raised $650 million.", "kicker": "Connect day 2 and day 3: the regulator's yes comes before big money.", "fullText": "On day 3 you saw that the FDA classes an implanted brain-computer interface as a significant risk device, and that it turned down Neuralink's requests for human testing several times before approving a first-in-human study in May 2023. On day 2 you saw what came after: a $650 million Series E in June 2025, at a reported valuation around $9 billion before the money, with five people implanted.\n\nThe order matters. Investors can fund a device company through animal tests, but people can only be implanted after the regulator says yes. Without that yes, there would have been no implanted patients to point to.", "sources": [{"url": "https://www.hhs.gov/guidance/sites/default/files/hhs-guidance-documents/FDA/Brain-Computer-Interface-Guidance.pdf", "label": "FDA guidance, Implanted brain-computer interface devices (2021)"}, {"url": "https://stuff.co.za/2023/05/26/neuralink-fda-approval-human-trials/", "label": "Stuff, Neuralink gets FDA approval for human trials"}, {"url": "https://techcrunch.com/2025/06/02/elon-musks-neuralink-closes-a-650m-series-e", "label": "TechCrunch, Neuralink closes a $650M Series E"}, {"url": "https://www.fiercebiotech.com/medtech/neuralink-secures-650m-series-e-funding-expand-patient-access-brain-chip-technology", "label": "FierceBiotech, Neuralink secures $650M Series E"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What had to happen before Neuralink could implant its first person in the US?", "options": ["It raised its $650 million round", "It sold its first implant", "The FDA approved a human study"], "correctIndex": 2, "explanation": "The FDA approved a first-in-human study in May 2023. The $650 million round came in June 2025, after five implants."}, "numbers": {"kind": "numberSense", "prompt": "From the FDA's yes in May 2023 to the $650 million round in June 2025, about how many months passed?", "min": 0, "max": 60, "value": 25, "unit": "months", "explanation": "About 25 months. The regulator opened the gate; the patients implanted after it gave investors something to price."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a BCI startup with strong animal data. They ask for its biggest near-term risk.", "prompt": "What do you say?", "options": ["Hiring enough good engineers quickly", "Choosing a brand name for the launch", "Getting the FDA to approve a human study"], "correctIndex": 2, "consequences": ["Hiring matters, but the FDA decides when people can be implanted.", "Launch is years away; the regulator comes first.", "Neuralink was turned down several times before its yes."], "explanation": "For an implant, the FDA decides when human testing starts. That gate comes before everything else."}, "proReasoning": "Name the gate that blocks the next step. For an implant, that is the FDA approving human testing.", "commonMistake": "Focusing on growth problems before the regulatory gate is passed.", "mentalModel": "Name the next gate."}, "invest": {"call": {"kind": "theCall", "situation": "A BCI startup asks you to invest before the FDA has approved any human study.", "prompt": "How should that shape your terms?", "options": ["Price in the risk of FDA rejections", "Pay a Neuralink-like valuation now", "Ignore it, since FDA approval is routine"], "correctIndex": 0, "consequences": ["Neuralink was turned down several times, so delay is a real risk.", "Neuralink had five patients when it raised at about $9 billion.", "Implanted BCIs are significant risk devices, a high bar."], "explanation": "Before the FDA says yes, there is no human data. That risk belongs in the price."}, "proReasoning": "Investors value the gate as a risk. Before the FDA's yes, a device company has no human data to show.", "commonMistake": "Paying for human-stage progress before the human stage begins.", "mentalModel": "Price the gate before it opens."}, "build_startup": {"call": {"kind": "theCall", "situation": "You've just won FDA approval for a first-in-human study. Your board asks when to raise a big round.", "prompt": "What's the best timing?", "options": ["Only after full market approval", "After the first implants show data", "Today, on the approval headline alone"], "correctIndex": 1, "consequences": ["Waiting years for market approval could starve the company.", "Neuralink raised $650 million after five people were implanted.", "A study approval alone shows no human results yet."], "explanation": "Human results are worth more to investors than permission to collect them. Raise when you can show them."}, "proReasoning": "Founders time big rounds to proof points. The first human results are worth far more to investors than permission to collect them.", "commonMistake": "Raising on the permission instead of the results.", "mentalModel": "Raise on results, not permission."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Neuralink took years to implant its first person.", "prompt": "What's the key reason?", "options": ["It could not find any volunteers", "Brain implants are banned in the US", "The FDA had to approve human testing"], "correctIndex": 2, "consequences": ["Volunteers were not the bottleneck; the approval was.", "They are allowed, but need FDA approval as significant risk devices.", "The FDA turned down its requests several times before May 2023."], "explanation": "The FDA classes implanted BCIs as significant risk devices. It approved Neuralink's first human study in May 2023, after earlier rejections."}, "proReasoning": "When a tech company moves slowly, look for a gatekeeper. In brain implants, the FDA decides when human testing starts.", "commonMistake": "Assuming delays come from the technology alone.", "mentalModel": "Look for the gatekeeper."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5f877ae11612$ml$]::text[]),
($ml$c7c9d95a-ae2c-5c69-819d-06ef91780d98$ml$::uuid, $ml$neuroscience$ml$, 3, 3, $ml${"id": "neuroscience-d3-c3", "title": "An antibody at the border", "lessonTitle": "The brain's two gatekeepers", "slot": 3, "type": "decide", "brief": {"headline": "You run a small biotech. Your antibody clears a brain disease protein in a dish, but essentially no large-molecule drug crosses the blood-brain barrier on its own.", "kicker": "Decide what to fix before your antibody goes into people.", "fullText": "You run a young biotech whose lead drug is an antibody, a large molecule. In lab tests it clears a protein linked to a brain disease, and your board wants to move fast.\n\nDay 3's first gatekeeper stands in the way. Pardridge wrote in 2005 that essentially 100% of large-molecule drugs and more than 98% of small-molecule drugs do not cross the blood-brain barrier. A dish has no barrier. A drug that works there can still fail in people if too little of it reaches brain tissue.", "sources": [{"url": "https://springeropen.altmetric.com/details/3182022", "label": "Pardridge 2005, The blood-brain barrier: bottleneck in brain drug development"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each result show the antibody gets into the brain?", "buckets": ["Shows it gets in", "Doesn't show it"], "items": [{"text": "Drug found in animal brain tissue after a dose", "bucket": 0}, {"text": "Brain levels high enough to hit the target", "bucket": 0}, {"text": "It clears the protein in a dish", "bucket": 1}, {"text": "It binds its target tightly", "bucket": 1}, {"text": "High drug levels in the blood", "bucket": 1}], "explanation": "Only measurements in the brain answer the barrier question. Dish results and blood levels can look great while the brain sees almost nothing."}, "numbers": {"kind": "numberSense", "prompt": "More than 98% of small-molecule drugs do not cross. Out of 1,000, fewer than how many get through?", "min": 0, "max": 100, "value": 20, "unit": "drugs", "explanation": "Under 2% of 1,000 is under 20. For large molecules like antibodies, essentially none."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at this biotech. The head of R&D asks what worries you about the lead drug.", "prompt": "What's your best answer?", "options": ["Whether enough antibody reaches the brain", "Whether the dish results are even real", "Whether the antibody is simply too small"], "correctIndex": 0, "consequences": ["Essentially no large-molecule drug crosses the barrier unaided.", "Possible, but the bigger known risk is the barrier.", "Antibodies are large molecules, which is the problem."], "explanation": "Antibodies are large molecules, and essentially none cross the barrier alone. Entry is the first question."}, "proReasoning": "For any brain drug, ask how it crosses the blood-brain barrier. It is the first gate, and most drugs never pass it.", "commonMistake": "Judging a brain drug by its lab potency alone.", "mentalModel": "Ask how it gets in."}, "invest": {"call": {"kind": "theCall", "situation": "The biotech asks you to fund human trials of its antibody.", "prompt": "What evidence do you want first?", "options": ["A larger team of chemists", "Proof the drug reaches brain tissue", "More dish results at higher doses"], "correctIndex": 1, "consequences": ["Team size does not get the drug across.", "Without it, the trial may test a drug the brain never sees.", "More dish results do not answer the barrier question."], "explanation": "Proof of brain entry is cheap to get early and expensive to discover missing in a trial."}, "proReasoning": "Investors in brain drugs ask for evidence the drug gets in before paying for big trials. It is the cheapest risk to test early.", "commonMistake": "Funding a trial before knowing the drug reaches its target.", "mentalModel": "Check entry before efficacy."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your antibody can't get in on its own. Your team has three ideas.", "prompt": "Which plan tackles the real problem?", "options": ["Raise the dose and hope", "Test it in a bigger dish study", "Find a way to carry it across"], "correctIndex": 2, "consequences": ["More drug in the blood still meets the same barrier.", "A dish has no barrier, so it cannot answer the question.", "Delivery is the bottleneck, so solve delivery."], "explanation": "The barrier, not the antibody, is what blocks you. Solve delivery first."}, "proReasoning": "Founders spend first on the gate that blocks them. For a large-molecule brain drug, delivery is the gate.", "commonMistake": "Improving the drug while ignoring how it reaches the brain.", "mentalModel": "Solve the gate first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why brain drugs that work in a lab so often fail in people.", "prompt": "What's one big reason?", "options": ["Most drugs cannot get into the brain", "Lab cells behave nothing like real cells", "Brain diseases have no targets to hit"], "correctIndex": 0, "consequences": ["Over 98% of small molecules and nearly all large ones are blocked.", "The cells can be fine; the dish just has no barrier.", "This antibody had a target; reaching it was the problem."], "explanation": "The blood-brain barrier blocks most drugs. A dish has no such barrier, so lab success can mislead."}, "proReasoning": "Explain the blood-brain barrier as a border guard. It protects the brain, and it also blocks most medicines.", "commonMistake": "Assuming a drug that works in a dish works in a brain.", "mentalModel": "The barrier blocks most drugs."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f7db69e4cbcf$ml$]::text[]),
($ml$cc149168-3e1c-5898-a43f-ae92e58148d4$ml$::uuid, $ml$neuroscience$ml$, 4, 1, $ml${"id": "neuroscience-d4-c1", "title": "A grain of sand, 523 million synapses", "lessonTitle": "The numbers inside your head", "slot": 1, "type": "apply", "brief": {"headline": "In April 2025, the MICrONS team mapped one cubic millimeter of mouse brain, about a grain of sand. It held more than 200,000 cells, 523 million synapses and 4 kilometers of axons.", "kicker": "Apply the lesson: count, don't judge the brain by its size.", "fullText": "MICrONS recorded a mouse's visual cortex while it watched movies and YouTube clips, then sliced and imaged the same tissue to trace its wiring. Published on April 9, 2025, across ten studies in the Nature journals, the map covers one cubic millimeter of tissue, no larger than a grain of sand.\n\nInside: more than 200,000 cells, 523 million synapses and about 4 kilometers of axons. The data fill 1.6 petabytes, about 22 years of continuous HD video. More than 150 scientists took part, funded by IARPA and the NIH BRAIN Initiative.\n\nA speck of tissue, and a staggering count. Size tells you almost nothing; the numbers tell you what you are dealing with.", "sources": [{"url": "https://sciencedaily.com/releases/2025/04/250409114838.htm", "label": "ScienceDaily, MICrONS maps a cubic millimeter of mouse brain, Apr 2025"}, {"url": "https://www.eurekalert.org/news-releases/1079296", "label": "EurekAlert, MICrONS wiring diagram of mouse visual cortex, Apr 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "The map covers a grain of sand of mouse cortex. How many synapses did it find inside?", "options": ["523 million", "About 5,000", "About 86 billion"], "correctIndex": 0, "explanation": "523 million synapses in one cubic millimeter. 86 billion is the neuron count of a whole human brain."}, "numbers": {"kind": "numberSense", "prompt": "About how many kilometers of axons did the map trace in that one cubic millimeter?", "min": 0, "max": 20, "value": 4, "unit": "km", "explanation": "About 4 kilometers of wiring, packed into a speck the size of a grain of sand."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're applying to a brain mapping lab. They ask why one cubic millimeter took more than 150 scientists.", "prompt": "What's your best answer?", "options": ["The tissue sample was the size of a fist", "Only a few cells needed mapping", "It held 523 million synapses to trace"], "correctIndex": 2, "consequences": ["It was no larger than a grain of sand.", "It held more than 200,000 cells.", "The count, not the size, made it a huge job."], "explanation": "The sample was tiny, but it held hundreds of millions of connections. The count set the workload."}, "proReasoning": "Explain big efforts with the number that drives them. Here, 523 million synapses in a speck of tissue.", "commonMistake": "Judging the difficulty by the sample's size.", "mentalModel": "The count sets the workload."}, "invest": {"call": {"kind": "theCall", "situation": "A startup wants to map a whole human brain at the MICrONS level of detail. It shows you the mouse results.", "prompt": "What should you check first?", "options": ["How data and costs grow with volume", "Whether the mouse watched the right movies", "How large the founders' lab is"], "correctIndex": 0, "consequences": ["One cubic millimeter already took 1.6 petabytes, so scale is the risk.", "The stimulus matters less than the mountain of data.", "Lab size says little about whether the plan can scale."], "explanation": "A grain of sand produced 1.6 petabytes. Scale the numbers before you believe the plan."}, "proReasoning": "Investors scale the numbers before backing a plan. If a grain of sand took 1.6 petabytes, ask what a whole brain would take.", "commonMistake": "Extrapolating a lab feat without doing the math.", "mentalModel": "Scale the numbers first."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells tools to labs that map brain wiring. MICrONS produced 1.6 petabytes from one cubic millimeter.", "prompt": "Which product need does that point to?", "options": ["Faster tissue shipping by courier", "Storing and analyzing huge image data", "Cheaper housing for lab mice"], "correctIndex": 1, "consequences": ["Shipping a grain of sand is easy; handling its data is not.", "1.6 petabytes is about 22 years of HD video from one speck.", "Mice are not the bottleneck; data is."], "explanation": "The tissue was tiny and the data enormous. Data handling is where the pain is."}, "proReasoning": "Founders look for the number that breaks today's tools. Petabytes from a speck of tissue say data handling is a bottleneck.", "commonMistake": "Building for the visible step instead of the overwhelming one.", "mentalModel": "Build where the numbers explode."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend can't see why mapping a grain-sized piece of brain was news.", "prompt": "Which fact makes it click?", "options": ["It took one afternoon to scan", "It held only a few hundred cells", "It held 4 kilometers of axons"], "correctIndex": 2, "consequences": ["It took a team of more than 150 scientists.", "It held more than 200,000 cells.", "Kilometers of wiring in a grain of sand makes the point."], "explanation": "Four kilometers of axons in a speck of tissue shows why the brain is so hard to map."}, "proReasoning": "Pick one number people can picture. Kilometers of wiring in a speck of tissue does more than any adjective.", "commonMistake": "Calling the brain complex without giving a number.", "mentalModel": "One vivid number beats adjectives."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:fe515e0ef064$ml$]::text[]),
($ml$4605948b-a065-5db4-8b22-85a68034e928$ml$::uuid, $ml$neuroscience$ml$, 4, 2, $ml${"id": "neuroscience-d4-c2", "title": "Small organ, big bill", "lessonTitle": "The numbers inside your head", "slot": 2, "type": "connect", "brief": {"headline": "The brain is about 2% of body weight but uses about 20% of resting energy. Inside it, the small cerebellum holds about 80% of the neurons.", "kicker": "Connect day 1 and day 4: two ways size misleads.", "fullText": "On day 1 you learned that the cerebellum, a wrinkled ball below and behind the rest of the brain, holds about 69 of the brain's 86 billion neurons. On day 4 you saw the energy side: the brain is about 2% of body weight, yet it uses about 20% of the body's resting energy.\n\nBoth facts break the same habit, judging by size. A small region can hold most of the cells, and a small organ can carry a large share of the body's energy bill. Check the counts and the energy, not the weight.", "sources": [{"url": "https://Gwern.net/doc/psychology/neuroscience/2009-azevedo.pdf", "label": "Azevedo et al. 2009, neuron counts in the human brain"}, {"url": "https://bionumbers.hms.harvard.edu/bionumber.aspx?id=108621", "label": "BioNumbers, brain share of resting metabolism"}, {"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The brain is about 2% of body weight.", "The brain uses about 2% of resting energy.", "The cerebellum holds about 69 billion neurons."], "fakeIndex": 1, "explanation": "The brain uses about 20% of resting energy, ten times its share of body weight."}, "numbers": {"kind": "numberSense", "prompt": "The brain is about 2% of body weight and uses about 20% of resting energy. How many times its weight share is that?", "min": 0, "max": 25, "value": 10, "unit": "times", "explanation": "20% against 2% is ten times. By energy, the brain punches far above its weight."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked to sum up the brain in numbers.", "prompt": "Which answer is strongest?", "options": ["86 billion neurons, 20% of resting energy", "It's the body's most complex organ by far", "About 86 billion neurons, mostly in the cortex"], "correctIndex": 0, "consequences": ["Two sourced numbers show you know the brain.", "Perhaps, but it gives them nothing to check.", "The cortex holds about 19%; most sit in the cerebellum."], "explanation": "Numbers beat adjectives, as long as they are right. Most neurons sit in the cerebellum, not the cortex."}, "proReasoning": "Quote numbers that surprise: 86 billion neurons, most in the cerebellum, 20% of resting energy. They show you know the brain beyond the cliché.", "commonMistake": "Using adjectives where numbers would land.", "mentalModel": "Numbers, not adjectives."}, "invest": {"call": {"kind": "theCall", "situation": "A pitch says its brain device barely uses energy, just like the brain.", "prompt": "What's wrong with the comparison?", "options": ["Devices and brains use the same power", "The brain uses about 20% of resting energy", "The brain uses no measurable energy"], "correctIndex": 1, "consequences": ["Nothing supports that; the brain's share is about 20%.", "At 2% of body weight, the brain is an energy-hungry organ.", "It uses about a fifth of resting energy."], "explanation": "The brain is one of the hungriest organs for its size. The analogy gets the basic fact backwards."}, "proReasoning": "Investors check analogies against numbers. A pitch that gets basic brain facts wrong deserves closer scrutiny.", "commonMistake": "Accepting a vivid analogy without checking it.", "mentalModel": "Test the analogy with a number."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're writing a product brief. A teammate says the brain is too small to matter much for metabolism.", "prompt": "How do you correct the brief?", "options": ["It uses about 2% of resting energy", "Brain energy use has never been measured", "It uses about 20% of resting energy"], "correctIndex": 2, "consequences": ["2% is its share of weight, not of energy.", "BioNumbers lists it at about 20%.", "Small by weight, large on the energy bill."], "explanation": "The brain is about 2% of body weight and about 20% of resting energy. Mixing them up skews the brief."}, "proReasoning": "Founders build on the right numbers from the start. A brief built on a wrong fact leads to wrong product claims.", "commonMistake": "Confusing the brain's weight share with its energy share.", "mentalModel": "Weight and energy are different numbers."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says the brain can't use much energy, since it's so light.", "prompt": "What do you tell them?", "options": ["At 2% of weight, it uses about 20% of energy", "It uses about as much as a fingernail", "Brains only use energy while we think hard"], "correctIndex": 0, "consequences": ["That is about ten times its share by weight.", "It uses about 20% of resting energy.", "The 20% figure is for the body at rest."], "explanation": "The brain takes about a fifth of the energy the body uses at rest."}, "proReasoning": "One ratio does the explaining: 2% of weight, 20% of energy. It is also why the brain suffers so fast when blood stops.", "commonMistake": "Assuming energy use follows weight.", "mentalModel": "Size misleads."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0f130b0c570d$ml$]::text[]),
($ml$494776ee-050a-5e84-b342-e5628d5db79e$ml$::uuid, $ml$neuroscience$ml$, 4, 3, $ml${"id": "neuroscience-d4-c3", "title": "Five patients, $9 billion", "lessonTitle": "The numbers inside your head", "slot": 3, "type": "decide", "brief": {"headline": "Neuralink raised $650 million in June 2025 at a reported valuation around $9 billion before the money. It had implanted five people. You decide what those numbers prove.", "kicker": "Decide which numbers are proof and which are a bet.", "fullText": "You run a small fund that follows brain-computer interfaces. Neuralink's Series E closed in June 2025 at $650 million, and Semafor reported a pre-money valuation around $9 billion. The company said five people with severe paralysis had its implant and could control digital devices with their minds.\n\nDay 4's habit applies to companies as well as brains: check the counts. Five patients prove something real. They do not yet prove long-term safety, a large market, or that payers will cover the device. A valuation prices those unproven parts too.", "sources": [{"url": "https://techcrunch.com/2025/06/02/elon-musks-neuralink-closes-a-650m-series-e", "label": "TechCrunch, Neuralink closes a $650M Series E"}, {"url": "https://www.fiercebiotech.com/medtech/neuralink-secures-650m-series-e-funding-expand-patient-access-brain-chip-technology", "label": "FierceBiotech, Neuralink secures $650M Series E"}]}, "evidence": {"kind": "sortSignal", "prompt": "Has each claim been shown yet, or is it still a bet?", "buckets": ["Shown so far", "Still a bet"], "items": [{"text": "People have been implanted with the chip", "bucket": 0}, {"text": "Patients control devices by thought", "bucket": 0}, {"text": "Years of safety in many patients", "bucket": 1}, {"text": "Thousands of paying patients", "bucket": 1}, {"text": "Insurers covering the implant", "bucket": 1}], "explanation": "Five implants show the device can work in people. Safety at scale, demand and coverage are still ahead."}, "numbers": {"kind": "numberSense", "prompt": "A $9 billion valuation over five implanted patients is about how many billion dollars per patient?", "min": 0, "max": 5, "value": 1.8, "unit": "B", "explanation": "$9 billion divided by five is $1.8 billion each. The price is for the future, not the five."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're offered a role at a BCI company valued like Neuralink, with a handful of patients.", "prompt": "What question protects you most?", "options": ["How many followers does the CEO have?", "What milestone does the next raise need?", "How big is the new office?"], "correctIndex": 1, "consequences": ["Attention is not evidence.", "Value rests on milestones still ahead, and so does your job.", "Offices say nothing about the path to patients."], "explanation": "A company priced on the future needs the next round. Ask what it takes to get there."}, "proReasoning": "At a company priced on the future, ask which milestone the next round depends on. That tells you how secure the role is.", "commonMistake": "Reading a high valuation as job security.", "mentalModel": "Ask what the next round needs."}, "invest": {"call": {"kind": "theCall", "situation": "Your fund can join a round valuing a BCI startup at $9 billion with five patients.", "prompt": "How do you frame the decision?", "options": ["Five patients prove the market is huge", "A big round means the risk is gone", "Price what is proven and what is a bet"], "correctIndex": 2, "consequences": ["Five patients show feasibility, not market size.", "Big money raises the stakes; it does not remove risk.", "Five implants show it works; safety and market are still bets."], "explanation": "Split the story into what five patients show and what the price assumes. Then decide if the bet is worth it."}, "proReasoning": "Investors split a story into what has been shown and what is assumed. Small numbers can justify a bet, not a certainty.", "commonMistake": "Letting a large valuation stand in for proof.", "mentalModel": "Proof versus bet."}, "build_startup": {"call": {"kind": "theCall", "situation": "You founded a BCI startup with two patients. Investors keep comparing you to Neuralink's $9 billion.", "prompt": "What should you anchor your pitch on?", "options": ["What your two patients show, and what is next", "Neuralink's valuation as your benchmark", "Forecasts of millions of future users"], "correctIndex": 0, "consequences": ["Honest evidence plus a clear next step builds trust.", "Their five patients and $650 million are not your numbers.", "Forecasts without patients are a story, not evidence."], "explanation": "Pitch what your numbers prove and the next proof the money will buy."}, "proReasoning": "Founders pitch what their numbers prove and the next proof the money will buy. Borrowed valuations invite hard questions.", "commonMistake": "Anchoring on someone else's valuation.", "mentalModel": "Pitch your proof, not their price."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend can't believe a company with five patients is worth about $9 billion.", "prompt": "What's a fair explanation?", "options": ["The FDA set the valuation", "Investors are pricing a large possible future", "Each patient pays billions for the implant"], "correctIndex": 1, "consequences": ["Investors, not regulators, set valuations.", "Five patients show it can work; the price bets on many more.", "The implants went to people in trials."], "explanation": "A valuation is a bet on what the company could become, not a measure of today's patients."}, "proReasoning": "Explain big valuations as bets on the future. The current numbers show what is possible; the price assumes much more.", "commonMistake": "Thinking a valuation reflects today's revenue.", "mentalModel": "Valuations price the future."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9fff63715803$ml$]::text[]),
($ml$e4c98f2a-ab6d-55af-aecb-f6fe1826d425$ml$::uuid, $ml$neuroscience$ml$, 5, 1, $ml${"id": "neuroscience-d5-c1", "title": "Novo's lottery ticket", "lessonTitle": "Why brain drugs fail so often", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, two Phase 3 trials of semaglutide in 3,808 people with early Alzheimer's failed to slow decline. UBS had given them a 10% chance; Novo's shares fell 8% that day.", "kicker": "Apply the base rate: even a famous drug faced long odds here.", "fullText": "Semaglutide, Novo Nordisk's drug approved for diabetes and obesity, was tested in early Alzheimer's in the evoke and evoke+ trials. 3,808 people aged 55 to 85 with mild cognitive impairment or mild Alzheimer's dementia took a daily semaglutide pill or a placebo for two years.\n\nOn November 24, 2025, Novo said semaglutide did not beat placebo on the CDR-SB, a measure of cognition and function, though it improved some Alzheimer's-related biomarkers. It dropped the planned one-year extension, and its shares fell 8.32% in Copenhagen.\n\nThe odds had been stated openly. UBS put the chance of success at 10%, a senior Novo executive had called the trials a lottery ticket, and the company's chief scientific officer had acknowledged a low likelihood of success.", "sources": [{"url": "https://www.alzheimer-europe.org/news/novo-nordisk-announces-topline-results-evoke-and-evoke-trials-semaglutide-early-ad", "label": "Alzheimer Europe, Novo Nordisk topline results from evoke and evoke+, Nov 2025"}, {"url": "https://www.hl.co.uk/shares/stock-market-news/company--news/novo-nordisk-shares-fall-on-failure-of-two-big-alzheimers-studies", "label": "Hargreaves Lansdown, Novo Nordisk shares fall on failure of two Alzheimer's studies, Nov 2025"}, {"url": "https://mind.uci.edu/novo-nordisk-announces-disappointing-glp1-results/", "label": "UCI MIND, Novo Nordisk announces disappointing GLP-1 results, Nov 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the evoke trials. Tap it.", "statements": ["Semaglutide improved some Alzheimer's biomarkers.", "Semaglutide slowed decline on the CDR-SB.", "Novo dropped the planned one-year extension."], "fakeIndex": 1, "explanation": "Biomarkers moved, but decline did not slow. A better marker is not the same as a better outcome."}, "numbers": {"kind": "numberSense", "prompt": "What chance of success, in percent, had UBS given the evoke trials?", "min": 0, "max": 40, "value": 10, "unit": "%", "explanation": "About 10%, above the 5.9% average for neurology drugs from Phase 1, and still a long shot."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're offered a role on a big drugmaker's Alzheimer's program. It's one of many bets the company runs.", "prompt": "How should the odds shape your choice?", "options": ["A failure hurts less inside a broad company", "A big company means the drug will work", "Odds only matter at small biotechs"], "correctIndex": 0, "consequences": ["Novo's shares fell 8%, but one trial was not the whole company.", "Novo's evoke trials failed despite its size.", "Neurology's 5.9% odds apply to every company."], "explanation": "Size does not change the science, but it changes what a failure does to your job."}, "proReasoning": "In neurology, judge a job by what happens if the trial fails. At a broad company, a failed program is a setback; at a one-drug biotech, it can be the end.", "commonMistake": "Assuming a famous company's program is safer science.", "mentalModel": "Ask what happens if it fails.", "sources": [{"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, Clinical Development Success Rates 2011 to 2020"}]}, "invest": {"call": {"kind": "theCall", "situation": "Before the readout, Novo calls the trials a lottery ticket and UBS gives them 10%. The stock falls 8% on failure.", "prompt": "What does the drop tell you?", "options": ["The drug will be pulled from diabetes use", "Some investors had priced in more hope", "The odds had been 90% in favor"], "correctIndex": 1, "consequences": ["The failure was in Alzheimer's, not its approved uses.", "Even long shots carry value until they fail.", "UBS put the chance at 10%, not 90%."], "explanation": "A 10% chance at a huge market is worth something. When it fails, that value comes out of the price."}, "proReasoning": "Investors size how much a binary event is worth before it happens. A 10% chance still carries value, and losing it moves the price.", "commonMistake": "Thinking a widely expected failure cannot move the stock.", "mentalModel": "Long shots carry value until they fail."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's Alzheimer's drug improves biomarkers in early tests. You're planning a pitch.", "prompt": "What lesson from evoke should shape it?", "options": ["Biomarker gains guarantee clinical success", "Large trials always succeed", "Better biomarkers may not slow decline"], "correctIndex": 2, "consequences": ["Evoke improved biomarkers and still failed.", "3,808 people did not save evoke.", "Semaglutide moved biomarkers but did not beat placebo on the CDR-SB."], "explanation": "Evoke showed that markers can move while patients still decline. Plan your evidence for that gap."}, "proReasoning": "Founders show they know the gap between markers and outcomes. Investors trust a team that plans for it.", "commonMistake": "Pitching biomarker gains as proof of benefit.", "mentalModel": "Markers are not outcomes."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a drug approved for diabetes and obesity could fail in Alzheimer's.", "prompt": "What's the best answer?", "options": ["One disease says little about another", "The trial was far too small to tell", "The drug was never tested in people"], "correctIndex": 0, "consequences": ["Brain drugs fail most of the time, whatever their record elsewhere.", "It enrolled 3,808 people over two years.", "It was tested in two Phase 3 trials."], "explanation": "Each disease has its own biology and its own odds. In Alzheimer's, most drugs fail."}, "proReasoning": "Explain trial failures with base rates. Most brain drugs fail, so a famous name does not change the odds much.", "commonMistake": "Assuming success in one disease carries over to the brain.", "mentalModel": "Every disease has its own odds."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0a5110f31c0a$ml$]::text[]),
($ml$951f48ce-820b-5cc5-8c46-a005745e3ca8$ml$::uuid, $ml$neuroscience$ml$, 5, 2, $ml${"id": "neuroscience-d5-c2", "title": "The barrier and the odds", "lessonTitle": "Why brain drugs fail so often", "slot": 2, "type": "connect", "brief": {"headline": "Neurology drugs entering Phase 1 had a 5.9% chance of approval in 2011 to 2020, below the 7.9% average. Brain drugs also face a gate most others do not: the blood-brain barrier.", "kicker": "Connect day 3 and day 5: one gate behind the long odds.", "fullText": "On day 5 you saw the odds: a BIO study found neurology drugs entering Phase 1 from 2011 to 2020 had a 5.9% chance of approval, against 7.9% across all diseases. Alzheimer's drug development failed 99.6% of the time from 2002 to 2012.\n\nOn day 3 you met one reason brain drugs start behind. Pardridge called the blood-brain barrier the bottleneck in brain drug development: more than 98% of small-molecule drugs and essentially all large ones do not cross it. A drug that cannot reach its target cannot work, however good the target.", "sources": [{"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, Clinical Development Success Rates 2011 to 2020"}, {"url": "https://www.fiercebiotech.com/r-d/alzheimer-s-r-d-suffers-as-trial-failure-rate-hits-an-astounding-99-6", "label": "FierceBiotech, Alzheimer's trial failure rate hits 99.6%"}, {"url": "https://springeropen.altmetric.com/details/3182022", "label": "Pardridge 2005, The blood-brain barrier: bottleneck in brain drug development"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how the barrier can sink a promising brain drug.", "steps": ["A drug works on its target in a dish", "In a patient, it enters the blood", "It meets the blood-brain barrier", "Too little of it reaches brain tissue", "The trial fails to show a benefit"], "explanation": "A dish has no barrier. In a body, the barrier can keep the drug from its target, and the trial fails."}, "numbers": {"kind": "numberSense", "prompt": "At 5.9% odds, about how many of 1,000 neurology drugs entering Phase 1 would win approval?", "min": 0, "max": 200, "value": 59, "unit": "drugs", "explanation": "About 59 of 1,000. At the 7.9% average it would be about 79."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a neurology biotech. They ask why brain drugs fail more often than others.", "prompt": "Which answer shows depth?", "options": ["The FDA rejects brain drugs on principle", "Many never get past the barrier", "Brain researchers are less skilled"], "correctIndex": 1, "consequences": ["The FDA gave Leqembi traditional approval in 2023.", "Over 98% of small molecules are blocked, a hurdle most fields lack.", "Nothing supports that; the biology is harder."], "explanation": "The barrier blocks most drugs before they reach brain tissue. It is a concrete reason for lower odds."}, "proReasoning": "Connect the base rate to a mechanism. Saying the barrier blocks most drugs explains part of neurology's lower odds.", "commonMistake": "Blaming people or regulators for a biological problem.", "mentalModel": "Explain odds with mechanisms.", "sources": [{"url": "https://www.biospace.com/fda-grants-traditional-approval-for-leqembi-lecanemab-irmb-for-the-treatment-of-alzheimer-s-disease", "label": "Eisai and Biogen via BioSpace, Leqembi traditional approval"}]}, "invest": {"call": {"kind": "theCall", "situation": "Two neurology biotechs pitch you. One has proof its drug reaches brain tissue; the other only dish data.", "prompt": "Which deserves better odds?", "options": ["The one with stronger dish results", "Both equal, since all start at 5.9%", "The one with proof of brain entry"], "correctIndex": 2, "consequences": ["A dish has no barrier, so it cannot test entry.", "Averages are a start; evidence about the barrier should shift them.", "It has passed a gate that blocks most brain drugs."], "explanation": "Base rates are where you start. Evidence that a drug gets in should move your estimate."}, "proReasoning": "Investors adjust base rates with specific evidence. Proof of brain entry removes one of the main reasons brain drugs fail.", "commonMistake": "Applying the average odds to every drug without adjusting.", "mentalModel": "Start with the base rate, then adjust."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're founding a company to help brain drugs reach their target. A friend says the market is too niche.", "prompt": "What's your best reply?", "options": ["Nearly every brain drug faces the barrier", "Only a few drugs ever need the brain", "The barrier only affects old drugs"], "correctIndex": 0, "consequences": ["Over 98% of small molecules and nearly all large ones are blocked.", "Every drug for a brain disease must reach the brain.", "The barrier blocks new and old drugs alike."], "explanation": "A problem shared by almost every brain drug is the opposite of niche."}, "proReasoning": "Founders size a delivery problem by how many drugs it blocks. Here, nearly all of them.", "commonMistake": "Seeing a platform problem as a niche one.", "mentalModel": "A shared gate is a big market."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Alzheimer's drug trials failed 99.6% of the time from 2002 to 2012.", "prompt": "What's one clear reason?", "options": ["Alzheimer's has too few patients to test", "Many drugs struggle to get into the brain", "Researchers stopped testing new ideas"], "correctIndex": 1, "consequences": ["Alzheimer's is common, so patients were not the problem.", "The barrier blocks most drugs before they reach brain tissue.", "Programs kept coming in that decade; most failed."], "explanation": "The blood-brain barrier is one concrete reason. Most drugs never reach brain tissue in useful amounts."}, "proReasoning": "Give one mechanism, not a mystery. The barrier is a concrete reason brain drugs fail more often.", "commonMistake": "Treating brain drug failure as bad luck.", "mentalModel": "Failures have mechanisms."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4b5adcc04f20$ml$]::text[]),
($ml$0a1cacab-d178-5baf-8ba0-5080b49a4fe9$ml$::uuid, $ml$neuroscience$ml$, 5, 3, $ml${"id": "neuroscience-d5-c3", "title": "One drug, 5.9% odds", "lessonTitle": "Why brain drugs fail so often", "slot": 3, "type": "decide", "brief": {"headline": "You run a biotech with one drug: an Alzheimer's candidate entering Phase 1. Neurology drugs at that stage had a 5.9% chance of approval in 2011 to 2020.", "kicker": "Decide how to plan around odds this long.", "fullText": "You run a young biotech built around a single drug for Alzheimer's disease, about to enter Phase 1. The BIO study of 2011 to 2020 gives neurology drugs at this stage a 5.9% chance of reaching approval, against 7.9% across all diseases. In Alzheimer's, 99.6% of programs failed from 2002 to 2012.\n\nWinners exist. Leqembi, from Eisai and Biogen, won traditional FDA approval on July 6, 2023, after slowing clinical decline by 27% against placebo over 18 months. Its label carries a boxed warning for ARIA, brain scan changes such as swelling or bleeding. Even a success slows the disease rather than stopping it.", "sources": [{"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, Clinical Development Success Rates 2011 to 2020"}, {"url": "https://www.fiercebiotech.com/r-d/alzheimer-s-r-d-suffers-as-trial-failure-rate-hits-an-astounding-99-6", "label": "FierceBiotech, Alzheimer's trial failure rate hits 99.6%"}, {"url": "https://www.biospace.com/fda-grants-traditional-approval-for-leqembi-lecanemab-irmb-for-the-treatment-of-alzheimer-s-disease", "label": "Eisai and Biogen via BioSpace, Leqembi traditional approval"}]}, "evidence": {"kind": "faceOff", "prompt": "Which setup better survives a failed first trial?", "left": {"name": "One drug, all the cash", "note": "Every dollar rides on one Phase 1 result"}, "right": {"name": "Two programs, shared costs", "note": "A second bet keeps the company going"}, "correctIndex": 1, "explanation": "With 5.9% odds, most single bets fail. A second, independent program keeps the company alive when one does."}, "numbers": {"kind": "numberSense", "prompt": "At 5.9% odds, about how many of 100 neurology drugs entering Phase 1 fail to win approval?", "min": 0, "max": 100, "value": 94, "unit": "drugs", "explanation": "About 94 of 100. Failure is the base case, so plan for it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "This biotech offers you a senior role with a lot of stock.", "prompt": "What should you ask before saying yes?", "options": ["How quickly can the drug launch?", "How big is the Alzheimer's market?", "What happens to us if Phase 1 fails?"], "correctIndex": 2, "consequences": ["Most drugs never reach launch at all.", "Market size matters little if the drug fails.", "With 5.9% odds, the failure plan decides your job."], "explanation": "In a one-drug company, the stock is worth a lot only in the rare case the drug works. Ask about the plan for the common case."}, "proReasoning": "In a one-drug company, ask about the plan for failure first. Stock is worth a lot only in the rare case it works.", "commonMistake": "Valuing the stock as if approval were likely.", "mentalModel": "Price in the odds."}, "invest": {"call": {"kind": "theCall", "situation": "You could put your whole neurology budget into this company's next round.", "prompt": "What's the sound approach?", "options": ["Spread the money across several bets", "Go all in, since Leqembi succeeded", "Wait for approval before investing"], "correctIndex": 0, "consequences": ["With 5.9% odds, one result can wipe out a single bet.", "One success does not change the base rate.", "Waiting removes the risk and most of the reward with it."], "explanation": "Single trials decide everything in neurology. Several bets protect you from one failure."}, "proReasoning": "Investors in neurology spread risk because single trials decide everything. Several bets at 5.9% beat one.", "commonMistake": "Concentrating on one drug because another drug won.", "mentalModel": "Spread out binary risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "As founder, you can license a second, unrelated drug to run alongside your Alzheimer's candidate.", "prompt": "Why might that be worth the cost?", "options": ["Investors dislike focused companies", "It lowers the risk of total failure", "It doubles the first drug's odds"], "correctIndex": 1, "consequences": ["Many investors like focus; the point here is survival.", "With odds this long, two independent bets protect the company.", "Each drug keeps its own odds."], "explanation": "One failure should not end the company. A second program buys another chance."}, "proReasoning": "Founders in neurology often add a second program so one failure isn't fatal. Focus is good; a single point of failure is not.", "commonMistake": "Betting the company on one trial in a field where most trials fail.", "mentalModel": "Never just one shot."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend hears Leqembi was approved and assumes Alzheimer's drugs now usually work.", "prompt": "What's the fair picture?", "options": ["Most Alzheimer's drugs now succeed", "Leqembi stops the disease", "Successes are rare and partial"], "correctIndex": 2, "consequences": ["The failure rate was 99.6% from 2002 to 2012.", "It slows decline; it does not stop it.", "Leqembi slowed decline by 27%; most candidates fail."], "explanation": "One approval is news because most drugs fail. And it slows the disease rather than stopping it."}, "proReasoning": "Pair any success story with the base rate. One approval is news precisely because most drugs fail.", "commonMistake": "Reading one approval as a trend.", "mentalModel": "One win, many losses."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e4785b7156ac$ml$]::text[]),
($ml$06205f66-218a-53d2-9f3c-32d2b61f5673$ml$::uuid, $ml$neuroscience$ml$, 6, 1, $ml${"id": "neuroscience-d6-c1", "title": "A five-second stroke drug", "lessonTitle": "When blood stops reaching the brain", "slot": 1, "type": "apply", "brief": {"headline": "In March 2025, the FDA approved tenecteplase for ischemic stroke, given as one five-second injection. The older drug, alteplase, needs a bolus plus a 60-minute infusion.", "kicker": "Apply time is brain: what does a simpler drug save?", "fullText": "Genentech's TNKase, tenecteplase, was approved on March 3, 2025, for adults with acute ischemic stroke, to be given within 3 hours of symptom onset. It was the first FDA-approved stroke medicine in nearly 30 years. In the AcT trial of about 1,600 patients at 22 Canadian stroke sites, 36.9% on tenecteplase and 34.8% on alteplase reached the best functional outcomes at 90 to 120 days, and bleeding rates were similar.\n\nThe difference is in the giving: one bolus replaces an hour-long infusion. When a New Zealand stroke network switched in 2020, its median door-to-needle time fell from 61 to 53 minutes, which the authors linked to more patients treated right in the CT scanner. That study was observational.", "sources": [{"url": "https://www.hcplive.com/view/fda-approves-tenecteplase-tnkase-for-acute-ischemic-stroke", "label": "HCPLive, FDA approves tenecteplase for acute ischemic stroke, Mar 2025"}, {"url": "https://www.tctmd.com/news/switching-tenecteplase-stroke-thrombolysis-may-boost-outcomes", "label": "TCTMD, Switching to tenecteplase for stroke may boost outcomes, Sep 2021"}]}, "evidence": {"kind": "faceOff", "prompt": "After switching, a New Zealand network cut its median door-to-needle time. Which drug did it switch to?", "left": {"name": "Tenecteplase", "note": "One bolus, about 5 seconds"}, "right": {"name": "Alteplase", "note": "Bolus plus a 60-minute infusion"}, "correctIndex": 0, "explanation": "After the switch to tenecteplase, the median fell from 61 to 53 minutes, with more patients treated in the scanner."}, "numbers": {"kind": "numberSense", "prompt": "At about 1.9 million neurons a minute, how many million neurons do 8 minutes represent in a large untreated stroke?", "min": 0, "max": 40, "value": 15, "unit": "M", "explanation": "8 times 1.9 million is about 15 million neurons. Minutes saved are brain saved."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a stroke network's quality team as it weighs switching to tenecteplase.", "prompt": "Which measure should you track first?", "options": ["Patient satisfaction scores", "Door-to-needle time", "Number of vials in stock"], "correctIndex": 1, "consequences": ["Worth tracking, but speed is what saves brain.", "Each minute costs about 1.9 million neurons in a large stroke.", "Stock matters, but it does not measure speed to treatment."], "explanation": "A simpler drug is worth what it does to the clock. Door-to-needle time measures that directly."}, "proReasoning": "Stroke teams judge changes by minutes saved to treatment. A simpler drug is worth what it does to that clock.", "commonMistake": "Measuring a stroke change by convenience instead of time.", "mentalModel": "Measure the minutes.", "sources": [{"url": "https://pubmed.ncbi.nlm.nih.gov/16339467/", "label": "Saver, Time is brain quantified, Stroke 2006"}]}, "invest": {"call": {"kind": "theCall", "situation": "TNKase wins FDA approval for stroke. Its trial showed outcomes close to alteplase.", "prompt": "What's its main selling point to hospitals?", "options": ["Far better outcomes than alteplase", "No bleeding risk at all", "Similar results with a much simpler dose"], "correctIndex": 2, "consequences": ["AcT showed 36.9% against 34.8%, a non-inferiority result.", "Bleeding is among its most common adverse reactions.", "One bolus replaces an hour-long infusion with comparable results."], "explanation": "AcT was a non-inferiority trial. The case for switching is speed and simplicity, not a big jump in outcomes."}, "proReasoning": "Investors read a non-inferiority win as a convenience story. Its value depends on whether hospitals switch for speed and simplicity.", "commonMistake": "Reading approval as proof of superior outcomes.", "mentalModel": "Same outcome, simpler workflow."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes stroke workflow software. Hospitals are switching to tenecteplase.", "prompt": "Where should your product focus?", "options": ["Cutting minutes before the needle", "Managing hour-long infusion pumps", "Billing for alteplase infusions"], "correctIndex": 0, "consequences": ["With a five-second bolus, the remaining delays come before treatment.", "The infusion step is shrinking to one injection.", "Hospitals switching drugs are leaving that workflow."], "explanation": "When the drug takes seconds to give, the delays left are the ones before it. Build there."}, "proReasoning": "When one step shrinks, founders move to the next bottleneck. With the drug given in seconds, delays before the needle matter most.", "commonMistake": "Building for the step that just got faster.", "mentalModel": "Chase the next bottleneck."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a stroke drug that works about as well as the old one is a big deal.", "prompt": "What's the best answer?", "options": ["It can be taken at home as a pill", "It is faster to give, and time is brain", "It works twice as well"], "correctIndex": 1, "consequences": ["It is a single injection into a vein.", "A five-second bolus can help teams start treatment sooner.", "Results were similar: 36.9% against 34.8%."], "explanation": "In stroke, every minute costs neurons. A drug that is quicker to give can save minutes."}, "proReasoning": "In stroke, speed counts as much as potency. A drug that is easier to give can save brain by saving minutes.", "commonMistake": "Judging a stroke drug only by its trial outcome.", "mentalModel": "In stroke, speed is a feature."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2f5c5584a889$ml$]::text[]),
($ml$4c5ba371-c1de-5be2-b7f7-1d0983a600c0$ml$::uuid, $ml$neuroscience$ml$, 6, 2, $ml${"id": "neuroscience-d6-c2", "title": "A hungry organ cannot wait", "lessonTitle": "When blood stops reaching the brain", "slot": 2, "type": "connect", "brief": {"headline": "The brain uses about 20% of the body's resting energy. When a large ischemic stroke goes untreated, it loses about 1.9 million neurons every minute.", "kicker": "Connect day 4 and day 6: a hungry organ can't wait.", "fullText": "On day 4 you learned the brain is about 2% of body weight yet uses about 20% of resting energy, and holds about 86 billion neurons. On day 6 you saw what happens when its blood supply stops. About 87% of strokes are ischemic, caused by a blocked vessel. In a typical large untreated ischemic stroke, Saver estimated the brain loses about 1.9 million neurons and 14 billion synapses each minute, aging about 3.6 years for each hour.\n\nAn organ that burns that much energy has little to fall back on. When a vessel blocks, the region it feeds starts dying within minutes.", "sources": [{"url": "https://bionumbers.hms.harvard.edu/bionumber.aspx?id=108621", "label": "BioNumbers, brain share of resting metabolism"}, {"url": "https://Gwern.net/doc/psychology/neuroscience/2009-azevedo.pdf", "label": "Azevedo et al. 2009, neuron counts in the human brain"}, {"url": "https://www.cdc.gov/stroke/data-research/facts-stats/index.html", "label": "CDC, Stroke facts"}, {"url": "https://pubmed.ncbi.nlm.nih.gov/16339467/", "label": "Saver, Time is brain quantified, Stroke 2006"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow what happens when a vessel to the brain blocks.", "steps": ["A blood vessel to the brain blocks", "The region it feeds loses its blood supply", "Energy-hungry neurons run out of fuel", "About 1.9 million neurons die each minute", "Lost function shows up as disability"], "explanation": "The brain needs a steady supply of energy. Without blood, the region starts dying within minutes."}, "numbers": {"kind": "numberSense", "prompt": "At 1.9 million neurons a minute, about how many million neurons does one hour without treatment cost?", "min": 0, "max": 300, "value": 114, "unit": "M", "explanation": "60 times 1.9 million is about 114 million neurons in an hour, along with about 3.6 years of brain aging."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a stroke program manager role. They ask why speed matters so much.", "prompt": "What's your strongest answer?", "options": ["Patients dislike waiting in hospitals", "Fast care lowers hospital paperwork", "About 1.9 million neurons die each minute"], "correctIndex": 2, "consequences": ["True, but it misses the biology.", "Paperwork is not why minutes matter.", "A number ties speed directly to brain saved."], "explanation": "The brain burns energy fast and dies fast without blood. One number makes the case."}, "proReasoning": "Tie stroke speed to the biology: an energy-hungry organ loses about 1.9 million neurons a minute without blood.", "commonMistake": "Explaining stroke urgency as a service issue.", "mentalModel": "Minutes are neurons."}, "invest": {"call": {"kind": "theCall", "situation": "A stroke startup claims its product saves 10 minutes per patient.", "prompt": "How can you put a number on that?", "options": ["Roughly 19 million neurons", "About 10 neurons saved per patient", "It cannot be measured in any way"], "correctIndex": 0, "consequences": ["10 minutes at 1.9 million a minute is about 19 million.", "Off by a factor of millions.", "Saver's estimate gives a way to measure it."], "explanation": "Saver's estimate turns minutes into neurons, so time claims can be compared."}, "proReasoning": "Investors turn a time claim into an outcome number. Saver's estimate makes minutes comparable.", "commonMistake": "Accepting time savings without asking what they are worth.", "mentalModel": "Convert minutes into brain."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building a stroke alert app. You can show one fact on its home screen.", "prompt": "Which fact best explains your mission?", "options": ["The brain holds 86 billion neurons", "1.9 million neurons lost each minute", "The brain is 2% of body weight"], "correctIndex": 1, "consequences": ["True, but it says nothing about urgency.", "It ties your product's speed to brain saved.", "Weight is the misleading number."], "explanation": "Your product sells speed. The cost of each minute is the number that makes speed matter."}, "proReasoning": "Founders pick the number that makes their value obvious. For a stroke alert, that is the cost of each minute.", "commonMistake": "Leading with a general brain fact instead of the urgent one.", "mentalModel": "Lead with the number that sets the clock."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why doctors say 'time is brain' about strokes.", "prompt": "What's the clearest explanation?", "options": ["Strokes spread like an infection", "Lost neurons are replaced in minutes", "Without blood, the brain dies fast"], "correctIndex": 2, "consequences": ["A blocked vessel starves a region; it is not an infection.", "Nothing replaces 1.9 million neurons a minute.", "It uses about 20% of resting energy and loses 1.9 million neurons a minute."], "explanation": "The brain needs a lot of energy and has little reserve. Without blood, neurons die by the million each minute."}, "proReasoning": "Explain time is brain with two numbers: the energy the brain needs and the neurons lost each minute without it.", "commonMistake": "Thinking stroke damage happens all at once.", "mentalModel": "No blood, no energy, lost neurons."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f7360c76d4b7$ml$]::text[]),
($ml$f3f9b737-cf61-5b35-8d02-ba27498f0c44$ml$::uuid, $ml$neuroscience$ml$, 6, 3, $ml${"id": "neuroscience-d6-c3", "title": "Which stroke to build for", "lessonTitle": "When blood stops reaching the brain", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup choosing its first stroke product. Of the more than 795,000 US strokes each year, about 87% are ischemic, caused by a blocked vessel.", "kicker": "Decide where a new stroke company should start.", "fullText": "You run a young medtech startup with money for one stroke product. More than 795,000 people in the US have a stroke each year, and about 87% are ischemic, caused by a blocked vessel to the brain. Stroke is a leading cause of serious long-term disability, and it cost the US nearly $56.2 billion in 2019 to 2020.\n\nTime sets the stakes. In a typical large untreated ischemic stroke, Saver estimated the brain loses about 1.9 million neurons each minute. Your choice: where in that story can one product make the biggest difference?", "sources": [{"url": "https://www.cdc.gov/stroke/data-research/facts-stats/index.html", "label": "CDC, Stroke facts"}, {"url": "https://pubmed.ncbi.nlm.nih.gov/16339467/", "label": "Saver, Time is brain quantified, Stroke 2006"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each fact support starting with ischemic stroke and speed?", "buckets": ["Supports it", "Doesn't bear on it"], "items": [{"text": "About 87% of strokes are ischemic", "bucket": 0}, {"text": "About 1.9 million neurons are lost each minute", "bucket": 0}, {"text": "More than 795,000 US strokes a year", "bucket": 0}, {"text": "The brain is about 2% of body weight", "bucket": 1}, {"text": "The cortex holds about 19% of neurons", "bucket": 1}], "explanation": "Patient numbers and the cost of each minute point to ischemic stroke and speed. General brain facts do not decide it."}, "numbers": {"kind": "numberSense", "prompt": "About 87% of more than 795,000 yearly US strokes are ischemic. About how many thousand is that?", "min": 0, "max": 1000, "value": 692, "unit": "K", "explanation": "87% of 795,000 is about 692,000 people a year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the startup's first clinical lead. The CEO asks where minutes are lost before treatment.", "prompt": "How do you find out?", "options": ["Map each step from symptoms to treatment", "Ask investors which step they like", "Assume the hospital is the slow part"], "correctIndex": 0, "consequences": ["Mapping the steps shows where the minutes, and neurons, go.", "Investors do not see where minutes go.", "Guessing skips the evidence you need."], "explanation": "Every step from first symptom to treatment costs neurons. Measure the whole path before choosing a fix."}, "proReasoning": "Clinical leads measure the whole path before picking a fix. In stroke, every step from first symptom to treatment costs neurons.", "commonMistake": "Picking a fix before mapping the delays.", "mentalModel": "Map the clock before fixing it."}, "invest": {"call": {"kind": "theCall", "situation": "The startup pitches you a product to speed care for ischemic stroke.", "prompt": "Which fact best supports the market size?", "options": ["The cerebellum holds 80% of neurons", "About 87% of 795,000 strokes are ischemic", "The brain uses 20% of resting energy"], "correctIndex": 1, "consequences": ["True, but it has nothing to do with stroke demand.", "That is roughly 692,000 people a year in the US.", "True, but it does not size a market."], "explanation": "Market size starts with patients. Ischemic stroke is most of all strokes."}, "proReasoning": "Investors size the market from the patients a product can reach. Ischemic stroke is most of all strokes.", "commonMistake": "Using a striking brain fact in place of a patient count.", "mentalModel": "Size it by patients."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your cofounder wants to start with the other 13% of strokes, where there is less competition.", "prompt": "What's the strongest case for ischemic first?", "options": ["It needs no regulatory approval", "It has no competitors at all", "It covers about 87% of patients"], "correctIndex": 2, "consequences": ["Medical products for stroke still need regulators.", "Treatments already exist, so you must beat them.", "Most patients have this type, so your product reaches more people."], "explanation": "Starting where most patients are gives a first product the widest use."}, "proReasoning": "Founders weigh reach against competition. Starting where 87% of patients are gives a product the widest use.", "commonMistake": "Choosing a smaller group only to avoid rivals.", "mentalModel": "Start where most patients are."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what 'ischemic' means in a stroke news story.", "prompt": "What do you say?", "options": ["A blocked vessel cuts blood to the brain", "A stroke caused mainly by stress", "A stroke that always heals by itself"], "correctIndex": 0, "consequences": ["About 87% of strokes are this type.", "Ischemic means blood flow is blocked.", "Untreated, neurons die by the minute."], "explanation": "Ischemic means blood flow to part of the brain is blocked. It is the most common kind of stroke."}, "proReasoning": "Explain medical words by what happens: ischemic means blood flow to part of the brain is blocked.", "commonMistake": "Using the term without saying what it means.", "mentalModel": "Name it by what happens."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:73a57e18ac5e$ml$]::text[]),
($ml$13d38de5-7104-5aad-aee5-5ce53b08d3ff$ml$::uuid, $ml$neuroscience$ml$, 7, 1, $ml${"id": "neuroscience-d7-c1", "title": "A pill that boosts the brakes", "lessonTitle": "The chemicals neurons use to talk", "slot": 1, "type": "apply", "brief": {"headline": "In August 2023, the FDA approved zuranolone, the first pill for postpartum depression. It acts on GABA-A receptors, part of the brain's main inhibitory system, not on serotonin or dopamine.", "kicker": "Apply the messengers: a depression drug that works through GABA.", "fullText": "Zurzuvae, or zuranolone, was approved on August 4, 2023, as the first oral treatment for postpartum depression in adults. It is taken once a day for 14 days. In two placebo-controlled studies, patients improved more than on placebo by day 15, and the effect lasted through four weeks of follow-up.\n\nIt is a neuroactive steroid that acts on GABA-A receptors. Unlike standard antidepressants, it does not act directly on serotonin or dopamine. The only earlier approved drug for postpartum depression, brexanolone, works the same way but needs a 60-hour continuous IV infusion in a hospital.\n\nThe FDA did not approve zuranolone for major depressive disorder. A different messenger target opened a new option for one condition, not for all depression.", "sources": [{"url": "https://psychiatrictimes.com/view/fda-approves-first-oral-treatment-for-postpartum-depression-in-adults", "label": "Psychiatric Times, FDA approves first oral treatment for postpartum depression, Aug 2023"}, {"url": "https://my.clevelandclinic.org/health/articles/22513-neurotransmitters", "label": "Cleveland Clinic, Neurotransmitters"}]}, "evidence": {"kind": "faceOff", "prompt": "Both drugs act on GABA-A receptors. Which one can be taken at home?", "left": {"name": "Zuranolone", "note": "One pill a day for 14 days"}, "right": {"name": "Brexanolone", "note": "60-hour IV infusion in a hospital"}, "correctIndex": 0, "explanation": "Same messenger target, very different delivery. Zuranolone moved the treatment from a hospital bed to a pill at home."}, "numbers": {"kind": "numberSense", "prompt": "Brexanolone needs a 60-hour continuous infusion. How many days of round-the-clock treatment is that?", "min": 0, "max": 7, "value": 2.5, "unit": "days", "explanation": "60 hours is two and a half days in a hospital, against a 14-day course of pills at home."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a medical affairs role on a GABA-based depression drug.", "prompt": "How do you explain what makes it different?", "options": ["It is a stronger serotonin booster", "It works by exciting glutamate signals", "It works through GABA, not serotonin"], "correctIndex": 2, "consequences": ["It does not act directly on serotonin or dopamine.", "Glutamate is the excitatory messenger; this drug targets GABA.", "It acts on GABA-A receptors, part of the main inhibitory system."], "explanation": "Zuranolone acts on GABA-A receptors rather than on serotonin or dopamine. That is its story in one line."}, "proReasoning": "Name the messenger system a drug targets and how that differs from the standard. It shows you understand why the drug exists.", "commonMistake": "Assuming every depression drug works through serotonin.", "mentalModel": "Name the messenger first."}, "invest": {"call": {"kind": "theCall", "situation": "Zuranolone wins approval for postpartum depression but not for major depressive disorder.", "prompt": "How should that shape your view of its market?", "options": ["A narrower group than all depression", "The whole depression market is open", "The approval is worthless without MDD"], "correctIndex": 0, "consequences": ["Postpartum depression is one condition, not all depression.", "The FDA did not approve it for major depressive disorder.", "A first oral option for postpartum depression still has value."], "explanation": "The approved use defines who can be treated. A broad mechanism does not mean a broad label."}, "proReasoning": "Investors read the label, not the mechanism's promise. The approved use defines the market.", "commonMistake": "Sizing a drug's market by the disease family instead of the label.", "mentalModel": "The label sets the market."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup supports new mothers. Zuranolone is a 14-day pill; the older option was a 60-hour hospital infusion.", "prompt": "What gap does the switch to a pill open?", "options": ["Selling the drug directly to mothers", "Support for treatment taken at home", "More hospital beds for long infusions"], "correctIndex": 1, "consequences": ["Startups can support care; prescribing stays with clinicians.", "A home course needs follow-up and support outside the hospital.", "The new pill moves treatment out of the hospital."], "explanation": "When treatment leaves the hospital, so does the support that came with it. That is the gap to fill."}, "proReasoning": "When treatment moves from hospital to home, founders look at what the hospital used to provide. Support and follow-up are the new gap.", "commonMistake": "Building for the old setting after the treatment has moved.", "mentalModel": "Follow where treatment moves."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thought all depression drugs raise serotonin. You mention zuranolone.", "prompt": "What's the simplest explanation?", "options": ["It is simply a faster serotonin drug", "It shuts dopamine down completely", "It boosts the brain's main brake, GABA"], "correctIndex": 2, "consequences": ["It does not act directly on serotonin.", "It does not act directly on dopamine either.", "GABA is the most common inhibitory messenger."], "explanation": "Zuranolone works on GABA-A receptors. Mood drugs can work through the stop signal, not only serotonin."}, "proReasoning": "Explain messengers as go and stop signals. Some depression drugs adjust the stop signal instead of serotonin.", "commonMistake": "Thinking serotonin is the only lever on mood.", "mentalModel": "Brakes and accelerators."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8822cb172e60$ml$]::text[]),
($ml$31f8c7f9-bea6-5d3a-b4b9-e07f97b7604b$ml$::uuid, $ml$neuroscience$ml$, 7, 2, $ml${"id": "neuroscience-d7-c2", "title": "To change a messenger, get in first", "lessonTitle": "The chemicals neurons use to talk", "slot": 2, "type": "connect", "brief": {"headline": "Brain drugs work by changing messenger systems such as glutamate, GABA, dopamine and serotonin. But more than 98% of small-molecule drugs cannot reach brain tissue.", "kicker": "Connect day 3 and day 7: the target sits behind the gate.", "fullText": "On day 7 you met the brain's chemical messengers: at least 100 of them, with glutamate the main excitatory signal, GABA the main inhibitory one, and dopamine and serotonin shaping reward, mood, sleep and appetite. Brain drugs work by changing these systems.\n\nOn day 3 you met the gate in front of them. Pardridge wrote that more than 98% of small-molecule drugs and essentially all large-molecule drugs do not cross the blood-brain barrier. Picking the right messenger is half the job. The drug also has to reach the neurons that use it.", "sources": [{"url": "https://my.clevelandclinic.org/health/articles/22513-neurotransmitters", "label": "Cleveland Clinic, Neurotransmitters"}, {"url": "https://springeropen.altmetric.com/details/3182022", "label": "Pardridge 2005, The blood-brain barrier: bottleneck in brain drug development"}]}, "evidence": {"kind": "buildChain", "prompt": "Put a messenger drug's journey in order.", "steps": ["Pick a messenger system to change", "Design a molecule that acts on it", "Get the molecule across the barrier", "It reaches the neurons it targets", "The messenger balance shifts"], "explanation": "The target comes first, but the barrier sits between the molecule and the neurons. Skip that step and nothing shifts."}, "numbers": {"kind": "numberSense", "prompt": "Scientists know of at least how many chemical messengers in the nervous system?", "min": 0, "max": 300, "value": 100, "unit": "messengers", "explanation": "At least 100. Plenty of targets, all behind the same barrier."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a company with a new GABA drug. They ask what you'd check first.", "prompt": "Which question shows depth?", "options": ["How does it get across the barrier?", "Is GABA really an inhibitory messenger?", "How many messengers exist in total?"], "correctIndex": 0, "consequences": ["Most drugs are blocked, so entry comes before effect.", "GABA is the most common inhibitory messenger; that is settled.", "At least 100, but the count does not test the drug."], "explanation": "The target is known. Whether the drug reaches it is the open question."}, "proReasoning": "Pair the target with the route. A good messenger target fails if the drug never reaches the brain.", "commonMistake": "Judging a brain drug by its target alone.", "mentalModel": "Target and route."}, "invest": {"call": {"kind": "theCall", "situation": "Two companies target the same messenger system. Only one has data showing its drug reaches the brain.", "prompt": "How should that weigh in your decision?", "options": ["Only if the drug is a large molecule", "Heavily, since it clears the first gate", "Not at all, since the target is what counts"], "correctIndex": 1, "consequences": ["Small molecules are blocked too, more than 98% of them.", "With over 98% of small molecules blocked, proof of entry is rare.", "A target the drug never reaches is useless."], "explanation": "Proof of entry separates a real candidate from a hopeful one, whatever the molecule size."}, "proReasoning": "Investors treat brain entry as a gate the target cannot skip. Evidence of entry separates real candidates from hopeful ones.", "commonMistake": "Assuming small molecules get in easily.", "mentalModel": "No entry, no effect."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your team has a molecule that calms overactive neurons in a dish by boosting GABA.", "prompt": "What's the next question to answer?", "options": ["Which messenger should we target?", "Can we market it as a supplement?", "Does it reach brain tissue in animals?"], "correctIndex": 2, "consequences": ["You already picked GABA; now prove it gets there.", "That skips the evidence a brain drug needs.", "A dish has no barrier, so test entry next."], "explanation": "A dish result says the target works. Only an animal test says the drug gets there."}, "proReasoning": "Founders test the hardest gate early. For a messenger drug, brain entry comes right after the dish.", "commonMistake": "Moving to marketing before proving the drug reaches the brain.", "mentalModel": "Test the gate early."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why you can't just swallow a calming messenger and send it to the brain.", "prompt": "What's a fair answer?", "options": ["Most molecules in blood can't reach the brain", "Calming messengers excite neurons instead", "The brain makes no messengers of its own"], "correctIndex": 0, "consequences": ["The blood-brain barrier keeps most molecules out of brain tissue.", "Inhibitory messengers like GABA tell neurons to stop.", "The brain makes its own, including glutamate and GABA."], "explanation": "The barrier blocks more than 98% of small-molecule drugs. Reaching the blood is not reaching the brain."}, "proReasoning": "Explain the barrier with an everyday example: what you swallow reaches your blood, but the brain is guarded.", "commonMistake": "Assuming anything in the blood reaches the brain.", "mentalModel": "Blood is not brain."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4843a3ae913e$ml$]::text[]),
($ml$b672d033-4a8d-5d1a-be7f-44978049eb47$ml$::uuid, $ml$neuroscience$ml$, 7, 3, $ml${"id": "neuroscience-d7-c3", "title": "Brake or accelerator", "lessonTitle": "The chemicals neurons use to talk", "slot": 3, "type": "decide", "brief": {"headline": "You run a small team designing a drug for seizures. Glutamate is the brain's main go signal, and GABA is its main stop signal, which helps regulate seizures.", "kicker": "Decide which messenger your seizure drug should push.", "fullText": "You run a drug discovery team with funding for one seizure program. Day 7 gives you the map of messengers. Glutamate is the most common excitatory neurotransmitter, passing signals on, and is key to learning and memory. GABA is the most common inhibitory one, blocking signals, and helps regulate anxiety, sleep and seizures.\n\nEvery signal is a balance of excitation and inhibition. Your choice is which side of that balance to push, and what else that push might touch.", "sources": [{"url": "https://my.clevelandclinic.org/health/articles/22513-neurotransmitters", "label": "Cleveland Clinic, Neurotransmitters"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Your drug must calm overactive signaling. Which change pushes the balance the right way?", "options": ["More excitation through glutamate", "More reward through dopamine", "More inhibition through GABA"], "correctIndex": 2, "explanation": "GABA blocks signals from passing on and helps regulate seizures. Adding excitation would push the wrong way."}, "numbers": {"kind": "numberSense", "prompt": "Your team screens 400 molecules. If over 98% cannot cross the barrier, fewer than how many might get in?", "min": 0, "max": 40, "value": 8, "unit": "molecules", "explanation": "Under 2% of 400 is under 8. A perfect GABA target still needs molecules that reach it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a new scientist on the team. Your lead asks which effects to watch for with a GABA booster.", "prompt": "Which worry follows most logically?", "options": ["Higher motivation from more dopamine release", "Sleepiness, since GABA helps regulate sleep", "Sharper memory from extra glutamate signals"], "correctIndex": 1, "consequences": ["Dopamine is a different messenger system.", "GABA helps regulate anxiety, sleep and seizures, so expect overlap.", "A GABA drug pushes inhibition, not glutamate."], "explanation": "A messenger system runs several jobs. Pushing it for seizures can touch sleep and anxiety too."}, "proReasoning": "A messenger touches many jobs. Scientists predict side effects from the other jobs the same system runs.", "commonMistake": "Expecting a drug to change only the job you want.", "mentalModel": "One messenger, many jobs."}, "invest": {"call": {"kind": "theCall", "situation": "The team pitches a GABA-boosting seizure drug to your fund.", "prompt": "What should you ask about competition?", "options": ["Whether glutamate exists in mice", "How many neurons a brain holds", "Who else already targets GABA?"], "correctIndex": 2, "consequences": ["That has nothing to do with competition.", "True numbers, wrong question.", "Many brain drugs act on the same systems, so rivals may be close."], "explanation": "The target sets the competition. Drugs acting on the same messenger compete for the same patients."}, "proReasoning": "The target sets the competition. Investors check who else acts on the same messenger system before backing a new entry.", "commonMistake": "Assuming a target is open because the science is solid.", "mentalModel": "Same target, same rivals."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. A board member suggests blocking glutamate instead, to cut excitation directly.", "prompt": "What's the key risk to weigh?", "options": ["Glutamate also drives learning and memory", "Glutamate plays no part in excitation", "GABA and glutamate are the same thing"], "correctIndex": 0, "consequences": ["Turning down the go signal can touch memory too.", "It is the most common excitatory messenger.", "They are opposites: go and stop."], "explanation": "Glutamate is key to learning and memory. Cutting it to calm seizures has a cost to weigh."}, "proReasoning": "Founders weigh what else a target touches. Glutamate is key to learning and memory, so cutting it has a cost.", "commonMistake": "Picking a target by its main job and ignoring its others.", "mentalModel": "Know what else it touches."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a seizure drug can work by adding a stop signal.", "prompt": "What's the clearest answer?", "options": ["It raises dopamine to calm the brain", "It tips the balance toward inhibition", "It deletes the go signal entirely"], "correctIndex": 1, "consequences": ["Dopamine shapes reward and motivation, not braking.", "GABA tells neurons to stop passing signals on.", "The brain needs glutamate for learning and memory."], "explanation": "Every signal is a balance of go and stop. More stop can calm too much go."}, "proReasoning": "Explain brain chemistry as balance. Too much go, add stop; too much stop, add go.", "commonMistake": "Thinking of messengers as simply on or off.", "mentalModel": "Every signal is a balance."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d7643402e90d$ml$]::text[]),
($ml$dd93b8ef-42e6-54f4-b1f1-5b10fca11cad$ml$::uuid, $ml$neuroscience$ml$, 8, 1, $ml${"id": "neuroscience-d8-c1", "title": "AbbVie's $8.7 billion miss", "lessonTitle": "A $14 billion bet on a new target", "slot": 1, "type": "apply", "brief": {"headline": "AbbVie paid $8.7 billion for Cerevel, betting on a new kind of schizophrenia drug. In November 2024, that drug, emraclidine, failed two Phase 2 trials, and AbbVie's shares fell 12%.", "kicker": "Apply the lesson: a new mechanism can be worth billions, or nothing.", "fullText": "Emraclidine targets the M4 muscarinic receptor alone. It was the centerpiece of AbbVie's $8.7 billion Cerevel deal, completed in August 2024. On November 11, 2024, AbbVie reported that neither EMPOWER-1 nor EMPOWER-2, Phase 2 trials with 372 patients in all, beat placebo on the PANSS symptom scale at week six. Analysts at Stifel pointed to a very high placebo response.\n\nAbbVie's shares fell 12% at the open, and Bristol Myers Squibb's rose more than 11%. BMS's Cobenfy, from its $14 billion Karuna deal, acts on both M1 and M4 receptors and had just been approved. Same new family of targets, opposite outcomes.", "sources": [{"url": "https://www.biospace.com/drug-development/abbvie-shares-plummet-12-as-cerevel-schizophrenia-asset-fails-phase-ii-trials", "label": "BioSpace, AbbVie shares plummet 12% as Cerevel schizophrenia asset fails Phase II, Nov 2024"}, {"url": "https://www.clinicaltrialsarena.com/news/abbvie-stock-plummets-over-12-after-schizophrenia-drug-flops-in-phase-ii-trials/", "label": "Clinical Trials Arena, AbbVie stock plummets after schizophrenia drug flops, Nov 2024"}, {"url": "https://www.fiercepharma.com/pharma/bristol-myers-squibbs-karuna-buyout-pays-approval-novel-schizophrenia-med-cobenfy", "label": "Fierce Pharma, BMS's Karuna buyout pays off with FDA approval for Cobenfy, Sep 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which drug does each fact describe?", "buckets": ["Emraclidine", "Cobenfy"], "items": [{"text": "Targets the M4 receptor alone", "bucket": 0}, {"text": "Came with the Cerevel deal", "bucket": 0}, {"text": "Missed its main goal in two trials", "bucket": 0}, {"text": "Acts on M1 and M4 receptors", "bucket": 1}, {"text": "Came with a $14 billion deal", "bucket": 1}, {"text": "Approved by the FDA in 2024", "bucket": 1}], "explanation": "Both bet on muscarinic receptors. One reached approval; the other missed in Phase 2."}, "numbers": {"kind": "numberSense", "prompt": "AbbVie's shares fell from $199.50 to $174.80 at the open. By about what percent?", "min": 0, "max": 40, "value": 12, "unit": "%", "explanation": "A drop of $24.70, about 12%, on one trial readout."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You were about to join AbbVie's neuroscience unit when emraclidine failed in November 2024.", "prompt": "What's the smart question to ask now?", "options": ["What else is in the neuroscience pipeline?", "Will my desk move to a different floor now?", "Will the drug still be approved anyway?"], "correctIndex": 0, "consequences": ["With the flagship gone, the rest of the pipeline carries the unit.", "Desks matter less than what the team now works on.", "It missed its main goal in both trials."], "explanation": "After a flagship failure, your role depends on what the unit still has to work on."}, "proReasoning": "After a flagship failure, ask what the unit works on next. Your role depends on the remaining pipeline.", "commonMistake": "Assuming a big company protects every program.", "mentalModel": "Ask what's left in the pipeline."}, "invest": {"call": {"kind": "theCall", "situation": "On November 11, 2024, AbbVie falls 12% and BMS rises over 11% on the same news.", "prompt": "Why did BMS rise?", "options": ["Emraclidine was licensed to BMS", "A rival to its new drug just stumbled", "BMS bought AbbVie that morning"], "correctIndex": 1, "consequences": ["Emraclidine was AbbVie's, from Cerevel.", "Cobenfy now faced one less close muscarinic rival.", "No such deal happened."], "explanation": "In a new drug class, a rival's failure can strengthen the leader. Analysts called it a clearer win for Bristol."}, "proReasoning": "Investors read a rival's failure as news for the survivor. In a new mechanism class, one stumble can widen the leader's lead.", "commonMistake": "Reading a trial result as news for one company only.", "mentalModel": "A rival's miss is your gain."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has an M4-only drug in early development. Emraclidine just failed with a high placebo response.", "prompt": "What should you change in your trial plan?", "options": ["Drop all muscarinic research at once", "Skip Phase 2 to save time", "Design to control placebo response"], "correctIndex": 2, "consequences": ["Cobenfy, acting on M1 and M4, was approved.", "Skipping steps risks a bigger, costlier failure.", "Stifel pointed to a very high placebo response in the failed trials."], "explanation": "Learn from the rival's trial before repeating it. Placebo response can sink a drug that might work."}, "proReasoning": "Founders learn from a rival's failure before repeating it. Trial design, like placebo control, can decide a result.", "commonMistake": "Abandoning a mechanism class after one rival fails.", "mentalModel": "Learn from the rival's miss."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how two drugs aimed at the same receptor family could end so differently.", "prompt": "What's a fair answer?", "options": ["Different receptors, different trials", "One company simply got luckier", "The FDA simply prefers BMS drugs"], "correctIndex": 0, "consequences": ["Cobenfy acts on M1 and M4; emraclidine on M4 alone.", "Luck plays a part, but the drugs differ too.", "Emraclidine failed its own trials before any FDA review."], "explanation": "Same family, different receptors and different trials. Real differences come before luck."}, "proReasoning": "Explain divergent results by real differences first: which receptors, which trials. Luck is the last resort.", "commonMistake": "Treating a drug family as one drug.", "mentalModel": "Same family, different drugs."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1ffb4d5a69f7$ml$]::text[]),
($ml$a3151dd8-dfb2-53ee-9ce7-8b27df0c84fb$ml$::uuid, $ml$neuroscience$ml$, 8, 2, $ml${"id": "neuroscience-d8-c2", "title": "Beyond dopamine", "lessonTitle": "A $14 billion bet on a new target", "slot": 2, "type": "connect", "brief": {"headline": "Dopamine shapes reward, motivation and learning, and schizophrenia drugs long relied on it. Cobenfy, approved in 2024, works through cholinergic muscarinic receptors instead.", "kicker": "Connect day 7 and day 8: a different messenger, a new class.", "fullText": "On day 7 you saw that scientists know at least 100 chemical messengers, and that dopamine plays a role in reward, motivation and learning. On day 8 you met Cobenfy, approved on September 26, 2024, for schizophrenia. The FDA called it the first antipsychotic to target cholinergic receptors as opposed to dopamine receptors. It acts on muscarinic M1 and M4 receptors.\n\nWith so many messengers, a drug that moves to a different one can open a new class. That is what Bristol Myers Squibb paid about $14 billion for when it bought Karuna.", "sources": [{"url": "https://my.clevelandclinic.org/health/articles/22513-neurotransmitters", "label": "Cleveland Clinic, Neurotransmitters"}, {"url": "https://www.fiercepharma.com/pharma/bristol-myers-squibbs-karuna-buyout-pays-approval-novel-schizophrenia-med-cobenfy", "label": "Fierce Pharma, BMS's Karuna buyout pays off with FDA approval for Cobenfy, Sep 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What made Cobenfy a first among antipsychotics?", "options": ["It targets cholinergic, not dopamine, receptors", "It was the very first pill for schizophrenia", "It sharply raises dopamine levels in the brain"], "correctIndex": 0, "explanation": "The FDA called it the first antipsychotic targeting cholinergic receptors as opposed to dopamine receptors."}, "numbers": {"kind": "numberSense", "prompt": "BMS paid about $14 billion. At about $22,500 a year, how many thousand patient-years at list price would match that?", "min": 0, "max": 1000, "value": 622, "unit": "K", "explanation": "$14 billion divided by $22,500 is about 622,000 patient-years, before any costs."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview at BMS, you're asked why Cobenfy matters scientifically.", "prompt": "What's the best answer?", "options": ["It works through serotonin alone", "It skips dopamine to treat psychosis", "It is a cheaper dopamine blocker"], "correctIndex": 1, "consequences": ["Its targets are cholinergic muscarinic receptors.", "It acts on muscarinic M1 and M4 receptors.", "It does not target dopamine receptors."], "explanation": "Its novelty is the messenger: muscarinic receptors instead of dopamine."}, "proReasoning": "Name the messenger shift: from dopamine to muscarinic receptors. That is why the drug was a first.", "commonMistake": "Describing a new class in terms of the old one.", "mentalModel": "Name the new messenger."}, "invest": {"call": {"kind": "theCall", "situation": "After Cobenfy, a biotech pitches you another schizophrenia drug that targets dopamine.", "prompt": "What should you probe?", "options": ["Whether dopamine exists in humans", "Whether BMS will pay $14 billion for it", "How it beats existing dopamine drugs"], "correctIndex": 2, "consequences": ["Dopamine shapes reward and motivation; that is settled.", "The Karuna price came from a new mechanism.", "Schizophrenia drugs long relied on dopamine, so the field is crowded."], "explanation": "A new messenger earned the premium. Another dopamine drug must prove an edge over many."}, "proReasoning": "Investors ask how a drug differs from what exists. A new messenger earned $14 billion; another dopamine drug must prove an edge.", "commonMistake": "Expecting any schizophrenia drug to fetch a Karuna price.", "mentalModel": "Novelty earns the premium."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are picking a target for a new psychiatric drug. Your advisor says to look beyond dopamine and serotonin.", "prompt": "What makes that advice sound?", "options": ["There are at least 100 messengers", "Dopamine and serotonin do nothing", "Muscarinic targets are now banned"], "correctIndex": 0, "consequences": ["With so many, less-used systems may hold new classes, as Cobenfy did.", "They shape reward and mood; they are just crowded.", "Cobenfy, a muscarinic drug, was approved in 2024."], "explanation": "Cobenfy showed that moving to a different messenger can open a new class."}, "proReasoning": "Founders look where few drugs act. Cobenfy showed a messenger system outside dopamine can open a new class.", "commonMistake": "Assuming the well-known systems are the only ones that matter.", "mentalModel": "Look past the crowded targets."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says all antipsychotics work the same way.", "prompt": "What's a good reply?", "options": ["Yes, they all raise dopamine in the brain", "Cobenfy acts on muscarinic receptors", "Yes, they all block serotonin the same way"], "correctIndex": 1, "consequences": ["Older antipsychotics relied on dopamine; Cobenfy does not.", "It was the first to target cholinergic, not dopamine, receptors.", "Older ones relied on dopamine; Cobenfy differs."], "explanation": "Cobenfy works through a different messenger system, so antipsychotics are not all alike."}, "proReasoning": "Use one counterexample to break a generalization. Cobenfy shows antipsychotics can work through another messenger.", "commonMistake": "Assuming a drug class is defined by one mechanism forever.", "mentalModel": "One counterexample breaks the rule."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7f8edb89ef35$ml$]::text[]),
($ml$fe694b93-0d0a-52a1-b343-5d95c6015cdd$ml$::uuid, $ml$neuroscience$ml$, 8, 3, $ml${"id": "neuroscience-d8-c3", "title": "What a new mechanism is worth", "lessonTitle": "A $14 billion bet on a new target", "slot": 3, "type": "decide", "brief": {"headline": "You run business development at a drugmaker. A biotech offers a late-stage psychiatric drug with a new mechanism, at a big price. BMS paid about $14 billion for Karuna.", "kicker": "Decide what to pay for, and what to check first.", "fullText": "You run business development at a mid-size drugmaker. A biotech offers a psychiatric drug with a new mechanism, in late-stage trials, and asks for a big price.\n\nDay 8 gives you the reference. Bristol Myers Squibb paid about $14 billion for Karuna Therapeutics. Its drug, Cobenfy, was approved on September 26, 2024, as the first antipsychotic to target cholinergic rather than dopamine receptors, at a list price of $1,850 a month, about $22,500 a year, in line with other branded antipsychotics. A new mechanism can be worth billions, but the buyer pays before the final answer.", "sources": [{"url": "https://www.fiercepharma.com/pharma/bristol-myers-squibbs-karuna-buyout-pays-approval-novel-schizophrenia-med-cobenfy", "label": "Fierce Pharma, BMS's Karuna buyout pays off with FDA approval for Cobenfy, Sep 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Which asset fits the logic behind the Karuna deal?", "left": {"name": "A new mechanism in Phase 3", "note": "First of its kind, if approved"}, "right": {"name": "One more dopamine drug", "note": "Joins a long-crowded class"}, "correctIndex": 0, "explanation": "Big drugmakers pay to own new ways of treating disease. BMS paid about $14 billion for one."}, "numbers": {"kind": "numberSense", "prompt": "At about $22,500 a year, how many thousand patient-years of sales make $1 billion?", "min": 0, "max": 100, "value": 44, "unit": "K", "explanation": "$1 billion divided by $22,500 is about 44,000 patient-years at list price."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks you to explain, in one line, why BMS paid $14 billion for Karuna.", "prompt": "What do you say?", "options": ["It bought a cheaper copy of old drugs", "It bought Karuna for its buildings", "It bought a new way to treat schizophrenia"], "correctIndex": 2, "consequences": ["Cobenfy was new, priced like other branded antipsychotics.", "The value was the drug and its mechanism.", "Cobenfy was the first antipsychotic to target cholinergic receptors."], "explanation": "BMS paid for a new mechanism. That is the one-line answer."}, "proReasoning": "Explain big deals by what is new. Big drugmakers buy biotechs to own new ways of treating disease.", "commonMistake": "Explaining a deal by its size rather than by what was bought.", "mentalModel": "Deals buy novelty."}, "invest": {"call": {"kind": "theCall", "situation": "You're judging whether the biotech's asking price is fair.", "prompt": "What should anchor your valuation?", "options": ["Approval odds times the market if new", "Karuna's $14 billion, with no changes", "What the biotech has spent so far"], "correctIndex": 0, "consequences": ["Novelty sets the prize; trial odds set what you should pay.", "Karuna's drug had its own data and timing.", "Past spending says nothing about future value."], "explanation": "A reference deal is a starting point. Scale it by this drug's odds and market."}, "proReasoning": "Investors scale a reference deal by the odds and the market. A new mechanism raises the prize, not the certainty.", "commonMistake": "Copying a famous price without adjusting for risk.", "mentalModel": "Prize times odds."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the biotech's founder. A buyer offers less than Karuna got.", "prompt": "What strengthens your position most?", "options": ["Saying your drug is like the old ones", "Evidence your mechanism is truly new", "Pointing to how much BMS paid"], "correctIndex": 1, "consequences": ["Sameness lowers the price.", "New mechanisms drive the big deals, so prove novelty.", "Their price reflected their drug, not yours."], "explanation": "Buyers pay premiums for mechanisms they cannot get elsewhere. Prove yours is one."}, "proReasoning": "Founders sell what is new about their drug. Buyers pay premiums for mechanisms they cannot get elsewhere.", "commonMistake": "Arguing from another company's price instead of your own data.", "mentalModel": "Prove the novelty."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend can't see why a company would pay billions for a drug not yet approved.", "prompt": "What's the best explanation?", "options": ["Approval was already guaranteed", "The drug was already selling well", "A new mechanism could open a new market"], "correctIndex": 2, "consequences": ["No approval is guaranteed before the FDA decides.", "Before approval, it had no sales.", "BMS paid about $14 billion; Cobenfy was approved later."], "explanation": "Drugmakers buy future markets. The bet paid off for BMS when Cobenfy was approved."}, "proReasoning": "Big pharma buys future markets. A new mechanism can be worth billions even before approval, if the bet pays off.", "commonMistake": "Thinking deals only buy drugs already on sale.", "mentalModel": "Buy the future, accept the risk."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:826ffe77c68c$ml$]::text[]),
($ml$cc46dbd9-e151-57ac-b228-6d2534a78596$ml$::uuid, $ml$neuroscience$ml$, 9, 1, $ml${"id": "neuroscience-d9-c1", "title": "The Adderall ceiling moves", "lessonTitle": "Who decides how much ADHD drug is made", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, the DEA raised the 2025 quota for d-amphetamine, Adderall's main active ingredient, by about 25%. It said the old quota met medical demand, as the shortage entered its third year.", "kicker": "Apply the ceiling: who decided how much of Adderall's ingredient was made?", "fullText": "On October 2, 2025, the DEA published a final order raising two 2025 aggregate production quotas. d-amphetamine went from 21.2 million grams to 26.45 million grams, and methylphenidate from 53.28 million to 58.28 million grams. Each followed a manufacturer's request in August 2025 citing a shortage of an active ingredient, and the DEA checked the FDA's shortage list.\n\nThe DEA said the old quotas were adequate for medical demand, and that the increases were mainly for product development, such as FDA approval of new manufacturing processes and products. Filter noted the d-amphetamine cap had not changed since 2021, and that at least five makers of amphetamine salts reported shortages.\n\nAs on day 9, the market did not set the supply. A regulator did.", "sources": [{"url": "https://public-inspection.federalregister.gov/2025-19335.pdf", "label": "Federal Register, DEA adjusts 2025 quotas for d-amphetamine and methylphenidate, Oct 2025"}, {"url": "https://filtermag.org/dea-adderall-production-quotas-adhd-medication-shortage/", "label": "Filter, DEA raises Adderall production quotas, Oct 2025"}, {"url": "https://www.govinfo.gov/content/pkg/FR-2025-09-19/html/2025-18110.htm", "label": "Federal Register, DEA adjusts 2025 aggregate production quotas for lisdexamfetamine and d-amphetamine, Sep 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the quota change in order.", "steps": ["A manufacturer reports an ingredient shortage", "It asks the DEA to raise the quota", "The DEA checks the FDA's shortage list", "The DEA publishes a higher quota", "Makers may produce more, up to the new ceiling"], "explanation": "Makers could not simply produce more. They had to ask, and the DEA decided."}, "numbers": {"kind": "numberSense", "prompt": "The d-amphetamine quota rose from 21.2 to 26.45 million grams. By about what percent?", "min": 0, "max": 60, "value": 25, "unit": "%", "explanation": "An increase of 5.25 million grams, about 25%, after four years without a change."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a generic drugmaker's supply team. Amphetamine salts are on the shortage list.", "prompt": "What decides how much can be made next year?", "options": ["How fast your plant can run", "The DEA's production quota", "How many orders pharmacies send"], "correctIndex": 1, "consequences": ["Plant speed matters only up to the quota.", "For Schedule II drugs, the DEA quota is the ceiling.", "Demand alone cannot raise a controlled ceiling."], "explanation": "For a Schedule II drug, supply planning starts with the DEA quota, not with orders."}, "proReasoning": "In controlled drugs, supply planning starts with the quota. Knowing how the DEA sets and adjusts it is part of the job.", "commonMistake": "Planning production from demand alone.", "mentalModel": "The quota is the ceiling."}, "invest": {"call": {"kind": "theCall", "situation": "A maker of ADHD stimulants says demand is surging. The DEA says medical demand fits within the quota.", "prompt": "How should you read the growth story?", "options": ["Rising demand guarantees higher sales", "Quotas apply only to brand-new drugs", "Growth is capped by what the DEA allows"], "correctIndex": 2, "consequences": ["A quota can hold supply below demand.", "Quotas cover each Schedule II substance every year.", "Sales cannot outrun the production ceiling."], "explanation": "For a controlled drug, the quota caps volume. Surging demand can mean shortages, not sales."}, "proReasoning": "Investors put the DEA's ceiling into any controlled drug thesis. A shortage can mean lost sales, not pricing power.", "commonMistake": "Assuming high demand turns into high volume.", "mentalModel": "Demand meets a ceiling."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup tracks pharmacy stock of ADHD drugs. The shortage is in its third year.", "prompt": "Which signal should your tool watch most closely?", "options": ["DEA quota changes and shortage lists", "Social media posts about ADHD meds", "Prices of drugs that have no quota"], "correctIndex": 0, "consequences": ["Quota moves and shortage lists change what can be made and sold.", "Posts reflect demand, not the supply ceiling.", "Drugs without a quota face no such ceiling."], "explanation": "Supply of these drugs moves when the DEA moves. Track the ceiling."}, "proReasoning": "Founders track the variable that actually moves supply. For stimulants, that is the DEA quota and the shortage list.", "commonMistake": "Watching demand signals when the bottleneck is a regulator.", "mentalModel": "Watch the ceiling, not the crowd."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why drugmakers didn't just make more Adderall during the shortage.", "prompt": "What's the answer?", "options": ["It is banned outright in the US", "The DEA caps how much can be made", "No company wanted to make it"], "correctIndex": 1, "consequences": ["It is a controlled drug, not a banned one.", "Makers need DEA quota to produce more of a Schedule II drug.", "At least five makers of amphetamine salts reported shortages."], "explanation": "For Schedule II drugs, the DEA sets a yearly ceiling. Makers had to ask to make more."}, "proReasoning": "When a needed drug runs short, ask who sets the supply. For Schedule II drugs, it is the DEA.", "commonMistake": "Assuming companies simply chose not to make more.", "mentalModel": "Ask who sets the supply."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e22225dab088$ml$]::text[]),
($ml$d464cb0f-aca8-526a-81f4-42aeec493aea$ml$::uuid, $ml$neuroscience$ml$, 9, 2, $ml${"id": "neuroscience-d9-c2", "title": "Two regulators, two questions", "lessonTitle": "Who decides how much ADHD drug is made", "slot": 2, "type": "connect", "brief": {"headline": "The FDA decides whether a drug may be sold. For Schedule II drugs, the DEA also decides how much can be made: in 2025 it raised the lisdexamfetamine quota by about 22%.", "kicker": "Connect day 3 and day 9: one gate on safety, one on supply.", "fullText": "On day 3 you met the regulator as a gatekeeper: the FDA decides what can be tested and sold, and it classes implanted brain-computer interfaces as significant risk devices. On day 9 you met a second regulator. Under the Controlled Substances Act, the DEA sets aggregate production quotas for each Schedule I and II substance.\n\nIn September 2025, with lisdexamfetamine products on the FDA's shortage list, the DEA raised the 2025 lisdexamfetamine quota from 32,736,000 grams to 39,907,536 grams. An approved drug can still be scarce if the second regulator caps how much of it can be made.", "sources": [{"url": "https://www.hhs.gov/guidance/sites/default/files/hhs-guidance-documents/FDA/Brain-Computer-Interface-Guidance.pdf", "label": "FDA guidance, Implanted brain-computer interface devices (2021)"}, {"url": "https://www.govinfo.gov/content/pkg/FR-2025-09-19/html/2025-18110.htm", "label": "Federal Register, DEA adjusts 2025 aggregate production quotas for lisdexamfetamine and d-amphetamine, Sep 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which regulator sets how much lisdexamfetamine can be produced each year?", "left": {"name": "The FDA", "note": "Approves drugs and keeps the shortage list"}, "right": {"name": "The DEA", "note": "Sets yearly quotas for Schedule II drugs"}, "correctIndex": 1, "explanation": "The FDA approved the drug and listed the shortage. The DEA set, and then raised, the ceiling on production."}, "numbers": {"kind": "numberSense", "prompt": "By law, the DEA must answer a shortage-related quota request within how many days?", "min": 0, "max": 90, "value": 30, "unit": "days", "explanation": "Within 30 days. Even the second regulator works on a clock when patients go without."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a company with an approved ADHD stimulant. They ask what limits its growth.", "prompt": "Which answer shows you know the field?", "options": ["Only what the FDA label allows", "Only the number of prescribers", "DEA quotas, on top of FDA approval"], "correctIndex": 2, "consequences": ["The label is one gate; the quota is another.", "Prescribers matter, but supply is capped by the DEA.", "Approval lets it be sold; the quota caps how much is made."], "explanation": "A controlled drug passes two regulators: one on safety, one on supply."}, "proReasoning": "Name both gates for a controlled drug: FDA approval and DEA quota. Most candidates only know one.", "commonMistake": "Thinking approval is the last regulatory hurdle.", "mentalModel": "Approval, then quota."}, "invest": {"call": {"kind": "theCall", "situation": "A controlled drug wins FDA approval. Management projects sales doubling next year.", "prompt": "What's the first check?", "options": ["Whether DEA quota allows that much", "Whether the FDA might reverse itself", "Whether anyone wants the drug"], "correctIndex": 0, "consequences": ["Without quota, the drug cannot be made in that volume.", "The approval stands; supply is the open question.", "Demand may be real and still be capped."], "explanation": "For a controlled drug, volume needs quota. Check the ceiling before the forecast."}, "proReasoning": "For controlled drugs, investors check the quota before the forecast. A second regulator can cap volume.", "commonMistake": "Forecasting a controlled drug like any other.", "mentalModel": "Check the quota before the forecast."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your telehealth startup wants to prescribe a Schedule II stimulant at scale.", "prompt": "What must your growth plan assume?", "options": ["The FDA sets the monthly supply", "Supply may be capped by DEA quotas", "Supply grows with your patient count"], "correctIndex": 1, "consequences": ["The DEA sets production quotas, not the FDA.", "The DEA, not the market, sets the ceiling.", "Supply of Schedule II drugs is capped each year."], "explanation": "More patients does not mean more pills. The DEA ceiling holds either way."}, "proReasoning": "Founders in controlled drugs plan around the supply ceiling. More patients does not mean more pills.", "commonMistake": "Assuming supply will follow demand.", "mentalModel": "Plan inside the ceiling."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why an approved medicine can still be hard to find.", "prompt": "What's one big reason?", "options": ["Approvals expire every year", "Pharmacies refuse to stock it", "A second regulator caps production"], "correctIndex": 2, "consequences": ["Approvals do not expire yearly; quotas are set yearly.", "The supply ceiling, not pharmacies, is the main limit.", "For Schedule II drugs, the DEA sets yearly quotas."], "explanation": "One regulator approves the drug; another caps how much of it is made."}, "proReasoning": "Explain shortages of controlled drugs with two regulators: one approves, one caps supply.", "commonMistake": "Assuming approval means unlimited supply.", "mentalModel": "Approved is not unlimited."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9b19a21ad292$ml$]::text[]),
($ml$9589fb1f-f7f6-5127-aac6-5891865d70d4$ml$::uuid, $ml$neuroscience$ml$, 9, 3, $ml${"id": "neuroscience-d9-c3", "title": "Growing into a ceiling", "lessonTitle": "Who decides how much ADHD drug is made", "slot": 3, "type": "decide", "brief": {"headline": "You run an ADHD telehealth startup with demand rising fast. Lisdexamfetamine was on the FDA's shortage list until the DEA raised its 2025 quota by about 22%.", "kicker": "Decide how to grow when a regulator caps the supply.", "fullText": "You run a telehealth startup that connects adults with ADHD to prescribers, and sign-ups are rising. Under the Controlled Substances Act, the DEA sets how much of each Schedule II substance may be produced each year, covering medical, scientific and industrial needs, exports and reserves.\n\nIn August 2025 a manufacturer asked for more lisdexamfetamine, citing an active ingredient shortage, while capsules and chewable tablets were on the FDA's shortage list. In September, the DEA raised the 2025 quota by about 22%, pointing to rising global demand, including approvals of Vyvanse in 29 other countries. The law gives the DEA 30 days to answer such requests.", "sources": [{"url": "https://www.govinfo.gov/content/pkg/FR-2025-09-19/html/2025-18110.htm", "label": "Federal Register, DEA adjusts 2025 aggregate production quotas for lisdexamfetamine and d-amphetamine, Sep 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The DEA sets yearly quotas for Schedule II drugs.", "Makers can produce as much as demand requires.", "The DEA must answer shortage requests within 30 days."], "fakeIndex": 1, "explanation": "For controlled drugs, makers cannot simply produce more. The quota is the ceiling."}, "numbers": {"kind": "numberSense", "prompt": "The quota rose from about 32.7 to 39.9 million grams. How many million grams were added?", "min": 0, "max": 20, "value": 7.2, "unit": "M", "explanation": "About 7.2 million grams, roughly 22% more, decided by the DEA."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're hiring a head of pharmacy partnerships for the startup.", "prompt": "Which experience matters most?", "options": ["Managing supply during drug shortages", "Running social media ad campaigns", "Building consumer fitness apps"], "correctIndex": 0, "consequences": ["Quotas and shortages decide whether patients can fill prescriptions.", "Ads drive sign-ups that supply may not support.", "Useful skills, wrong problem."], "explanation": "Your bottleneck is supply, so hire for it."}, "proReasoning": "In controlled drugs, operations skill around supply is rare and valuable. Hire for the constraint.", "commonMistake": "Hiring for growth when the bottleneck is supply.", "mentalModel": "Hire for the constraint."}, "invest": {"call": {"kind": "theCall", "situation": "The startup asks you to fund a big marketing push.", "prompt": "What's your main concern?", "options": ["The DEA will ban telehealth tomorrow", "Patients may not be able to fill scripts", "Too few adults have ADHD"], "correctIndex": 1, "consequences": ["Nothing in the facts suggests that.", "With quotas capping supply, more sign-ups can mean unfilled scripts.", "Demand is rising; supply is the issue."], "explanation": "Marketing grows demand. The quota limits what patients can actually get."}, "proReasoning": "Investors ask whether growth can be served. When a regulator caps supply, marketing can outrun what patients can get.", "commonMistake": "Funding demand when supply is the bottleneck.", "mentalModel": "Can the growth be served?"}, "build_startup": {"call": {"kind": "theCall", "situation": "Sign-ups keep rising while the shortage continues. Your team proposes a response.", "prompt": "What's the soundest move?", "options": ["Promise every patient a fast refill", "Stop serving patients until supply returns", "Pace growth and help patients find stock"], "correctIndex": 2, "consequences": ["A promise the quota can break hurts patients and trust.", "Patients already in care still need support.", "You grow at the rate supply allows and keep trust."], "explanation": "Grow at the pace the ceiling allows, and help patients through the gaps."}, "proReasoning": "Founders under a supply ceiling grow at the pace the ceiling allows and help patients through the gaps.", "commonMistake": "Making promises a regulator's quota can break.", "mentalModel": "Grow at the pace of supply."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the DEA, an enforcement agency, decides how much medicine is made.", "prompt": "What's the reason?", "options": ["The law tasks it with drug quotas", "The FDA asked it to run pharmacies", "It owns the factories that make them"], "correctIndex": 0, "consequences": ["The Controlled Substances Act has it set yearly production quotas.", "The FDA keeps the shortage list; the DEA sets quotas.", "Manufacturers make the drugs; the DEA sets the cap."], "explanation": "Under the Controlled Substances Act, the DEA sets quotas for each Schedule I and II substance."}, "proReasoning": "Explain the DEA's role through the law: for Schedule I and II substances, it sets how much may be made.", "commonMistake": "Assuming drug supply is set by companies alone.", "mentalModel": "The law puts the DEA in charge."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:393c922d046e$ml$]::text[]),
($ml$ca53949e-2ebc-50f2-b03d-75f4bfa10946$ml$::uuid, $ml$neuroscience$ml$, 10, 1, $ml${"id": "neuroscience-d10-c1", "title": "One in five teens", "lessonTitle": "How many people take antidepressants", "slot": 1, "type": "apply", "brief": {"headline": "A CDC report in April 2025 found 13.1% of Americans 12 and older had depression in 2021 to 2023, up from 8.2% a decade earlier. Among teens 12 to 19, it was 19.2%.", "kicker": "Apply the market lens: who has depression, and who gets care?", "fullText": "The NCHS data brief measured depression with a standard questionnaire covering the past two weeks, from August 2021 to August 2023. Prevalence was 13.1% overall, 16.0% in females and 10.1% in males. It was highest in adolescents, 19.2%, and reached 26.5% among girls 12 to 19. It fell with age, to 8.7% of adults 60 and over.\n\nOnly 39.3% of people with depression had received counseling or therapy from a mental health professional in the past year, and 87.9% reported at least some difficulty with work, home or social activities.\n\nThe day 10 lesson counted who takes antidepressants. This survey counts who has depression, and how many go without therapy.", "sources": [{"url": "https://www.cdc.gov/nchs/products/databriefs/db527.htm", "label": "CDC NCHS, Depression prevalence in adolescents and adults, Apr 2025"}, {"url": "https://www.cdc.gov/nchs/products/databriefs/db377.htm", "label": "CDC NCHS, Antidepressant use among adults: United States, 2015-2018"}]}, "evidence": {"kind": "sortSignal", "prompt": "Was each group above or below the 13.1% overall rate?", "buckets": ["Above 13.1%", "Below 13.1%"], "items": [{"text": "Teens 12 to 19", "bucket": 0}, {"text": "Girls 12 to 19", "bucket": 0}, {"text": "Females of all ages", "bucket": 0}, {"text": "Males of all ages", "bucket": 1}, {"text": "Adults 60 and over", "bucket": 1}], "explanation": "Teens, girls and females overall ran above the average. Males and older adults ran below it."}, "numbers": {"kind": "numberSense", "prompt": "What share of people with depression had counseling or therapy in the past year?", "min": 0, "max": 100, "value": 39, "unit": "%", "explanation": "About 39%. More than 60% went without professional therapy in the past year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a youth mental health company. They ask what the latest data shows.", "prompt": "Which fact lands best?", "options": ["Depression mostly affects people over 60", "Rates have barely changed in a decade", "19.2% of teens 12 to 19 had depression"], "correctIndex": 2, "consequences": ["Adults 60 and over had the lowest rate, 8.7%.", "Overall it rose from 8.2% to 13.1%.", "It is the highest rate of any age group."], "explanation": "The teen rate is the number that matches a youth company's mission."}, "proReasoning": "Bring the one number that matches the company's mission. For a youth company, it is the 19.2% teen rate.", "commonMistake": "Quoting a general statistic that misses the company's users.", "mentalModel": "Match the number to the mission."}, "invest": {"call": {"kind": "theCall", "situation": "A therapy platform cites the report: only 39.3% of people with depression got therapy last year.", "prompt": "How do you read that number?", "options": ["A large group with unmet need", "Proof that therapy does not work", "A sign the market is saturated"], "correctIndex": 0, "consequences": ["Over 60% went without professional therapy in the past year.", "The figure measures access, not effectiveness.", "Most people with depression were not in therapy."], "explanation": "Low treatment rates point to unmet need. Whether that need pays is the next question."}, "proReasoning": "Investors separate unmet need from willingness to pay. A big untreated group is a start, not a business by itself.", "commonMistake": "Reading low treatment rates as low demand.", "mentalModel": "Unmet need is not yet revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is choosing a first audience for a depression support tool.", "prompt": "Which fact best points to a group in need?", "options": ["Overall rates rose from 8.2% to 13.1%", "26.5% of girls 12 to 19 had depression", "Adults 60 and over had the lowest rate"], "correctIndex": 1, "consequences": ["True, but it does not pick an audience.", "It is the highest rate in the report.", "A lower rate means a smaller group to serve."], "explanation": "Teen girls had the highest rate in the report, 26.5%."}, "proReasoning": "Founders pick a first audience from the sharpest number. Teen girls stand out at 26.5%.", "commonMistake": "Starting with everyone because the overall rate is high.", "mentalModel": "Start where the rate is highest."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether depression is really more common now.", "prompt": "What does the CDC data say?", "options": ["It has stayed about flat since 2013", "It fell, especially among young people", "It rose from 8.2% to 13.1% in a decade"], "correctIndex": 2, "consequences": ["It rose by more than half.", "Teens had the highest rate, 19.2%.", "The rise was similar for females and males."], "explanation": "From 2013 to 2014 to 2021 to 2023, prevalence rose from 8.2% to 13.1%."}, "proReasoning": "Answer with the trend and its starting point: 8.2% in 2013 to 2014, 13.1% in 2021 to 2023.", "commonMistake": "Answering from impressions instead of data.", "mentalModel": "Trend plus baseline."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f03863bde614$ml$]::text[]),
($ml$aa636141-9a70-5711-ac78-bb17f27ff75e$ml$::uuid, $ml$neuroscience$ml$, 10, 2, $ml${"id": "neuroscience-d10-c2", "title": "Price times patients", "lessonTitle": "How many people take antidepressants", "slot": 2, "type": "connect", "brief": {"headline": "Leqembi launched at $26,500 a year, but price is only half of sales. Antidepressants show the other half: 13.2% of US adults had used one in the past 30 days in 2015 to 2018.", "kicker": "Connect day 2 and day 10: drug sales are price times patients.", "fullText": "On day 2 you met drug sales as one of the three streams of brain money, and Leqembi's $26,500 yearly price. The lesson's point for investors: revenue depends on how many patients get a drug and who pays.\n\nOn day 10 you saw the patient side at scale. A CDC survey found 13.2% of US adults used an antidepressant in the past 30 days during 2015 to 2018, and use rose from 10.6% in 2009 to 2010 to 13.8% in 2017 to 2018. A high price for a few patients and a modest price for many can both build a large stream.", "sources": [{"url": "https://biopharma-reporter.com/Article/2023/01/10/Next-steps-for-lecanemab-Eisai-reveals-pricing-US-and-global-rollout-plans", "label": "BioPharma Reporter, Eisai reveals Leqembi pricing"}, {"url": "https://www.cdc.gov/nchs/products/databriefs/db377.htm", "label": "CDC NCHS, Antidepressant use among adults: United States, 2015-2018"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What two things set a drug's sales?", "options": ["The number of messengers it targets", "Price and the number of patients treated", "Price alone, whatever the volume"], "correctIndex": 1, "explanation": "Revenue is price times patients treated, shaped by who pays."}, "numbers": {"kind": "numberSense", "prompt": "Antidepressant use rose from 10.6% to 13.8% of US adults. By how many percentage points?", "min": 0, "max": 10, "value": 3.2, "unit": "points", "explanation": "3.2 points, a rise of about 30% in the share of adults using them."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're weighing jobs on a high-priced Alzheimer's drug and a common antidepressant.", "prompt": "How do their sales engines differ?", "options": ["Few patients at a high price, or many", "They earn in exactly the same way", "Only the costly drug earns revenue"], "correctIndex": 0, "consequences": ["Both multiply price by patients, from opposite ends.", "Their mix of price and volume is very different.", "Common drugs earn through volume."], "explanation": "Every drug earns price times patients. The mix shapes what the commercial team worries about."}, "proReasoning": "Know how your product earns: price, volume or both. It shapes what the commercial team worries about.", "commonMistake": "Judging a drug's business by its price tag.", "mentalModel": "Price times patients."}, "invest": {"call": {"kind": "theCall", "situation": "A company touts its drug's high price. You want to estimate sales.", "prompt": "What else must you know?", "options": ["How many years it took to develop", "How many patients get it, and who pays", "Only how its price compares to rivals"], "correctIndex": 1, "consequences": ["Development time does not set sales.", "Revenue is price times patients treated.", "Price alone tells you nothing about volume."], "explanation": "Price is half the story. Patients treated and who pays decide the revenue."}, "proReasoning": "Investors never stop at price. Patients treated and who pays decide the revenue.", "commonMistake": "Letting a headline price stand in for sales.", "mentalModel": "Price is half the story."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building a service for people on antidepressants. A cofounder worries the market is small.", "prompt": "Which fact answers that?", "options": ["Leqembi costs $26,500 a year", "There are at least 100 messengers", "13.2% of US adults used one in a month"], "correctIndex": 2, "consequences": ["True, but it is about a different drug.", "True, but not about market size.", "That is more than one in eight adults."], "explanation": "More than one in eight adults is a very large base of users."}, "proReasoning": "Founders size a market by users. More than one in eight adults is a very large base.", "commonMistake": "Sizing a market by price instead of people.", "mentalModel": "Count the users."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a cheap, common drug can earn as much as an expensive one.", "prompt": "What's the answer?", "options": ["Sales are price times patients", "Cheap drugs never earn much", "The NIH sets drug prices"], "correctIndex": 0, "consequences": ["Many patients at a low price can match few at a high one.", "Volume can make up for price.", "The NIH funds research; it does not set prices."], "explanation": "Revenue is price times patients. Either side can be big."}, "proReasoning": "Explain drug revenue with one formula: price times patients. Either side can be big.", "commonMistake": "Assuming the most expensive drugs earn the most.", "mentalModel": "Price times patients."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f4f49e0d393c$ml$]::text[]),
($ml$7d371a44-8231-5a28-9468-f62973cc1371$ml$::uuid, $ml$neuroscience$ml$, 10, 3, $ml${"id": "neuroscience-d10-c3", "title": "Planning for steady growth", "lessonTitle": "How many people take antidepressants", "slot": 3, "type": "decide", "brief": {"headline": "You plan production at a generic antidepressant maker. US adult use rose from 10.6% in 2009 to 2010 to 13.8% in 2017 to 2018, and was highest among older adults.", "kicker": "Decide how to plan supply for a growing, uneven market.", "fullText": "You run demand planning at a maker of generic antidepressants. The CDC data you rely on: 13.2% of US adults used an antidepressant in the past 30 days in 2015 to 2018. Use was 17.7% among women and 8.4% among men, and rose with age, from 7.9% of adults 18 to 39 to 19.0% of those 60 and over, reaching 24.3% of women 60 and over.\n\nUse rose from 10.6% in 2009 to 2010 to 13.8% in 2017 to 2018. Your job is to turn that trend and that mix into a supply plan.", "sources": [{"url": "https://www.cdc.gov/nchs/products/databriefs/db377.htm", "label": "CDC NCHS, Antidepressant use among adults: United States, 2015-2018"}]}, "evidence": {"kind": "faceOff", "prompt": "Which group used antidepressants at the higher rate?", "left": {"name": "Adults 18 to 39", "note": "Younger adults"}, "right": {"name": "Adults 60 and over", "note": "Older adults"}, "correctIndex": 1, "explanation": "19.0% of adults 60 and over, against 7.9% of adults 18 to 39. Use rose with age."}, "numbers": {"kind": "numberSense", "prompt": "Use among women 60 and over was 24.3%. About how many times the 7.9% rate for adults 18 to 39 is that?", "min": 0, "max": 8, "value": 3.1, "unit": "times", "explanation": "24.3 divided by 7.9 is about 3. Demand is very uneven across groups."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks for one sentence on why antidepressant demand should keep growing.", "prompt": "Which is best supported?", "options": ["Use is falling among older women", "Use rose about 30% in eight years", "Every adult will soon take one"], "correctIndex": 1, "consequences": ["Women 60 and over had the highest rate, 24.3%.", "10.6% to 13.8% is a rise of about 30%.", "Use was 13.2%, far from everyone."], "explanation": "The trend, with its size, is the strongest support for a forecast."}, "proReasoning": "Support a forecast with the trend and its size. 10.6% to 13.8% is a steady, measurable rise.", "commonMistake": "Forecasting from impressions instead of the trend.", "mentalModel": "Forecast from the trend."}, "invest": {"call": {"kind": "theCall", "situation": "You're looking at a generic antidepressant maker's stock.", "prompt": "What does the CDC trend tell you about its volumes?", "options": ["Demand has collapsed since 2010", "Demand swings at random each year", "Demand has grown steadily"], "correctIndex": 2, "consequences": ["It rose, not fell.", "The surveys show a steady upward trend.", "Use rose from 10.6% to 13.8% over about eight years."], "explanation": "A steady rise in use supports volume, even for low-priced generics."}, "proReasoning": "Investors look for durable demand. A steady rise in use supports volume, even if prices are low.", "commonMistake": "Ignoring volume trends in low-price products.", "mentalModel": "Steady demand, steady volume."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup supplies pharmacies. You must choose where to add antidepressant stock first.", "prompt": "Which areas likely need more stock?", "options": ["Areas with many older adults", "Areas with mostly young men", "Areas with no pharmacies at all"], "correctIndex": 0, "consequences": ["Use rose with age, to 19.0% of adults 60 and over.", "Men and younger adults had lower use.", "No pharmacies, no customers for you."], "explanation": "Group rates turn into geography. Older populations use more."}, "proReasoning": "Founders turn group rates into geography. Where older adults and women cluster, demand runs higher.", "commonMistake": "Spreading stock evenly when use is uneven.", "mentalModel": "Stock where use is highest."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend is surprised that older adults use antidepressants more than younger ones.", "prompt": "What does the data show?", "options": ["Use is the same at every age", "19.0% at 60-plus, 7.9% at 18 to 39", "Younger adults use them twice as much"], "correctIndex": 1, "consequences": ["It ranged from 7.9% to 19.0% by age.", "Use rose with age in the CDC survey.", "The reverse: older adults used them more."], "explanation": "In the CDC survey, use rose steadily with age."}, "proReasoning": "Check surprising claims against group rates. Here, use clearly rose with age.", "commonMistake": "Assuming the group in the news is the biggest user.", "mentalModel": "Check the group rates."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:da840c8a3b99$ml$]::text[]),
($ml$a907296c-e96e-5d58-9195-afebc137e811$ml$::uuid, $ml$neuroscience$ml$, 11, 1, $ml${"id": "neuroscience-d11-c1", "title": "Clozapine loses its REMS", "lessonTitle": "Why some brain drugs need a supervised room", "slot": 1, "type": "apply", "brief": {"headline": "On June 13, 2025, the FDA ended the safety program that required blood results before clozapine could be dispensed. Blood monitoring is still recommended; the program is gone.", "kicker": "Apply the lesson: when a safety rule goes, access changes.", "fullText": "Clozapine, an antipsychotic first approved in 1989, can cause severe neutropenia, a drop in a type of white blood cell that can lead to serious infections. Under its REMS, prescribers, pharmacies and patients had to enroll, and absolute neutrophil count results had to be reported before the drug could be dispensed.\n\nIn November 2024, FDA advisory committees agreed blood monitoring should continue but REMS documentation was no longer needed. In February 2025 the FDA said it no longer expected participation, and on June 13, 2025, it eliminated the REMS. The FDA said the program could impede access and expected removal to improve it. Prescribers should still monitor blood counts as the label says, and the label keeps a boxed warning.", "sources": [{"url": "https://www.fda.gov/drugs/drug-safety-and-availability/fda-removes-risk-evaluation-and-mitigation-strategy-rems-program-antipsychotic-drug-clozapine", "label": "FDA, FDA removes REMS program for the antipsychotic drug clozapine, 2025"}, {"url": "https://www.psychiatrictimes.com/view/fda-officially-eliminates-clozapine-rems", "label": "Psychiatric Times, FDA officially eliminates clozapine REMS, Jun 2025"}, {"url": "https://ncpa.org/newsroom/qam/2025/03/31/clozapine-rems-has-ended", "label": "NCPA, Clozapine REMS has ended, Mar 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Did each item end with the REMS, or stay in place?", "buckets": ["Ended with the REMS", "Still in place"], "items": [{"text": "Enrolling prescribers and pharmacies", "bucket": 0}, {"text": "Reporting blood results before dispensing", "bucket": 0}, {"text": "Blood count monitoring by prescribers", "bucket": 1}, {"text": "A boxed warning on the label", "bucket": 1}, {"text": "The risk of severe neutropenia", "bucket": 1}], "explanation": "The program and its paperwork ended. The risk, the warning and the recommended monitoring stayed."}, "numbers": {"kind": "numberSense", "prompt": "Clozapine was first approved in 1989. About how many years later did the FDA end its REMS?", "min": 0, "max": 60, "value": 36, "unit": "years", "explanation": "From 1989 to 2025 is 36 years. Safety rules can change long after approval."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a hospital pharmacist in mid-2025. Your team asks what changes for clozapine.", "prompt": "What's the accurate summary?", "options": ["No REMS paperwork, but monitoring continues", "No more blood tests are needed at all", "Clozapine has been pulled from the market"], "correctIndex": 0, "consequences": ["The FDA still recommends blood count monitoring.", "Monitoring is still recommended in the label.", "It remains available, now without the REMS."], "explanation": "The REMS ended; the clinical monitoring did not."}, "proReasoning": "When a REMS ends, separate the paperwork from the medicine. Clinical monitoring can stay even when the program goes.", "commonMistake": "Assuming the risk ended with the program.", "mentalModel": "Program gone, risk remains."}, "invest": {"call": {"kind": "theCall", "situation": "Clozapine's REMS ends in 2025. You follow companies that make or support it.", "prompt": "What's the most likely effect?", "options": ["Higher paperwork costs for pharmacies", "Easier access for patients and clinics", "A ban on new prescriptions"], "correctIndex": 1, "consequences": ["Pharmacies no longer need blood results before dispensing.", "The FDA expected removal to improve access.", "Nothing was banned; a requirement was lifted."], "explanation": "The FDA said the REMS could impede access. Removing it should widen use."}, "proReasoning": "Investors read safety rules as a cap on reach. Removing one can widen use, as the FDA expected here.", "commonMistake": "Assuming rule changes only matter to regulators.", "mentalModel": "Rules cap reach."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sold software that helped clinics handle clozapine REMS reporting.", "prompt": "What's your smartest pivot?", "options": ["Keep selling REMS reporting as before", "Lobby to bring the REMS back", "Help clinics run blood monitoring well"], "correctIndex": 2, "consequences": ["There is no REMS left to report to.", "The FDA found the REMS no longer necessary.", "Monitoring is still recommended, so the need moves there."], "explanation": "The paperwork went away; the monitoring work did not. Follow the work."}, "proReasoning": "When a rule your product served disappears, founders follow the work that remains. Here, the monitoring stayed.", "commonMistake": "Betting on a requirement the regulator just removed.", "mentalModel": "Follow the work that remains."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads that the FDA dropped clozapine's safety program and worries the drug is less safe.", "prompt": "What's a fair explanation?", "options": ["The risk is still labeled and monitored", "The drug was found to be risk-free", "The FDA stopped regulating the drug"], "correctIndex": 0, "consequences": ["It keeps a boxed warning, and blood monitoring is still recommended.", "Severe neutropenia is still a known risk.", "The FDA still oversees its label and warnings."], "explanation": "A REMS is one safety tool. Warnings and monitoring remain without it."}, "proReasoning": "Explain that a REMS is one tool among several. Removing it can improve access while warnings and monitoring remain.", "commonMistake": "Equating less paperwork with less safety.", "mentalModel": "Paperwork is not the only safety."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:af367b470692$ml$]::text[]),
($ml$dc34880f-5c9a-5910-8a83-036ba49b781f$ml$::uuid, $ml$neuroscience$ml$, 11, 2, $ml${"id": "neuroscience-d11-c2", "title": "A ceiling and a room", "lessonTitle": "Why some brain drugs need a supervised room", "slot": 2, "type": "connect", "brief": {"headline": "The DEA caps how much of a Schedule II drug can be made. Spravato's REMS decides where it can be given: certified sites, with at least 2 hours of monitoring.", "kicker": "Connect day 9 and day 11: two rules, two different limits.", "fullText": "On day 9 you saw the DEA set aggregate production quotas for each Schedule I and II substance, a ceiling on supply. On day 11 you saw a different kind of limit. Spravato, J&J's esketamine nasal spray, is available only through a REMS: patients take it at certified healthcare settings under supervision and are monitored for at least 2 hours, because of risks including sedation, dissociation, slowed breathing and misuse.\n\nOne rule limits how much can be made. The other limits where and how a drug is used. Yet Spravato's sales grew 40% in the second quarter of 2026, to $584 million.", "sources": [{"url": "https://www.govinfo.gov/content/pkg/FR-2025-09-19/html/2025-18110.htm", "label": "Federal Register, DEA adjusts 2025 aggregate production quotas for lisdexamfetamine and d-amphetamine, Sep 2025"}, {"url": "https://www.jnjmedicalconnect.com/products/spravato/medical-content/how-will-i-take-spravato", "label": "Johnson & Johnson Medical Connect, How will I take Spravato"}, {"url": "https://www.biospace.com/business/j-j-sees-spravato-sales-surge-as-psychedelic-competitors-loom", "label": "BioSpace, J&J sees Spravato sales surge as psychedelic competitors loom, Jul 2026"}]}, "evidence": {"kind": "faceOff", "prompt": "Which kind of rule decides where Spravato can be given?", "left": {"name": "A DEA production quota", "note": "Caps how much of a drug is made"}, "right": {"name": "An FDA REMS", "note": "Sets where and how a drug is used"}, "correctIndex": 1, "explanation": "Spravato's REMS requires certified sites and at least 2 hours of monitoring. A quota limits supply, not setting."}, "numbers": {"kind": "numberSense", "prompt": "Spravato sold $584 million in the second quarter of 2026, up 40%. About how much a year earlier, in millions?", "min": 0, "max": 1000, "value": 417, "unit": "M", "explanation": "$584 million divided by 1.4 is about $417 million. Strong growth, inside tight rules."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview at a psychiatric drug company, you're asked how rules shape its products.", "prompt": "Which answer shows range?", "options": ["Rules apply only to illegal street drugs", "Quotas cap supply; a REMS limits setting", "Only the FDA approval really matters"], "correctIndex": 1, "consequences": ["Approved drugs face quotas and REMS too.", "Two different rules, two different limits on a drug.", "Approval is only the first of several rules."], "explanation": "Quotas, REMS and approval each limit a drug in their own way."}, "proReasoning": "Show you know the different rule types: production quotas, REMS and approval. Each limits a drug in its own way.", "commonMistake": "Treating all drug rules as one.", "mentalModel": "Different rules, different limits."}, "invest": {"call": {"kind": "theCall", "situation": "Spravato's sales grew 40% while it stayed under a REMS.", "prompt": "What does that suggest?", "options": ["REMS programs boost demand", "The REMS was dropped in 2026", "Rules can cap reach, not growth"], "correctIndex": 2, "consequences": ["The REMS limits access; growth came despite it.", "Spravato was still under its REMS.", "Supervised dosing limits where it is given, yet sales grew."], "explanation": "Rules shape a drug's reach. Strong demand can still drive growth inside them."}, "proReasoning": "Investors weigh how a rule shapes reach. Spravato shows a drug can grow inside tight rules, if demand is strong.", "commonMistake": "Assuming a REMS makes a drug commercially weak.", "mentalModel": "Rules shape, not stop."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're planning a clinic network for a supervised brain drug.", "prompt": "Which rule shapes your clinic design most?", "options": ["The REMS rules on site and monitoring", "The DEA production quota for it", "The NIH grant rules for research"], "correctIndex": 0, "consequences": ["Certified sites and 2-hour monitoring set your space and staff.", "The quota limits supply, not your rooms.", "Grants fund research, not clinics."], "explanation": "The REMS decides the room, the staff and the time. Design for it first."}, "proReasoning": "Founders building around a supervised drug design for the REMS first. Monitoring time sets how many patients a site can serve.", "commonMistake": "Designing a clinic without the REMS in mind.", "mentalModel": "Design for the REMS."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why some brain drugs are hard to get, for different reasons.", "prompt": "What's the best explanation?", "options": ["Doctors simply prefer the older drugs", "Some are capped in supply, some in setting", "They are all banned outright in the US"], "correctIndex": 1, "consequences": ["The limits come from rules, not preference.", "The DEA caps supply; a REMS limits where a drug is given.", "They are approved, with limits."], "explanation": "A supply ceiling and a supervised setting create different bottlenecks."}, "proReasoning": "Explain access with the type of rule: a supply ceiling or a supervised setting. Each creates a different bottleneck.", "commonMistake": "Lumping all access problems together.", "mentalModel": "Name the rule, name the bottleneck."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:91a4b79f087f$ml$]::text[]),
($ml$4df6a0b2-93a7-5a9e-8e1d-5f46e87aae9d$ml$::uuid, $ml$neuroscience$ml$, 11, 3, $ml${"id": "neuroscience-d11-c3", "title": "How many chairs?", "lessonTitle": "Why some brain drugs need a supervised room", "slot": 3, "type": "decide", "brief": {"headline": "You run a psychiatry practice weighing whether to offer Spravato. Each dose needs a certified site and at least 2 hours of monitoring, and sales grew 40% in early 2026.", "kicker": "Decide what supervised dosing means for your clinic.", "fullText": "You run an outpatient psychiatry practice. Spravato, J&J's esketamine nasal spray, became in January 2025 the first monotherapy for treatment-resistant depression. It is available only through a REMS: patients take it at certified healthcare settings under a provider's supervision and must be monitored for at least 2 hours, because of risks of sedation, dissociation, slowed breathing, and abuse and misuse.\n\nDemand is growing: second quarter 2026 sales were $584 million, up 40%. Your decision is whether you can offer it, and how the 2-hour rule shapes your rooms and staff.", "sources": [{"url": "https://www.jnjmedicalconnect.com/products/spravato/medical-content/how-will-i-take-spravato", "label": "Johnson & Johnson Medical Connect, How will I take Spravato"}, {"url": "https://www.biospace.com/business/j-j-sees-spravato-sales-surge-as-psychedelic-competitors-loom", "label": "BioSpace, J&J sees Spravato sales surge as psychedelic competitors loom, Jul 2026"}]}, "evidence": {"kind": "buildChain", "prompt": "Put a Spravato visit in order.", "steps": ["The site is certified under the REMS", "The patient arrives for a scheduled dose", "The patient takes the spray under supervision", "Staff monitor the patient for at least 2 hours", "The patient leaves once monitoring ends"], "explanation": "Certification comes first, and the monitoring window is the longest part of every visit."}, "numbers": {"kind": "numberSense", "prompt": "If each monitoring chair holds one patient for at least 2 hours, how many doses can it host in an 8-hour day, at most?", "min": 0, "max": 12, "value": 4, "unit": "doses", "explanation": "Eight hours divided by two is four doses per chair at most. Chairs, not demand, set the ceiling."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The practice hires you as operations lead to launch Spravato.", "prompt": "Which staffing fact matters most?", "options": ["Doses can be mailed to patients at home", "No staff are needed once the dose is taken", "Each patient needs 2 hours of monitoring"], "correctIndex": 2, "consequences": ["It is taken under supervision at certified sites.", "Patients must be monitored for at least 2 hours.", "Monitoring time sets how many staff hours each dose takes."], "explanation": "The monitoring window turns into staff hours for every single dose."}, "proReasoning": "Operations leads turn safety rules into staff hours. A 2-hour monitoring window is a staffing plan.", "commonMistake": "Planning for the dose and forgetting the monitoring.", "mentalModel": "Rules become staff hours."}, "invest": {"call": {"kind": "theCall", "situation": "You're valuing a chain of clinics built around Spravato.", "prompt": "What limits each clinic's revenue most?", "options": ["Chairs and staff for 2-hour monitoring", "The price of a nasal spray bottle", "How many patients see its ads"], "correctIndex": 0, "consequences": ["Each chair handles only a few doses a day.", "Price matters, but capacity sets volume.", "Demand is growing; capacity is the cap."], "explanation": "With supervised dosing, chairs and staff hours set how many doses a clinic can give."}, "proReasoning": "Investors find the capacity limit in a service business. With supervised dosing, chairs and staff hours set the ceiling.", "commonMistake": "Valuing clinics on demand without checking capacity.", "mentalModel": "Capacity caps revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to help clinics offer Spravato.", "prompt": "Which product idea fits the REMS?", "options": ["An app that replaces staff monitoring", "Scheduling that fills monitoring chairs", "A home delivery service for the spray"], "correctIndex": 1, "consequences": ["The REMS requires a provider's supervision.", "Filling every 2-hour slot raises what each clinic can serve.", "It must be taken at certified sites."], "explanation": "Work inside the rule: help clinics use every monitoring slot they have."}, "proReasoning": "Founders build within the rule, not against it. Better scheduling helps clinics serve more patients under the same REMS.", "commonMistake": "Building a product the safety rules forbid.", "mentalModel": "Build inside the rules."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their cousin spends half a day at a clinic for a nasal spray.", "prompt": "What's the reason?", "options": ["The spray takes hours to fully inhale", "Clinics charge patients by the hour", "Patients must be monitored for 2 hours"], "correctIndex": 2, "consequences": ["The dose is quick; the monitoring is long.", "The time comes from safety rules.", "The REMS requires monitoring for sedation and dissociation."], "explanation": "Risks like sedation and dissociation are why patients stay at least 2 hours."}, "proReasoning": "Explain supervised dosing by its risks: sedation, dissociation and slowed breathing are why patients stay.", "commonMistake": "Blaming the clinic for a time the rules require.", "mentalModel": "The rule sets the visit."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:75a29438d0c4$ml$]::text[]),
($ml$a6f04678-22b3-577f-9739-87fc3224600e$ml$::uuid, $ml$neuroscience$ml$, 12, 1, $ml${"id": "neuroscience-d12-c1", "title": "A retracted paper, a surviving theory", "lessonTitle": "When the serotonin story was challenged", "slot": 1, "type": "apply", "brief": {"headline": "In 2024, Nature retracted a landmark 2006 Alzheimer's paper on an amyloid protein, Aβ*56, after signs of image manipulation. Experts said one bad paper does not sink the whole amyloid theory.", "kicker": "Apply the lesson: separate a theory, a paper and a treatment.", "fullText": "The 2006 Nature paper, led by Sylvain Lesné with Karen Ashe among its co-authors, reported that a form of amyloid beta called Aβ*56 caused memory loss in rats. In 2022, Science reported concerns first raised by Vanderbilt neuroscientist Matthew Schrag, finding more than 20 suspect papers by Lesné and over 70 possible instances of image tampering. NBC News noted that more than $1 billion in NIH money had gone to amyloid-related Alzheimer's research.\n\nThe retraction note said figures showed signs of excessive manipulation, including splicing, duplication and use of an eraser tool. Lesné disagreed with the retraction. Ashe had said a retraction does not call the amyloid-beta hypothesis into question, and experts largely argued against discarding the whole theory.\n\nDrugs are judged separately: Leqembi won traditional approval in 2023 on a trial in which it slowed decline by 27%.", "sources": [{"url": "https://experts.umn.edu/en/publications/retraction-note-a-specific-amyloid-%CE%B2-protein-assembly-in-the-brai/", "label": "Nature retraction note via University of Minnesota, Jul 2024"}, {"url": "https://www.nbcnews.com/science/science-news/alzheimers-theory-undermined-accusations-fabricated-research-rcna39843", "label": "NBC News, Alzheimer's theory undermined by accusations of fabricated research, Jul 2022"}, {"url": "https://www.biospace.com/fda-grants-traditional-approval-for-leqembi-lecanemab-irmb-for-the-treatment-of-alzheimer-s-disease", "label": "Eisai and Biogen via BioSpace, Leqembi traditional approval"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did the retraction undermine most directly?", "options": ["The existence of amyloid plaques", "The Aβ*56 findings in that paper", "Every amyloid drug trial result"], "correctIndex": 1, "explanation": "The retraction concerned figures in one paper about Aβ*56. Drug trials stand or fall on their own data."}, "numbers": {"kind": "numberSense", "prompt": "Science's investigation found over how many possible instances of image tampering?", "min": 0, "max": 200, "value": 70, "unit": "instances", "explanation": "Over 70, across more than 20 suspect papers. One lab, many questions; the wider theory still had support."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an Alzheimer's biotech in 2025. They ask what the Lesné retraction means.", "prompt": "Which answer is most careful?", "options": ["It changes nothing at all for the field", "One strand is gone; trials judge the drugs", "The amyloid theory is now fully disproven"], "correctIndex": 1, "consequences": ["It removed a landmark paper and spurred new scrutiny.", "Experts kept the broad theory while rechecking Aβ*56.", "Experts largely argued against discarding the whole theory."], "explanation": "A retraction removes one finding. The broad theory and the drug trials are separate questions."}, "proReasoning": "Separate a paper, a theory and a treatment. A retraction can remove one finding without settling the others.", "commonMistake": "Turning one retraction into a verdict on a whole field.", "mentalModel": "Paper, theory, treatment."}, "invest": {"call": {"kind": "theCall", "situation": "After the retraction, a friend wants to sell every stock tied to amyloid drugs.", "prompt": "What's the better question?", "options": ["Which paper had the most citations?", "Whether rats can get Alzheimer's", "What do the drug trials themselves show?"], "correctIndex": 2, "consequences": ["Citations do not measure whether a drug works.", "The drug trials were in people, which is what counts.", "Leqembi was approved on a trial that slowed decline by 27%."], "explanation": "A drug is judged by its trials, not by one lab paper about a protein form."}, "proReasoning": "Investors back evidence of benefit, not neat stories. A drug's trial data matters more than any single theory paper.", "commonMistake": "Selling on a theory headline without checking the trial data.", "mentalModel": "Back trial data, not stories."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's Alzheimer's drug builds on research about specific amyloid forms.", "prompt": "What should you do after the Lesné news?", "options": ["Retest the findings you rely on", "Hide the link from investors", "Drop all amyloid research at once"], "correctIndex": 0, "consequences": ["Knowing your evidence base protects the program.", "Investors will find it, and trust will suffer.", "The broad theory still has support."], "explanation": "Audit the papers your program stands on, and replicate the ones that matter."}, "proReasoning": "Founders audit the papers their program stands on. Replicating key findings early beats discovering a problem late.", "commonMistake": "Building on a single famous paper without checking it.", "mentalModel": "Audit your foundations."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads that a famous Alzheimer's paper was retracted for doctored images and asks if the drugs are bogus too.", "prompt": "What's a fair answer?", "options": ["The paper itself was about a drug", "Drugs are judged by their own trials", "Yes, all of them must be useless"], "correctIndex": 1, "consequences": ["It was about a protein form, Aβ*56.", "Leqembi slowed decline by 27% in its trial.", "Approved drugs were tested in their own trials."], "explanation": "A lab paper and a drug trial are different kinds of evidence. Each stands on its own."}, "proReasoning": "Explain the chain: lab theory, then drug, then trial. A drug stands on its trial, not on one lab paper.", "commonMistake": "Assuming a broken paper breaks every treatment in its field.", "mentalModel": "Treatments stand on trials."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d95e988f1eb1$ml$]::text[]),
($ml$91501c3d-cc06-5867-a056-ed1153bdeef7$ml$::uuid, $ml$neuroscience$ml$, 12, 2, $ml${"id": "neuroscience-d12-c2", "title": "Millions of users, a broken story", "lessonTitle": "When the serotonin story was challenged", "slot": 2, "type": "connect", "brief": {"headline": "13.2% of US adults used an antidepressant in 2015 to 2018. In 2022, a review found no convincing evidence that low serotonin causes depression, a story 85% to 90% of the public believed.", "kicker": "Connect day 10 and day 12: a big market and a shaky story.", "fullText": "On day 10 you saw how common antidepressants are: 13.2% of US adults had used one in the past 30 days in 2015 to 2018, and use was rising. On day 12 you saw the explanation many of them heard come under fire. Joanna Moncrieff's 2022 umbrella review found no support for the idea that depression is caused by low serotonin, and the authors said 85% to 90% of the public believed it.\n\nThe review did not assess whether antidepressants work, and critics noted drugs can help without fixing a shortage. A huge market can rest on a treatment that helps and a story that does not hold.", "sources": [{"url": "https://www.cdc.gov/nchs/products/databriefs/db377.htm", "label": "CDC NCHS, Antidepressant use among adults: United States, 2015-2018"}, {"url": "https://www.sciencedaily.com/releases/2022/07/220720080145.htm", "label": "ScienceDaily via UCL, No evidence that depression is caused by low serotonin, Jul 2022"}, {"url": "https://www.newswise.com/articles/don-t-throw-away-your-antidepressants-just-yet", "label": "Newswise, Don't throw away your antidepressants just yet, 2022"}]}, "evidence": {"kind": "faceOff", "prompt": "Which question did the 2022 review actually test?", "left": {"name": "The low-serotonin cause", "note": "Is depression caused by low serotonin?"}, "right": {"name": "Antidepressant benefit", "note": "Do the drugs help patients?"}, "correctIndex": 0, "explanation": "The review tested the cause story. It did not assess whether antidepressants work."}, "numbers": {"kind": "numberSense", "prompt": "The authors said at least what share of the public believed the low-serotonin story?", "min": 0, "max": 100, "value": 85, "unit": "%", "explanation": "85% to 90%. A story can be almost universal and still lack support."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in medical communications for an antidepressant. A draft says it fixes a chemical imbalance.", "prompt": "What's the right edit?", "options": ["Keep it, since most people believe it", "Say the drug does not work", "Describe benefits shown in trials instead"], "correctIndex": 2, "consequences": ["Belief is not evidence, even at 85% to 90%.", "The review did not assess whether the drugs work.", "The review found no consistent evidence for low serotonin as the cause."], "explanation": "Explain a drug by evidence of benefit. A disputed cause story does not belong in the copy."}, "proReasoning": "Communicators explain treatments by evidence of benefit, not by a disputed cause. It keeps messages accurate as theories change.", "commonMistake": "Repeating a popular explanation the evidence does not support.", "mentalModel": "Explain the benefit, not the myth."}, "invest": {"call": {"kind": "theCall", "situation": "A company's pitch for a new antidepressant leans on fixing low serotonin.", "prompt": "How should that affect your view?", "options": ["Look for benefit, not the story", "Invest, since the public believes it", "Reject every antidepressant company"], "correctIndex": 0, "consequences": ["Drugs can help even if the theory behind them is wrong.", "Belief in a story does not prove a drug works.", "The review did not show antidepressants fail."], "explanation": "Theories shift; benefit in trials is what counts."}, "proReasoning": "Investors back evidence of benefit, not a neat mechanism story. Theories shift; trial results are what count.", "commonMistake": "Valuing a drug on a disputed theory.", "mentalModel": "Benefit beats story."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your mental health app explains treatment to millions of users.", "prompt": "How should you explain antidepressants now?", "options": ["They have been proven useless", "They can help; the cause is unclear", "They work by fixing low serotonin"], "correctIndex": 1, "consequences": ["The review did not assess whether they work.", "Accurate, and in line with both the review and its critics.", "The 2022 review found no consistent support for that."], "explanation": "Honest uncertainty matches the evidence and keeps users' trust."}, "proReasoning": "Founders explaining health topics keep pace with the evidence. Honest uncertainty builds more trust than a tidy myth.", "commonMistake": "Using a simple story the science has moved past.", "mentalModel": "Honest uncertainty."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend on an antidepressant reads about the 2022 review and feels misled.", "prompt": "What's a fair way to put it?", "options": ["The drug was proven not to work at all", "The review was about painkillers", "The story was challenged, not the drug"], "correctIndex": 2, "consequences": ["It did not assess drug benefit.", "Painkillers were the critics' example of help without a shortage.", "The review did not test whether antidepressants work."], "explanation": "The review questioned why the drugs were said to work, not whether they help. Any change to treatment is a talk with their doctor."}, "proReasoning": "Separate why a drug was said to work from whether it helps. A broken story is not a broken treatment.", "commonMistake": "Concluding a drug fails because its popular explanation did.", "mentalModel": "Story and benefit are separate."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:124197dfd45b$ml$]::text[]),
($ml$fa86686d-88a2-5247-8d37-1c593ce4cfa0$ml$::uuid, $ml$neuroscience$ml$, 12, 3, $ml${"id": "neuroscience-d12-c3", "title": "Rewriting the explainer", "lessonTitle": "When the serotonin story was challenged", "slot": 3, "type": "decide", "brief": {"headline": "You run a health site whose antidepressant page says depression comes from low serotonin. A 2022 review found no convincing evidence for that, but did not test whether the drugs work.", "kicker": "Decide how to fix the page without misleading readers.", "fullText": "You run a popular health information site. Its page on antidepressants still says depression is caused by a chemical imbalance, low serotonin.\n\nIn July 2022, Moncrieff and colleagues published an umbrella review finding no support for that idea: blood and brain-fluid measures showed no difference, and lowering serotonin in healthy volunteers did not cause depression. The review did not assess whether antidepressants work. Critics such as UCL psychiatrist Michael Bloomfield noted the drugs can help even if low serotonin is not the cause, as painkillers help headaches. Many of your readers may be taking these drugs.", "sources": [{"url": "https://www.sciencedaily.com/releases/2022/07/220720080145.htm", "label": "ScienceDaily via UCL, No evidence that depression is caused by low serotonin, Jul 2022"}, {"url": "https://www.newswise.com/articles/don-t-throw-away-your-antidepressants-just-yet", "label": "Newswise, Don't throw away your antidepressants just yet, 2022"}]}, "evidence": {"kind": "sortSignal", "prompt": "Did the 2022 review find this?", "buckets": ["The review found it", "It did not"], "items": [{"text": "No consistent link between low serotonin and depression", "bucket": 0}, {"text": "Lowering serotonin did not cause depression in volunteers", "bucket": 0}, {"text": "No difference in blood and brain-fluid measures", "bucket": 0}, {"text": "Antidepressants do not work", "bucket": 1}, {"text": "People on antidepressants should stop them", "bucket": 1}], "explanation": "The review tested the cause story. It made no finding on whether the drugs work, and gave no advice to stop them."}, "numbers": {"kind": "numberSense", "prompt": "If 85% of your 1,000 most loyal readers believe the old story, how many does the new page need to reach?", "min": 0, "max": 1000, "value": 850, "unit": "readers", "explanation": "85% of 1,000 is 850 readers who may hold the old story. That is the audience for the rewrite."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the site's medical editor. The CEO wants a one-line headline for the new page.", "prompt": "Which line is accurate?", "options": ["They can help; the cause is complex", "Depression is caused by low serotonin", "Science shows antidepressants fail"], "correctIndex": 0, "consequences": ["It matches both the review and its critics.", "The review found no consistent evidence for that.", "The review did not assess drug benefit."], "explanation": "Write the line that will still be true after the next study."}, "proReasoning": "Medical editors write lines that survive the next study. Keep claims to what the evidence supports.", "commonMistake": "Swapping one oversimplification for another.", "mentalModel": "Claim only what holds."}, "invest": {"call": {"kind": "theCall", "situation": "You're an investor in the site. Its traffic depends on readers' trust.", "prompt": "Why update the page quickly?", "options": ["The review legally requires an update", "Outdated claims put reader trust at risk", "Search engines reward older content more"], "correctIndex": 1, "consequences": ["No rule forces it; trust does.", "A health site lives on being right.", "Accuracy, not age, keeps readers."], "explanation": "For a health site, accuracy is the asset. A page the science has passed by is a liability."}, "proReasoning": "Investors in health media treat accuracy as an asset. A page the science has passed by is a liability.", "commonMistake": "Treating content updates as optional.", "mentalModel": "Accuracy is the asset."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Rewriting means admitting the old page was wrong.", "prompt": "How should you handle the change?", "options": ["Quietly delete the page", "Leave it, since many readers believe it", "Update it openly and cite the review"], "correctIndex": 2, "consequences": ["Readers who relied on it get no explanation.", "Popularity does not make it accurate.", "Openness keeps trust and shows readers the evidence."], "explanation": "Correct in the open and show the evidence. Hiding the change costs more trust than it saves."}, "proReasoning": "Founders of health products correct mistakes in the open. Showing the evidence builds more trust than hiding the change.", "commonMistake": "Hiding a correction to avoid looking wrong.", "mentalModel": "Correct in the open."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a drug can help if the theory behind it was wrong.", "prompt": "What's the best analogy?", "options": ["Painkillers ease headaches, no shortage", "A wrong theory means the drug is fake", "Theories and drugs are the same thing"], "correctIndex": 0, "consequences": ["Critics used exactly that example.", "Drugs are judged by results, not by their backstory.", "A theory explains; a drug is tested."], "explanation": "A headache is not caused by a painkiller shortage, yet painkillers help. Relief does not prove the cause."}, "proReasoning": "Use the painkiller analogy: relief does not prove a shortage caused the pain.", "commonMistake": "Assuming a treatment's story must be true for it to work.", "mentalModel": "Relief is not proof of cause."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ed49350afe50$ml$]::text[]),
($ml$608dfe1d-f114-59d3-9684-6100022e57f3$ml$::uuid, $ml$neuroscience$ml$, 13, 1, $ml${"id": "neuroscience-d13-c1", "title": "The 132-ton magnet", "lessonTitle": "How scientists see inside a living brain", "slot": 1, "type": "apply", "brief": {"headline": "In April 2024, France's Iseult, an 11.7-tesla MRI, released its first images of living human brains: 0.2 mm detail in about four minutes. Hospital scanners would need hours to match them.", "kicker": "Apply the lesson: every tool pays for its detail somehow.", "fullText": "Iseult, at the CEA's NeuroSpin center, is the most powerful MRI machine in the world, at 11.7 teslas. Its first brain images, published on April 2, 2024, reached an in-plane resolution of 0.2 mm with 1 mm slices, in about four minutes. The CEA said hospital scanners at 1.5 or 3 teslas would need hours to match that quality, and any movement would blur the image.\n\nThe price is size and complexity. The magnet weighs 132 tons, measures 5 meters by 5 meters, and is cooled with 7,500 liters of liquid helium. Planned work includes the anatomy of Alzheimer's and Parkinson's, where the drug lithium goes in the brain, and molecules such as glucose and glutamate.\n\nDay 13's rule still holds. MRI gives superb detail in space; for millisecond timing, researchers still turn to EEG and MEG.", "sources": [{"url": "https://www.cea.fr/english/Pages/News/world-premiere-living-brain-imaged-with-unrivaled-clarity-thanks-to-world-most-powerful-MRI-machine.aspx", "label": "CEA, World premiere: living brain imaged with the world's most powerful MRI, Apr 2024"}, {"url": "https://synapse.patsnap.com/article/what-are-the-common-methods-used-in-brain-imaging-eg-fmri-pet-eeg", "label": "Patsnap Synapse, Common methods used in brain imaging"}, {"url": "https://www.mcgill.ca/bic/core-facilities/meg", "label": "McGill Brain Imaging Centre, Magnetoencephalography"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which tool does each fact describe?", "buckets": ["Iseult MRI", "EEG"], "items": [{"text": "0.2 mm detail in about four minutes", "bucket": 0}, {"text": "A 132-ton magnet", "bucket": 0}, {"text": "Cooled by 7,500 liters of helium", "bucket": 0}, {"text": "Electrodes on the scalp", "bucket": 1}, {"text": "Millisecond timing", "bucket": 1}, {"text": "Low cost and portable", "bucket": 1}], "explanation": "Iseult buys spatial detail with size and cost. EEG buys timing and reach, and gives up localization."}, "numbers": {"kind": "numberSense", "prompt": "How many tons does Iseult's magnet weigh?", "min": 0, "max": 300, "value": 132, "unit": "tons", "explanation": "132 tons, five meters long and wide. Detail in space comes at a cost in size and reach."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're applying to work on Iseult. They ask what kind of question it is best suited for.", "prompt": "What's your answer?", "options": ["Millisecond timing of brain signals", "Cheap screening in local clinics", "Fine anatomy and brain chemistry"], "correctIndex": 2, "consequences": ["For timing, EEG and MEG are the tools.", "A 132-ton magnet is the opposite of cheap and local.", "0.2 mm detail suits anatomy, and its plans include molecules like glucose."], "explanation": "Iseult is built for detail in space. Timing and low-cost reach belong to other tools."}, "proReasoning": "Imaging teams pick tools by question. Show you know what each machine is good at, and what it is not.", "commonMistake": "Assuming the most powerful scanner is best for every question.", "mentalModel": "Pick the tool by the question."}, "invest": {"call": {"kind": "theCall", "situation": "A company wants to sell 11.7-tesla scanners to hospitals.", "prompt": "What should worry you most?", "options": ["Size and cost limit where they can go", "Its images are too blurry to use", "Doctors prefer slower scans"], "correctIndex": 0, "consequences": ["A 132-ton magnet with 7,500 liters of helium suits few sites.", "Iseult reached 0.2 mm detail in about four minutes.", "Faster high-quality scans are an advantage."], "explanation": "Image quality is not the problem. How many places can house and run such a machine is."}, "proReasoning": "Investors ask who can actually use a tool. Cost and size decide reach as much as image quality does.", "commonMistake": "Valuing a scanner on image quality alone.", "mentalModel": "Cost shapes reach."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds a brain-health product for homes. Iseult's images are stunning.", "prompt": "Which tool should your product rely on?", "options": ["PET scans for daily tracking", "EEG, since it is cheap and portable", "An 11.7-tesla MRI in every town"], "correctIndex": 1, "consequences": ["PET uses radioactive tracers, a poor fit for daily use.", "Low cost and portability let it reach far more people.", "One magnet weighs 132 tons; that will not spread."], "explanation": "Superb detail helps research. A home product needs a tool that is cheap and portable."}, "proReasoning": "Founders build on tools that can spread. Superb detail helps research; cheap, portable sensing reaches customers.", "commonMistake": "Building on the most impressive tool rather than the most reachable one.", "mentalModel": "Cheap tools spread faster."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why we don't use the world's strongest MRI to watch thoughts in real time.", "prompt": "What's a fair answer?", "options": ["Iseult cannot image living people", "Thoughts give off no signals at all", "MRI shows where, EEG shows when"], "correctIndex": 2, "consequences": ["Its first images were of living brains.", "EEG and MEG pick up electrical and magnetic signals.", "Every tool trades detail in space for detail in time."], "explanation": "The strongest magnet sharpens where activity is. Timing comes from EEG and MEG."}, "proReasoning": "Explain imaging as a trade: where versus when. The strongest magnet sharpens where, not when.", "commonMistake": "Assuming one machine can do everything.", "mentalModel": "Where or when: pick your tool."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4abcdef4f45b$ml$]::text[]),
($ml$9cba84c7-d96f-5f10-a451-1539b198afc3$ml$::uuid, $ml$neuroscience$ml$, 13, 2, $ml${"id": "neuroscience-d13-c2", "title": "fMRI reads the energy bill", "lessonTitle": "How scientists see inside a living brain", "slot": 2, "type": "connect", "brief": {"headline": "The brain uses about 20% of the body's resting energy. fMRI turns that hunger into a picture: active regions need more oxygen, so it tracks the blood flowing to them.", "kicker": "Connect day 4 and day 13: fMRI reads the brain's energy bill.", "fullText": "On day 4 you learned the brain is about 2% of body weight but uses about 20% of resting energy. On day 13 you saw how fMRI uses that. It measures activity by detecting changes in blood flow, since active regions need more oxygen. That gives strong spatial detail, but limited timing.\n\nEEG and MEG read electrical and magnetic signals instead, with millisecond timing. PET uses radioactive tracers to measure processes such as glucose use, another view of the same energy bill.", "sources": [{"url": "https://bionumbers.hms.harvard.edu/bionumber.aspx?id=108621", "label": "BioNumbers, brain share of resting metabolism"}, {"url": "https://synapse.patsnap.com/article/what-are-the-common-methods-used-in-brain-imaging-eg-fmri-pet-eeg", "label": "Patsnap Synapse, Common methods used in brain imaging"}, {"url": "https://www.mcgill.ca/bic/core-facilities/meg", "label": "McGill Brain Imaging Centre, Magnetoencephalography"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how fMRI turns activity into an image.", "steps": ["A brain region becomes more active", "It needs more oxygen", "Blood flow to the region rises", "fMRI detects the change in blood flow", "The scan shows where activity rose"], "explanation": "fMRI never reads neurons directly. It reads the blood that follows the brain's energy needs."}, "numbers": {"kind": "numberSense", "prompt": "The brain is about 2% of body weight. What share of the body's resting energy does it use?", "min": 0, "max": 60, "value": 20, "unit": "%", "explanation": "About 20%. That appetite is what makes blood flow a useful signal of activity."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an imaging interview, you're asked what fMRI actually measures.", "prompt": "What's the precise answer?", "options": ["Changes in blood flow to active regions", "Electrical signals from scalp electrodes", "Radioactive tracers in the blood"], "correctIndex": 0, "consequences": ["Active regions need more oxygen, so blood flow is the signal.", "That is EEG.", "That is PET."], "explanation": "fMRI measures blood flow, an indirect sign of activity."}, "proReasoning": "Say what a tool measures, not just what it shows. fMRI measures blood flow, an indirect sign of activity.", "commonMistake": "Saying fMRI reads neurons directly.", "mentalModel": "Know the signal behind the picture."}, "invest": {"call": {"kind": "theCall", "situation": "A startup claims its fMRI product reads thoughts in real time.", "prompt": "What's the strongest reason for doubt?", "options": ["The brain uses too little energy to see", "fMRI tracks blood flow, with limited timing", "fMRI cannot show where any activity is"], "correctIndex": 1, "consequences": ["The brain uses about 20% of resting energy.", "Blood flow is indirect, and its timing is limited.", "Spatial detail is its strength."], "explanation": "An indirect signal with limited timing does not fit a real-time claim."}, "proReasoning": "Investors check a claim against what the tool can measure. A slow, indirect signal limits real-time claims.", "commonMistake": "Taking imaging claims at face value.", "mentalModel": "Check the claim against the signal."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want a product that tracks brain activity second by second, at home.", "prompt": "Which signal fits best?", "options": ["Blood flow changes, via fMRI", "Glucose use, via a PET scan", "Electrical signals, via EEG"], "correctIndex": 2, "consequences": ["fMRI has limited timing and needs a large scanner.", "PET needs radioactive tracers.", "EEG gives millisecond timing and is cheap and portable."], "explanation": "Second-by-second tracking at home calls for electrical signals, not blood flow."}, "proReasoning": "Founders match the signal to the product's need. Second-by-second tracking at home calls for electrical signals, not blood flow.", "commonMistake": "Choosing the signal with the best pictures instead of the right timing.", "mentalModel": "Match the signal to the need."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a scanner can see thinking.", "prompt": "What's the simplest answer?", "options": ["Busy regions draw more blood; fMRI sees it", "It photographs individual thoughts", "It listens to neurons through the skull"], "correctIndex": 0, "consequences": ["The brain's energy needs leave a trace in blood flow.", "It measures blood flow, not thoughts.", "That is closer to EEG, with electrodes on the scalp."], "explanation": "Active regions need more oxygen. fMRI tracks the blood that brings it."}, "proReasoning": "Explain fMRI through energy: busy regions use more oxygen, and blood rushes in.", "commonMistake": "Thinking scanners read thoughts directly.", "mentalModel": "Blood follows activity."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3424e4b052cb$ml$]::text[]),
($ml$7d61cfa7-a573-5778-a886-58e45a02f5a3$ml$::uuid, $ml$neuroscience$ml$, 13, 3, $ml${"id": "neuroscience-d13-c3", "title": "One budget, four tools", "lessonTitle": "How scientists see inside a living brain", "slot": 3, "type": "decide", "brief": {"headline": "You run a hospital epilepsy program with money for one new imaging tool. fMRI, EEG, MEG and PET each see something different, at very different costs.", "kicker": "Decide which tool fits the question your program asks.", "fullText": "You run an epilepsy program and can add one imaging tool. Day 13 sets out the trade. fMRI tracks blood flow with strong spatial detail but limited timing. EEG records electrical activity through scalp electrodes with millisecond timing but weak localization, and it is low cost. MEG detects tiny magnetic fields from neuronal currents, with millisecond timing across the whole brain, inside a magnetically shielded room. PET uses radioactive tracers to measure processes such as glucose use, and is used clinically in epilepsy, Alzheimer's and cancer.\n\nYour team's main question: when, to the millisecond, does abnormal activity start, and roughly where?", "sources": [{"url": "https://synapse.patsnap.com/article/what-are-the-common-methods-used-in-brain-imaging-eg-fmri-pet-eeg", "label": "Patsnap Synapse, Common methods used in brain imaging"}, {"url": "https://www.mcgill.ca/bic/core-facilities/meg", "label": "McGill Brain Imaging Centre, Magnetoencephalography"}]}, "evidence": {"kind": "faceOff", "prompt": "For millisecond timing across the whole brain, which tool fits?", "left": {"name": "MEG", "note": "Magnetic fields, in a shielded room"}, "right": {"name": "fMRI", "note": "Blood flow, strong spatial detail"}, "correctIndex": 0, "explanation": "MEG reaches millisecond timing across the whole brain. fMRI shows where well, but slowly."}, "numbers": {"kind": "numberSense", "prompt": "EEG and MEG catch activity within milliseconds. How many milliseconds is a quarter of a second?", "min": 0, "max": 1000, "value": 250, "unit": "ms", "explanation": "250 milliseconds. EEG and MEG resolve events far shorter than that."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The program director asks you to make the case for MEG over a second fMRI scanner.", "prompt": "What's the strongest point?", "options": ["It uses radioactive tracers", "It captures millisecond timing", "It needs no special room"], "correctIndex": 1, "consequences": ["That is PET.", "Timing is exactly what the team's question needs.", "MEG needs a magnetically shielded room."], "explanation": "Your question is about when. MEG answers when, across the whole brain."}, "proReasoning": "Argue for a tool by the question it answers. For when-questions, millisecond timing wins.", "commonMistake": "Arguing for a tool on prestige rather than fit.", "mentalModel": "The question picks the tool."}, "invest": {"call": {"kind": "theCall", "situation": "You're on the hospital board weighing MEG against more EEG units.", "prompt": "What's the key trade-off?", "options": ["EEG is much slower at timing than MEG", "MEG is portable and cheap to run", "Whole-brain MEG versus low-cost EEG"], "correctIndex": 2, "consequences": ["Both catch activity within milliseconds.", "MEG needs a magnetically shielded room.", "Both are fast; the trade is setup and coverage against cost."], "explanation": "Both tools are fast. The choice is MEG's whole-brain reach against EEG's low cost."}, "proReasoning": "Board members weigh capability against reach. A cheaper tool used widely can beat a better one used rarely.", "commonMistake": "Comparing tools on speed when both are fast.", "mentalModel": "Weigh capability against cost."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells to epilepsy clinics that cannot afford MEG.", "prompt": "What product makes sense?", "options": ["Better software for low-cost EEG", "A cheaper shielded room for MEG", "A new factory for PET tracers"], "correctIndex": 0, "consequences": ["EEG is low cost, so better analysis can reach many clinics.", "Possible, but still a big build for each clinic.", "Tracers are a far larger, slower bet."], "explanation": "Improve the tool your customers can already afford."}, "proReasoning": "Founders improve the tool customers can already afford. Better EEG analysis reaches more clinics than a rare scanner.", "commonMistake": "Building for the premium tool in a market that cannot buy it.", "mentalModel": "Upgrade the affordable tool."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why an epilepsy patient might get several different brain scans.", "prompt": "What's the reason?", "options": ["No single scan is ever accurate", "Each tool shows a different piece", "Doctors like to repeat the same test"], "correctIndex": 1, "consequences": ["Each is accurate for what it measures.", "Timing, location and chemistry come from different tools.", "They are different tests, not repeats."], "explanation": "Every tool trades space for time. Together they fill each other's gaps."}, "proReasoning": "Explain multiple scans as a team of tools. Each fills a gap the others leave.", "commonMistake": "Thinking more scans mean the first one failed.", "mentalModel": "Each tool, one piece."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:eba901f1330d$ml$]::text[]),
($ml$5a38ea07-be74-5ae9-b3fe-95f9b7e0e22b$ml$::uuid, $ml$neuroscience$ml$, 14, 1, $ml${"id": "neuroscience-d14-c1", "title": "How good is good enough?", "lessonTitle": "A blood test takes on the brain scan", "slot": 1, "type": "apply", "brief": {"headline": "In July 2025, the Alzheimer's Association issued its first guideline on Alzheimer's blood tests. Tests with 90% sensitivity and specificity can stand in for a PET scan or spinal fluid test in specialist care.", "kicker": "Apply the lesson: a cheaper test must clear a set bar.", "fullText": "The guideline, published on July 29, 2025, in Alzheimer's & Dementia and presented in Toronto, reviewed how well blood tests for markers such as phosphorylated tau and amyloid ratios matched spinal fluid tests, amyloid PET or brain tissue.\n\nIt set two bars, by performance rather than brand. Tests with at least 90% sensitivity and 75% specificity can serve as triage tools. Tests that reach 90% on both can substitute for amyloid PET or spinal fluid testing in people with cognitive impairment seen by specialists. Accuracy varies across commercial tests, and the panel said blood tests should complement, not replace, a full clinical assessment.\n\nAn amyloid PET scan averages $5,000 to $6,000. A test that clears the bar can change who gets checked, and where.", "sources": [{"url": "https://www.alzheimer-europe.org/news/alzheimers-association-issues-clinical-guideline-use-blood-based-biomarkers-diagnosing", "label": "Alzheimer Europe, Alzheimer's Association guideline on blood-based biomarkers, Jul 2025"}, {"url": "https://www.dementiacarecentral.com/lumipulse-test", "label": "DementiaCareCentral, Lumipulse test"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the guideline. Tap it.", "statements": ["Triage tests need at least 90% sensitivity.", "Any blood test can now replace a PET scan.", "Blood tests should complement a clinical assessment."], "fakeIndex": 1, "explanation": "Only tests reaching 90% sensitivity and specificity can substitute, and accuracy varies across tests."}, "numbers": {"kind": "numberSense", "prompt": "For a triage test, what minimum specificity did the guideline set, in percent?", "min": 0, "max": 100, "value": 75, "unit": "%", "explanation": "At least 75%, with at least 90% sensitivity. Replacement needs 90% on both."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a diagnostics company's medical team. Sales asks if your blood test can replace PET.", "prompt": "What's the accurate answer?", "options": ["Only if it hits 90% on both measures", "Yes, every blood test now can", "No blood test can ever replace PET"], "correctIndex": 0, "consequences": ["That is the bar for substituting in specialist care.", "Accuracy varies, and the bar is 90% on both.", "The guideline allows it for tests that clear the bar."], "explanation": "The guideline judges tests by performance. Replacement needs 90% sensitivity and specificity."}, "proReasoning": "Know the performance bar your product must clear. Guidelines now judge tests by sensitivity and specificity, not brand.", "commonMistake": "Claiming more than your test's numbers support.", "mentalModel": "Know the bar."}, "invest": {"call": {"kind": "theCall", "situation": "Two blood test makers pitch you. One reports 92% sensitivity and 80% specificity; the other 91% and 91%.", "prompt": "Which has the wider use under the guideline?", "options": ["Both have the same uses", "The 91% and 91% test", "The 92% and 80% test"], "correctIndex": 1, "consequences": ["The thresholds put them in different roles.", "It can substitute for PET in specialist care, not just triage.", "At 80% specificity, it qualifies only for triage."], "explanation": "A few points of specificity move a test from triage to replacement."}, "proReasoning": "Investors map a test's numbers to its allowed role. A few points of specificity can move a test from triage to replacement.", "commonMistake": "Treating all promising blood tests as equal.", "mentalModel": "Numbers set the role."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your blood test has 90% sensitivity and 78% specificity.", "prompt": "How should you position it?", "options": ["As a full replacement for PET", "As proof of Alzheimer's on its own", "As a triage tool before further tests"], "correctIndex": 2, "consequences": ["Replacement needs 90% specificity too.", "Blood tests should complement a full clinical assessment.", "It clears the 90% and 75% triage bar."], "explanation": "Your numbers fit the triage role. That is a real product; overclaiming invites trouble."}, "proReasoning": "Founders position a product where its numbers fit. A strong triage test is a real product; overclaiming invites trouble.", "commonMistake": "Positioning a triage test as a replacement.", "mentalModel": "Position by performance."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend's parent is offered an Alzheimer's blood test instead of a PET scan.", "prompt": "What's a fair way to explain it?", "options": ["Good tests can stand in for PET", "Blood tests are always better than PET", "Blood tests are never reliable"], "correctIndex": 0, "consequences": ["Tests at 90% on both can substitute, within a full assessment.", "Accuracy varies across tests.", "Some reach the 90% bar on both measures."], "explanation": "A test that is accurate enough can stand in for a costly scan, as one part of a full assessment."}, "proReasoning": "Explain new tests by their bar: a test accurate enough can stand in for a costly scan, as one part of a full assessment.", "commonMistake": "Assuming new tests are either perfect or useless.", "mentalModel": "Good enough is a number."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8a60a5d8f3f7$ml$]::text[]),
($ml$a6cd123a-f6d0-5390-8c18-1ffcf6ffee90$ml$::uuid, $ml$neuroscience$ml$, 14, 2, $ml${"id": "neuroscience-d14-c2", "title": "From tracer to test tube", "lessonTitle": "A blood test takes on the brain scan", "slot": 2, "type": "connect", "brief": {"headline": "PET uses radioactive tracers and is used clinically in Alzheimer's. In May 2025, the FDA cleared the first Alzheimer's blood test and said it could reduce the need for PET scans.", "kicker": "Connect day 13 and day 14: a lab test takes on an imaging tool.", "fullText": "Day 13 laid out the imaging toolkit. PET uses radioactive tracers to measure processes such as glucose use, and is used clinically in Alzheimer's disease, cancer and epilepsy. Day 14 showed its cost: an amyloid PET scan averages $5,000 to $6,000 and exposes patients to radiation.\n\nIn May 2025, the FDA cleared Lumipulse, the first blood test to aid in detecting the amyloid plaques of Alzheimer's in adults over 55 with symptoms, and said it could reduce the need for PET scans. In October 2025, Roche's Elecsys pTau181 became the first blood test cleared for primary care to help rule out Alzheimer's-related amyloid. Blood tests run on lab machines that already exist.", "sources": [{"url": "https://synapse.patsnap.com/article/what-are-the-common-methods-used-in-brain-imaging-eg-fmri-pet-eeg", "label": "Patsnap Synapse, Common methods used in brain imaging"}, {"url": "https://www.dementiacarecentral.com/lumipulse-test", "label": "DementiaCareCentral, Lumipulse test"}, {"url": "https://www.fox5ny.com/news/first-blood-test-alzheimers-diagnosis-cleared-fda", "label": "FOX 5 New York, First blood test for Alzheimer's diagnosis cleared by FDA, May 2025"}, {"url": "https://www.roche.com/investors/updates/inv-update-2025-10-13b", "label": "Roche, Elecsys pTau181 FDA clearance for primary care, Oct 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which test does each fact describe?", "buckets": ["Amyloid PET", "Blood test"], "items": [{"text": "Uses radioactive tracers", "bucket": 0}, {"text": "Averages $5,000 to $6,000", "bucket": 0}, {"text": "Exposes patients to radiation", "bucket": 0}, {"text": "Runs on existing lab machines", "bucket": 1}, {"text": "Cleared for primary care in 2025", "bucket": 1}], "explanation": "PET is precise but costly and specialized. Blood tests are cheaper and run where labs already are."}, "numbers": {"kind": "numberSense", "prompt": "Roche has more than how many thousand instruments in US clinical labs?", "min": 0, "max": 10, "value": 4.5, "unit": "K", "explanation": "More than 4,500. A test that runs on machines already in place can spread fast."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work at a PET imaging center in 2025. Blood tests for amyloid have just been cleared.", "prompt": "What's the realistic effect on your work?", "options": ["Nothing will change for PET", "Fewer routine scans over time", "PET scans will stop completely"], "correctIndex": 1, "consequences": ["Cheaper tests change who gets scanned.", "The FDA said blood tests could reduce the need for PET.", "Reduce is not eliminate."], "explanation": "A cheaper test that is good enough pulls volume from a costly scan without ending it."}, "proReasoning": "Watch for cheaper substitutes to your tool. Knowing what they replace, and what they do not, protects your career.", "commonMistake": "Assuming an established tool is safe from cheaper rivals.", "mentalModel": "Watch for the cheaper substitute."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a company that makes amyloid PET tracers.", "prompt": "How should the blood test news shape your view?", "options": ["Tracer demand will double from here", "The tests will have no effect on PET", "Volume may shift from scans to lab tests"], "correctIndex": 2, "consequences": ["A cheaper substitute usually cuts demand, not doubles it.", "The FDA expected a reduced need for PET.", "The FDA said Lumipulse could reduce the need for PET scans."], "explanation": "Cheap tests at scale can outgrow costly scans. Tracer volume is at risk."}, "proReasoning": "Investors track substitutes. A cheaper test running on 4,500 existing instruments can pull volume from costly scans.", "commonMistake": "Ignoring a cheaper rival because it is less precise.", "mentalModel": "Cheap and good enough wins volume."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps clinics order and track Alzheimer's tests.", "prompt": "Where is demand likely to grow fastest?", "options": ["Blood tests in primary care", "PET scans at specialist sites", "Yearly scans for healthy adults"], "correctIndex": 0, "consequences": ["Roche's test was cleared for primary care in 2025.", "PET is costly, needs special sites and uses radiation.", "Radiation and cost make that hard to justify."], "explanation": "Blood tests bring Alzheimer's checks to primary care, a far larger setting than PET sites."}, "proReasoning": "Founders follow where testing moves. Blood tests bring Alzheimer's checks to primary care, a far larger setting than PET sites.", "commonMistake": "Building around the expensive tool as it loses volume.", "mentalModel": "Follow the test to primary care."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a blood test is big news if PET scans already worked.", "prompt": "What's the answer?", "options": ["Blood tests see plaques directly", "It is cheaper and needs no radiation", "PET scans never really worked"], "correctIndex": 1, "consequences": ["They measure markers in blood, not the plaques themselves.", "PET averages $5,000 to $6,000 and exposes patients to radiation.", "PET works; it is costly and hard to reach."], "explanation": "A cheaper, safer test that is good enough can reach far more people."}, "proReasoning": "Explain diagnostics by cost and reach, not only accuracy. A cheaper, safer test can reach far more people.", "commonMistake": "Thinking the most precise test always wins.", "mentalModel": "Reach matters as much as precision."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:698147f3d79f$ml$]::text[]),
($ml$a061db67-cbd9-58ff-bca1-fbee95e0586d$ml$::uuid, $ml$neuroscience$ml$, 14, 3, $ml${"id": "neuroscience-d14-c3", "title": "What a negative result means", "lessonTitle": "A blood test takes on the brain scan", "slot": 3, "type": "decide", "brief": {"headline": "You run a primary care network. Roche's blood test, cleared in October 2025, helps rule out Alzheimer's-related amyloid, with a 97.9% negative predictive value.", "kicker": "Decide how your clinics should use a rule-out test.", "fullText": "You run a network of primary care clinics. Many older patients raise memory concerns, and amyloid PET, which averages $5,000 to $6,000, needs special sites and exposes patients to radiation.\n\nIn October 2025, Roche's Elecsys pTau181 became the first blood test cleared for primary care to help rule out Alzheimer's-related amyloid. Its negative predictive value was 97.9%: of people who test negative, about 97.9% truly lack the amyloid. Roche has more than 4,500 instruments in US clinical labs, so the test runs on machines that already exist.", "sources": [{"url": "https://www.roche.com/investors/updates/inv-update-2025-10-13b", "label": "Roche, Elecsys pTau181 FDA clearance for primary care, Oct 2025"}, {"url": "https://www.dementiacarecentral.com/lumipulse-test", "label": "DementiaCareCentral, Lumipulse test"}, {"url": "https://www.fox5ny.com/news/first-blood-test-alzheimers-diagnosis-cleared-fda", "label": "FOX 5 New York, First blood test for Alzheimer's diagnosis cleared by FDA, May 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the rule-out pathway in order.", "steps": ["A patient raises a memory concern", "The clinic orders the blood test", "A lab runs it on an existing instrument", "A negative result makes amyloid unlikely", "A positive result leads to further workup"], "explanation": "A rule-out test is strongest when it comes back negative. Positives move on to fuller testing."}, "numbers": {"kind": "numberSense", "prompt": "With a 97.9% negative predictive value, about how many of 1,000 negative results would be wrong?", "min": 0, "max": 100, "value": 21, "unit": "results", "explanation": "About 21 of 1,000, or 2.1%. Good enough to rule out most people, not perfect."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the network's clinical lead. A doctor asks what a negative result on the test means.", "prompt": "What's the accurate answer?", "options": ["The patient definitely has Alzheimer's", "The test told us nothing useful", "Amyloid is unlikely, about 98% of the time"], "correctIndex": 2, "consequences": ["A negative result points the other way.", "A negative is exactly what it is built to give.", "That is what a 97.9% negative predictive value means."], "explanation": "A 97.9% negative predictive value means about 98 of 100 negatives truly lack the amyloid."}, "proReasoning": "Clinical leads explain what each result means in plain terms. A rule-out test is strongest when it comes back negative.", "commonMistake": "Reading a rule-out test as a diagnosis.", "mentalModel": "Rule-out tests shine when negative."}, "invest": {"call": {"kind": "theCall", "situation": "You're valuing Roche's diagnostics unit after the clearance.", "prompt": "What drives the test's revenue potential most?", "options": ["Volume on 4,500 existing instruments", "A high price per test, like PET", "Selling new scanners to clinics"], "correctIndex": 0, "consequences": ["Existing machines let the test spread fast.", "Its edge is volume and cost, not PET-level price.", "It runs on lab instruments, not scanners."], "explanation": "A cheap test on machines already in place wins on volume."}, "proReasoning": "Investors look for tests that ride existing infrastructure. Volume at low cost can outgrow expensive scans.", "commonMistake": "Valuing a cheap test by its price per use.", "mentalModel": "Volume beats price."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds software for primary care. Memory concerns are rising among patients.", "prompt": "Which tool fills the biggest gap?", "options": ["A device to replace lab instruments", "Workflow to order and act on blood tests", "Booking software for PET centers"], "correctIndex": 1, "consequences": ["Labs already have 4,500 instruments.", "Primary care can now test, and needs help acting on results.", "PET is costly and needs special sites."], "explanation": "Primary care now has a test. It needs the workflow around it."}, "proReasoning": "Founders bring tools to where testing is moving. Primary care now has a test; it needs the workflow around it.", "commonMistake": "Building for the costly old pathway.", "mentalModel": "Build for the new front door."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend was told a negative blood test makes Alzheimer's plaques unlikely, and wonders how sure that is.", "prompt": "What does 97.9% mean here?", "options": ["The test is 97.9% right about everything", "It finds 97.9% of all dementia", "About 98 of 100 negatives are right"], "correctIndex": 2, "consequences": ["It describes negative results specifically.", "It is about amyloid, not all dementia.", "That is the negative predictive value."], "explanation": "Of 100 people who test negative, about 98 truly lack the amyloid."}, "proReasoning": "Explain a predictive value by counting people: of 100 negative results, about 98 are right.", "commonMistake": "Treating one accuracy number as a promise about everything.", "mentalModel": "Count the people."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:fd73b9fe33b3$ml$]::text[]),
($ml$c34022dc-d1db-51b9-b4ce-7e7db47225f8$ml$::uuid, $ml$neuroscience$ml$, 15, 1, $ml${"id": "neuroscience-d15-c1", "title": "Medicare starts paying for therapy apps", "lessonTitle": "Who decides if Medicare pays for a scan", "slot": 1, "type": "apply", "brief": {"headline": "From January 2025, Medicare pays clinicians to supply and manage digital mental health treatment devices. Only devices the FDA cleared in one specific category qualify.", "kicker": "Apply the lesson: the payer decides which apps get used.", "fullText": "Under the 2025 physician fee schedule, CMS created three codes. G0552 pays for supplying a digital mental health treatment device, with education and onboarding. G0553 and G0554 pay for 20-minute blocks of monthly treatment management, each worth roughly $21.67 depending on location.\n\nThe conditions are strict. The device must be FDA cleared or authorized under 21 CFR 882.5801, computerized behavioral therapy devices for psychiatric disorders; from 2026, a category for ADHD digital therapy devices also counts. It must be used alongside ongoing behavioral health treatment under a plan of care, and the billing clinician must bear the cost of the device. Fierce Healthcare called the digital health changes meager.\n\nAn app can work and still go unused if no one pays for it. Medicare opened a narrow door.", "sources": [{"url": "https://med.noridianmedicare.com/web/jeb/article-detail/-/view/10525/digital-mental-health-treatment-device-medicare-billing-and-documentation-requirements", "label": "Noridian Medicare, Digital mental health treatment device billing requirements, 2025"}, {"url": "https://www.fiercehealthcare.com/regulatory/final-digital-health-changes-pfs", "label": "Fierce Healthcare, Digital health in the final 2025 Medicare physician fee schedule, Nov 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Could Medicare pay for each under the new codes?", "buckets": ["Can qualify", "Does not qualify"], "items": [{"text": "An FDA-cleared therapy device used with a plan of care", "bucket": 0}, {"text": "A clinician reviewing device use for 20 minutes a month", "bucket": 0}, {"text": "A wellness app with no FDA clearance", "bucket": 1}, {"text": "A device the patient bought on their own", "bucket": 1}, {"text": "A cleared device used with no ongoing treatment", "bucket": 1}], "explanation": "Payment needs the right FDA category, ongoing treatment and a clinician who supplies the device."}, "numbers": {"kind": "numberSense", "prompt": "Each 20-minute management code pays roughly how many dollars, depending on location?", "min": 0, "max": 100, "value": 22, "unit": "$", "explanation": "Roughly $21.67 per code. A small fee, but it marks Medicare paying for this work at all."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a digital therapy company's market access team in 2025.", "prompt": "What's your first task under the new codes?", "options": ["Cut the price to win many more users", "Confirm the device fits the FDA category", "Launch ads directly to patients now"], "correctIndex": 1, "consequences": ["Price matters less than eligibility.", "Only devices under 21 CFR 882.5801 qualify for payment.", "Payment needs a clinician and a plan of care."], "explanation": "Eligibility comes first. Without the right FDA category, no code applies."}, "proReasoning": "Market access teams start with eligibility: the right FDA category and the payer's conditions. Without them, no code applies.", "commonMistake": "Assuming a code covers every mental health app.", "mentalModel": "Eligibility before price."}, "invest": {"call": {"kind": "theCall", "situation": "A digital therapy startup says the new Medicare codes make it a sure winner.", "prompt": "What should you check?", "options": ["Whether its app has many downloads", "Whether it has a famous founder", "Whether its device meets every condition"], "correctIndex": 2, "consequences": ["Downloads do not make it billable.", "Fame does not satisfy CMS conditions.", "FDA category, plan of care and clinician cost all apply."], "explanation": "A new code is revenue only for products that qualify."}, "proReasoning": "Investors read the conditions behind a new code. Coverage is the thesis only if the product qualifies.", "commonMistake": "Treating a new code as automatic revenue.", "mentalModel": "Read the conditions."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your mental health app works well in pilots but has no FDA clearance.", "prompt": "What does Medicare's new code mean for you?", "options": ["Get cleared in the right category", "You can bill Medicare right away", "Medicare will pay for any app"], "correctIndex": 0, "consequences": ["Payment requires FDA clearance in a specific category.", "Without clearance, no code applies.", "Only qualifying devices are covered."], "explanation": "The payer path runs through the FDA. Plan for the right category early."}, "proReasoning": "Founders plan the payer path with the product. The right FDA category can decide whether anyone pays.", "commonMistake": "Building first and asking about payment later.", "mentalModel": "Plan the payer path early."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a doctor would prescribe a therapy app instead of just recommending one.", "prompt": "What's one reason?", "options": ["Doctors earn nothing either way", "Medicare pays for managed use", "Apps only work when prescribed"], "correctIndex": 1, "consequences": ["The new codes pay clinicians for this work.", "The codes pay for supply and monthly management.", "The payment rules, not the app, require the prescription."], "explanation": "When Medicare pays for a managed device, clinicians have a reason to prescribe it."}, "proReasoning": "Explain medical behavior through payment. When Medicare pays for a managed device, clinicians have a reason to prescribe it.", "commonMistake": "Assuming doctors choose tools only on clinical grounds.", "mentalModel": "Payment shapes practice."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8423585566be$ml$]::text[]),
($ml$2f3d9f70-8bc8-557a-9215-0b3f7d6017c4$ml$::uuid, $ml$neuroscience$ml$, 15, 2, $ml${"id": "neuroscience-d15-c2", "title": "Cleared, then covered", "lessonTitle": "Who decides if Medicare pays for a scan", "slot": 2, "type": "connect", "brief": {"headline": "The FDA cleared the first Alzheimer's blood test in May 2025. But payers still decide use: for amyloid PET, Medicare paid for one scan per lifetime until October 2023.", "kicker": "Connect day 14 and day 15: cleared is not the same as covered.", "fullText": "On day 14 you saw blood tests arrive: Lumipulse, cleared in May 2025, and Roche's primary care test in October 2025. The FDA said blood tests could reduce the need for amyloid PET, which averages $5,000 to $6,000.\n\nOn day 15 you saw what decides whether a test is used. Until October 13, 2023, Medicare covered one amyloid PET scan per lifetime. CMS then removed the limit and its national coverage rule, leaving decisions to regional Medicare Administrative Contractors, as the new antibody drugs made amyloid confirmation part of treatment. Any newly cleared test faces the same question: who will pay for it?", "sources": [{"url": "https://www.fox5ny.com/news/first-blood-test-alzheimers-diagnosis-cleared-fda", "label": "FOX 5 New York, First blood test for Alzheimer's diagnosis cleared by FDA, May 2025"}, {"url": "https://www.roche.com/investors/updates/inv-update-2025-10-13b", "label": "Roche, Elecsys pTau181 FDA clearance for primary care, Oct 2025"}, {"url": "https://www.dementiacarecentral.com/lumipulse-test", "label": "DementiaCareCentral, Lumipulse test"}, {"url": "https://www.auntminnie.com/clinical-news/molecular-imaging/article/15636449/cms-lifts-limit-on-amyloid-pet-coverage", "label": "AuntMinnie, CMS lifts limit on amyloid PET coverage, Oct 2023"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Since October 2023, who decides Medicare coverage for amyloid PET?", "options": ["The FDA, at the time of clearance", "Each patient's doctor alone", "Regional Medicare contractors"], "correctIndex": 2, "explanation": "CMS removed its national rule. Regional Medicare Administrative Contractors now decide."}, "numbers": {"kind": "numberSense", "prompt": "At about $5,500 a scan, roughly how much do 100 amyloid PET scans cost, in thousands of dollars?", "min": 0, "max": 1000, "value": 550, "unit": "K", "explanation": "About $550,000. Who pays for that decides how often the scan is used."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a diagnostics company that just won FDA clearance for a blood test.", "prompt": "What's the next big hurdle?", "options": ["Getting the FDA to clear it again", "Making the test more famous", "Getting payers to cover it"], "correctIndex": 2, "consequences": ["Clearance is done; coverage is next.", "Fame does not pay for tests.", "Coverage decides whether doctors order it."], "explanation": "Clearance lets a test be sold. Coverage decides whether it gets used."}, "proReasoning": "Know the path after clearance: coverage, then use. Coverage often matters as much as the technology.", "commonMistake": "Treating FDA clearance as the finish line.", "mentalModel": "Cleared, then covered."}, "invest": {"call": {"kind": "theCall", "situation": "A blood test maker celebrates FDA clearance. You are deciding whether to buy shares.", "prompt": "What should you watch next?", "options": ["Coverage decisions by payers", "The number of press releases", "How many patents it files"], "correctIndex": 0, "consequences": ["Coverage decides how often the test is used and paid for.", "Press does not drive orders.", "Patents protect; coverage pays."], "explanation": "CMS decisions can expand or limit a test's market. Watch them as closely as the FDA."}, "proReasoning": "Investors track coverage as closely as clearance. CMS decisions can expand or limit a test's market.", "commonMistake": "Pricing in sales before coverage is settled.", "mentalModel": "Coverage is the thesis."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's test is cleared, and coverage is decided region by region.", "prompt": "How should you plan your launch?", "options": ["Wait for one national rule", "Start where contractors cover it", "Launch everywhere at once"], "correctIndex": 1, "consequences": ["CMS moved away from a national rule for PET.", "Regional coverage sets where doctors can order it.", "Regions without coverage will order little."], "explanation": "Regional coverage turns a national launch into a map. Start where payers say yes."}, "proReasoning": "Founders launch where payers say yes. Regional coverage turns a national launch into a map.", "commonMistake": "Assuming one coverage answer applies everywhere.", "mentalModel": "Launch where you are covered."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why an FDA-cleared test might not be offered at their clinic.", "prompt": "What's a likely reason?", "options": ["The FDA bars clinics from using it", "Cleared tests are only for research", "Their payer may not cover it yet"], "correctIndex": 2, "consequences": ["Clearance allows use; payment is separate.", "Cleared tests can be used in clinics.", "Payers decide which tools actually get used."], "explanation": "The FDA clears; the payer covers. Both gates shape what a clinic offers."}, "proReasoning": "Explain availability with two gates: the FDA clears, the payer covers.", "commonMistake": "Assuming cleared means available everywhere.", "mentalModel": "Cleared is not covered."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c240d78cda7f$ml$]::text[]),
($ml$bb9f1dcb-911e-5faf-8795-09db58436887$ml$::uuid, $ml$neuroscience$ml$, 15, 3, $ml${"id": "neuroscience-d15-c3", "title": "Where to open the next scanner", "lessonTitle": "Who decides if Medicare pays for a scan", "slot": 3, "type": "decide", "brief": {"headline": "You run a chain of imaging centers. Since October 2023, regional Medicare contractors, not one national rule, decide coverage for amyloid PET.", "kicker": "Decide where to grow when coverage varies by region.", "fullText": "You run a chain of outpatient imaging centers and plan to add amyloid PET, which averages $5,000 to $6,000 a scan, at two new sites. Until October 13, 2023, Medicare covered one amyloid PET scan per lifetime. CMS then lifted the limit, removed its national coverage determination and ended coverage with evidence development. Regional Medicare Administrative Contractors now decide.\n\nCMS said amyloid PET can confirm amyloid pathology so clinicians can select patients for the new antibody drugs. Many patient groups had asked for a single national rule instead, and regional coverage can differ.", "sources": [{"url": "https://www.auntminnie.com/clinical-news/molecular-imaging/article/15636449/cms-lifts-limit-on-amyloid-pet-coverage", "label": "AuntMinnie, CMS lifts limit on amyloid PET coverage, Oct 2023"}, {"url": "https://www.dementiacarecentral.com/lumipulse-test", "label": "DementiaCareCentral, Lumipulse test"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Medicare once covered one amyloid PET per lifetime.", "CMS kept a single national coverage rule.", "Regional contractors now decide coverage."], "fakeIndex": 1, "explanation": "CMS removed its national coverage determination. Regional contractors decide now."}, "numbers": {"kind": "numberSense", "prompt": "A site does 400 amyloid PET scans a year at about $5,500 each. What is that in millions of dollars?", "min": 0, "max": 5, "value": 2.2, "unit": "M", "explanation": "About $2.2 million a year, if the scans are covered. Without coverage, much of it may never be paid."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You manage operations for the chain. Your boss asks why coverage differs between two sites.", "prompt": "What's the explanation?", "options": ["Different regional contractors decide", "The FDA rates each site separately", "Patients set their own coverage rules"], "correctIndex": 0, "consequences": ["Since 2023, regional contractors make PET coverage decisions.", "The FDA does not set Medicare coverage.", "Coverage rules come from payers, not patients."], "explanation": "Each region's contractor decides. The same scan can be easy to bill in one place and hard in another."}, "proReasoning": "Know who makes coverage decisions for your services. Regional contractors can make the same scan easy or hard to bill.", "commonMistake": "Assuming Medicare coverage is the same everywhere.", "mentalModel": "Know who decides coverage."}, "invest": {"call": {"kind": "theCall", "situation": "You're valuing the chain. Its growth plan assumes PET coverage everywhere.", "prompt": "What's the risk?", "options": ["The new drugs need no confirmation", "Coverage can differ by region", "CMS has banned PET scans"], "correctIndex": 1, "consequences": ["CMS said PET helps select patients for the drugs.", "Regional decisions can leave some sites with less volume.", "CMS lifted a limit; it did not ban scans."], "explanation": "A plan built on uniform coverage overstates the market under regional rules."}, "proReasoning": "Investors map revenue to coverage. A plan built on uniform coverage overstates the market under regional rules.", "commonMistake": "Assuming national demand when coverage is regional.", "mentalModel": "Map revenue to coverage."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. You must choose the next two sites.", "prompt": "What's the sound approach?", "options": ["Open where rent is cheapest", "Open everywhere and lobby later", "Open where contractors cover the scan"], "correctIndex": 2, "consequences": ["Cheap rent does not help if scans go unpaid.", "Unpaid scans drain cash while you lobby.", "Covered regions let you get paid for the scans you do."], "explanation": "Put new capacity where payers already say yes. Coverage first, then cost."}, "proReasoning": "Founders put new capacity where payers already say yes. Coverage first, then cost.", "commonMistake": "Choosing sites on cost before checking coverage.", "mentalModel": "Coverage first, then cost."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend in one state got an amyloid PET covered easily; a cousin elsewhere did not.", "prompt": "How can that be?", "options": ["Different regional contractors decide", "One of them must be lying", "PET is legal only in some states"], "correctIndex": 0, "consequences": ["Regional coverage can differ, as patient groups feared.", "Different rules, not dishonesty, explain it.", "The scan is the same; coverage varies."], "explanation": "With regional decisions, geography can change the answer."}, "proReasoning": "Explain uneven access through who decides. Regional coverage means geography can change the answer.", "commonMistake": "Assuming one person's experience applies everywhere.", "mentalModel": "Geography can change coverage."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ed766e4ac371$ml$]::text[]),
($ml$d80e09bd-d974-5df4-a75a-89c87af71823$ml$::uuid, $ml$neuroscience$ml$, 16, 1, $ml${"id": "neuroscience-d16-c1", "title": "Fifty patients, then 804", "lessonTitle": "Why most brain scan studies were too small", "slot": 1, "type": "apply", "brief": {"headline": "In 2021, Cassava said 50 patients on its Alzheimer's drug improved 18% on a cognition test, with no placebo group. In 2024, a placebo-controlled trial of 804 people found no benefit.", "kicker": "Apply the lesson: small, uncontrolled studies make big claims.", "fullText": "On July 29, 2021, Cassava Sciences reported interim results from an open-label study of simufilam: among the first 50 patients to complete nine months, scores on the ADAS-Cog11 cognition scale improved by 3.0 points, an 18% mean improvement. Open-label means everyone knew they were getting the drug, and there was no placebo group to compare with.\n\nThe test came in the Phase 3 ReThink-ALZ trial: 804 people with mild to moderate Alzheimer's at more than 75 sites, double-blind and placebo-controlled for 52 weeks. On November 26, 2024, Cassava said simufilam did not significantly slow decline in cognition or function, and missed its secondary and exploratory endpoints. It stopped the open-label extension and its second Phase 3 trial.", "sources": [{"url": "https://www.alzheimer-europe.org/news/cassava-sciences-announces-simufilam-improved-cognition-open-label-study-mild-moderate-ad", "label": "Alzheimer Europe, Cassava says simufilam improved cognition in open-label study, Jul 2021"}, {"url": "https://www.alzheimer-europe.org/news/cassava-sciencess-experimental-ad-drug-fails-phase-3-study", "label": "Alzheimer Europe, Cassava Sciences's experimental AD drug fails in Phase 3, Nov 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Which result deserves more weight?", "left": {"name": "2021 open-label study", "note": "50 patients, no placebo group"}, "right": {"name": "2024 Phase 3 trial", "note": "804 people, placebo-controlled"}, "correctIndex": 1, "explanation": "The larger, blinded, placebo-controlled trial is the real test. The small open study could not separate drug from chance."}, "numbers": {"kind": "numberSense", "prompt": "The Phase 3 trial enrolled 804 people. About how many times the 50 patients in the 2021 analysis is that?", "min": 0, "max": 40, "value": 16, "unit": "times", "explanation": "About 16 times as many people, plus a placebo group. The bigger, controlled test erased the signal."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In 2022 you're offered a job at a biotech whose case rests on a 50-patient open-label study.", "prompt": "What question protects you?", "options": ["How fast is the stock rising lately?", "How many patients said they liked it?", "When does a controlled trial read out?"], "correctIndex": 2, "consequences": ["Stock moves are not evidence.", "Without a placebo group, liking it proves little.", "Only a controlled trial can confirm the early signal."], "explanation": "The controlled readout decides whether the early claim survives, and your job with it."}, "proReasoning": "Before betting a career on early data, ask when the controlled test comes. Small open-label studies often shrink when repeated properly.", "commonMistake": "Treating an uncontrolled result as proof.", "mentalModel": "Wait for the control group."}, "invest": {"call": {"kind": "theCall", "situation": "It's 2021. Cassava's 50-patient open-label data shows an 18% improvement, and the stock soars.", "prompt": "How should you read the data?", "options": ["A small signal with no control group", "Proof that the drug clearly works", "Proof that the drug already failed"], "correctIndex": 0, "consequences": ["Without placebo, gains cannot be told apart from other causes.", "The 804-person trial later found no benefit.", "It was not a test of efficacy at all."], "explanation": "A small, open-label result is a reason to test, not a reason to believe."}, "proReasoning": "Investors discount small, uncontrolled studies heavily. The placebo-controlled trial is where most such signals vanish.", "commonMistake": "Paying for a big claim built on a small, open-label sample.", "mentalModel": "Small and open is not proof."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's drug shows strong results in a 30-patient open-label study.", "prompt": "What's the honest next step?", "options": ["Grow the open-label study only", "Run a placebo-controlled trial", "Announce that the drug works"], "correctIndex": 1, "consequences": ["More open-label patients still lack a comparison.", "Only a control group can test whether the drug caused the gains.", "Cassava's open-label gains vanished under control."], "explanation": "Treat a small open study as a hypothesis. The control group is where it gets tested."}, "proReasoning": "Founders treat small open studies as hypotheses. The control group is where the claim gets tested.", "commonMistake": "Announcing efficacy from a study that cannot show it.", "mentalModel": "Test before you claim."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a drug can help 50 patients and then fail in 804.", "prompt": "What's the best explanation?", "options": ["The 804 patients took the wrong pills", "Bigger trials are built to fail", "The first study had no placebo to compare"], "correctIndex": 2, "consequences": ["Nothing suggests a mix-up.", "Big trials are how real effects get confirmed.", "Without a comparison group, gains can come from other causes."], "explanation": "Without a placebo group, you cannot tell the drug from hope or chance."}, "proReasoning": "Explain with the missing comparison. Without a placebo group, you cannot tell the drug from hope or chance.", "commonMistake": "Assuming early improvement must come from the drug.", "mentalModel": "No comparison, no conclusion."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7777925bcb8d$ml$]::text[]),
($ml$d6fe00f9-1b81-5409-9ee3-4889b9ad4890$ml$::uuid, $ml$neuroscience$ml$, 16, 2, $ml${"id": "neuroscience-d16-c2", "title": "Sharp scanner, small sample", "lessonTitle": "Why most brain scan studies were too small", "slot": 2, "type": "connect", "brief": {"headline": "fMRI gives strong spatial detail. But the median published study linking brain scans to behavior used just 25 people, and reproducible results need thousands.", "kicker": "Connect day 13 and day 16: a sharp tool cannot save a small study.", "fullText": "On day 13 you saw fMRI's strength: it tracks blood flow to active regions with strong spatial detail. On day 16 you saw the weak link. In 2022, Scott Marek, Nico Dosenbach and colleagues analyzed nearly 50,000 participants from the ABCD Study, the Human Connectome Project and the UK Biobank. The median sample in published brain-wide association studies was 25 people, and reproducible results linking brain features to complex traits needed thousands.\n\nA sharp picture of 25 brains is still 25 brains. Marek noted that effect sizes of 0.8 appear in the literature, but nothing in nature has an effect size of 0.8.", "sources": [{"url": "https://synapse.patsnap.com/article/what-are-the-common-methods-used-in-brain-imaging-eg-fmri-pet-eeg", "label": "Patsnap Synapse, Common methods used in brain imaging"}, {"url": "https://source.washu.edu/2022/03/for-accuracy-brain-studies-of-complex-behavior-require-thousands-of-people/", "label": "Washington University, For accuracy, brain studies of complex behavior require thousands of people, Mar 2022"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each about the tool, or about the study design?", "buckets": ["The tool", "The study design"], "items": [{"text": "Strong spatial detail", "bucket": 0}, {"text": "Tracks blood flow to active regions", "bucket": 0}, {"text": "A sample of 25 people", "bucket": 1}, {"text": "Data from nearly 50,000 people", "bucket": 1}, {"text": "Results repeated in thousands", "bucket": 1}], "explanation": "fMRI's precision is a property of the tool. Whether a finding holds depends on the study design."}, "numbers": {"kind": "numberSense", "prompt": "The team analyzed data from nearly how many thousand participants?", "min": 0, "max": 120, "value": 50, "unit": "K", "explanation": "Nearly 50,000, two thousand times the median study of 25."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how you'd judge a striking fMRI finding.", "prompt": "What do you check first?", "options": ["How many people were scanned", "How sharp the images look", "Which scanner brand was used"], "correctIndex": 0, "consequences": ["The median study used 25; reliable results need thousands.", "Sharp images do not fix a small sample.", "Brand says nothing about reliability."], "explanation": "Sample size decides whether a brain-behavior finding is likely to hold."}, "proReasoning": "Judge brain-behavior claims by sample size first. Quote the 25 and the thousands.", "commonMistake": "Trusting a finding because the images look precise.", "mentalModel": "Check the sample first."}, "invest": {"call": {"kind": "theCall", "situation": "A company sells a brain-scan personality test based on a study of 30 people.", "prompt": "How do you rate the evidence?", "options": ["Fine, since 30 beats the median of 25", "Weak, since reliable results need thousands", "Strong, since fMRI is precise"], "correctIndex": 1, "consequences": ["Beating a too-small median is still too small.", "Brain-behavior results need thousands to be reproducible.", "Precision in space does not fix sample size."], "explanation": "Thirty people is far below the thousands reproducible results need."}, "proReasoning": "Investors ask how many people the evidence covers. Small samples carry hidden risk, however good the tool.", "commonMistake": "Comparing against a weak median instead of the needed size.", "mentalModel": "Beat the bar, not the median."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to build a scan-based product that predicts behavior.", "prompt": "What's the smarter evidence plan?", "options": ["Run your own 25-person study", "Skip validation and launch", "Test it on large shared datasets"], "correctIndex": 2, "consequences": ["Twenty-five is the size that produced shaky claims.", "Launching unvalidated claims invites failure.", "ABCD, HCP and UK Biobank cover tens of thousands."], "explanation": "Big public datasets now make validation at scale possible."}, "proReasoning": "Founders can now test on big public datasets. That beats running another small study.", "commonMistake": "Repeating the small-sample mistake with a new product.", "mentalModel": "Validate at scale."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend shares a headline: scans of 20 brains reveal the root of kindness.", "prompt": "What's a fair response?", "options": ["Twenty brains is far too few to be sure", "Brain scans can never show anything", "Twenty is plenty with a good scanner"], "correctIndex": 0, "consequences": ["Reliable brain-behavior links need thousands of people.", "Scans work; small samples are the problem.", "A better scanner does not fix sample size."], "explanation": "Ask how many brains before believing a scan headline."}, "proReasoning": "Ask 'how many brains?' before believing a scan headline. Thousands, not dozens, make a finding hold.", "commonMistake": "Believing a scan study because it sounds scientific.", "mentalModel": "How many brains?"}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9e7d6946d4c1$ml$]::text[]),
($ml$d24a98ec-ebed-599c-93e6-ef69ab4d7fb6$ml$::uuid, $ml$neuroscience$ml$, 16, 3, $ml${"id": "neuroscience-d16-c3", "title": "Four small studies or one big one", "lessonTitle": "Why most brain scan studies were too small", "slot": 3, "type": "decide", "brief": {"headline": "You run a brain imaging lab with money for either four new 25-person studies or one analysis of thousands of people in shared datasets.", "kicker": "Decide how to spend a research budget so results hold.", "fullText": "You run a university imaging lab studying how brain features relate to anxiety. You can fund four new studies of 25 people each, or one analysis of existing data covering thousands.\n\nDay 16 gives you the numbers. In 2022, Marek, Dosenbach and colleagues found the median published brain-wide association study used 25 people, and that reproducible results need thousands. They analyzed nearly 50,000 participants from the ABCD Study, the Human Connectome Project and the UK Biobank, datasets that together cover tens of thousands of people.", "sources": [{"url": "https://source.washu.edu/2022/03/for-accuracy-brain-studies-of-complex-behavior-require-thousands-of-people/", "label": "Washington University, For accuracy, brain studies of complex behavior require thousands of people, Mar 2022"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how a small study produces a big claim that fails.", "steps": ["A lab scans 25 people", "Chance creates a large apparent effect", "The striking result gets published", "Others try to repeat it with more people", "The effect shrinks or vanishes"], "explanation": "Small studies can find dramatic effects that vanish when repeated. Big samples stop the chain at step two."}, "numbers": {"kind": "numberSense", "prompt": "Four studies of 25 people scan how many people in total?", "min": 0, "max": 400, "value": 100, "unit": "people", "explanation": "100 people across four studies, still far short of the thousands needed."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a postdoc in the lab. Your PI asks which project will strengthen your record more.", "prompt": "Which is the better bet?", "options": ["Whichever gets published fastest", "The large shared-data analysis", "Four quick 25-person studies"], "correctIndex": 1, "consequences": ["Speed without reliability can backfire later.", "Results from thousands are more likely to hold up.", "Small studies often fail to replicate."], "explanation": "Findings that replicate build a lasting record. Large samples are now within reach."}, "proReasoning": "Researchers build careers on results that replicate. Large samples are now within reach.", "commonMistake": "Counting papers instead of findings that last.", "mentalModel": "Reliable beats numerous."}, "invest": {"call": {"kind": "theCall", "situation": "A foundation asks you, as an adviser, which grant to fund.", "prompt": "What's your recommendation?", "options": ["Fund the four small studies", "Fund neither, since imaging is useless", "Fund the analysis of thousands"], "correctIndex": 2, "consequences": ["Four small studies risk four unreliable results.", "The tool is fine; the sample was the issue.", "Reproducible brain-behavior results need thousands."], "explanation": "Fund the design that can give a reliable answer."}, "proReasoning": "Funders back designs that can produce reliable answers. Sample size is the first thing to check.", "commonMistake": "Spreading money across many underpowered studies.", "mentalModel": "Fund the sample size."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers analysis tools for brain imaging labs.", "prompt": "Which product fits the shift in the field?", "options": ["Tools for huge shared datasets", "Faster scanning for 25-person studies", "Software that inflates effect sizes"], "correctIndex": 0, "consequences": ["Labs are moving to datasets of tens of thousands.", "Faster small studies keep the old problem.", "That is the problem, not a product."], "explanation": "Big datasets need tools built for scale."}, "proReasoning": "Founders follow how research is changing. Big datasets need tools built for scale.", "commonMistake": "Building for the study design the field is leaving behind.", "mentalModel": "Build for the big datasets."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why scientists don't just run more small brain studies.", "prompt": "What's the answer?", "options": ["Large studies are against the rules", "Their big effects often vanish", "Small studies cost far too much"], "correctIndex": 1, "consequences": ["Large datasets like UK Biobank exist and are used.", "Dramatic results in 25 people often fail to repeat.", "Cost is not the issue; reliability is."], "explanation": "Many small studies multiply unreliable results instead of settling the question."}, "proReasoning": "Explain why more is not better: many small studies multiply unreliable results.", "commonMistake": "Assuming more studies always means more knowledge.", "mentalModel": "Bigger samples, sturdier findings."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:58d9cf4803c9$ml$]::text[]),
($ml$20a9169f-9d67-5cf2-8b7e-2c4ea8249550$ml$::uuid, $ml$neuroscience$ml$, 17, 1, $ml${"id": "neuroscience-d17-c1", "title": "A slower start, less swelling", "lessonTitle": "Why some patients need repeated MRIs", "slot": 1, "type": "apply", "brief": {"headline": "In July 2025, the FDA approved a slower starting schedule for the Alzheimer's drug Kisunla. In a trial of 843 people, brain swelling seen on MRI fell from 24% to 14% at 24 weeks.", "kicker": "Apply the lesson: MRI shows the risk, and dosing can change it.", "fullText": "Kisunla, Eli Lilly's donanemab, can cause ARIA-E, swelling that brain MRI detects. In TRAILBLAZER-ALZ 6, 843 participants were split across four dosing arms. The new schedule moves the second vial from the first dose to the third, so the dose builds more gradually while delivering the same total amount by week 24.\n\nARIA-E fell from 24% to 14% at week 24, a 41% lower relative risk, and from 25% to 16% at week 52. Amyloid on PET fell 67% from baseline on the new schedule against 69% on the original. ARIA with bleeding still occurred in 25% of those on the new schedule.\n\nThe drug did not change; the schedule did. MRI is how anyone knows it worked.", "sources": [{"url": "https://practicalneurology.com/news/new-titration-schedule-for-kisunladonanemab-approved-by-fda/2475633/", "label": "Practical Neurology, New titration schedule for Kisunla approved by FDA, Jul 2025"}, {"url": "https://www.fda.gov/drugs/drug-safety-and-availability/fda-recommend-additional-earlier-mri-monitoring-patients-alzheimers-disease-taking-leqembi-lecanemab", "label": "FDA, FDA to recommend additional, earlier MRI monitoring for patients taking Leqembi, Aug 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did the new Kisunla schedule change?", "options": ["The total dose by week 24", "The drug's active ingredient", "How fast the dose builds up"], "correctIndex": 2, "explanation": "The second vial moved from the first dose to the third. Same drug, same total by week 24, gentler start."}, "numbers": {"kind": "numberSense", "prompt": "ARIA-E at 24 weeks fell from 24% to 14%. What relative risk reduction was that, in percent?", "min": 0, "max": 100, "value": 41, "unit": "%", "explanation": "A 41% lower relative risk, measured by counting swelling on MRI."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a neurology nurse coordinator when the new Kisunla schedule arrives.", "prompt": "What should you still plan carefully?", "options": ["MRIs to watch for swelling", "Nothing, since ARIA is now gone", "Dropping all safety checks"], "correctIndex": 0, "consequences": ["ARIA-E still occurred in 14% at 24 weeks.", "It fell, but did not disappear.", "Swelling and bleeding still occur and need watching."], "explanation": "Lower risk is not zero risk. Scans stay part of the treatment."}, "proReasoning": "Care teams treat lower risk as lower, not zero. Scans stay part of the treatment.", "commonMistake": "Assuming a safer schedule removes the need for monitoring.", "mentalModel": "Lower risk still needs watching."}, "invest": {"call": {"kind": "theCall", "situation": "Lilly's new schedule cuts ARIA-E while clearing amyloid about as well.", "prompt": "Why might that matter for uptake?", "options": ["It ends the need for any monitoring", "Less swelling eases the load on clinics", "It doubles the drug's effect on plaque"], "correctIndex": 1, "consequences": ["ARIA still occurred, so monitoring stays.", "Fewer ARIA cases can mean fewer complications to manage.", "Amyloid clearance was similar, 67% against 69%."], "explanation": "Safer, easier dosing can widen adoption as much as a stronger drug."}, "proReasoning": "Investors watch safety changes that lower the burden of use. Easier, safer dosing can widen adoption more than a stronger drug.", "commonMistake": "Valuing only efficacy and ignoring the burden of safety monitoring.", "mentalModel": "Burden shapes uptake."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup reads safety MRIs for infusion clinics.", "prompt": "What does the new schedule mean for you?", "options": ["Your service is no longer needed", "Clinics will scan patients daily", "MRIs still matter; findings may shift"], "correctIndex": 2, "consequences": ["ARIA-E still hit 14% at 24 weeks.", "Nothing suggests daily scans.", "Swelling dropped but did not vanish, and bleeding persists."], "explanation": "A lower rate shifts the workload. It does not end it."}, "proReasoning": "Founders in safety monitoring track every change in risk. A lower rate shifts the workload; it does not end it.", "commonMistake": "Assuming a safety improvement kills the monitoring market.", "mentalModel": "Risk shifts, monitoring stays."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how doctors know a new dosing schedule is safer for the brain.", "prompt": "What's the answer?", "options": ["MRIs counted swelling in each group", "Patients all said they felt fine", "The drug label changed its color"], "correctIndex": 0, "consequences": ["ARIA-E shows on MRI, and it fell from 24% to 14%.", "Feelings cannot show swelling an MRI can detect.", "Labels do not measure safety."], "explanation": "The trial counted ARIA-E on MRI in each dosing group."}, "proReasoning": "Explain safety claims by how they were measured. Here, MRI counted swelling in each dosing group.", "commonMistake": "Thinking safety is judged by how patients feel alone.", "mentalModel": "Ask how it was measured."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8857dc269fc7$ml$]::text[]),
($ml$b2520422-25aa-50d4-a1e9-50721a1e76b5$ml$::uuid, $ml$neuroscience$ml$, 17, 2, $ml${"id": "neuroscience-d17-c2", "title": "From boxed warning to scan schedule", "lessonTitle": "Why some patients need repeated MRIs", "slot": 2, "type": "connect", "brief": {"headline": "When Leqembi won full approval in 2023, its label carried a boxed warning for ARIA. By 2025, the FDA had added an earlier MRI after identifying six deaths from brain swelling.", "kicker": "Connect day 5 and day 17: a warning becomes a schedule of scans.", "fullText": "On day 5 you saw Leqembi win traditional FDA approval on July 6, 2023, after slowing decline by 27% over 18 months, with a boxed warning for ARIA, brain scan changes such as swelling or bleeding. On day 17 you saw what that warning turned into.\n\nIn August 2025, the FDA said it had identified six fatal ARIA-E cases and 101 serious ones; five of the six fatal cases had symptoms within 8 days of their latest infusion. It added an MRI before the third infusion, on top of MRIs before the fifth, seventh and 14th, and a baseline MRI within a year before starting. A warning on the label became appointments on the calendar.", "sources": [{"url": "https://www.biospace.com/fda-grants-traditional-approval-for-leqembi-lecanemab-irmb-for-the-treatment-of-alzheimer-s-disease", "label": "Eisai and Biogen via BioSpace, Leqembi traditional approval"}, {"url": "https://www.fda.gov/drugs/drug-safety-and-availability/fda-recommend-additional-earlier-mri-monitoring-patients-alzheimers-disease-taking-leqembi-lecanemab", "label": "FDA, FDA to recommend additional, earlier MRI monitoring for patients taking Leqembi, Aug 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Leqembi's label carries a boxed warning for ARIA.", "The FDA removed MRI checks for Leqembi in 2025.", "MRIs now come before the 3rd, 5th, 7th and 14th infusions."], "fakeIndex": 1, "explanation": "The FDA added an MRI in 2025. Monitoring grew, it did not shrink."}, "numbers": {"kind": "numberSense", "prompt": "Counting the baseline scan, how many MRIs does the updated schedule call for by the 14th infusion?", "min": 0, "max": 12, "value": 5, "unit": "MRIs", "explanation": "Five: baseline, then before the 3rd, 5th, 7th and 14th infusions."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're joining a memory clinic that gives Leqembi. Your manager asks what changed in 2025.", "prompt": "What's the key update?", "options": ["The drug is now taken as a pill", "An added MRI before the 3rd infusion", "MRIs are no longer required"], "correctIndex": 1, "consequences": ["It is still given by infusion.", "The FDA added it after reviewing fatal and serious ARIA cases.", "Monitoring increased, not decreased."], "explanation": "The FDA added an earlier MRI to the schedule in August 2025."}, "proReasoning": "Know how a drug's safety schedule has changed. Clinics run on those calendars.", "commonMistake": "Working from an outdated monitoring schedule.", "mentalModel": "Know the current schedule."}, "invest": {"call": {"kind": "theCall", "situation": "The FDA adds an earlier MRI to Leqembi's label.", "prompt": "What does that mean for the drug's growth?", "options": ["Sales will jump because of the MRI", "Nothing, since scans are free", "More scans per patient may slow uptake"], "correctIndex": 2, "consequences": ["More monitoring adds burden, not demand.", "Scans add cost and need scanner access.", "Each patient needs several MRIs, and scanner access can cap growth."], "explanation": "Every added scan is cost and capacity a clinic must find."}, "proReasoning": "Investors count the monitoring burden. Every added scan is cost and capacity a clinic must find.", "commonMistake": "Ignoring safety monitoring when forecasting uptake.", "mentalModel": "Monitoring can limit uptake."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup schedules imaging for clinics. Leqembi now needs an MRI before the third infusion.", "prompt": "What product need does that create?", "options": ["Timing MRIs around infusion dates", "Replacing MRIs with phone check-ins", "Removing scans to save time"], "correctIndex": 0, "consequences": ["Each scan must land before a specific infusion.", "The label calls for MRIs, not calls.", "The label requires these scans."], "explanation": "Scans tied to specific infusions need tight scheduling."}, "proReasoning": "Founders see a new safety rule as a workflow problem. Scans tied to specific infusions need tight scheduling.", "commonMistake": "Building around the old monitoring schedule.", "mentalModel": "Rules create workflows."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend's parent on Leqembi gets many brain scans and asks why.", "prompt": "What's the reason?", "options": ["Because the drug is radioactive", "To catch brain swelling early", "To measure how smart they are"], "correctIndex": 1, "consequences": ["The scans watch for a side effect, not a tracer.", "ARIA-E is swelling an MRI can detect.", "The scans look for swelling, not intelligence."], "explanation": "The drug can cause swelling, and MRIs at set points watch for it."}, "proReasoning": "Explain monitoring by the risk it watches. The scans look for swelling the drug can cause.", "commonMistake": "Assuming scans mean the treatment is failing.", "mentalModel": "Scans watch the risk."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0e4d1d4595f0$ml$]::text[]),
($ml$dee4a32a-3455-5065-91e9-70becf54735d$ml$::uuid, $ml$neuroscience$ml$, 17, 3, $ml${"id": "neuroscience-d17-c3", "title": "Booking the scanner first", "lessonTitle": "Why some patients need repeated MRIs", "slot": 3, "type": "decide", "brief": {"headline": "You run an infusion clinic adding Leqembi for 40 patients. Each needs a baseline MRI plus scans before the 3rd, 5th, 7th and 14th infusions.", "kicker": "Decide what to secure before you start treating patients.", "fullText": "You run an infusion clinic that plans to start 40 patients on Leqembi, and it has no MRI of its own. The FDA's August 2025 update calls for a baseline MRI within a year before starting, and MRIs before the third, fifth, seventh and 14th infusions. It added the earlier scan after identifying six fatal ARIA-E cases and 101 serious ones; five of the six fatal cases had symptoms within 8 days of their latest infusion.\n\nAnti-amyloid drugs need regular brain scans to be given safely, which adds cost and needs scanner access.", "sources": [{"url": "https://www.fda.gov/drugs/drug-safety-and-availability/fda-recommend-additional-earlier-mri-monitoring-patients-alzheimers-disease-taking-leqembi-lecanemab", "label": "FDA, FDA to recommend additional, earlier MRI monitoring for patients taking Leqembi, Aug 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does the schedule call for each scan?", "buckets": ["On the schedule", "Not on it"], "items": [{"text": "A baseline MRI within a year of starting", "bucket": 0}, {"text": "An MRI before the 3rd infusion", "bucket": 0}, {"text": "An MRI before the 7th infusion", "bucket": 0}, {"text": "An MRI before the 2nd infusion", "bucket": 1}, {"text": "A PET scan before every infusion", "bucket": 1}], "explanation": "Baseline, then before the 3rd, 5th, 7th and 14th infusions. Those are the slots to book."}, "numbers": {"kind": "numberSense", "prompt": "40 patients each need 5 MRIs by the 14th infusion. How many MRIs is that?", "min": 0, "max": 500, "value": 200, "unit": "MRIs", "explanation": "200 MRIs, each tied to a specific point in a patient's schedule."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the clinic's operations lead. The first patients start next month.", "prompt": "What must be locked in first?", "options": ["A bigger waiting room", "A new logo for the clinic", "MRI slots at the right times"], "correctIndex": 2, "consequences": ["Space helps, but scans gate the treatment.", "Branding does not affect safety rules.", "Scans must land before set infusions on the schedule."], "explanation": "For these drugs, MRI access gates every step of treatment."}, "proReasoning": "Operations leads secure the gating resource first. For these drugs, MRI access gates every step.", "commonMistake": "Starting patients before scanner time is secured.", "mentalModel": "Secure the gate first."}, "invest": {"call": {"kind": "theCall", "situation": "You're backing a chain of infusion clinics that plans to scale Leqembi fast.", "prompt": "What's the most likely bottleneck?", "options": ["MRI capacity near each clinic", "The supply of infusion chairs", "Demand from patients"], "correctIndex": 0, "consequences": ["Each patient needs five MRIs by the 14th infusion.", "Chairs matter, but MRIs gate each step.", "Demand is not what the schedule limits."], "explanation": "Scanner access can cap how fast these drugs grow."}, "proReasoning": "Investors find the resource that gates growth. For anti-amyloid drugs, scanner access can cap expansion.", "commonMistake": "Forecasting growth from demand without checking MRI capacity.", "mentalModel": "Find the gating resource."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're founding a company to support clinics that give anti-amyloid drugs.", "prompt": "Which product solves the biggest pain?", "options": ["A wellness app for caregivers only", "Booking and reading safety MRIs on time", "Selling the drug itself at a discount"], "correctIndex": 1, "consequences": ["Useful, but not the clinical bottleneck.", "Clinics must schedule and read many safety MRIs.", "You cannot discount another company's drug."], "explanation": "The safety rules create a lot of imaging work. Build there."}, "proReasoning": "Founders build where safety rules create work. Clinics must schedule and read many MRIs, fast.", "commonMistake": "Building around the drug rather than the work it requires.", "mentalModel": "Build where rules create work."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their grandmother's Alzheimer's treatment comes with so many scans.", "prompt": "What's the reason?", "options": ["Scans make the drug work better", "Clinics add scans to raise bills", "The label sets MRIs at fixed points"], "correctIndex": 2, "consequences": ["Scans watch for side effects; they do not treat.", "The schedule comes from the FDA label.", "The FDA set MRIs before key infusions to catch swelling."], "explanation": "For these drugs, imaging is part of the safety rules."}, "proReasoning": "Explain scans as part of the treatment. For these drugs, safety rules make imaging a step in every course.", "commonMistake": "Assuming extra scans mean extra illness.", "mentalModel": "Scans are part of the treatment."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6dd90c6672d0$ml$]::text[]),
($ml$8c53d606-dea6-5d9e-8944-aa2652217a0a$ml$::uuid, $ml$neuroscience$ml$, 18, 1, $ml${"id": "neuroscience-d18-c1", "title": "70 teams, one brain dataset", "lessonTitle": "When a dead fish lit up a brain scan", "slot": 1, "type": "apply", "brief": {"headline": "In 2020, 70 research teams analyzed the same fMRI data from 108 people to test nine hypotheses. Their conclusions differed significantly for five of the nine.", "kicker": "Apply the lesson: analysis choices can change what a scan seems to show.", "fullText": "The Neuroimaging Analysis Replication and Prediction Study, published in Nature on May 20, 2020, gave 70 teams, 180 researchers in all, the same brain scans of 108 people doing a task about gambles with possible gains and losses. Each team chose its own analysis method, software and definitions.\n\nResults varied significantly across teams for five of the nine hypotheses, even though early-stage analyses showed consensus among most teams. Experts and the researchers themselves, betting in prediction markets, were overly optimistic. Russell Poldrack noted the many choices at each step of the analysis. The authors urged running and reporting multiple analyses and sharing data and code.\n\nThe dead salmon showed that uncorrected statistics can invent a signal. NARPS showed that reasonable choices can move one.", "sources": [{"url": "https://www.sciencedaily.com/releases/2020/05/200520191245.htm", "label": "ScienceDaily, Complex analytical methods contribute to variability of research outcomes, May 2020"}, {"url": "https://significancemagazine.com/the-lab-of-the-thinking-dead-2/", "label": "Significance, The lab of the thinking dead"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how 70 teams reached different answers.", "steps": ["Teams receive the same fMRI scans", "Each picks its own analysis method", "Early analyses largely agree", "Different choices add up step by step", "Conclusions split on five of nine hypotheses"], "explanation": "No team had to be wrong. Many reasonable choices, stacked up, moved the final answers."}, "numbers": {"kind": "numberSense", "prompt": "How many teams analyzed the same dataset?", "min": 0, "max": 200, "value": 70, "unit": "teams", "explanation": "70 teams and 180 researchers, with conclusions that split on five of nine hypotheses."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for an imaging analyst job. They ask how you'd make results more trustworthy.", "prompt": "What's the strongest answer?", "options": ["Use whichever software is fastest", "Run several analyses and report them all", "Pick the analysis with the best result"], "correctIndex": 1, "consequences": ["Speed does not address analysis choices.", "That is what the NARPS authors recommended.", "Choosing the best-looking result is how false signals spread."], "explanation": "Results that hold across several reasonable analyses are the ones to trust."}, "proReasoning": "Show you know analysis choices matter. Running and reporting several analyses separates sturdy findings from fragile ones.", "commonMistake": "Treating one analysis path as the truth.", "mentalModel": "Many paths, one sturdy answer."}, "invest": {"call": {"kind": "theCall", "situation": "A neurotech startup's key claim rests on one team's analysis of one fMRI dataset.", "prompt": "What should you ask for?", "options": ["A more colorful brain image for the deck", "A bigger budget for marketing it", "An independent reanalysis of the data"], "correctIndex": 2, "consequences": ["Pictures do not test the analysis.", "Marketing cannot fix fragile results.", "NARPS showed different teams can reach different conclusions."], "explanation": "One team's answer may be one of several possible answers. Ask a second analyst."}, "proReasoning": "Investors ask whether a finding survives other analysts. NARPS showed one team's result can be one of many possible answers.", "commonMistake": "Trusting one analysis because it looks precise.", "mentalModel": "Ask for a second analyst."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells fMRI analysis software.", "prompt": "Which feature answers the NARPS problem?", "options": ["Running many pipelines side by side", "Making results look more dramatic", "Hiding the analysis settings"], "correctIndex": 0, "consequences": ["Users can see which results hold across choices.", "Drama makes the problem worse.", "Hidden settings block the sharing NARPS urged."], "explanation": "Side-by-side pipelines show which results are robust."}, "proReasoning": "Founders build tools that make rigor easy. Side-by-side pipelines show which results are robust.", "commonMistake": "Building features that reward cherry-picking.", "mentalModel": "Make robustness visible."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how 70 expert teams could disagree about the same brain scans.", "prompt": "What's the best explanation?", "options": ["The teams scanned different people", "Each made different reasonable choices", "Most teams made basic errors"], "correctIndex": 1, "consequences": ["Every team got the same 108 people's scans.", "Software, models and definitions varied at every step.", "Their early analyses largely agreed."], "explanation": "Small, reasonable differences can add up to different conclusions."}, "proReasoning": "Explain analysis as a chain of choices. Small, reasonable differences can add up to different conclusions.", "commonMistake": "Assuming disagreement means someone cheated.", "mentalModel": "Choices add up."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b86224a6d797$ml$]::text[]),
($ml$39d71b65-986b-59f9-8d66-c078bf6c6842$ml$::uuid, $ml$neuroscience$ml$, 18, 2, $ml${"id": "neuroscience-d18-c2", "title": "Two ways to see a ghost", "lessonTitle": "When a dead fish lit up a brain scan", "slot": 2, "type": "connect", "brief": {"headline": "A dead salmon showed brain activity until the statistics were corrected. Meanwhile, the median brain-behavior scan study used 25 people. Both traps produce signals that are not there.", "kicker": "Connect day 16 and day 18: small samples and uncorrected tests.", "fullText": "On day 16 you saw that the median published brain-wide association study used 25 people, and that reproducible results need thousands. Small studies can find dramatic effects that vanish when repeated.\n\nOn day 18 you saw the other trap. Craig Bennett's team scanned a dead salmon, and several voxels passed a p < 0.001 threshold until they corrected for multiple comparisons. In 2016, Eklund, Nichols and Knutsson reported that common fMRI cluster methods could produce false positive rates of up to 70%, though Nichols later estimated only about 10% of studies used the affected tests. Brain scans run thousands of tests at once.", "sources": [{"url": "https://source.washu.edu/2022/03/for-accuracy-brain-studies-of-complex-behavior-require-thousands-of-people/", "label": "Washington University, For accuracy, brain studies of complex behavior require thousands of people, Mar 2022"}, {"url": "https://significancemagazine.com/the-lab-of-the-thinking-dead-2/", "label": "Significance, The lab of the thinking dead"}, {"url": "https://brainfacts.org/in-the-lab/tools-and-techniques/2016/are-fmri-data-analysis-methods-reliable", "label": "BrainFacts, Are fMRI data analysis methods reliable?, 2016"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which trap does each fact belong to?", "buckets": ["Small samples", "Many tests at once"], "items": [{"text": "A median study of 25 people", "bucket": 0}, {"text": "Reproducible results need thousands", "bucket": 0}, {"text": "Dramatic effects that vanish when repeated", "bucket": 0}, {"text": "A dead salmon lighting up", "bucket": 1}, {"text": "Fixed by correcting for multiple comparisons", "bucket": 1}, {"text": "False positive rates of up to 70%", "bucket": 1}], "explanation": "Two different traps, one result: signals that are not real. Large samples fix one; correction fixes the other."}, "numbers": {"kind": "numberSense", "prompt": "Nichols later estimated about what share of studies used the affected tests?", "min": 0, "max": 50, "value": 10, "unit": "%", "explanation": "About 10%. A real problem, but narrower than the 70% headline suggested."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked to review a colleague's fMRI paper before submission.", "prompt": "Which two checks matter most?", "options": ["The color scheme and the figure fonts", "The author list and the title length", "Sample size and multiple-comparison fixes"], "correctIndex": 2, "consequences": ["Presentation does not affect validity.", "Neither affects whether the result is real.", "Those are the two traps that create false signals."], "explanation": "Too few people and too many uncorrected tests are the classic traps."}, "proReasoning": "Reviewers check the two classic traps first: too few people and too many uncorrected tests.", "commonMistake": "Reviewing presentation before statistics.", "mentalModel": "Sample, then correction."}, "invest": {"call": {"kind": "theCall", "situation": "A neuromarketing firm shows a brain scan study of 20 shoppers with uncorrected results.", "prompt": "How do you treat its claims?", "options": ["As unproven on two counts", "As strong, since scans are objective", "As proven, since it was published"], "correctIndex": 0, "consequences": ["Too few people and no correction both invite false signals.", "Scans can mislead without proper statistics.", "Publication does not fix a small, uncorrected study."], "explanation": "A small, uncorrected study has two independent ways to be wrong."}, "proReasoning": "Investors stack the red flags. A small, uncorrected study has two independent ways to be wrong.", "commonMistake": "Treating scan data as objective by default.", "mentalModel": "Count the red flags."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup plans a brain-scan study to show its product works.", "prompt": "What design protects you most?", "options": ["Uncorrected results, for bigger effects", "Thousands of people, corrected statistics", "Twenty people, to move fast"], "correctIndex": 1, "consequences": ["Uncorrected tests can make a dead fish light up.", "That avoids both traps at once.", "Small samples produce claims that fail."], "explanation": "Large samples and corrected statistics avoid both traps."}, "proReasoning": "Founders design studies to survive scrutiny. Large samples and corrected statistics avoid the two classic traps.", "commonMistake": "Designing a study to look impressive rather than hold up.", "mentalModel": "Design to survive scrutiny."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend laughs at the dead salmon study and asks what it proved.", "prompt": "What's the point of it?", "options": ["Fish can keep thinking after death", "fMRI scanners are all broken", "Uncorrected tests can invent activity"], "correctIndex": 2, "consequences": ["The salmon was dead; the signal was a fluke.", "The scanner worked; the statistics needed fixing.", "The activity vanished once tests were corrected."], "explanation": "Test enough spots, and some light up by chance. Correction removes them."}, "proReasoning": "Use the salmon to explain multiple comparisons: test enough spots, and some light up by chance.", "commonMistake": "Thinking the salmon study was a joke with no lesson.", "mentalModel": "Test enough, find flukes."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9312124dc6ba$ml$]::text[]),
($ml$de882225-3da8-5a07-a1bf-125e6e737e7e$ml$::uuid, $ml$neuroscience$ml$, 18, 3, $ml${"id": "neuroscience-d18-c3", "title": "The client wants the uncorrected map", "lessonTitle": "When a dead fish lit up a brain scan", "slot": 3, "type": "decide", "brief": {"headline": "You run a neuromarketing agency. A client loves an fMRI map from 24 shoppers that lights up only before correcting for multiple comparisons.", "kicker": "Decide what to report when the exciting result is a likely fluke.", "fullText": "You run an agency that uses fMRI to test how shoppers respond to ads. Your latest study scanned 24 people. Before correction, several brain regions light up for the client's new ad. After correcting for multiple comparisons, nothing survives.\n\nDay 18 says why that matters. A dead salmon once showed apparent activity at p < 0.001 until the team corrected for multiple comparisons, and common fMRI cluster methods could produce false positive rates of up to 70%. Brain scans run thousands of tests at once, and without correction, flukes look like findings.", "sources": [{"url": "https://significancemagazine.com/the-lab-of-the-thinking-dead-2/", "label": "Significance, The lab of the thinking dead"}, {"url": "https://brainfacts.org/in-the-lab/tools-and-techniques/2016/are-fmri-data-analysis-methods-reliable", "label": "BrainFacts, Are fMRI data analysis methods reliable?, 2016"}]}, "evidence": {"kind": "faceOff", "prompt": "Which result should you present as the finding?", "left": {"name": "The uncorrected map", "note": "Several regions light up"}, "right": {"name": "The corrected map", "note": "Nothing survives correction"}, "correctIndex": 1, "explanation": "The corrected map is the finding. The uncorrected one is what made a dead salmon look alive."}, "numbers": {"kind": "numberSense", "prompt": "A scan runs 10,000 tests at p < 0.001 with no real effect. About how many false hits would chance produce?", "min": 0, "max": 50, "value": 10, "unit": "hits", "explanation": "0.001 times 10,000 is about 10 false hits, enough to make a dead fish light up."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the agency's lead analyst. The account manager wants the uncorrected map in the deck.", "prompt": "What do you do?", "options": ["Report the corrected result and explain", "Use the uncorrected map, as asked", "Delete the study and say nothing at all"], "correctIndex": 0, "consequences": ["Corrected statistics are what make a finding real.", "That is how a dead salmon appeared to think.", "Hiding results loses the client's trust too."], "explanation": "Report what survives correction, and explain why that is the honest answer."}, "proReasoning": "Analysts protect the work by reporting corrected results. Explaining why is part of the job.", "commonMistake": "Letting a client's excitement pick the statistics.", "mentalModel": "Correct, then report."}, "invest": {"call": {"kind": "theCall", "situation": "You're thinking of buying the agency. Its pitch deck is full of uncorrected brain maps.", "prompt": "What does that tell you?", "options": ["Its clients will always be happy", "Its results may not hold up", "Its science is the most advanced"], "correctIndex": 1, "consequences": ["Happy clients today can leave when results fail.", "Uncorrected maps can show activity that is not there.", "Advanced tools still mislead without correction."], "explanation": "Uncorrected maps are a liability, not an asset."}, "proReasoning": "Investors check whether a firm's evidence is corrected and repeated. Uncorrected maps are a liability, not an asset.", "commonMistake": "Mistaking impressive images for solid results.", "mentalModel": "Corrected and repeated, or pass."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. A rival agency wins deals with dramatic uncorrected maps.", "prompt": "How do you compete?", "options": ["Copy their dramatic uncorrected maps", "Cut prices and skip the statistics", "Sell rigor: corrected results that hold"], "correctIndex": 2, "consequences": ["Their maps may be flukes, and so would yours.", "Cheaper flukes are still flukes.", "Results that replicate build lasting trust with clients."], "explanation": "After the salmon, results that hold up are a selling point."}, "proReasoning": "Founders can make rigor the selling point. After the salmon, results that hold up stand apart.", "commonMistake": "Matching a rival's shortcuts to win a deal.", "mentalModel": "Rigor is the moat."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend sees an ad claiming brain scans prove it's the most exciting ad ever.", "prompt": "What should they ask?", "options": ["Were the results corrected and repeated?", "Which scanner brand did they use?", "How bright were the colors in the image?"], "correctIndex": 0, "consequences": ["Those two checks separate findings from flukes.", "The brand does not fix the statistics.", "Colors are a display choice."], "explanation": "Correction and replication separate real findings from flukes."}, "proReasoning": "Teach two questions for any brain-scan claim: was it corrected, and has it been repeated?", "commonMistake": "Trusting a claim because it shows a brain image.", "mentalModel": "Corrected? Repeated?"}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:028b8e2fa4b1$ml$]::text[]),
($ml$ce71a594-04bc-5410-ac0a-f519b3f238ab$ml$::uuid, $ml$neuroscience$ml$, 19, 1, $ml${"id": "neuroscience-d19-c1", "title": "The tag that keeps a memory", "lessonTitle": "The patient who could not form memories", "slot": 1, "type": "apply", "brief": {"headline": "Synapse proteins are replaced within days, yet memories last for years. In 2024, researchers showed a molecule called KIBRA tags strengthened synapses so a key protein keeps them strong.", "kicker": "Apply the lesson: memory lives in the strength of connections.", "fullText": "PKMzeta is the best-known molecule for strengthening synapses in mammals, but it breaks down within a few days. In a study in Science Advances in June 2024, a team led by André Fenton at NYU and Todd Sacktor at SUNY Downstate showed how memory survives that turnover. KIBRA sits at strongly activated synapses, avoids weak ones, and binds PKMzeta, so each new copy of the protein lands where the old one was.\n\nIn mice, breaking the bond between KIBRA and PKMzeta erased old memories. Sacktor compared it to the Ship of Theseus, every part replaced while the ship stays the same, and credited Francis Crick with a similar idea in 1984.\n\nDay 19's rule in molecular form: learning strengthens connections, and keeping a memory means keeping them strong.", "sources": [{"url": "https://www.sciencedaily.com/releases/2024/06/240626152118.htm", "label": "ScienceDaily via NYU, How do our memories last a lifetime?, Jun 2024"}, {"url": "https://en.wikipedia.org/wiki/Long-term_potentiation", "label": "Long-term potentiation, overview"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the memory-keeping mechanism in order.", "steps": ["Learning strongly activates some synapses", "KIBRA settles at those synapses", "KIBRA binds PKMzeta, keeping them strong", "Old PKMzeta breaks down within days", "New PKMzeta lands on the same tags"], "explanation": "The proteins come and go. The tag stays, so the strengthened connections stay strong."}, "numbers": {"kind": "numberSense", "prompt": "Francis Crick proposed a similar idea in 1984. How many years before the 2024 study was that?", "min": 0, "max": 100, "value": 40, "unit": "years", "explanation": "Forty years from idea to mechanism. Good questions can wait a long time for the tools to answer them."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a memory research lab. They ask what the KIBRA study adds.", "prompt": "What's the best answer?", "options": ["It found memories stored as tidy files", "It proved that memories never fade away", "It shows how strong synapses stay strong"], "correctIndex": 2, "consequences": ["Memories live in connection strength, not files.", "Breaking the bond erased memories, so they can fade.", "KIBRA keeps PKMzeta at strengthened synapses despite turnover."], "explanation": "The study explains how strengthened connections last while their proteins are replaced."}, "proReasoning": "Tie a new finding to the core idea: memory lives in connection strength. The KIBRA tag explains how that strength lasts.", "commonMistake": "Describing memory as stored files instead of connections.", "mentalModel": "Memory is connection strength."}, "invest": {"call": {"kind": "theCall", "situation": "A startup wants to boost PKMzeta to treat memory loss, citing the KIBRA work.", "prompt": "What's the key caution?", "options": ["The work so far is in mice", "PKMzeta has nothing to do with memory", "Memories cannot be erased at all"], "correctIndex": 0, "consequences": ["Mouse results must still be shown in people.", "It is the best-known molecule for strengthening synapses.", "Breaking the KIBRA bond erased mouse memories."], "explanation": "A mechanism in mice is a starting point. It is not yet a treatment for people."}, "proReasoning": "Investors separate a mechanism found in mice from a treatment for people. Day 5's odds apply to every new target.", "commonMistake": "Treating a mouse mechanism as a human therapy.", "mentalModel": "Mouse first, people later."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's supplement ad wants to say it locks in memories, citing the KIBRA study.", "prompt": "What should you do?", "options": ["Promise memories that last forever", "Drop the claim; the work is in mice", "Cite the study as proof in people"], "correctIndex": 1, "consequences": ["Nothing in the study supports that promise.", "Claims need human evidence, not mouse mechanisms.", "The study used mice and tested no supplement."], "explanation": "A lab mechanism is not evidence that a product works."}, "proReasoning": "Founders keep claims inside the evidence. A mechanism in mice is not proof that a product works in people.", "commonMistake": "Borrowing a lab finding as a marketing claim.", "mentalModel": "Mechanism is not proof."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how memories last for years if brain proteins are replaced every few days.", "prompt": "What's the answer?", "options": ["The same proteins last a lifetime", "Memories are stored outside the brain", "A tag keeps new proteins at the same spots"], "correctIndex": 2, "consequences": ["PKMzeta breaks down within days.", "They live in connections between neurons.", "KIBRA marks strengthened synapses for new PKMzeta."], "explanation": "Like the Ship of Theseus, the parts are replaced while the tag keeps the pattern."}, "proReasoning": "Explain lasting memory with the Ship of Theseus: parts are replaced, and the tag keeps the shape.", "commonMistake": "Assuming memories need permanent molecules.", "mentalModel": "The parts change, the pattern stays."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0a7f40369659$ml$]::text[]),
($ml$213464ad-7c6c-5d5e-8400-af1ea1963cd6$ml$::uuid, $ml$neuroscience$ml$, 19, 2, $ml${"id": "neuroscience-d19-c2", "title": "The structure that files memories", "lessonTitle": "The patient who could not form memories", "slot": 2, "type": "connect", "brief": {"headline": "Day 1 named the hippocampus as the structure that sends memories to storage and retrieves them. In 1953, Henry Molaison lost it on both sides, and with it the power to form new memories.", "kicker": "Connect day 1 and day 19: the map predicted the loss.", "fullText": "On day 1 you learned that deep, paired structures in the limbic system govern emotions and memories, and that the hippocampus sends memories off to be stored and later retrieves them. On day 19 you met the patient who showed it.\n\nIn 1953, surgeons removed Henry Molaison's hippocampus on both sides to stop his seizures. Afterward he could not form new long-term memories, though his short-term memory was intact and he still improved at skills such as mirror tracing without remembering the practice. Brenda Milner and later Suzanne Corkin studied him for decades. The loss matched the region's job, and showed memory runs on more than one system.", "sources": [{"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}, {"url": "https://bcs.mit.edu/news/unforgettable-life", "label": "MIT Brain and Cognitive Sciences, An unforgettable life"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which ability did Henry Molaison keep after surgery?", "options": ["Recalling each practice session", "Getting better at mirror tracing", "Forming new long-term memories"], "correctIndex": 1, "explanation": "He improved at mirror tracing without remembering any of the practice. Skills ran on a different system."}, "numbers": {"kind": "numberSense", "prompt": "Henry Molaison lived about how many years after his surgery?", "min": 0, "max": 100, "value": 55, "unit": "years", "explanation": "About 55 years without forming new long-term memories, and decades of research that shaped the field."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why Henry Molaison matters to neuroscience.", "prompt": "What's the strongest answer?", "options": ["He showed memory has separate systems", "He proved the hippocampus does nothing", "He lost every kind of memory"], "correctIndex": 0, "consequences": ["He lost new long-term memories but kept skills and short-term memory.", "Removing it took away new long-term memories.", "His short-term memory and skill learning stayed."], "explanation": "His case split memory into systems: new facts and events lost, skills kept."}, "proReasoning": "Use the right terms: long-term memory for facts and events, and skill learning, which can survive without the hippocampus.", "commonMistake": "Saying he lost all memory.", "mentalModel": "Separate systems, separate losses."}, "invest": {"call": {"kind": "theCall", "situation": "A company's drug targets the hippocampus to help people form new memories.", "prompt": "Which memory system is it aiming at?", "options": ["Short-term memory on its own", "Forming new long-term memories", "Learning new motor skills"], "correctIndex": 1, "consequences": ["His short-term memory survived the surgery.", "That is what Molaison lost when his hippocampus was removed.", "Molaison kept skill learning without his hippocampus."], "explanation": "The hippocampus maps to forming new long-term memories."}, "proReasoning": "Know which memory system a treatment aims at. The hippocampus maps to forming new long-term memories.", "commonMistake": "Treating memory as one thing.", "mentalModel": "Name the memory system."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're designing tools for people with damage to the hippocampus.", "prompt": "What can your product build on?", "options": ["New fact memory, which is intact", "Nothing, since all memory is gone", "Skill learning, which can survive"], "correctIndex": 2, "consequences": ["Forming new long-term memories is what is lost.", "Skills and short-term memory can remain.", "Molaison improved at mirror tracing without recalling practice."], "explanation": "Build on the system that still works: skill learning."}, "proReasoning": "Founders build on what still works. Skill learning survived in Molaison, so rehab can train through it.", "commonMistake": "Designing as if all memory were lost.", "mentalModel": "Build on what remains."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how someone could learn a skill without remembering practicing it.", "prompt": "What's the explanation?", "options": ["Skills use a different memory system", "He was secretly remembering it all", "Skills need no brain at all to learn"], "correctIndex": 0, "consequences": ["Molaison's case showed skills do not need the hippocampus.", "He showed no memory of the practice.", "Skills rely on the brain, just on different systems."], "explanation": "Facts and skills are stored by different systems, so one can fail while the other works."}, "proReasoning": "Explain with Molaison: facts and skills are stored by different systems, so one can fail while the other works.", "commonMistake": "Thinking memory is a single store.", "mentalModel": "More than one memory."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:85bcef432e6d$ml$]::text[]),
($ml$3f14688f-dc48-5372-a469-e589c776752a$ml$::uuid, $ml$neuroscience$ml$, 19, 3, $ml${"id": "neuroscience-d19-c3", "title": "Train the skill, not the fact", "lessonTitle": "The patient who could not form memories", "slot": 3, "type": "decide", "brief": {"headline": "You run a rehab startup for people who cannot form new memories after damage to the hippocampus. Henry Molaison could not recall practice, yet his skills still improved.", "kicker": "Decide what your rehab product should train.", "fullText": "You run a startup building rehab programs for people with damage to the hippocampus. Day 19's evidence: after surgery removed his hippocampus on both sides, Henry Molaison could not form new long-term memories, but his short-term memory was intact and he improved at mirror tracing without remembering the practice.\n\nIn 1973, Bliss and Lømo described long-term potentiation, a lasting strengthening of connections between neurons, widely seen as a cellular basis of learning. Learning means changing the strength of connections, and not every kind of learning runs through the hippocampus.", "sources": [{"url": "https://bcs.mit.edu/news/unforgettable-life", "label": "MIT Brain and Cognitive Sciences, An unforgettable life"}, {"url": "https://en.wikipedia.org/wiki/Long-term_potentiation", "label": "Long-term potentiation, overview"}]}, "evidence": {"kind": "sortSignal", "prompt": "Did Henry Molaison keep or lose each ability?", "buckets": ["Kept", "Lost"], "items": [{"text": "Short-term memory", "bucket": 0}, {"text": "Improving at mirror tracing", "bucket": 0}, {"text": "Getting better with practice", "bucket": 0}, {"text": "Forming new long-term memories", "bucket": 1}, {"text": "Recalling the practice sessions", "bucket": 1}], "explanation": "Skills and short-term memory stayed. New long-term memories, including memories of practice, did not form."}, "numbers": {"kind": "numberSense", "prompt": "Molaison's surgery was in 1953, and long-term potentiation was described in 1973. How many years apart?", "min": 0, "max": 60, "value": 20, "unit": "years", "explanation": "Twenty years from the patient who showed the loss to the mechanism behind learning."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the startup's first clinician. The CEO asks which therapy to build first.", "prompt": "What do you recommend?", "options": ["Daily quizzes on new facts", "Repeated practice of daily skills", "Lectures that users must recall"], "correctIndex": 1, "consequences": ["New fact memory is the damaged system.", "Skill learning survived in Molaison without recall.", "Recalling new facts is what is lost."], "explanation": "Design around the system that still works. Practice builds skill without needing recall."}, "proReasoning": "Clinicians design around the intact system. Practice-based skill training works even when recall does not.", "commonMistake": "Designing therapy that depends on the lost memory system.", "mentalModel": "Train through what works."}, "invest": {"call": {"kind": "theCall", "situation": "The startup pitches you a skill-training rehab product.", "prompt": "Which fact best supports its approach?", "options": ["Molaison's short-term memory was lost", "The hippocampus stores all skills", "Molaison improved at skills without recall"], "correctIndex": 2, "consequences": ["His short-term memory was intact.", "Skills survived its removal.", "Skill learning can work without the hippocampus."], "explanation": "The product's design matches the science: skill learning survives hippocampal loss."}, "proReasoning": "Investors check that a product's design matches the science. Here, skill learning surviving hippocampal loss is the key fact.", "commonMistake": "Backing a rehab product that relies on the lost system.", "mentalModel": "Design must match the science."}, "build_startup": {"call": {"kind": "theCall", "situation": "Users improve at tasks but say they never practiced. Your team worries the app isn't working.", "prompt": "How should you measure success?", "options": ["Track performance, not memory of practice", "Ask users if they recall the sessions", "Shut the program down as a failure"], "correctIndex": 0, "consequences": ["Gains can grow even when practice is forgotten.", "They may not recall, yet still improve.", "Molaison improved without recalling practice."], "explanation": "For skill training, performance is the outcome. Recall is the system that is damaged."}, "proReasoning": "Founders measure what the product changes. For skill training, performance is the outcome, not recall.", "commonMistake": "Judging success by a memory the user cannot form.", "mentalModel": "Measure performance, not recall."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how practice can help someone who forgets each session.", "prompt": "What's the answer?", "options": ["They secretly remember each session", "Practice still strengthens connections", "Practice does nothing without recall"], "correctIndex": 1, "consequences": ["He showed no memory of practicing.", "Learning means changing connection strength, recalled or not.", "Molaison improved without recall."], "explanation": "Skills can strengthen even when the memory of practice is gone."}, "proReasoning": "Explain learning as changing connections. Skills can strengthen even when the memory of practice is gone.", "commonMistake": "Thinking learning requires remembering the lesson.", "mentalModel": "Practice changes the wiring."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:76a1e2f7edbe$ml$]::text[]),
($ml$8d99bfc7-f1db-5cdb-a5e6-03878d7f3d04$ml$::uuid, $ml$neuroscience$ml$, 20, 1, $ml${"id": "neuroscience-d20-c1", "title": "Medicare pays for dementia support", "lessonTitle": "What memory loss costs America", "slot": 1, "type": "apply", "brief": {"headline": "In July 2024, Medicare launched GUIDE, an 8-year model paying dementia care programs a monthly fee per patient. It funds a 24/7 support line and up to $2,500 a year of caregiver respite.", "kicker": "Apply the lesson: the biggest payer reshapes dementia care.", "fullText": "GUIDE, short for Guiding an Improved Dementia Experience, began on July 1, 2024. Participating programs, 292 in CMS's summary, receive tiered monthly payments per patient, based on the patient's complexity and the caregiver's burden and adjusted by quality measures.\n\nThe payments cover care navigators who connect families to clinical and community services, a 24/7 support line, caregiver training and education, and screening for social needs. For qualifying caregivers, GUIDE pays for respite, such as in-home care or adult day programs, up to $2,500 per patient per year.\n\nDay 20 showed that Medicare and Medicaid pay 64% of dementia care costs, and that unpaid caregivers gave more than 19 billion hours in 2025. GUIDE is the biggest payer starting to fund some of that unpaid work.", "sources": [{"url": "https://www.cms.gov/priorities/innovation/innovation-models/guide", "label": "CMS, Guiding an Improved Dementia Experience (GUIDE) Model"}, {"url": "https://www.alz.org/facts-and-figures", "label": "Alzheimer's Association, 2026 Alzheimer's disease facts and figures"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how GUIDE reaches a family.", "steps": ["A Medicare patient with dementia joins a GUIDE program", "A care navigator assesses patient and caregiver", "The program gets a monthly payment, tiered by need", "The family gets support, training and a 24/7 line", "Qualifying caregivers get up to $2,500 of respite"], "explanation": "The payer funds the program, and the program funds support that families used to give alone."}, "numbers": {"kind": "numberSense", "prompt": "GUIDE is set to run for how many years?", "min": 0, "max": 20, "value": 8, "unit": "years", "explanation": "Eight years, long enough to test whether paying for support changes dementia care."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're offered a care navigator job at a GUIDE program.", "prompt": "What's the core of the role?", "options": ["Connecting families to care and support", "Prescribing new Alzheimer's drugs", "Reading brain scans for the clinic"], "correctIndex": 0, "consequences": ["Navigators link patients and caregivers to clinical and community services.", "Navigation is coordination, not prescribing.", "Scans are not part of the navigator role."], "explanation": "GUIDE pays for coordination and caregiver support, so that is the job."}, "proReasoning": "Know what the payer is buying. GUIDE pays for coordination and caregiver support, so that is the job.", "commonMistake": "Assuming dementia jobs are only clinical.", "mentalModel": "Know what the payer buys."}, "invest": {"call": {"kind": "theCall", "situation": "A home care company says GUIDE will transform its revenue.", "prompt": "What should you check?", "options": ["Whether dementia is becoming rare", "Whether it can join and meet GUIDE terms", "Whether its logo looks trustworthy"], "correctIndex": 1, "consequences": ["7.4 million Americans 65 and older have Alzheimer's in 2026.", "Payments go to participating programs and adjust for quality.", "Branding does not earn GUIDE payments."], "explanation": "A new payment helps only the providers who join and perform."}, "proReasoning": "Investors check who can actually collect a new payment. A model helps only the providers who join and perform.", "commonMistake": "Assuming every provider benefits from a new payment model.", "mentalModel": "Who can collect?"}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers respite care for dementia caregivers.", "prompt": "How does GUIDE change your plan?", "options": ["Ignore it, since families pay for everything", "Bill GUIDE as if you made a drug", "Partner with GUIDE programs that fund respite"], "correctIndex": 2, "consequences": ["Medicare now pays for some respite through GUIDE.", "GUIDE pays programs for care services, not drugs.", "GUIDE pays up to $2,500 a year per patient for respite."], "explanation": "When the biggest payer funds respite, respite providers gain a customer."}, "proReasoning": "Founders follow new payment streams. When the biggest payer funds respite, respite providers gain a customer.", "commonMistake": "Selling only to families when a payer now funds the service.", "mentalModel": "Follow the new payment."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend caring for a parent with dementia hears Medicare now helps caregivers.", "prompt": "What is GUIDE?", "options": ["A Medicare dementia support model", "A new Alzheimer's drug on the market", "A private insurance plan for seniors"], "correctIndex": 0, "consequences": ["It funds navigation, a 24/7 line, training and some respite.", "It pays for care services, not a drug.", "It is run by Medicare through CMS."], "explanation": "GUIDE is the payer funding work families used to do alone."}, "proReasoning": "Explain GUIDE as the payer funding the work families used to do alone: navigation, support and respite.", "commonMistake": "Assuming Medicare only pays for doctors and drugs.", "mentalModel": "Payers can fund caregiving."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f5d392497e7e$ml$]::text[]),
($ml$3bc8f976-0e76-5fcd-845f-526d1a834f63$ml$::uuid, $ml$neuroscience$ml$, 20, 2, $ml${"id": "neuroscience-d20-c2", "title": "The payer behind most of the bill", "lessonTitle": "What memory loss costs America", "slot": 2, "type": "connect", "brief": {"headline": "Medicare and Medicaid will cover 64% of the $409 billion spent on dementia care in 2026. So when CMS changes a coverage rule, as it did for amyloid PET in 2023, the market moves.", "kicker": "Connect day 15 and day 20: the biggest payer sets the rules.", "fullText": "On day 15 you saw that payers decide which tools get used: CMS lifted its one-scan-per-lifetime limit on amyloid PET in October 2023 and handed coverage to regional contractors. On day 20 you saw why CMS matters so much in dementia. The Alzheimer's Association projects $409 billion in 2026 health and long-term care costs for people with dementia, with Medicare and Medicaid covering $263 billion, or 64%, and $103 billion paid out of pocket.\n\nWhen one payer covers most of the bill, its rules shape what doctors offer, what companies build and what families get.", "sources": [{"url": "https://www.auntminnie.com/clinical-news/molecular-imaging/article/15636449/cms-lifts-limit-on-amyloid-pet-coverage", "label": "AuntMinnie, CMS lifts limit on amyloid PET coverage, Oct 2023"}, {"url": "https://www.alz.org/facts-and-figures", "label": "Alzheimer's Association, 2026 Alzheimer's disease facts and figures"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Who pays the largest share of US dementia care costs in 2026?", "options": ["Medicare and Medicaid", "Families, out of pocket", "Private insurers"], "correctIndex": 0, "explanation": "Medicare and Medicaid cover 64%, or $263 billion. Families pay $103 billion out of pocket."}, "numbers": {"kind": "numberSense", "prompt": "Medicare and Medicaid are projected to cover how many billion dollars of dementia care in 2026?", "min": 0, "max": 600, "value": 263, "unit": "B", "explanation": "$263 billion of $409 billion, which is why CMS decisions move the whole market."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a dementia care company. They ask what drives the market.", "prompt": "What's the best answer?", "options": ["Families paying the bulk out of pocket", "CMS rules, since public payers cover 64%", "Celebrity endorsements of care brands"], "correctIndex": 1, "consequences": ["Families pay $103 billion; public payers cover 64%.", "Medicare and Medicaid pay most of the bill.", "Endorsements do not pay for care."], "explanation": "Public payers cover most of the cost, so their rules drive the market."}, "proReasoning": "Explain the dementia market through who pays: Medicare and Medicaid 64%, families $103 billion out of pocket.", "commonMistake": "Thinking families or private insurers drive the market.", "mentalModel": "Follow the biggest payer."}, "invest": {"call": {"kind": "theCall", "situation": "A dementia diagnostics company's revenue jumped after a CMS coverage change.", "prompt": "What's the lesson for your next investment?", "options": ["Ignore payers and watch the tech", "Bet only on private insurers", "Track CMS decisions closely"], "correctIndex": 2, "consequences": ["Technology without coverage often goes unused.", "Public payers, not private ones, pay most.", "With public payers at 64%, CMS can make or break a market."], "explanation": "In dementia, coverage decisions by CMS can expand a market overnight."}, "proReasoning": "In dementia, coverage is the thesis. CMS decisions can expand a market overnight, as the PET change did.", "commonMistake": "Valuing dementia companies without tracking CMS.", "mentalModel": "Coverage is the thesis."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has a dementia care tool. Your first sales plan targets families paying cash.", "prompt": "What should you add?", "options": ["A path to Medicare or Medicaid payment", "More ads aimed at paying families", "A higher cash price for families"], "correctIndex": 0, "consequences": ["Public payers cover 64% of dementia care costs.", "Families pay $103 billion, but public payers pay far more.", "Raising cash prices narrows the market."], "explanation": "Most of the money in dementia care comes from public payers."}, "proReasoning": "Founders in dementia care plan for public payment early. That is where most of the money is.", "commonMistake": "Building a cash-only model in a publicly funded market.", "mentalModel": "Go where the money is."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why government decisions matter so much for Alzheimer's care.", "prompt": "What's the answer?", "options": ["Families pay for almost everything", "Public payers cover most of the bill", "The government makes all the drugs"], "correctIndex": 1, "consequences": ["Families pay $103 billion; public payers pay more.", "They cover $263 billion of $409 billion in 2026.", "Companies make the drugs; payers pay for them."], "explanation": "Public payers cover 64% of dementia care costs, so their rules reach almost everyone."}, "proReasoning": "Explain policy power with one share: public payers cover 64% of dementia care costs.", "commonMistake": "Thinking families or charities fund most dementia care.", "mentalModel": "Who pays decides."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:831235a89457$ml$]::text[]),
($ml$21d2a927-b9c5-59c1-b27b-e561ae2f2347$ml$::uuid, $ml$neuroscience$ml$, 20, 3, $ml${"id": "neuroscience-d20-c3", "title": "Who will pay your agency?", "lessonTitle": "What memory loss costs America", "slot": 3, "type": "decide", "brief": {"headline": "You run a home care agency for families living with dementia. Public payers cover 64% of dementia care costs, while families pay $103 billion out of pocket and give billions of unpaid hours.", "kicker": "Decide which payer your agency should build around.", "fullText": "You run a home care agency that supports people with dementia and their families. The Alzheimer's Association projects 2026 health and long-term care costs for people with dementia at $409 billion. Medicare and Medicaid cover $263 billion, or 64%, and families pay $103 billion out of pocket. Nearly 13 million family members and friends gave more than 19 billion hours of unpaid care in 2025, valued at more than $446 billion.\n\nAbout 7.4 million Americans 65 and older have Alzheimer's in 2026, and payments are projected to approach $1 trillion by 2050. Your agency can build around cash-paying families, public payers, or both.", "sources": [{"url": "https://www.alz.org/facts-and-figures", "label": "Alzheimer's Association, 2026 Alzheimer's disease facts and figures"}]}, "evidence": {"kind": "faceOff", "prompt": "Which source pays more of 2026 dementia care costs?", "left": {"name": "Medicare and Medicaid", "note": "64% of the $409 billion"}, "right": {"name": "Families, out of pocket", "note": "$103 billion"}, "correctIndex": 0, "explanation": "$263 billion from public payers against $103 billion from families. The bigger stream is public."}, "numbers": {"kind": "numberSense", "prompt": "Unpaid dementia care in 2025 was valued at more than how many billion dollars?", "min": 0, "max": 1000, "value": 446, "unit": "B", "explanation": "More than $446 billion, from over 19 billion hours given by nearly 13 million people."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're hiring a head of growth for the agency.", "prompt": "Which experience matters most?", "options": ["Consumer fashion ad campaigns", "Selling luxury travel packages", "Medicare and Medicaid programs"], "correctIndex": 2, "consequences": ["Consumer ads miss where most money flows.", "A different market with different payers.", "Public payers cover most dementia care costs."], "explanation": "Hire for the payer you depend on most."}, "proReasoning": "Hire for the payer you depend on. In dementia care, public program experience is worth more than consumer marketing.", "commonMistake": "Hiring as if families paid most of the bill.", "mentalModel": "Hire for the payer."}, "invest": {"call": {"kind": "theCall", "situation": "You're valuing the agency. Almost all its revenue comes from cash-paying families.", "prompt": "What's the risk and the opportunity?", "options": ["It misses the 64% that public payers cover", "Families pay most costs, so it is safe", "Public payers are shrinking to nothing"], "correctIndex": 0, "consequences": ["Adding public payment could reach far more of the market.", "Families pay $103 billion; public payers pay $263 billion.", "Payments are projected to approach $1 trillion by 2050."], "explanation": "A cash-only agency taps the smaller of the two streams."}, "proReasoning": "Investors map a company's revenue to the market's payers. A cash-only agency taps the smaller stream.", "commonMistake": "Assuming the most visible payer is the largest.", "mentalModel": "Map revenue to payers."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Families say their biggest struggle is the hours of care they give.", "prompt": "Which offer fits both the need and the money?", "options": ["A free app with no revenue plan", "Publicly funded respite and support", "A luxury concierge for rich families"], "correctIndex": 1, "consequences": ["Need without a payer is not a business.", "It meets the caregiving need with money from the largest payers.", "A tiny slice of the market."], "explanation": "Match the deepest need, caregiver hours, to the deepest pocket, public payers."}, "proReasoning": "Founders match the deepest need to the deepest pocket. Caregiver hours are the need; public payers hold most of the money.", "commonMistake": "Building for the need without a payer, or the payer without the need.", "mentalModel": "Need meets payer."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend is surprised that unpaid family care is valued above what families spend in cash.", "prompt": "What do the numbers say?", "options": ["Families pay nothing out of pocket", "Unpaid care is worth almost nothing", "Unpaid care is worth about 4 times more"], "correctIndex": 2, "consequences": ["Families pay $103 billion out of pocket.", "Over 19 billion hours were worth more than $446 billion.", "Over $446 billion of unpaid care against $103 billion in cash."], "explanation": "The hidden cost, unpaid hours, is far larger than the cash families spend."}, "proReasoning": "Show hidden costs with a comparison: unpaid care is worth more than four times the cash families spend.", "commonMistake": "Counting only the money that changes hands.", "mentalModel": "Count the hidden cost."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:db97371afd61$ml$]::text[]),
($ml$ba185372-1aa5-5235-8c84-8210e129d8f0$ml$::uuid, $ml$neuroscience$ml$, 21, 1, $ml${"id": "neuroscience-d21-c1", "title": "Licensed, but not funded", "lessonTitle": "Who decides access to Alzheimer's drugs", "slot": 1, "type": "apply", "brief": {"headline": "Britain's regulator licensed Leqembi and Kisunla in 2024. In June 2025, NICE said England's NHS should not fund either: the benefit was real but too small for the cost.", "kicker": "Apply the lesson: the payer decides access, not just the regulator.", "fullText": "The MHRA licensed lecanemab in August 2024 and donanemab in October 2024. On June 19, 2025, NICE, which advises England's NHS on what to fund, published final guidance recommending neither drug for routine use or managed access.\n\nNICE judged the effects clinically meaningful but small: lecanemab slowed decline by 27% to 33% on the CDR-SB scale over 18 months, and donanemab by 23% to 29% over 76 weeks. Their cost per quality-adjusted life year was far above NICE's thresholds. It also weighed the burden: lecanemab infusions every two weeks, donanemab every four, with frequent MRIs. Eisai and Lilly said they would appeal.\n\nAs with Medicare's registry rule on day 21, approval let the drugs be sold. The payer decided who would get them.", "sources": [{"url": "https://www.alzheimer-europe.org/news/nice-publishes-final-guidance-recommending-against-routine-nhs-use-donanemab-and-lecanemab", "label": "Alzheimer Europe, NICE final guidance against routine NHS use of donanemab and lecanemab, Jun 2025"}, {"url": "https://www.auntminnie.com/clinical-news/molecular-imaging/article/15633540/cms-to-cover-alzheimers-drugs-for-patients-enrolled-in-registry", "label": "AuntMinnie, CMS to cover Alzheimer's drugs for patients enrolled in registry, May 2023"}]}, "evidence": {"kind": "faceOff", "prompt": "Who decided whether England's NHS would fund the drugs?", "left": {"name": "MHRA", "note": "Licensed both drugs in 2024"}, "right": {"name": "NICE", "note": "Advises the NHS on what to fund"}, "correctIndex": 1, "explanation": "The MHRA licensed the drugs. NICE judged their value and said the NHS should not fund them."}, "numbers": {"kind": "numberSense", "prompt": "Lecanemab infusions come every two weeks. About how many is that in a year?", "min": 0, "max": 60, "value": 26, "unit": "infusions", "explanation": "About 26 infusions a year, plus MRIs. Burden was part of the value judgment."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a drugmaker's UK market access team after the NICE decision.", "prompt": "What will your work focus on?", "options": ["Advertising to NHS patients directly", "Evidence on long-term benefit and value", "Getting the MHRA to license it again"], "correctIndex": 1, "consequences": ["Funding decisions rest on value evidence, not ads.", "NICE said it needs more long-term data and better cost-effectiveness.", "The drugs are already licensed."], "explanation": "Give the payer what it asked for: long-term benefit data and a better value case."}, "proReasoning": "Market access teams work on what the payer asked for. Here, NICE wanted long-term benefit data and a better value case.", "commonMistake": "Treating a licence as the end of the access fight.", "mentalModel": "Give the payer what it asked for."}, "invest": {"call": {"kind": "theCall", "situation": "NICE rejects NHS funding for both Alzheimer's antibodies.", "prompt": "How does that affect the drugs' sales in England?", "options": ["Sales jump, since they are licensed", "No effect, since NICE only advises", "Little routine NHS use unless it changes"], "correctIndex": 2, "consequences": ["A licence alone does not fund treatment.", "NICE's advice decides routine NHS funding in England.", "Without NHS funding, few patients in England get them."], "explanation": "A licence without funding can mean little revenue in that market."}, "proReasoning": "Investors watch payers country by country. A licence without funding can mean little revenue in that market.", "commonMistake": "Counting every licensed market as a revenue market.", "mentalModel": "Licensed is not funded."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells MRI scheduling for anti-amyloid drugs and wants to expand to England.", "prompt": "What does NICE's decision mean for you?", "options": ["Wait, since routine NHS use is unfunded", "Launch now, since the drugs are licensed", "Sell to NICE instead of to clinics"], "correctIndex": 0, "consequences": ["Without funding, there are few NHS patients to schedule.", "Licence without funding means little routine use.", "NICE advises on funding; it does not run clinics."], "explanation": "Downstream services follow funded demand, not approvals."}, "proReasoning": "Founders follow funded demand, not approvals. Where the payer says no, downstream services wait.", "commonMistake": "Expanding into a market where the payer has not funded the treatment.", "mentalModel": "Follow funded demand."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a drug can be approved in Britain but not offered by the NHS.", "prompt": "What's the explanation?", "options": ["The NHS cannot buy any new drugs at all", "Approval and funding are separate calls", "The approval must have been fake"], "correctIndex": 1, "consequences": ["NICE decides drug by drug, on value.", "The MHRA licensed it; NICE judged it poor value for the NHS.", "The MHRA licensed both drugs in 2024."], "explanation": "The regulator licenses; the payer funds. Either can say no."}, "proReasoning": "Explain access with two gates: the regulator licenses, the payer funds. Either can say no.", "commonMistake": "Assuming approval means patients get the drug.", "mentalModel": "Two gates: license and pay."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0474528b67ed$ml$]::text[]),
($ml$59b4ff16-a14f-511e-a5c0-4265a5863ab4$ml$::uuid, $ml$neuroscience$ml$, 21, 2, $ml${"id": "neuroscience-d21-c2", "title": "The payer that sets the conditions", "lessonTitle": "Who decides access to Alzheimer's drugs", "slot": 2, "type": "connect", "brief": {"headline": "Medicare and Medicaid cover 64% of dementia care costs. So in 2023, when CMS said Medicare would cover new Alzheimer's antibodies only through a registry, that condition shaped access nationwide.", "kicker": "Connect day 20 and day 21: who pays sets the terms.", "fullText": "On day 20 you saw who pays for dementia care: Medicare and Medicaid cover $263 billion of a projected $409 billion in 2026, or 64%. On day 21 you saw how that power gets used. On June 1, 2023, CMS said Medicare would cover Alzheimer's drugs with traditional FDA approval only when the physician and clinical team join a registry that collects evidence on how the drugs work in routine practice.\n\nEligible patients need Medicare Part B and mild cognitive impairment or early dementia caused by Alzheimer's. When the largest payer adds a condition, every clinic serving its patients has to meet it.", "sources": [{"url": "https://www.alz.org/facts-and-figures", "label": "Alzheimer's Association, 2026 Alzheimer's disease facts and figures"}, {"url": "https://www.auntminnie.com/clinical-news/molecular-imaging/article/15633540/cms-to-cover-alzheimers-drugs-for-patients-enrolled-in-registry", "label": "AuntMinnie, CMS to cover Alzheimer's drugs for patients enrolled in registry, May 2023"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Medicare and Medicaid cover 64% of dementia costs.", "Medicare covers the drugs with no conditions.", "Clinical teams must join a registry for coverage."], "fakeIndex": 1, "explanation": "Coverage came with a condition: the clinical team joins a registry."}, "numbers": {"kind": "numberSense", "prompt": "Families pay how many billion dollars out of pocket for dementia care in 2026?", "min": 0, "max": 300, "value": 103, "unit": "B", "explanation": "$103 billion, far less than the $263 billion public payers cover. That gap is why CMS can set the rules."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a neurology practice's operations team in 2024.", "prompt": "Why does the Medicare registry dominate your work?", "options": ["The registry is optional for coverage", "Families pay for most of the treatment", "Medicare pays for most of these patients"], "correctIndex": 2, "consequences": ["Coverage depends on joining it.", "Families pay $103 billion; public payers pay $263 billion.", "Public payers cover most dementia care, and Medicare requires the registry."], "explanation": "The registry matters because Medicare pays."}, "proReasoning": "Explain operational burdens by the payer behind them. The registry matters because Medicare pays.", "commonMistake": "Treating payer conditions as paperwork rather than access.", "mentalModel": "The payer's rule is the clinic's job."}, "invest": {"call": {"kind": "theCall", "situation": "A company's Alzheimer's drug wins traditional approval. Most patients are on Medicare.", "prompt": "What shapes how fast it reaches patients?", "options": ["Clinics joining the Medicare registry", "How many TV ads the company runs", "Prices that families set themselves"], "correctIndex": 0, "consequences": ["Coverage depends on teams joining the registry.", "Ads do not satisfy coverage conditions.", "Payers, not families, cover most costs."], "explanation": "Registry work can slow how fast new drugs reach patients. Model uptake through the payer's conditions."}, "proReasoning": "Investors model uptake through the payer's conditions. Registry work can slow how fast new drugs reach patients.", "commonMistake": "Forecasting uptake without the payer's conditions.", "mentalModel": "Conditions shape uptake."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds software for neurology clinics.", "prompt": "Which product rides the biggest payer's rule?", "options": ["Billing tools for private pay only", "Tools that simplify registry reporting", "A social app for family caregivers"], "correctIndex": 1, "consequences": ["Most dementia care is paid for publicly.", "Clinics need registry reporting to get Medicare coverage.", "Unrelated to the payer rule."], "explanation": "Registry reporting falls on busy clinical teams. That is the work to simplify."}, "proReasoning": "Founders build where the largest payer creates work. Registry reporting falls on busy clinical teams.", "commonMistake": "Ignoring the payer rule that every clinic must meet.", "mentalModel": "Build where the payer adds work."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their parent's doctor had to join a registry before treatment.", "prompt": "What's the reason?", "options": ["The FDA requires every doctor to join", "The drugmaker asked for it", "Medicare requires it for coverage"], "correctIndex": 2, "consequences": ["It was a Medicare coverage condition.", "The condition came from CMS.", "CMS tied coverage to registry participation."], "explanation": "Medicare pays most dementia costs, so its conditions reach every clinic."}, "proReasoning": "Explain rules by who set them and why: Medicare pays most dementia costs, so its conditions reach every clinic.", "commonMistake": "Assuming every rule comes from the FDA.", "mentalModel": "Ask who set the rule."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7fccc6602f49$ml$]::text[]),
($ml$9aedb0e8-f1cd-54c3-8ad3-4ba779807c23$ml$::uuid, $ml$neuroscience$ml$, 21, 3, $ml${"id": "neuroscience-d21-c3", "title": "Accelerated, but not covered", "lessonTitle": "Who decides access to Alzheimer's drugs", "slot": 3, "type": "decide", "brief": {"headline": "You run a fund weighing an Alzheimer's antibody that has only accelerated FDA approval. In 2023, Medicare tied coverage to traditional approval plus a registry.", "kicker": "Decide what to wait for before betting on sales.", "fullText": "You run a healthcare fund. A company's Alzheimer's antibody has accelerated FDA approval, and its shares already price in fast sales.\n\nDay 21 sets the terms. In its June 1, 2023 statement, CMS said Medicare would cover Alzheimer's antibody drugs that receive traditional FDA approval, but only when a physician and clinical team join a registry collecting evidence on how the drugs work in routine practice. Eligible patients need Medicare Part B and mild cognitive impairment or early dementia caused by Alzheimer's. Coverage required traditional approval, not just accelerated approval. Leqembi received traditional approval on July 6, 2023.", "sources": [{"url": "https://www.auntminnie.com/clinical-news/molecular-imaging/article/15633540/cms-to-cover-alzheimers-drugs-for-patients-enrolled-in-registry", "label": "AuntMinnie, CMS to cover Alzheimer's drugs for patients enrolled in registry, May 2023"}, {"url": "https://www.biospace.com/fda-grants-traditional-approval-for-leqembi-lecanemab-irmb-for-the-treatment-of-alzheimer-s-disease", "label": "Eisai and Biogen via BioSpace, Leqembi traditional approval"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the path from approval to Medicare payment in order.", "steps": ["The FDA grants accelerated approval", "More trial evidence comes in", "The FDA grants traditional approval", "Clinical teams join the Medicare registry", "Medicare covers eligible patients"], "explanation": "Accelerated approval was not enough. Coverage started after traditional approval, through the registry."}, "numbers": {"kind": "numberSense", "prompt": "CMS's statement came on June 1, 2023, and Leqembi's traditional approval on July 6. About how many days apart?", "min": 0, "max": 100, "value": 35, "unit": "days", "explanation": "About 35 days. The payer set its terms just before the trigger arrived."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the fund's analyst. Your boss asks what must happen before Medicare covers the drug.", "prompt": "What's the answer?", "options": ["Traditional approval, then registry use", "Nothing more; it is already approved", "A new price set by the FDA itself"], "correctIndex": 0, "consequences": ["Coverage required traditional approval and a registry.", "Accelerated approval was not enough for coverage.", "The FDA does not set prices."], "explanation": "Map the steps between approval and payment."}, "proReasoning": "Analysts map the steps between approval and payment. For these drugs, traditional approval and the registry came first.", "commonMistake": "Treating any FDA approval as coverage.", "mentalModel": "Map the steps to payment."}, "invest": {"call": {"kind": "theCall", "situation": "The shares price in big sales this year.", "prompt": "What's your call?", "options": ["Short it, since the approval is fake", "Wait for traditional approval news", "Buy now, since it is approved"], "correctIndex": 1, "consequences": ["The approval is real, just not the kind coverage needed.", "Medicare coverage hinged on traditional approval.", "Accelerated approval alone did not bring coverage."], "explanation": "Time the bet to the payer's trigger."}, "proReasoning": "Investors time bets to the payer's trigger. Here, Medicare coverage hinged on traditional approval.", "commonMistake": "Pricing in sales before the coverage trigger.", "mentalModel": "Time it to the payer's trigger."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells registry software. The drug still has only accelerated approval.", "prompt": "When will demand for your product jump?", "options": ["Right now, at accelerated approval", "Never, since registries are optional", "When traditional approval arrives"], "correctIndex": 2, "consequences": ["Coverage was not yet available.", "The registry is a condition of coverage.", "Coverage, and the registry, start with traditional approval."], "explanation": "Registry tools sell when coverage begins."}, "proReasoning": "Founders time launches to the trigger that creates demand. Registry tools sell when coverage begins.", "commonMistake": "Launching before the rule that creates demand takes effect.", "mentalModel": "Launch on the trigger."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why an FDA-approved Alzheimer's drug wasn't covered by Medicare at first.", "prompt": "What's the reason?", "options": ["Coverage required traditional approval", "Medicare covers no Alzheimer's drugs", "The drug was never approved"], "correctIndex": 0, "consequences": ["Accelerated approval was not enough for CMS.", "It covers them, under conditions.", "It had accelerated approval."], "explanation": "Approvals come in kinds, and Medicare tied coverage to traditional approval."}, "proReasoning": "Explain that approvals come in kinds. Medicare tied coverage to traditional approval, not accelerated.", "commonMistake": "Assuming all approvals are the same.", "mentalModel": "Approvals come in kinds."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d50d0d304037$ml$]::text[]),
($ml$6872c5e3-4642-50cc-addf-6e6787ecede7$ml$::uuid, $ml$neuroscience$ml$, 22, 1, $ml${"id": "neuroscience-d22-c1", "title": "Europe weighs the benefit", "lessonTitle": "How much the new Alzheimer's drugs help", "slot": 1, "type": "apply", "brief": {"headline": "In July 2024, Europe's drug committee said Leqembi's benefit was not large enough to offset brain swelling risks. In November, it said yes, for patients with one or no copies of the ApoE4 gene.", "kicker": "Apply the lesson: a modest benefit must be weighed against real risk.", "fullText": "The EMA's CHMP issued a negative opinion on Leqembi in July 2024. It judged the slowing of decline not large enough to offset the risk of ARIA, brain swelling or bleeding seen on MRI, across the broad early Alzheimer's population.\n\nEisai asked for a re-examination. In November 2024, the committee recommended Leqembi for people with mild cognitive impairment or mild dementia due to Alzheimer's who carry one or no copies of ApoE4, leaving out those with two copies, who have the highest ARIA risk. In that group, ARIA-E was 8.9% against 12.6% across all treated patients, and ARIA-H 12.9% against 16.9%. Access would run through a controlled program, with MRIs before starting and before the 5th, 7th and 14th doses.\n\nThe drug did not change. The group it was weighed in did.", "sources": [{"url": "https://www.pharmaceutical-technology.com/news/ema-rethinks-stance-committee-now-recommends-leqembi-for-alzheimers-disease/", "label": "Pharmaceutical Technology, EMA committee rethinks stance and recommends Leqembi, Nov 2024"}, {"url": "https://alzheimersnewstoday.com/news/fda-committee-supports-leqembi-early-treatment-alzheimers/", "label": "Alzheimer's News Today, FDA committee supports Leqembi, Jun 2023"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What changed between the committee's no and its yes?", "options": ["The patient group it covered", "The drug was made stronger", "ARIA vanished for everyone"], "correctIndex": 0, "explanation": "Leaving out people with two ApoE4 copies lowered the risk enough for the benefit to win."}, "numbers": {"kind": "numberSense", "prompt": "In the restricted group, ARIA-E occurred in about what share of treated patients?", "min": 0, "max": 30, "value": 8.9, "unit": "%", "explanation": "About 8.9%, against 12.6% across all treated patients. A narrower group, a better balance."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Eisai's European medical team after the re-examination.", "prompt": "What's the key point to communicate?", "options": ["Every early Alzheimer's patient qualifies", "No MRI monitoring is needed", "Use is limited to one or no ApoE4 copies"], "correctIndex": 2, "consequences": ["People with two ApoE4 copies were left out.", "MRIs come before starting and before the 5th, 7th and 14th doses.", "That group had lower ARIA rates."], "explanation": "A restricted recommendation is the price of a favorable benefit-risk balance."}, "proReasoning": "Medical teams communicate exactly who a drug is for. A restricted label is the price of a favorable benefit-risk balance.", "commonMistake": "Describing a restricted approval as a broad one.", "mentalModel": "Know exactly who it is for."}, "invest": {"call": {"kind": "theCall", "situation": "Europe recommends Leqembi only for a restricted group, through a controlled program.", "prompt": "How should you adjust your European forecast?", "options": ["Fewer eligible patients, slower uptake", "Same as the full US population", "Higher, since rules boost demand"], "correctIndex": 0, "consequences": ["Excluding two-copy carriers and adding controls narrows use.", "Europe's group is narrower.", "Controls tend to slow uptake, not speed it."], "explanation": "Size the eligible group, not the disease."}, "proReasoning": "Investors size the eligible group, not the disease. Restrictions and controlled access both shrink the near-term market.", "commonMistake": "Forecasting Europe like the US after a restricted recommendation.", "mentalModel": "Size the eligible group."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers genetic testing to clinics.", "prompt": "How does the EMA decision affect demand?", "options": ["Only blood pressure checks matter", "ApoE4 testing now decides eligibility", "Genetics no longer matter for Leqembi"], "correctIndex": 1, "consequences": ["The decision turns on ApoE4 status.", "The recommendation depends on how many ApoE4 copies a patient has.", "Eligibility now hinges on ApoE4 copies."], "explanation": "A label restricted by genotype makes genotyping part of the pathway."}, "proReasoning": "Founders spot when a label creates a new test. Eligibility by ApoE4 status makes genotyping part of the pathway.", "commonMistake": "Missing the test a restricted label requires.", "mentalModel": "Labels create tests."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Europe first said no to an Alzheimer's drug the US had approved.", "prompt": "What's the reason?", "options": ["The drug did not work at all in trials", "Europe bans all new Alzheimer's drugs", "Benefit seemed too small for the risk"], "correctIndex": 2, "consequences": ["It slows decline; the debate was benefit against risk.", "It later recommended Leqembi for a restricted group.", "Slowing decline was judged not large enough against ARIA."], "explanation": "Modest benefit plus real risk can tip either way, depending on who is treated."}, "proReasoning": "Explain regulatory splits as different weighing of the same data. Modest benefit plus real risk can go either way.", "commonMistake": "Assuming a no means the drug does nothing.", "mentalModel": "Same data, different weighing."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:516434de18b7$ml$]::text[]),
($ml$95c1c734-fd34-59f3-8065-20692dbacf80$ml$::uuid, $ml$neuroscience$ml$, 22, 2, $ml${"id": "neuroscience-d22-c2", "title": "The benefit and its scans", "lessonTitle": "How much the new Alzheimer's drugs help", "slot": 2, "type": "connect", "brief": {"headline": "Leqembi slowed decline by about 27% in a trial of 1,795 people, but 12.6% had brain swelling and 17.3% had small bleeds. That is why the FDA wants MRIs before key infusions.", "kicker": "Connect day 17 and day 22: the benefit comes with a scan schedule.", "fullText": "On day 22 you saw the size of the benefit: in Clarity AD, with 1,795 people, Leqembi slowed decline on the CDR-SB by about 27% against placebo over 18 months. ARIA-E, brain swelling, occurred in 12.6% on Leqembi and ARIA-H, small brain bleeds, in 17.3%.\n\nOn day 17 you saw what those risks require. In August 2025, after identifying six fatal ARIA-E cases and 101 serious ones, the FDA added an MRI before the third infusion, on top of scans before the fifth, seventh and 14th, plus a baseline MRI. Patients and doctors weigh a slowing of roughly a quarter against risks that must be watched on a schedule.", "sources": [{"url": "https://alzheimersnewstoday.com/news/fda-committee-supports-leqembi-early-treatment-alzheimers/", "label": "Alzheimer's News Today, FDA committee supports Leqembi, Jun 2023"}, {"url": "https://www.fda.gov/drugs/drug-safety-and-availability/fda-recommend-additional-earlier-mri-monitoring-patients-alzheimers-disease-taking-leqembi-lecanemab", "label": "FDA, FDA to recommend additional, earlier MRI monitoring for patients taking Leqembi, Aug 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each a benefit, or a risk or burden?", "buckets": ["Benefit", "Risk or burden"], "items": [{"text": "About 27% slower decline over 18 months", "bucket": 0}, {"text": "Brain swelling in 12.6% of patients", "bucket": 1}, {"text": "Small brain bleeds in 17.3%", "bucket": 1}, {"text": "Six fatal ARIA-E cases identified", "bucket": 1}, {"text": "MRIs before the 3rd, 5th, 7th and 14th infusions", "bucket": 1}], "explanation": "One real benefit against several risks and burdens. That is the weighing patients and doctors do."}, "numbers": {"kind": "numberSense", "prompt": "In Clarity AD, what share of Leqembi patients had small brain bleeds (ARIA-H)?", "min": 0, "max": 50, "value": 17.3, "unit": "%", "explanation": "About 17.3%, roughly one in six. Common enough that scans are part of the treatment."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A care coordinator is asked what Leqembi offers and what it asks of patients.", "prompt": "What's the honest summary?", "options": ["Modest slowing, with scans to watch risks", "A full cure, with no monitoring at all", "No real benefit, only added risk"], "correctIndex": 0, "consequences": ["About 27% slower decline, plus scheduled MRIs for ARIA.", "It slows decline; it does not cure, and MRIs are required.", "The trial showed slower decline."], "explanation": "Benefit and burden belong in the same sentence."}, "proReasoning": "Coordinators explain benefit and burden together. Families decide better with both numbers.", "commonMistake": "Describing the benefit without the monitoring it requires.", "mentalModel": "Benefit and burden, together."}, "invest": {"call": {"kind": "theCall", "situation": "You compare Leqembi's 27% benefit with its MRI schedule.", "prompt": "What limits uptake most?", "options": ["Too few people with Alzheimer's", "Modest benefit plus monitoring burden", "Lack of any measurable benefit"], "correctIndex": 1, "consequences": ["7.4 million Americans 65 and older have it.", "Modest slowing plus MRIs and infusions limit uptake.", "It slowed decline by about 27%."], "explanation": "Benefit versus burden decides uptake. Watch whether easier dosing changes the balance."}, "proReasoning": "Investors weigh benefit against burden. Watch whether easier dosing or fewer scans change the balance.", "commonMistake": "Judging uptake on efficacy alone.", "mentalModel": "Benefit versus burden.", "sources": [{"url": "https://www.alz.org/facts-and-figures", "label": "Alzheimer's Association, 2026 Alzheimer's disease facts and figures"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to make anti-amyloid treatment easier for clinics.", "prompt": "Which pain is most directly tied to the risk data?", "options": ["Choosing colors for infusion chairs", "Designing new patient brochures", "Scheduling and reading safety MRIs"], "correctIndex": 2, "consequences": ["Unrelated to the safety burden.", "Useful, but not the burden ARIA creates.", "ARIA rates drive the MRI schedule clinics must run."], "explanation": "ARIA rates create the MRI schedule, and the schedule creates the work."}, "proReasoning": "Founders trace a burden to its source. ARIA rates create the MRI schedule, and the schedule creates the work.", "commonMistake": "Solving cosmetic problems while the safety workload grows.", "mentalModel": "Trace the burden to its source."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why patients on a new Alzheimer's drug need so many brain scans.", "prompt": "What's the answer?", "options": ["Swelling and bleeds need watching", "Scans are what make the drug work", "Doctors want pictures for research"], "correctIndex": 0, "consequences": ["12.6% had swelling and 17.3% small bleeds in the trial.", "Scans watch for side effects; they do not treat.", "The scans are part of the safety rules."], "explanation": "When about one in eight patients has swelling, scans become part of the treatment."}, "proReasoning": "Explain monitoring with the rates: when about one in eight patients has swelling, scans are part of the treatment.", "commonMistake": "Thinking scans mean something went wrong.", "mentalModel": "Rates set the schedule."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:65c892073e0b$ml$]::text[]),
($ml$d0904884-29aa-507a-b7c2-409150ada804$ml$::uuid, $ml$neuroscience$ml$, 22, 3, $ml${"id": "neuroscience-d22-c3", "title": "When to stop treatment", "lessonTitle": "How much the new Alzheimer's drugs help", "slot": 3, "type": "decide", "brief": {"headline": "You run a memory clinic giving Kisunla. In its main trial, plaque fell an average of 84% by 18 months, and patients whose scans cleared could stop treatment.", "kicker": "Decide how your clinic should handle stopping treatment.", "fullText": "You run a memory clinic that offers Kisunla. In TRAILBLAZER-ALZ 2, with 1,736 people, Kisunla slowed decline on the iADRS scale by 35% in people with low to medium tau and 22% overall, and plaque fell an average of 84% by 18 months. Patients whose scans showed plaque had cleared could stop treatment.\n\nLeqembi, by comparison, slowed decline by about 27% over 18 months. These drugs slow decline by roughly a quarter to a third; they do not stop it. A clear stopping point can cut cost and infusions, but only if your clinic checks for it.", "sources": [{"url": "https://practicalneurology.com/news/donanemabkisunla-approved-to-treat-early-alzheimer-disease/2470522/", "label": "Practical Neurology, Donanemab (Kisunla) approved to treat early Alzheimer disease, Jul 2024"}, {"url": "https://alzheimersnewstoday.com/news/fda-committee-supports-leqembi-early-treatment-alzheimers/", "label": "Alzheimer's News Today, FDA committee supports Leqembi, Jun 2023"}]}, "evidence": {"kind": "faceOff", "prompt": "In the trial, which patients could stop Kisunla?", "left": {"name": "Scans show plaque cleared", "note": "Plaque cleared on a scan"}, "right": {"name": "Symptoms feel better", "note": "The patient reports feeling better"}, "correctIndex": 0, "explanation": "The stopping rule was based on scans showing cleared plaque, not on how patients felt."}, "numbers": {"kind": "numberSense", "prompt": "Kisunla cut plaque by an average of what percent by 18 months?", "min": 0, "max": 100, "value": 84, "unit": "%", "explanation": "An average of 84%. For some patients, that clearance opened the door to stopping."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the clinic's nurse lead. A patient has been on Kisunla for a year.", "prompt": "What should the care plan include?", "options": ["Stopping when the patient feels better", "A scan to check whether plaque cleared", "Treatment forever, with no review"], "correctIndex": 1, "consequences": ["The stopping rule was based on scans, not feelings.", "Patients whose scans cleared could stop treatment.", "Clearance can allow stopping."], "explanation": "Build the stopping check into the plan. It can save infusions for patients who qualify."}, "proReasoning": "Care teams build the stopping check into the plan. It can save infusions and cost for patients who qualify.", "commonMistake": "Continuing treatment without checking whether stopping is allowed.", "mentalModel": "Plan the stop check."}, "invest": {"call": {"kind": "theCall", "situation": "You compare Kisunla and Leqembi as businesses.", "prompt": "How does Kisunla's stopping rule affect revenue per patient?", "options": ["It doubles revenue per patient", "It has no effect at all", "It can shorten treatment and revenue"], "correctIndex": 2, "consequences": ["Stopping reduces, not increases, doses given.", "Fewer doses per patient changes revenue.", "Patients who clear plaque can stop, ending infusions."], "explanation": "A drug that can be stopped earns less per patient over time."}, "proReasoning": "Investors read stopping rules as revenue rules. A drug that can be stopped earns less per patient over time.", "commonMistake": "Assuming every patient stays on treatment indefinitely.", "mentalModel": "Stopping rules shape revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup tracks patients on anti-amyloid drugs.", "prompt": "Which feature adds the most value for Kisunla clinics?", "options": ["Flagging when a clearance scan is due", "Sending patients birthday greetings", "Tracking local weather each day"], "correctIndex": 0, "consequences": ["Stopping when plaque clears saves cost and infusions.", "Nice, but not clinical value.", "Irrelevant to treatment."], "explanation": "Knowing when a patient can stop is worth a lot to clinics and payers."}, "proReasoning": "Founders find the moments that save money. Knowing when a patient can stop is worth a lot to clinics and payers.", "commonMistake": "Tracking everything except the decision that matters.", "mentalModel": "Track the decision that matters."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if their grandfather could ever stop his Alzheimer's infusions.", "prompt": "What does the Kisunla trial suggest?", "options": ["Only if he skips his scans", "Possibly, once scans show plaque cleared", "Never, since treatment is lifelong"], "correctIndex": 1, "consequences": ["Scans decide when stopping is possible.", "In the trial, patients whose scans cleared could stop.", "Kisunla allowed stopping after clearance."], "explanation": "In the trial, scans showing cleared plaque allowed stopping. His own doctors would make that call."}, "proReasoning": "Explain stopping rules by what the trial measured: plaque on scans, not how a patient feels.", "commonMistake": "Assuming every treatment must continue forever.", "mentalModel": "Scans decide when to stop."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:658fd591f2f9$ml$]::text[]),
($ml$c6609a9e-ce10-556a-ba53-f7a4978f76f0$ml$::uuid, $ml$neuroscience$ml$, 23, 1, $ml${"id": "neuroscience-d23-c1", "title": "The cleared game that sold for $34 million", "lessonTitle": "When a brain game promised too much", "slot": 1, "type": "apply", "brief": {"headline": "In 2020, Akili's EndeavorRx became an FDA-cleared prescription video game for children with ADHD. In 2024, struggling to get insurers to pay, Akili sold itself for about $34 million.", "kicker": "Apply the lesson: evidence earns claims; payers keep you alive.", "fullText": "Unlike Lumosity, Akili did the evidence work. EndeavorRx won FDA de novo clearance in 2020 as a prescription game to improve attention in children with ADHD.\n\nThe business did not follow. Akili struggled to get payers to cover the product, and in 2023 it shifted away from prescriptions to sell an over-the-counter version for adults. That year it had $1.7 million in revenue, $1.2 million of it from the over-the-counter version and $523,000 from EndeavorRx, and a net loss of $59.5 million. After layoffs in 2023 and a 46% staff cut in April 2024, Akili agreed in May 2024 to be bought by Virtual Therapeutics for about $34 million, or 43 cents a share.\n\nDay 23's rule still holds: claims need evidence. Evidence alone did not make a business.", "sources": [{"url": "https://www.medtechdive.com/news/akili-sell-34m-virtual-therapeutics-digital/717570/", "label": "MedTech Dive, Akili to sell for $34M to Virtual Therapeutics, May 2024"}, {"url": "https://ftc.gov/news-events/press-releases/2016/01/lumosity-pay-2-million-settle-ftc-deceptive-advertising-charges", "label": "FTC, Lumosity to pay $2 million to settle deceptive advertising charges, Jan 2016"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which company does each fact describe?", "buckets": ["Lumosity", "Akili"], "items": [{"text": "Paid $2 million to settle FTC charges", "bucket": 0}, {"text": "Claimed to delay dementia without support", "bucket": 0}, {"text": "Cleared by the FDA in 2020", "bucket": 1}, {"text": "Struggled to get insurers to pay", "bucket": 1}, {"text": "Sold for about $34 million", "bucket": 1}], "explanation": "Lumosity had claims without proof. Akili had proof without a payer. Each gap hurt in its own way."}, "numbers": {"kind": "numberSense", "prompt": "Akili's 2023 revenue was $1.7 million. Its net loss was about how many times that?", "min": 0, "max": 80, "value": 35, "unit": "times", "explanation": "$59.5 million divided by $1.7 million is about 35. Cleared, and still far from paying its way."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're offered a job at a digital therapeutics startup with FDA clearance but no insurer coverage.", "prompt": "What question matters most?", "options": ["Who will pay for it, and when?", "Is the FDA clearance really real?", "How fun is the game to play?"], "correctIndex": 0, "consequences": ["Akili had clearance but struggled to get payers to cover it.", "Akili's clearance was real too; payment was the gap.", "Fun does not pay salaries."], "explanation": "In digital health, reimbursement decides survival as much as evidence."}, "proReasoning": "In digital health, ask about reimbursement as hard as about evidence. Akili had a clearance and a payment problem.", "commonMistake": "Assuming FDA clearance guarantees a business.", "mentalModel": "Clearance is not coverage."}, "invest": {"call": {"kind": "theCall", "situation": "A brain-game startup has FDA clearance and strong trial data, but no insurer pays yet.", "prompt": "How should Akili's story shape your view?", "options": ["Games can never be medicine", "Evidence is necessary but not enough", "FDA clearance means guaranteed sales"], "correctIndex": 1, "consequences": ["EndeavorRx was cleared as a prescription game.", "Akili sold for about $34 million despite its clearance.", "Akili's prescription game earned $523,000 in 2023."], "explanation": "Check both the evidence and the payer path."}, "proReasoning": "Investors check both the evidence and the payer path. Akili shows strong claims can still meet a weak business.", "commonMistake": "Valuing a cleared product without a payer.", "mentalModel": "Evidence plus payer."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're founding a brain-training company and must choose a path.", "prompt": "What do Akili and Lumosity teach you together?", "options": ["Skip the evidence, spend on ads", "Get cleared, then ignore payers", "Prove your claims, and secure a payer"], "correctIndex": 2, "consequences": ["That is the Lumosity path, and it led to the FTC.", "That is roughly Akili's path, and it sold for $34 million.", "Lumosity lacked proof; Akili lacked payers."], "explanation": "You need evidence for every claim and someone who will pay."}, "proReasoning": "Founders need two things: evidence for every claim, and someone who will pay. Either gap can sink the company.", "commonMistake": "Solving the evidence problem and forgetting the payment one.", "mentalModel": "Proof and a payer."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if any video game has been cleared as medicine.", "prompt": "What's a fair answer?", "options": ["Yes, EndeavorRx was cleared for ADHD", "No, the FDA never clears games", "Yes, Lumosity is cleared for dementia"], "correctIndex": 0, "consequences": ["It won FDA de novo clearance in 2020 for children with ADHD.", "EndeavorRx is a counterexample.", "The FTC said Lumosity's dementia claims lacked support."], "explanation": "EndeavorRx was cleared; Lumosity paid to settle charges. Not all brain games are alike."}, "proReasoning": "Separate evidence-backed games from marketing claims. EndeavorRx was cleared; Lumosity paid to settle charges.", "commonMistake": "Lumping all brain games together.", "mentalModel": "Cleared versus claimed."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:000d63756301$ml$]::text[]),
($ml$d1a61240-b1c8-5fee-b044-02e91ac6716f$ml$::uuid, $ml$neuroscience$ml$, 23, 2, $ml${"id": "neuroscience-d23-c2", "title": "Small studies, big promises", "lessonTitle": "When a brain game promised too much", "slot": 2, "type": "connect", "brief": {"headline": "The median brain-behavior scan study used 25 people, and small studies can find effects that vanish. Lumosity claimed its games delayed dementia without scientific support, and paid $2 million.", "kicker": "Connect day 16 and day 23: weak evidence makes risky claims.", "fullText": "On day 16 you saw that small samples produce big claims that often fail: the median published brain-wide association study used 25 people, and reproducible results need thousands. On day 23 you saw what happens when claims outrun evidence in advertising. On January 5, 2016, the FTC announced that Lumos Labs would pay $2 million to settle charges that Lumosity claimed, without scientific support, that its games would improve work and school performance and delay age-related decline, dementia and Alzheimer's. A $50 million judgment was suspended because of its finances.\n\nLumosity must now have competent and reliable scientific evidence before making such claims. In brain health, the size of the evidence has to match the size of the claim.", "sources": [{"url": "https://source.washu.edu/2022/03/for-accuracy-brain-studies-of-complex-behavior-require-thousands-of-people/", "label": "Washington University, For accuracy, brain studies of complex behavior require thousands of people, Mar 2022"}, {"url": "https://ftc.gov/news-events/press-releases/2016/01/lumosity-pay-2-million-settle-ftc-deceptive-advertising-charges", "label": "FTC, Lumosity to pay $2 million to settle deceptive advertising charges, Jan 2016"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which evidence would best support a claim that a brain game slows decline?", "options": ["A large, controlled study", "A study of 25 keen users", "Glowing customer reviews"], "correctIndex": 0, "explanation": "Big claims need big, controlled studies. Small samples and reviews cannot carry them."}, "numbers": {"kind": "numberSense", "prompt": "The FTC suspended a judgment of how many million dollars against Lumos Labs?", "min": 0, "max": 120, "value": 50, "unit": "M", "explanation": "A $50 million judgment, suspended because of its finances, on top of the $2 million paid."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a brain-health app's marketing team. A draft ad cites a 20-person pilot.", "prompt": "What do you flag?", "options": ["The ad needs brighter colors", "The claim outruns a tiny study", "The font is too small to read"], "correctIndex": 1, "consequences": ["Colors do not fix weak evidence.", "Small studies often fail, and the FTC requires solid evidence.", "Presentation is not the legal risk."], "explanation": "A 20-person pilot cannot carry a big ad claim."}, "proReasoning": "Marketers in brain health check that the evidence matches the claim. A 20-person pilot cannot carry a dementia claim.", "commonMistake": "Letting a small pilot support a big ad claim.", "mentalModel": "Match the claim to the evidence."}, "invest": {"call": {"kind": "theCall", "situation": "A brain-training startup's ads promise better memory, based on a 25-person study.", "prompt": "What risk do you see?", "options": ["Far too much scientific rigor", "None, since games are harmless", "Regulatory risk from weak evidence"], "correctIndex": 2, "consequences": ["The problem is too little rigor.", "The risk is the claim, not the game.", "Lumosity paid $2 million for claims without support."], "explanation": "Claims built on small studies invite FTC action and fade when tested."}, "proReasoning": "Investors check marketing against evidence. Claims built on small studies invite FTC action and fade when tested.", "commonMistake": "Ignoring the gap between ads and evidence.", "mentalModel": "Claims can backfire."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app helped 25 users in a pilot. You want to claim it slows cognitive decline.", "prompt": "What should you do first?", "options": ["Run a larger controlled study", "Launch the claim and see", "Cite user reviews as proof"], "correctIndex": 0, "consequences": ["Thousands, not 25, make a finding hold.", "That is the path that led to the FTC case.", "Reviews are not competent scientific evidence."], "explanation": "Grow the evidence before you grow the claim."}, "proReasoning": "Founders grow the evidence before the claim. Proof can beat bigger ad budgets.", "commonMistake": "Advertising a claim your sample cannot support.", "mentalModel": "Evidence first, claim second."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if brain games really prevent dementia, as some ads say.", "prompt": "What's a fair answer?", "options": ["No such game has ever been studied", "Big claims need proof, often missing", "Yes, every game prevents dementia"], "correctIndex": 1, "consequences": ["Some have been; the question is how well.", "The FTC found Lumosity's dementia claims lacked support.", "The FTC challenged exactly that kind of claim."], "explanation": "Ask what evidence backs the claim, and how many people it covered."}, "proReasoning": "Ask what evidence backs a brain claim and how many people it covered. Big promises need big studies.", "commonMistake": "Believing ad claims because they sound scientific.", "mentalModel": "Big claims need big studies."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c67afef87a45$ml$]::text[]),
($ml$c002cff0-1f9d-5f60-99c5-6f062392be64$ml$::uuid, $ml$neuroscience$ml$, 23, 3, $ml${"id": "neuroscience-d23-c3", "title": "Ads or a trial?", "lessonTitle": "When a brain game promised too much", "slot": 3, "type": "decide", "brief": {"headline": "You run a brain-training app with money for either a big ad campaign or a controlled trial. Lumosity paid $2 million after the FTC said its brain claims lacked proof.", "kicker": "Decide where to spend when your claims need proof.", "fullText": "You run a brain-training app with growing users and one budget decision: a national ad campaign promising sharper memory, or a controlled study to test whether the app works.\n\nDay 23's case is the warning. The FTC said Lumosity claimed its games would improve performance at work and school and delay age-related decline, dementia and Alzheimer's, without scientific support. Lumos Labs paid $2 million, with a $50 million judgment suspended, and must now have competent and reliable scientific evidence before making such claims. The FTC's Jessica Rich said it preyed on consumers' fears about age-related cognitive decline.", "sources": [{"url": "https://ftc.gov/news-events/press-releases/2016/01/lumosity-pay-2-million-settle-ftc-deceptive-advertising-charges", "label": "FTC, Lumosity to pay $2 million to settle deceptive advertising charges, Jan 2016"}]}, "evidence": {"kind": "faceOff", "prompt": "Which spend protects the company better?", "left": {"name": "National ad campaign", "note": "Promises sharper memory now"}, "right": {"name": "Controlled trial", "note": "Tests whether the app works"}, "correctIndex": 1, "explanation": "Evidence must come before the ad. A trial protects the claims you make later."}, "numbers": {"kind": "numberSense", "prompt": "Lumosity paid $2 million of a $50 million judgment. What share of the judgment did it pay?", "min": 0, "max": 20, "value": 4, "unit": "%", "explanation": "$2 million is 4% of $50 million. The rest was suspended, and the evidence rule stays."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the app's head of marketing. The CEO wants ads saying the app delays dementia.", "prompt": "What do you advise?", "options": ["Run the ads now and fix it later", "Hint at it without saying it outright", "Wait for a study that supports it"], "correctIndex": 2, "consequences": ["The FTC acted on claims already made.", "Hinting at dementia benefits carries the same risk.", "Competent and reliable evidence must come before the claim."], "explanation": "Evidence comes before the ad, not after."}, "proReasoning": "Marketing leaders protect the company by matching claims to evidence. The FTC case shows the cost of the alternative.", "commonMistake": "Treating evidence as something to add after the ads run.", "mentalModel": "Evidence before the ad."}, "invest": {"call": {"kind": "theCall", "situation": "You're on the app's board. Management wants the ad campaign.", "prompt": "What's your view?", "options": ["Fund the trial; proof is the moat", "Fund ads; growth beats proof", "Fund neither; brain apps are doomed"], "correctIndex": 0, "consequences": ["Evidence can set the app apart after Lumosity.", "Unproven claims invite FTC action.", "Apps with real evidence can stand apart."], "explanation": "Evidence protects the company and sets it apart."}, "proReasoning": "Board members weigh legal risk and lasting value. Evidence protects the company and sets it apart.", "commonMistake": "Choosing short-term growth over claims you can defend.", "mentalModel": "Proof is the moat."}, "build_startup": {"call": {"kind": "theCall", "situation": "The trial finds your app improves scores on its own games, but not daily memory.", "prompt": "What can you claim?", "options": ["Protection against later dementia", "Better scores on the trained tasks", "Better memory in everyday life"], "correctIndex": 1, "consequences": ["Nothing in the study supports that.", "That is what the study supports.", "The study did not show that."], "explanation": "Claim exactly what the study showed, and no more."}, "proReasoning": "Founders claim exactly what the study showed. Narrow, true claims survive; broad ones invite trouble.", "commonMistake": "Stretching a narrow result into a broad promise.", "mentalModel": "Claim what you showed."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why brain-game ads now sound more careful than they used to.", "prompt": "What's one reason?", "options": ["The games got worse over time", "All such ads became illegal", "The FTC acted on Lumosity's claims"], "correctIndex": 2, "consequences": ["The caution came from enforcement.", "Ads are legal; unsupported claims are not.", "Lumosity paid $2 million and must now have evidence first."], "explanation": "The FTC's 2016 case set the bar: evidence before the claim."}, "proReasoning": "Explain marketing caution with the case that caused it: the FTC's 2016 settlement with Lumosity.", "commonMistake": "Assuming careful wording means a worse product.", "mentalModel": "Enforcement shapes claims."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:528d0a708276$ml$]::text[]),
($ml$664144c3-5ec2-5372-85bf-5c3d681b9609$ml$::uuid, $ml$neuroscience$ml$, 24, 1, $ml${"id": "neuroscience-d24-c1", "title": "New evidence, old debate", "lessonTitle": "Do adults grow new neurons?", "slot": 1, "type": "apply", "brief": {"headline": "In July 2025, a Karolinska team reported in Science that adult human brains contain dividing precursors of new neurons in the hippocampus. Some adults had many; others had hardly any.", "kicker": "Apply the lesson: one strong study does not end a dispute.", "fullText": "Jonas Frisén's team studied brain tissue from people aged 0 to 78, from several international biobanks. Using single-nucleus RNA sequencing, flow cytometry and machine learning, they identified neural progenitor cells, from stem cells to immature neurons, many of them dividing, in the dentate gyrus of the hippocampus, a region involved in memory and learning.\n\nThe cells resembled those found in mice, pigs and monkeys, though some genes were active differently. Levels varied widely: some adults had many progenitor cells, others hardly any. Karolinska noted that the extent and significance of adult neurogenesis are still debated.\n\nIn 2018, a UCSF team found no new neurons past age 13, while a Columbia team found them in all 26 brains it studied. This adds strong evidence to one side. It does not yet show what the new neurons do.", "sources": [{"url": "https://news.ki.se/new-research-confirms-that-neurons-form-in-the-adult-brain", "label": "Karolinska Institutet, New research confirms that neurons form in the adult brain, Jul 2025"}, {"url": "https://healthexec.com/topics/patient-care/precision-medicine/can-brain-grow-neurons-later-life-now-answer-maybe", "label": "HealthExec, Can the brain grow neurons later in life? For now, the answer is maybe, 2018"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the 2025 study. Tap it.", "statements": ["The cells were found in the dentate gyrus.", "Every adult had high levels of the cells.", "Many of the progenitor cells were dividing."], "fakeIndex": 1, "explanation": "Levels varied widely. Some adults had many progenitor cells and others hardly any."}, "numbers": {"kind": "numberSense", "prompt": "The brain tissue came from people aged 0 to how many years?", "min": 0, "max": 100, "value": 78, "unit": "years", "explanation": "From newborns to 78, which let the team look for these cells across the whole lifespan."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a lab studying adult neurogenesis. They ask what the 2025 study settled.", "prompt": "What's the careful answer?", "options": ["Nothing, since it only used mice", "That precursors exist, not what they do", "That every adult grows many neurons"], "correctIndex": 1, "consequences": ["It used human brain tissue.", "Significance is still debated, and levels varied widely.", "Some adults had hardly any progenitor cells."], "explanation": "Finding precursors is not the same as showing they matter for memory."}, "proReasoning": "Say exactly what a study shows. Finding precursors is not the same as showing they matter for memory.", "commonMistake": "Overstating a strong study as the final word.", "mentalModel": "Say exactly what it shows."}, "invest": {"call": {"kind": "theCall", "situation": "A startup pitches a drug to boost adult neurogenesis, citing the 2025 Science paper.", "prompt": "What's the key question left?", "options": ["Do adult humans have a hippocampus?", "Was the paper in a real journal?", "Do the new neurons matter for health?"], "correctIndex": 2, "consequences": ["Everyone has one; the question is new neurons.", "It was published in Science.", "Their extent and significance are still debated."], "explanation": "A process existing is step one. Showing it matters is step two."}, "proReasoning": "Investors ask whether a biology finding leads to benefit. Existence of a process is step one; its role is step two.", "commonMistake": "Funding a treatment on proof that a process exists.", "mentalModel": "Exists is not matters."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your brain-health startup wants to say its program grows new neurons.", "prompt": "What does the 2025 study let you say?", "options": ["Nothing about your product yet", "Your program grows new neurons", "Anyone can double their neurons"], "correctIndex": 0, "consequences": ["The study did not test any product.", "No evidence links your program to new neurons.", "Levels varied widely, and some had hardly any."], "explanation": "A study of brain tissue says nothing about an app or supplement."}, "proReasoning": "Founders keep a lab finding separate from a product claim. A study of brain tissue says nothing about an app or supplement.", "commonMistake": "Borrowing a headline as proof your product works.", "mentalModel": "A finding is not a feature."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads that adults grow new brain cells and asks if that's settled now.", "prompt": "What's a fair answer?", "options": ["No, it was firmly disproven in 2025", "Stronger evidence, but still debated", "Yes, it is now settled for good"], "correctIndex": 1, "consequences": ["The 2025 study found evidence for it.", "Precursors were found, and their significance is still debated.", "Levels varied widely, and questions remain."], "explanation": "One strong study moves the debate. It rarely ends it."}, "proReasoning": "Explain science as evidence piling up. One strong study moves the debate; it rarely ends it.", "commonMistake": "Treating each new headline as the final answer.", "mentalModel": "Evidence piles up."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:eb5099086d47$ml$]::text[]),
($ml$0391b248-6f75-5514-bd4e-cb8c698c6564$ml$::uuid, $ml$neuroscience$ml$, 24, 2, $ml${"id": "neuroscience-d24-c2", "title": "The same small region, twice", "lessonTitle": "Do adults grow new neurons?", "slot": 2, "type": "connect", "brief": {"headline": "Henry Molaison lost his hippocampus in 1953 and could no longer form new long-term memories. Whether adult humans grow new neurons in that same region is still disputed.", "kicker": "Connect day 19 and day 24: one region, a settled fact and an open question.", "fullText": "On day 19 you saw what the hippocampus does. After surgeons removed it on both sides in 1953, Henry Molaison could not form new long-term memories, though his skills still improved.\n\nOn day 24 you saw a dispute about the same region. In March 2018, a UCSF team examined 59 brains and found no new hippocampal neurons past age 13. In April 2018, a Columbia team found new neurons in all 26 brains it studied, from people aged 14 to 79, and suggested they may support thinking throughout life. The region's role in memory is settled. Whether it keeps adding neurons in adults is not.", "sources": [{"url": "https://bcs.mit.edu/news/unforgettable-life", "label": "MIT Brain and Cognitive Sciences, An unforgettable life"}, {"url": "https://healthexec.com/topics/patient-care/precision-medicine/can-brain-grow-neurons-later-life-now-answer-maybe", "label": "HealthExec, Can the brain grow neurons later in life? For now, the answer is maybe, 2018"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the hippocampus story in order.", "steps": ["1953: surgery removes Molaison's hippocampus", "He can no longer form new long-term memories", "Decades of study map the memory systems", "March 2018: UCSF finds no new neurons past 13", "April 2018: Columbia finds them in all 26 brains"], "explanation": "The memory role was settled decades ago. The question of new neurons split two labs within a month."}, "numbers": {"kind": "numberSense", "prompt": "The UCSF team examined how many brains?", "min": 0, "max": 150, "value": 59, "unit": "brains", "explanation": "59 brains, against Columbia's 26. Neither count settled the question."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked what is settled and what is open about the hippocampus.", "prompt": "What's the best answer?", "options": ["Both questions are now fully settled", "Neither question has any real evidence", "Its role is settled; new neurons are not"], "correctIndex": 2, "consequences": ["The neurogenesis studies disagreed.", "Both have decades of evidence.", "Molaison settled the role; the 2018 studies split on new neurons."], "explanation": "Separate the settled memory role from the open question of adult neurogenesis."}, "proReasoning": "Separate settled facts from open questions. It shows you think like a scientist.", "commonMistake": "Treating a disputed finding as settled because the region is well known.", "mentalModel": "Settled versus open."}, "invest": {"call": {"kind": "theCall", "situation": "A company's memory drug assumes adults grow new hippocampal neurons.", "prompt": "How do you rate that foundation?", "options": ["Shaky, since the labs disagree", "Solid, since Molaison proved it", "Irrelevant to memory"], "correctIndex": 0, "consequences": ["UCSF found none past 13; Columbia found them in all 26.", "Molaison showed the role in memory, not neurogenesis.", "The hippocampus is central to memory."], "explanation": "The drug rests on the disputed part of the science, not the settled part."}, "proReasoning": "Investors check which part of the science a product rests on. A settled region can still host an open question.", "commonMistake": "Borrowing certainty from one finding for another.", "mentalModel": "Check which fact it rests on."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building a memory product around the hippocampus.", "prompt": "What's the safer scientific base?", "options": ["Its role in running breathing", "Its role in forming new memories", "Its ability to grow new neurons"], "correctIndex": 1, "consequences": ["The brainstem runs breathing.", "Molaison showed this decades ago.", "Still disputed between respected labs."], "explanation": "Build on the settled part of the science."}, "proReasoning": "Founders build on the settled part of the science and treat the disputed part as a risk.", "commonMistake": "Building a product on a disputed finding.", "mentalModel": "Build on settled ground.", "sources": [{"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}]}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether the brain's memory center can grow new cells.", "prompt": "What's the honest answer?", "options": ["Yes, it grows them every day", "No, it has no cells to grow", "Scientists still disagree"], "correctIndex": 2, "consequences": ["That is not settled.", "The question is new neurons, not whether it has cells.", "Two respected labs reached opposite answers in 2018."], "explanation": "When respected labs disagree, the honest answer says so."}, "proReasoning": "Say 'scientists disagree' when they do. It is more accurate than a confident guess.", "commonMistake": "Picking an answer to a question science has not settled.", "mentalModel": "Say when it is open."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:635a23214a6b$ml$]::text[]),
($ml$583a33ae-4dd0-545a-8f06-2740a7bd23c7$ml$::uuid, $ml$neuroscience$ml$, 24, 3, $ml${"id": "neuroscience-d24-c3", "title": "Grows new brain cells?", "lessonTitle": "Do adults grow new neurons?", "slot": 3, "type": "decide", "brief": {"headline": "You run a supplement brand. Marketing wants the label to say it grows new brain cells. Two respected labs disagree on whether adults grow new hippocampal neurons at all.", "kicker": "Decide what your label can honestly say.", "fullText": "You run a supplement company. Marketing wants a new label: grows new brain cells for a sharper memory.\n\nDay 24 shows the science underneath. In March 2018, Shawn Sorrells and colleagues at UCSF examined 59 brains and found no new hippocampal neurons past age 13, concluding adult neurogenesis does not continue or is extremely rare. In April 2018, a Columbia team found new neurons in all 26 brains it studied, aged 14 to 79. Whether adult humans grow new hippocampal neurons remains an open question, and a disputed finding is a shaky base for a product.", "sources": [{"url": "https://healthexec.com/topics/patient-care/precision-medicine/can-brain-grow-neurons-later-life-now-answer-maybe", "label": "HealthExec, Can the brain grow neurons later in life? For now, the answer is maybe, 2018"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What does the 2018 evidence say about new neurons in adults?", "options": ["Respected labs disagree", "It is proven in every adult", "It is proven never to happen"], "correctIndex": 0, "explanation": "UCSF found none past 13; Columbia found them in all 26 brains. The question is open."}, "numbers": {"kind": "numberSense", "prompt": "The UCSF team found no new hippocampal neurons past what age?", "min": 0, "max": 60, "value": 13, "unit": "years", "explanation": "Age 13, while Columbia found new neurons in people up to 79. Your label would be picking a side."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the company's regulatory lead. Marketing sends you the new label.", "prompt": "What do you advise?", "options": ["Drop it; the science is disputed", "Approve it; one lab supports it", "Add a disclaimer in small print"], "correctIndex": 0, "consequences": ["A disputed finding cannot support a product claim.", "Another lab found the opposite.", "Fine print does not fix an unsupported claim."], "explanation": "A claim the science cannot carry is a legal and trust risk."}, "proReasoning": "Regulatory leads stop claims the science cannot carry. After Lumosity, unsupported brain claims are a known legal risk.", "commonMistake": "Approving a claim because one study points that way.", "mentalModel": "Disputed science, no claim.", "sources": [{"url": "https://ftc.gov/news-events/press-releases/2016/01/lumosity-pay-2-million-settle-ftc-deceptive-advertising-charges", "label": "FTC, Lumosity to pay $2 million to settle deceptive advertising charges, Jan 2016"}]}, "invest": {"call": {"kind": "theCall", "situation": "You're considering investing in the brand. Its growth plan rests on the new label.", "prompt": "What's the risk?", "options": ["Labels are never checked", "The claim rests on disputed science", "Supplements are always proven"], "correctIndex": 1, "consequences": ["The FTC has acted on brain claims before.", "A shaky scientific base makes the claim a liability.", "They are not, and neither is this claim."], "explanation": "Growth built on a disputed finding can reverse fast."}, "proReasoning": "Investors treat unsupported claims as liabilities. Growth built on a disputed finding can reverse fast.", "commonMistake": "Counting a marketing claim as an asset.", "mentalModel": "Unsupported claims are liabilities.", "sources": [{"url": "https://ftc.gov/news-events/press-releases/2016/01/lumosity-pay-2-million-settle-ftc-deceptive-advertising-charges", "label": "FTC, Lumosity to pay $2 million to settle deceptive advertising charges, Jan 2016"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. You want a claim that is both true and appealing.", "prompt": "Which direction is soundest?", "options": ["Claim new neurons, since it sounds great", "Claim whatever rivals claim", "Claim only what your studies show"], "correctIndex": 2, "consequences": ["The science is disputed.", "Copying weak claims copies the risk.", "True claims survive scrutiny and build trust."], "explanation": "Build claims on your own evidence, not on an open debate."}, "proReasoning": "Founders build claims on their own evidence, not on open scientific debates.", "commonMistake": "Choosing a claim for appeal over support.", "mentalModel": "Own evidence, own claims."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend sees a supplement that promises to grow new brain cells.", "prompt": "What should they know?", "options": ["Scientists disagree that adults do this", "It is proven for all adults", "Brain cells are made from supplements"], "correctIndex": 0, "consequences": ["Two respected labs reached opposite conclusions.", "That is not established.", "No such evidence was presented."], "explanation": "The science behind the label is not settled."}, "proReasoning": "Teach the question behind the label: is the science settled? Here, it is not.", "commonMistake": "Trusting a label because it names real biology.", "mentalModel": "Is the science settled?"}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:99aa5c96d6c8$ml$]::text[]),
($ml$5e130f05-b260-5c47-8665-bd7b2c8c55aa$ml$::uuid, $ml$neuroscience$ml$, 25, 1, $ml${"id": "neuroscience-d25-c1", "title": "Nine emitters, four minutes", "lessonTitle": "Three ways past the brain's gate", "slot": 1, "type": "apply", "brief": {"headline": "In 2023, a Northwestern team reported that a skull implant with nine ultrasound emitters opened the blood-brain barrier in about four minutes, raising chemotherapy levels in the brain four- to six-fold.", "kicker": "Apply the routes: ultrasound opens the gate for a short window.", "fullText": "Paclitaxel, a powerful chemotherapy drug, does not cross the blood-brain barrier under normal conditions. In a phase 1 trial published in The Lancet Oncology on May 2, 2023, patients with glioblastoma, an aggressive brain tumor, had Carthera's SonoCloud-9 implanted in the skull: a grid of nine ultrasound emitters covering nine times the brain volume of an earlier single-emitter device.\n\nThe ultrasound opened the barrier in about four minutes while patients were awake, and drug concentrations in the brain rose about four- to six-fold for paclitaxel and carboplatin. Most of the barrier's integrity returned within about an hour, far sooner than the roughly six hours the field had assumed. A phase 2 trial is testing whether this extends survival.\n\nOf day 25's three routes, this is the third: open the gate briefly, and time the drug to the window.", "sources": [{"url": "https://www.eurekalert.org/news-releases/987695", "label": "EurekAlert via Northwestern, Ultrasound opens the brain barrier for chemotherapy, May 2023"}, {"url": "https://news.feinberg.northwestern.edu/?p=161385", "label": "Northwestern Medicine, Chemotherapy drug reaches brain tumors using ultrasound, May 2023"}, {"url": "https://www.neurologylive.com/view/combination-ultrasound-blood-brain-barrier-opening-aducanumab-significantly-reduces-amyloid-ad", "label": "NeurologyLive, Ultrasound blood-brain barrier opening with aducanumab reduces amyloid, Feb 2024"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the ultrasound approach in order.", "steps": ["A nine-emitter implant is placed in the skull", "Ultrasound opens the barrier in about four minutes", "Drug levels in the brain rise four- to six-fold", "Most of the barrier closes within about an hour", "A phase 2 trial tests whether survival improves"], "explanation": "The barrier opens briefly and closes fast. More drug gets in, and survival is what the next trial must show."}, "numbers": {"kind": "numberSense", "prompt": "About how many minutes did the ultrasound take to open the barrier?", "min": 0, "max": 20, "value": 4, "unit": "minutes", "explanation": "About four minutes, with patients awake. The window then closes within about an hour."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a focused ultrasound company. They ask what the 2023 study changed.", "prompt": "What's the strongest answer?", "options": ["The barrier stays open for several days", "Drugs now cross the barrier without help", "The barrier closes within about an hour"], "correctIndex": 2, "consequences": ["Most of it closed within about an hour.", "The ultrasound opening is what let the drug in.", "Faster closing than the six hours assumed means tighter drug timing."], "explanation": "A one-hour window, not six hours, means drug timing has to be precise."}, "proReasoning": "Name the finding that changes practice. A one-hour window means drug timing has to be precise.", "commonMistake": "Describing ultrasound as a lasting opening.", "mentalModel": "Time the drug to the window."}, "invest": {"call": {"kind": "theCall", "situation": "A company sells implanted ultrasound to get chemotherapy into brain tumors.", "prompt": "What must the phase 2 trial show?", "options": ["That more drug in the brain helps survival", "That the barrier can be opened at all", "That patients can stay awake for it"], "correctIndex": 0, "consequences": ["Higher drug levels matter only if patients live longer.", "Phase 1 already showed it opens in about four minutes.", "Phase 1 already showed that."], "explanation": "Four- to six-fold more drug is a means. Survival is the end."}, "proReasoning": "Investors separate delivery proof from outcome proof. Four- to six-fold more drug is a means; survival is the end.", "commonMistake": "Treating better delivery as proof of benefit.", "mentalModel": "Delivery is a means, not the end."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building software to plan ultrasound sessions alongside chemotherapy.", "prompt": "Which finding should shape your product most?", "options": ["Only one emitter can be used", "Most of the barrier closes in an hour", "The barrier stays open six hours"], "correctIndex": 1, "consequences": ["The new device uses a grid of nine.", "Drug dosing must fit inside a short window.", "That was the old assumption, now revised."], "explanation": "A short window makes timing the core problem your product solves."}, "proReasoning": "Founders build around the constraint the data revealed. A one-hour window makes timing the core problem.", "commonMistake": "Designing around an outdated assumption.", "mentalModel": "Build around the real window."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how sound waves could help a cancer drug reach the brain.", "prompt": "What's the simple answer?", "options": ["They push the drug through the skull", "They destroy the tumor directly", "They briefly open the brain's barrier"], "correctIndex": 2, "consequences": ["The drug travels in the blood; ultrasound opens the gate.", "Here ultrasound helps the drug in rather than attacking the tumor.", "The barrier opened in about four minutes and closed within about an hour."], "explanation": "Ultrasound works like a door that opens briefly, so drug in the blood can get through."}, "proReasoning": "Explain ultrasound as a timed door: it opens the barrier briefly so the drug in the blood can get through.", "commonMistake": "Thinking the ultrasound itself is the treatment.", "mentalModel": "A door that opens briefly."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:22d8315a40a4$ml$]::text[]),
($ml$29dfc439-e03c-550f-a21a-923f816df73a$ml$::uuid, $ml$neuroscience$ml$, 25, 2, $ml${"id": "neuroscience-d25-c2", "title": "Three ways around one wall", "lessonTitle": "Three ways past the brain's gate", "slot": 2, "type": "connect", "brief": {"headline": "More than 98% of small-molecule drugs and nearly all large ones cannot cross the blood-brain barrier. Developers go around it, ride through it on a receptor, or open it briefly with ultrasound.", "kicker": "Connect day 3 and day 25: one barrier, three workarounds.", "fullText": "On day 3 you met the problem: Pardridge wrote that essentially 100% of large-molecule drugs and more than 98% of small-molecule drugs do not cross the blood-brain barrier. On day 25 you met three workarounds.\n\nSpinraza, approved in 2016 for spinal muscular atrophy, goes around the barrier by intrathecal injection into the fluid surrounding the spinal cord. Brain shuttles ride through it: Denali's Avlayah, approved in March 2026 for neurologic Hunter syndrome, binds the transferrin receptor, which carries it across. Focused ultrasound can open it briefly; a 2024 study paired it with an Alzheimer's antibody in 3 patients.", "sources": [{"url": "https://springeropen.altmetric.com/details/3182022", "label": "Pardridge 2005, The blood-brain barrier: bottleneck in brain drug development"}, {"url": "https://investors.biogen.com/news-releases/news-release-details/us-fda-approves-biogens-spinrazatm-nusinersen-first-treatment", "label": "Biogen, US FDA approves Spinraza, the first treatment for spinal muscular atrophy, Dec 2016"}, {"url": "https://www.neurologylive.com/view/fda-grants-accelerated-approval-to-tividenofusp-alfa-for-neurologic-hunter-syndrome", "label": "NeurologyLive, FDA grants accelerated approval to tividenofusp alfa for neurologic Hunter syndrome, Mar 2026"}, {"url": "https://www.neurologylive.com/view/combination-ultrasound-blood-brain-barrier-opening-aducanumab-significantly-reduces-amyloid-ad", "label": "NeurologyLive, Ultrasound blood-brain barrier opening with aducanumab reduces amyloid, Feb 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "How does a brain shuttle cross the barrier?", "options": ["It opens the barrier with sound", "It rides a receptor such as transferrin", "It is injected into the spinal fluid"], "correctIndex": 1, "explanation": "Shuttles bind the transferrin receptor, which carries them across. Spinal injection goes around; ultrasound opens."}, "numbers": {"kind": "numberSense", "prompt": "Spinraza was approved in 2016 and Avlayah in 2026. How many years apart?", "min": 0, "max": 30, "value": 10, "unit": "years", "explanation": "A decade between going around the barrier and riding through it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a brain drug company. They ask how you'd get an antibody into the brain.", "prompt": "Which answer shows you know the field?", "options": ["Name the routes and their trade-offs", "Say antibodies cross the barrier easily", "Say it simply cannot be done"], "correctIndex": 0, "consequences": ["Spinal fluid, receptor shuttles and ultrasound each fit different drugs.", "Essentially no large molecules cross on their own.", "Avlayah crossed by shuttle and was approved."], "explanation": "Each route fits a different drug and disease. Knowing the trade-offs is the skill."}, "proReasoning": "Know the delivery routes and when each fits. How you get in matters as much as what you deliver.", "commonMistake": "Ignoring delivery when discussing a brain drug.", "mentalModel": "Route matters as much as cargo."}, "invest": {"call": {"kind": "theCall", "situation": "Three brain drug startups each use a different route: spinal injection, a shuttle and ultrasound.", "prompt": "What's the key question for each?", "options": ["Which one can avoid the FDA", "How well its route fits its drug", "Which one has the flashiest name"], "correctIndex": 1, "consequences": ["All of them need FDA approval.", "Each route has a different reach and burden.", "Names do not deliver drugs."], "explanation": "A route that suits one drug and disease may not suit another."}, "proReasoning": "Investors judge delivery by fit. A route that suits one drug and disease may not suit another.", "commonMistake": "Assuming one route is best for everything.", "mentalModel": "Judge the route by the fit."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your team has an antisense drug for a spinal cord disease.", "prompt": "Which route has a proven precedent?", "options": ["A daily pill taken by mouth", "Ultrasound through the skull bone", "Intrathecal injection, like Spinraza"], "correctIndex": 2, "consequences": ["Most small molecules cannot cross the barrier.", "Ultrasound targets brain regions; your target is the spinal cord.", "Spinraza reached the spinal fluid by intrathecal injection."], "explanation": "Spinraza shows the spinal fluid route works for this kind of drug."}, "proReasoning": "Founders start from a precedent that fits. Spinraza shows the spinal fluid route works for this kind of drug.", "commonMistake": "Choosing a route with no fit to the target.", "mentalModel": "Start from a fitting precedent."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how doctors get medicine into the brain if the barrier blocks it.", "prompt": "What's a good answer?", "options": ["They go around, through, or open it", "They just give much bigger doses", "They remove the barrier surgically"], "correctIndex": 0, "consequences": ["Spinal injection, receptor shuttles and ultrasound are the three routes.", "Bigger doses meet the same barrier.", "The barrier is worked around, not removed."], "explanation": "Go around it, ride through it, or open it briefly."}, "proReasoning": "Explain delivery with three verbs: go around, ride through, open briefly.", "commonMistake": "Thinking more drug alone solves the barrier.", "mentalModel": "Around, through, or open."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0e8b89a1c641$ml$]::text[]),
($ml$d2bfd356-ccdf-5163-8d1e-2b7947403de1$ml$::uuid, $ml$neuroscience$ml$, 25, 3, $ml${"id": "neuroscience-d25-c3", "title": "A route for each program", "lessonTitle": "Three ways past the brain's gate", "slot": 3, "type": "decide", "brief": {"headline": "You run R&D at a biotech with three brain programs: an antisense drug for a spinal cord disease, an enzyme for a disease of the whole brain, and a drug that needs brief access to one region.", "kicker": "Decide which route fits each program.", "fullText": "You run research at a biotech with three programs and must pick a delivery route for each. Day 25 gives you the options. Spinraza, approved in 2016 for spinal muscular atrophy, is given by intrathecal injection into the fluid around the spinal cord. Brain shuttles bind the transferrin receptor, which carries the drug across the barrier; Denali's Avlayah, approved in March 2026 for neurologic Hunter syndrome, was the first approved drug using this approach. Focused ultrasound can open the barrier briefly over a chosen region.\n\nIn brain drugs, how you get in matters as much as what you deliver.", "sources": [{"url": "https://investors.biogen.com/news-releases/news-release-details/us-fda-approves-biogens-spinrazatm-nusinersen-first-treatment", "label": "Biogen, US FDA approves Spinraza, the first treatment for spinal muscular atrophy, Dec 2016"}, {"url": "https://www.neurologylive.com/view/fda-grants-accelerated-approval-to-tividenofusp-alfa-for-neurologic-hunter-syndrome", "label": "NeurologyLive, FDA grants accelerated approval to tividenofusp alfa for neurologic Hunter syndrome, Mar 2026"}, {"url": "https://www.neurologylive.com/view/combination-ultrasound-blood-brain-barrier-opening-aducanumab-significantly-reduces-amyloid-ad", "label": "NeurologyLive, Ultrasound blood-brain barrier opening with aducanumab reduces amyloid, Feb 2024"}, {"url": "https://springeropen.altmetric.com/details/3182022", "label": "Pardridge 2005, The blood-brain barrier: bottleneck in brain drug development"}]}, "evidence": {"kind": "faceOff", "prompt": "For an enzyme given by vein to treat a whole-brain disease, which route fits better?", "left": {"name": "A transferrin receptor shuttle", "note": "Rides across the barrier, like Avlayah"}, "right": {"name": "Focused ultrasound", "note": "Opens one region briefly"}, "correctIndex": 0, "explanation": "Avlayah, a shuttle, was approved for neurologic Hunter syndrome. Ultrasound suits brief access to one region."}, "numbers": {"kind": "numberSense", "prompt": "Avlayah's 2026 approval came about how many years after Pardridge's 2005 review called the barrier a bottleneck?", "min": 0, "max": 50, "value": 21, "unit": "years", "explanation": "About 21 years from naming the bottleneck to the first FDA-approved shuttle drug."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You lead the antisense program for the spinal cord disease. The CEO asks for your route.", "prompt": "What do you propose?", "options": ["Daily pills taken by mouth at home", "Intrathecal injection, as with Spinraza", "A transferrin receptor shuttle drug"], "correctIndex": 1, "consequences": ["Most drugs in the blood cannot cross the barrier.", "It delivers into the fluid around the spinal cord.", "Possible later, but the spinal fluid route has a precedent."], "explanation": "Spinraza shows intrathecal delivery works for the spinal cord."}, "proReasoning": "Leads propose the route with the best precedent for their target. Spinraza shows intrathecal delivery works for the spinal cord.", "commonMistake": "Picking a fashionable route over a proven one.", "mentalModel": "Precedent first."}, "invest": {"call": {"kind": "theCall", "situation": "The biotech asks investors to fund a shuttle for its whole-brain enzyme.", "prompt": "What makes that plausible now?", "options": ["Shuttles need no FDA approval", "Enzymes cross the barrier unaided", "Avlayah was approved using a shuttle"], "correctIndex": 2, "consequences": ["Shuttle drugs still need full review.", "Large proteins are blocked without help.", "A shuttle drug won FDA approval in March 2026."], "explanation": "Avlayah's approval showed shuttle drugs can get through regulators."}, "proReasoning": "Investors look for a precedent that lowers risk. Avlayah's approval showed shuttle drugs can get through regulators.", "commonMistake": "Ignoring precedents that change the odds.", "mentalModel": "Precedents lower risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your third program needs brief access to one brain region, a few times a year.", "prompt": "Which route fits best?", "options": ["Focused ultrasound over that region", "Intrathecal injection into the spine", "A daily high-dose pill"], "correctIndex": 0, "consequences": ["Ultrasound opens a chosen region briefly.", "That reaches spinal fluid, not one chosen region.", "More drug in the blood meets the same barrier."], "explanation": "Brief, local access is what ultrasound does."}, "proReasoning": "Founders match the route to the access they need. Brief, local access is what ultrasound does.", "commonMistake": "Using a whole-body route for a local need.", "mentalModel": "Match route to access."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why one company would use three different ways into the brain.", "prompt": "What's the reason?", "options": ["One route works for everything", "Each drug suits a different route", "Routes are chosen at random"], "correctIndex": 1, "consequences": ["No single route suits every drug.", "Spinal fluid, shuttles and ultrasound each fit different needs.", "Routes are chosen by fit."], "explanation": "Where the drug must go, and how often, decides the route."}, "proReasoning": "Explain that delivery is chosen per drug: where it must go and how often decide the route.", "commonMistake": "Assuming one delivery method fits all brain drugs.", "mentalModel": "One drug, one route."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d9dad290e674$ml$]::text[]),
($ml$12a466e7-124b-576e-8afe-b155320f74bf$ml$::uuid, $ml$neuroscience$ml$, 26, 1, $ml${"id": "neuroscience-d26-c1", "title": "$18 million now, $1.4 billion maybe", "lessonTitle": "What getting into the brain is worth", "slot": 1, "type": "apply", "brief": {"headline": "In April 2025, Lilly paid Sangamo $18 million upfront for a gene therapy shell that crossed the blood-brain barrier in monkeys, with up to $1.4 billion more if milestones are met.", "kicker": "Apply the lesson: a way into the brain is worth paying for.", "fullText": "Sangamo's STAC-BBB is an adeno-associated virus capsid, a delivery shell for gene therapies, that showed blood-brain barrier penetration and reached neurons in nonhuman primates. Under the deal reported on April 4, 2025, Lilly took exclusive worldwide rights to use it for one neurology target, with the option to add up to four more.\n\nSangamo received $18 million upfront and could earn up to $1.4 billion more in target fees and milestones, plus royalties on sales. The Pharma Letter called Sangamo a struggling company and the deal a lifeline; its shares rose 24%, to 77 cents.\n\nAs with AbbVie's $1.4 billion for Aliada, the buyer paid for a vehicle that can carry many cargoes, not for one drug.", "sources": [{"url": "https://www.thepharmaletter.com/sangamo-thera-enters-critical-deal-with-lilly", "label": "The Pharma Letter, Sangamo enters critical deal with Lilly, Apr 2025"}, {"url": "https://thepharmaletter.com/abbvie-punts-1-billion-dollars-to-buy-early-stage-alzheimers-drug-developer-aliada", "label": "The Pharma Letter, AbbVie to buy Alzheimer's drug developer Aliada for $1.4 billion, Oct 2024"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the deal. Tap it.", "statements": ["Lilly paid $18 million upfront.", "The capsid had already worked in human patients.", "Lilly can add up to four more targets."], "fakeIndex": 1, "explanation": "The capsid showed barrier penetration in nonhuman primates. Human data were still ahead."}, "numbers": {"kind": "numberSense", "prompt": "The $18 million upfront is about what percent of the $1.4 billion in possible further payments?", "min": 0, "max": 5, "value": 1.3, "unit": "%", "explanation": "About 1.3%. Nearly all the headline money depends on milestones."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Sangamo just after the Lilly deal.", "prompt": "What does the deal structure tell you?", "options": ["Most of the money rides on milestones", "Sangamo got $1.4 billion in cash", "Lilly bought the whole company"], "correctIndex": 0, "consequences": ["Only $18 million came upfront; the rest is conditional.", "Up to $1.4 billion is possible, not paid.", "It licensed the capsid for neurology targets."], "explanation": "A small upfront and large milestones keep the risk on the work ahead."}, "proReasoning": "Read a deal's structure, not its headline. A small upfront and big milestones mean the risk stays with the work ahead.", "commonMistake": "Reading 'up to $1.4 billion' as money in the bank.", "mentalModel": "Upfront is real; milestones are maybe."}, "invest": {"call": {"kind": "theCall", "situation": "Sangamo shares jump 24% on the Lilly deal.", "prompt": "What did the market most likely value?", "options": ["An approved gene therapy", "A big partner validating the capsid", "A guaranteed $1.4 billion in cash"], "correctIndex": 1, "consequences": ["The capsid had been tested in nonhuman primates, not approved.", "A big partner paying for the vehicle signals its worth.", "Only $18 million was paid upfront."], "explanation": "The upfront proves interest; the milestones are a bet."}, "proReasoning": "Investors read partner deals as validation, then discount the milestones. The upfront proves interest; the rest is a bet.", "commonMistake": "Valuing milestone totals at face value.", "mentalModel": "Validation, then discount."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has a brain delivery platform and one drug. Two buyers call.", "prompt": "What should you protect in a deal?", "options": ["Only the name of your first drug", "Nothing; take the first offer", "Platform rights for other targets"], "correctIndex": 2, "consequences": ["The platform is worth more than one name.", "Platforms can earn per target, as Sangamo's deal shows.", "One vehicle can carry many drugs; keep that value."], "explanation": "The vehicle is the asset. License it target by target."}, "proReasoning": "Founders with a delivery platform license it target by target. The vehicle is the asset, not one cargo.", "commonMistake": "Selling the whole platform for the price of one drug.", "mentalModel": "License the vehicle per target."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Lilly would pay for an empty gene therapy shell.", "prompt": "What's the answer?", "options": ["It could carry many drugs in", "Lilly collects unusual viruses", "The shell is itself a cure"], "correctIndex": 0, "consequences": ["A way into the brain can serve many drugs.", "The value is delivery, not collection.", "It carries treatments; it does not treat on its own."], "explanation": "One good vehicle can carry many cargoes into the brain."}, "proReasoning": "Explain delivery value with a vehicle: one good truck can carry many cargoes.", "commonMistake": "Thinking only the drug inside has value.", "mentalModel": "The vehicle has value too."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c23494631f0b$ml$]::text[]),
($ml$b01621a2-b615-5c4b-ab44-5332c5c370f0$ml$::uuid, $ml$neuroscience$ml$, 26, 2, $ml${"id": "neuroscience-d26-c2", "title": "New target, new way in", "lessonTitle": "What getting into the brain is worth", "slot": 2, "type": "connect", "brief": {"headline": "BMS paid about $14 billion for Karuna and its new schizophrenia mechanism. AbbVie paid $1.4 billion for Aliada and its way of carrying drugs into the brain. Big drugmakers pay for both.", "kicker": "Connect day 8 and day 26: buying a target versus buying a vehicle.", "fullText": "On day 8 you saw Bristol Myers Squibb pay about $14 billion for Karuna Therapeutics, whose Cobenfy became the first antipsychotic to target cholinergic rather than dopamine receptors. On day 26 you saw AbbVie agree in October 2024 to pay $1.4 billion for Aliada Therapeutics, whose MODEL platform targets transferrin and CD98 receptors to carry antibodies and genetic medicines into the brain. Months earlier, AbbVie had discontinued its own anti-amyloid antibody.\n\nOne deal bought a new target with a drug nearing approval. The other bought a vehicle at an early stage. Both are ways big companies pay for what they cannot build fast enough.", "sources": [{"url": "https://www.fiercepharma.com/pharma/bristol-myers-squibbs-karuna-buyout-pays-approval-novel-schizophrenia-med-cobenfy", "label": "Fierce Pharma, BMS's Karuna buyout pays off with FDA approval for Cobenfy, Sep 2024"}, {"url": "https://thepharmaletter.com/abbvie-punts-1-billion-dollars-to-buy-early-stage-alzheimers-drug-developer-aliada", "label": "The Pharma Letter, AbbVie to buy Alzheimer's drug developer Aliada for $1.4 billion, Oct 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Which deal bought a delivery platform rather than a new mechanism?", "left": {"name": "BMS buys Karuna", "note": "About $14 billion, new receptor target"}, "right": {"name": "AbbVie buys Aliada", "note": "$1.4 billion, brain delivery platform"}, "correctIndex": 1, "explanation": "Aliada brought a way into the brain. Karuna brought a new mechanism."}, "numbers": {"kind": "numberSense", "prompt": "BMS paid about $14 billion and AbbVie $1.4 billion. About how many times larger was the BMS deal?", "min": 0, "max": 25, "value": 10, "unit": "times", "explanation": "About ten times larger, reflecting a drug near approval against an early platform."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a business development interview, you're asked to compare the Karuna and Aliada deals.", "prompt": "What's the key distinction?", "options": ["Neither deal involved the brain", "One bought a target, one a vehicle", "Both bought the same kind of asset"], "correctIndex": 1, "consequences": ["Both were brain deals.", "Karuna brought a new mechanism; Aliada a way into the brain.", "One was a mechanism, the other a delivery platform."], "explanation": "Classify deals by what was bought: a target, a drug or a vehicle."}, "proReasoning": "Classify deals by what was bought: a target, a drug or a vehicle. It shows you think like a deal team.", "commonMistake": "Comparing deals only by price.", "mentalModel": "Target, drug or vehicle?"}, "invest": {"call": {"kind": "theCall", "situation": "You compare the Karuna and Aliada deals as an investor.", "prompt": "Why might the vehicle deal be smaller?", "options": ["Delivery has no value at all", "Aliada had more sales than Karuna", "Aliada was early, with no approved drug"], "correctIndex": 2, "consequences": ["AbbVie paid $1.4 billion for it.", "Aliada was early stage, with no sales.", "Earlier assets carry more risk, so they fetch lower prices."], "explanation": "Price reflects stage as well as type."}, "proReasoning": "Investors price stage as well as type. An early platform is worth less today, but can serve many drugs later.", "commonMistake": "Assuming a smaller price means less strategic value.", "mentalModel": "Price reflects stage."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has a promising brain target and no way into the brain.", "prompt": "What's a smart partnership?", "options": ["Pair with a delivery platform owner", "Ignore delivery until Phase 3", "Sell the target at a Karuna price"], "correctIndex": 0, "consequences": ["Target plus vehicle makes a complete drug.", "Delivery problems can sink brain drugs late.", "Karuna had a drug nearing approval."], "explanation": "A good target needs a way in, and platform owners have it."}, "proReasoning": "Founders fill their gap through partners. A good target needs a way in, and platform owners have it.", "commonMistake": "Postponing the delivery question.", "mentalModel": "Target plus vehicle."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what big drug companies actually buy when they buy biotechs.", "prompt": "What's a good answer?", "options": ["Only famous scientists", "New targets, new ways in", "Only office buildings"], "correctIndex": 1, "consequences": ["They buy the science and its assets.", "Karuna brought a target; Aliada a way into the brain.", "The value was the science."], "explanation": "Biotech deals buy missing pieces: a new target, or a way to deliver drugs."}, "proReasoning": "Explain biotech deals as buying missing pieces: a new target, or a way to deliver drugs.", "commonMistake": "Thinking acquisitions are only about size.", "mentalModel": "Deals buy missing pieces."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:94d74de8efda$ml$]::text[]),
($ml$4b5ea7ff-e714-5955-8a09-9a963d983574$ml$::uuid, $ml$neuroscience$ml$, 26, 3, $ml${"id": "neuroscience-d26-c3", "title": "Budgeting for year one", "lessonTitle": "What getting into the brain is worth", "slot": 3, "type": "decide", "brief": {"headline": "You run a health plan's drug budget. Spinraza, given by spinal injection, cost $750,000 for six doses in its first year and $375,000 a year after.", "kicker": "Decide how to plan for a brain therapy with a costly first year.", "fullText": "You manage drug spending for a regional health plan. In December 2016, Biogen's Spinraza became the first US treatment for spinal muscular atrophy, given by intrathecal injection into the fluid around the spinal cord. It cost $750,000 for six doses in the first year and $375,000 a year after.\n\nGetting a drug past the blood-brain barrier is valuable, and the price reflects it. A reliable way into the nervous system is worth billions to the companies that own one, and the bill lands on payers like you.", "sources": [{"url": "https://investors.biogen.com/news-releases/news-release-details/us-fda-approves-biogens-spinrazatm-nusinersen-first-treatment", "label": "Biogen, US FDA approves Spinraza, the first treatment for spinal muscular atrophy, Dec 2016"}, {"url": "https://www.cbsnews.com/amp/news/the-cost-of-biogens-new-drug-spinraza-750000-per-patient", "label": "CBS News, The cost of Biogen's new drug: $750,000 per patient, Dec 2016"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why did Spinraza's first year cost twice as much as later years?", "options": ["Year one included surgery", "More doses were given in year one", "The price doubled after approval"], "correctIndex": 1, "explanation": "Six doses at about $125,000 each in year one. $375,000 a year after works out to about three."}, "numbers": {"kind": "numberSense", "prompt": "At $750,000 for six doses, about how much is each dose, in thousands of dollars?", "min": 0, "max": 300, "value": 125, "unit": "K", "explanation": "About $125,000 a dose. Year one is expensive because it packs in the most doses."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the plan's pharmacy analyst. Your boss asks why Spinraza spending spikes, then falls.", "prompt": "What's the explanation?", "options": ["The drug gets cheaper each month", "Patients stop needing it after a year", "Six doses in year one, fewer after"], "correctIndex": 2, "consequences": ["The price per dose did not drop; fewer doses were given.", "Spending continues at $375,000 a year.", "$750,000 in year one, $375,000 a year after."], "explanation": "Loading doses make year one the expensive year."}, "proReasoning": "Analysts explain spending by dosing schedule and price. Loading doses make year one the expensive year.", "commonMistake": "Assuming spending falls because the drug stops.", "mentalModel": "Doses drive the bill."}, "invest": {"call": {"kind": "theCall", "situation": "You're modeling Biogen's Spinraza revenue.", "prompt": "How do new and continuing patients differ?", "options": ["New patients bring twice the revenue", "Every patient brings the same each year", "Continuing patients bring more"], "correctIndex": 0, "consequences": ["$750,000 in year one against $375,000 after.", "Year one carries the extra doses.", "Continuing patients bring half as much."], "explanation": "A loading phase front-loads revenue into each patient's first year."}, "proReasoning": "Investors split revenue into new and continuing patients. A loading phase front-loads revenue.", "commonMistake": "Using one average price for every patient-year.", "mentalModel": "Split new from continuing."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers care coordination for therapies given by spinal injection.", "prompt": "When do clinics need you most?", "options": ["Never, since injections are rare", "In year one, with six injections", "Only after five years"], "correctIndex": 1, "consequences": ["Spinraza patients get repeated spinal injections.", "The first year packs in the most procedures.", "The densest schedule comes first."], "explanation": "For loading-dose therapies, the workload peaks in the first year."}, "proReasoning": "Founders find when the workload peaks. For loading-dose therapies, that is the first year.", "commonMistake": "Planning service capacity evenly across years.", "mentalModel": "Plan for the peak."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend is shocked a drug can cost $750,000 in a year.", "prompt": "What's one part of the reason?", "options": ["Spinal injections cost nothing to make", "Every drug costs about that much", "It was the first treatment for its disease"], "correctIndex": 2, "consequences": ["Delivery into spinal fluid is a medical procedure.", "Spinraza stood out for its price.", "Spinraza was the first US treatment for spinal muscular atrophy."], "explanation": "A first treatment that reaches the nervous system commands a premium."}, "proReasoning": "Explain high prices with scarcity and delivery: a first treatment that reaches the nervous system commands a premium.", "commonMistake": "Assuming price reflects only manufacturing cost.", "mentalModel": "First, and hard to deliver."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:fd9909ee067e$ml$]::text[]),
($ml$91c5c324-14ad-5b7e-9265-1031778cfa04$ml$::uuid, $ml$neuroscience$ml$, 27, 1, $ml${"id": "neuroscience-d27-c1", "title": "GSK rents a Korean shuttle", "lessonTitle": "Who owns the brain shuttles", "slot": 1, "type": "apply", "brief": {"headline": "In April 2025, GSK agreed to pay ABL Bio up to £2.1 billion, about $2.8 billion, to use its Grabody-B brain shuttle. ABL Bio keeps the platform and had already licensed it to Sanofi.", "kicker": "Apply the lesson: whoever owns the way in holds the power.", "fullText": "ABL Bio's Grabody-B targets the insulin-like growth factor 1 receptor, IGF1R, to carry drugs across the blood-brain barrier without disrupting its protective function. Under the deal reported on April 7, 2025, GSK can use it to develop antibodies, polynucleotides and oligonucleotides for diseases such as Alzheimer's and Parkinson's, and takes on development, manufacturing and sales.\n\nABL Bio gets £38.5 million upfront, up to £77.1 million with near-term milestones, up to £2.1 billion in all, plus royalties. Its shares rose 30%. In 2022 it had signed a $1.06 billion deal with Sanofi for a Parkinson's candidate built on its technology.\n\nRoche built its own shuttle. GSK chose to rent one, from a small company that can rent it to others too.", "sources": [{"url": "https://www.kedglobal.com/newsView/ked202504070003", "label": "KED Global, ABL Bio licenses its brain shuttle platform to GSK, Apr 2025"}, {"url": "https://www.roche.com/media/releases/med-cor-2025-07-28.htm", "label": "Roche, New insights in Alzheimer's disease research at AAIC, Jul 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Who keeps or takes on each part of the deal?", "buckets": ["ABL Bio", "GSK"], "items": [{"text": "Ownership of the Grabody-B platform", "bucket": 0}, {"text": "£38.5 million upfront", "bucket": 0}, {"text": "Royalties on future sales", "bucket": 0}, {"text": "Development and manufacturing", "bucket": 1}, {"text": "Selling any resulting drugs", "bucket": 1}], "explanation": "ABL Bio keeps the platform and collects payments. GSK does the costly work of turning it into drugs."}, "numbers": {"kind": "numberSense", "prompt": "The £38.5 million upfront is about what percent of the £2.1 billion total?", "min": 0, "max": 6, "value": 1.8, "unit": "%", "explanation": "About 1.8%. The owner keeps the platform and earns more as each program advances."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're offered roles at ABL Bio and at GSK's neuroscience unit after the deal.", "prompt": "What does each role revolve around?", "options": ["GSK now owns all of ABL Bio outright", "ABL owns the shuttle; GSK builds drugs", "Both of them just sell the same drug"], "correctIndex": 1, "consequences": ["GSK licensed the platform; it did not buy the company.", "ABL keeps the platform; GSK develops and sells the drugs.", "They play different roles in the deal."], "explanation": "One side improves the vehicle; the other builds cargo on it."}, "proReasoning": "Know which side of a platform deal you join: the owner improving the vehicle, or the partner building cargo.", "commonMistake": "Assuming a license makes the partner the owner.", "mentalModel": "Owner or user?"}, "invest": {"call": {"kind": "theCall", "situation": "ABL Bio has now licensed its shuttle technology to Sanofi and to GSK.", "prompt": "What does that say about its position?", "options": ["It has lost control of its platform", "Its platform must be failing", "Owning the way in lets it deal with many"], "correctIndex": 2, "consequences": ["It kept the platform and licensed uses.", "Two big partners suggest interest, not failure.", "A platform can earn from several partners at once."], "explanation": "Each partner adds upfronts, milestones and royalties."}, "proReasoning": "Investors value platforms that can be licensed many times. Each partner adds upfronts, milestones and royalties.", "commonMistake": "Valuing a platform company on one deal.", "mentalModel": "Platforms license many times."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a small biotech with a brain drug but no shuttle.", "prompt": "What does the GSK deal suggest?", "options": ["Shuttle owners will license to partners", "Only giants can get brain shuttles", "Shuttles are no longer needed"], "correctIndex": 0, "consequences": ["ABL Bio licensed to Sanofi and GSK; you could approach owners too.", "Platform owners earn by licensing.", "Most drugs still cannot cross the barrier."], "explanation": "Platform owners earn by licensing. Partnering can replace years of building."}, "proReasoning": "Founders without a shuttle look for owners willing to license. Partnerships can replace years of building.", "commonMistake": "Assuming you must build your own way in.", "mentalModel": "Rent the way in."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why GSK would pay a small Korean company billions.", "prompt": "What's the answer?", "options": ["It makes the cheapest pills", "It owns a way into the brain", "GSK wanted its office in Korea"], "correctIndex": 1, "consequences": ["The deal was about brain delivery.", "Grabody-B targets IGF1R to cross the barrier.", "The value was the platform."], "explanation": "In drug delivery, owning the way in matters more than company size."}, "proReasoning": "Explain that size does not decide power in drug delivery: owning the way in does.", "commonMistake": "Assuming big companies own all the key technology.", "mentalModel": "Owning the way in is power."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:421db0ad60ac$ml$]::text[]),
($ml$4d748ea9-1c76-53f6-aad8-e80222f07060$ml$::uuid, $ml$neuroscience$ml$, 27, 2, $ml${"id": "neuroscience-d27-c2", "title": "Build it or buy it", "lessonTitle": "Who owns the brain shuttles", "slot": 2, "type": "connect", "brief": {"headline": "Roche built its own Brainshuttle and is running Phase 3 trials with about 1,600 patients. AbbVie, after dropping its own anti-amyloid antibody, bought Aliada and its platform for $1.4 billion.", "kicker": "Connect day 26 and day 27: two ways to own the way in.", "fullText": "On day 27 you saw Roche's trontinemab, which pairs an anti-amyloid antibody with a module that binds transferrin receptor 1. Two Phase 3 trials began in 2025 with about 1,600 patients in 18 countries, and in July 2026 Roche unveiled PrevenTRON, a Phase 3 prevention trial of about 1,600 people.\n\nOn day 26 you saw the other path. In October 2024, AbbVie agreed to pay $1.4 billion for Aliada, whose MODEL platform targets transferrin and CD98 receptors, months after discontinuing its own anti-amyloid antibody. Roche built; AbbVie bought. Either way, owning the way in lets a company run more programs and bigger trials.", "sources": [{"url": "https://www.roche.com/media/releases/med-cor-2025-07-28.htm", "label": "Roche, New insights in Alzheimer's disease research at AAIC, Jul 2025"}, {"url": "https://www.neurologylive.com/view/roche-unveils-preventron-phase-3-prevention-trial-trontinemab-cognitively-unimpaired-individuals-high-risk-alzheimers", "label": "NeurologyLive, Roche unveils PrevenTRON phase 3 prevention trial of trontinemab, Jul 2026"}, {"url": "https://thepharmaletter.com/abbvie-punts-1-billion-dollars-to-buy-early-stage-alzheimers-drug-developer-aliada", "label": "The Pharma Letter, AbbVie to buy Alzheimer's drug developer Aliada for $1.4 billion, Oct 2024"}]}, "evidence": {"kind": "buildChain", "prompt": "Put AbbVie's path in order.", "steps": ["AbbVie develops its own anti-amyloid antibody", "It discontinues that antibody", "It agrees to buy Aliada for $1.4 billion", "It gains a platform targeting transferrin and CD98", "It can carry antibodies and genetic medicines in"], "explanation": "AbbVie bought what Roche built: its own way into the brain."}, "numbers": {"kind": "numberSense", "prompt": "Roche's two Phase 3 treatment trials enroll about how many thousand patients in total?", "min": 0, "max": 5, "value": 1.6, "unit": "K", "explanation": "About 1,600 in 18 countries, with another 1,600 planned for prevention. Ownership pays for scale."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're choosing between Roche's shuttle team and AbbVie's Aliada team.", "prompt": "What's similar about both roles?", "options": ["Both rent a shuttle from a rival firm", "Neither one works on brain delivery", "Both work on a platform the company owns"], "correctIndex": 2, "consequences": ["Each company owns its platform.", "Both are brain delivery platforms.", "Roche built its shuttle; AbbVie bought one."], "explanation": "Both companies own their way in, by building or buying."}, "proReasoning": "Know whether your employer owns its delivery platform. Owners can run more programs and bigger trials.", "commonMistake": "Ignoring who owns the technology you work on.", "mentalModel": "Owners set the pace."}, "invest": {"call": {"kind": "theCall", "situation": "You compare Roche and AbbVie in Alzheimer's.", "prompt": "What gives both an edge over companies without shuttles?", "options": ["They own a way past the barrier", "They avoid FDA review entirely", "They can skip Phase 3 trials"], "correctIndex": 0, "consequences": ["Owning a shuttle lets them run more brain programs.", "Both still need FDA approval.", "Roche is running large Phase 3 trials."], "explanation": "A company that owns the way in can run more brain programs."}, "proReasoning": "Investors value platform ownership. A company that owns the way in can run more brain programs.", "commonMistake": "Comparing brain drug companies without asking about delivery.", "mentalModel": "Delivery ownership is an edge."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your small biotech has an anti-amyloid antibody but no shuttle.", "prompt": "Which path fits your size?", "options": ["Skip delivery and hope", "Partner with a platform owner", "Build a shuttle from scratch alone"], "correctIndex": 1, "consequences": ["Too little drug in the brain can sink a trial.", "Small biotechs often partner for access.", "Roche and AbbVie had far more money to build or buy."], "explanation": "For most small biotechs, owning the way in means partnering."}, "proReasoning": "Founders pick the ownership path their resources allow. For most small biotechs, that means partnering.", "commonMistake": "Trying to copy a giant's build-or-buy strategy without its money.", "mentalModel": "Partner if you cannot build."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why drug giants race to own brain shuttles.", "prompt": "What's the answer?", "options": ["Shuttles are cheap and easy to copy", "Shuttles replace the drug itself", "Whoever owns the way in holds the power"], "correctIndex": 2, "consequences": ["Roche built one and AbbVie paid $1.4 billion.", "Shuttles carry the drug; they do not replace it.", "Owners can run more programs and bigger trials."], "explanation": "Whoever holds the key decides which drugs get in."}, "proReasoning": "Explain the race with a gate: whoever holds the key decides which drugs get in.", "commonMistake": "Thinking delivery is a minor detail.", "mentalModel": "Hold the key, hold the power."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:fc1223387dd5$ml$]::text[]),
($ml$88a8f252-7bfb-5f99-8888-7093b916474d$ml$::uuid, $ml$neuroscience$ml$, 27, 3, $ml${"id": "neuroscience-d27-c3", "title": "One partner or many?", "lessonTitle": "Who owns the brain shuttles", "slot": 3, "type": "decide", "brief": {"headline": "You run a small company that owns a brain shuttle. A drug giant offers a big payment for exclusive rights to use it for every brain disease.", "kicker": "Decide how much of your platform to give away.", "fullText": "You run a biotech whose shuttle binds a receptor to carry drugs across the blood-brain barrier. A drug giant offers a large upfront payment for exclusive rights to use it for every brain disease.\n\nDay 27 shows what is at stake. Roche owns its Brainshuttle and can run Phase 3 trials of about 1,600 patients each in treatment and prevention, including PrevenTRON in adults aged 55 to 80. Denali and AbbVie own competing platforms. Companies that own a way into the brain can run more programs and bigger trials; others must partner or build. Whoever owns the way in holds the power.", "sources": [{"url": "https://www.roche.com/media/releases/med-cor-2025-07-28.htm", "label": "Roche, New insights in Alzheimer's disease research at AAIC, Jul 2025"}, {"url": "https://www.neurologylive.com/view/roche-unveils-preventron-phase-3-prevention-trial-trontinemab-cognitively-unimpaired-individuals-high-risk-alzheimers", "label": "NeurologyLive, Roche unveils PrevenTRON phase 3 prevention trial of trontinemab, Jul 2026"}]}, "evidence": {"kind": "faceOff", "prompt": "Which deal keeps more power with you?", "left": {"name": "Exclusive, all targets", "note": "One partner, one big payment"}, "right": {"name": "Licenses by target", "note": "Several partners, each for set uses"}, "correctIndex": 1, "explanation": "Licensing by target keeps the platform, and the power that comes with it, in your hands."}, "numbers": {"kind": "numberSense", "prompt": "PrevenTRON enrolls adults aged 55 to how many years?", "min": 0, "max": 100, "value": 80, "unit": "years", "explanation": "Ages 55 to 80, people with no symptoms yet. Owning the shuttle lets Roche chase that market."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the company's business development lead. The CEO asks for a recommendation.", "prompt": "What do you advise?", "options": ["License by target and keep the rest", "Take exclusivity for everything", "Refuse all partners forever"], "correctIndex": 0, "consequences": ["You keep the power to deal with others.", "You give away the asset that holds the power.", "You lose the money partners bring."], "explanation": "Licensing by target keeps your options open."}, "proReasoning": "Business development leads protect the platform's future value. Licensing by target keeps options open.", "commonMistake": "Trading the whole platform for one upfront.", "mentalModel": "Keep the platform's options."}, "invest": {"call": {"kind": "theCall", "situation": "You're an investor in the shuttle company.", "prompt": "What should worry you about the exclusive offer?", "options": ["Exclusivity always brings more money", "It caps future deals at one partner", "The upfront is too large to accept"], "correctIndex": 1, "consequences": ["Several partners can bring more over time.", "One partner means no other upfronts or royalties.", "Big upfronts are welcome; the cost is exclusivity."], "explanation": "Exclusivity can sell the platform's power too cheaply."}, "proReasoning": "Investors weigh upfront cash against future options. Exclusivity can sell the platform's power too cheaply.", "commonMistake": "Choosing the biggest cheque without pricing what it gives up.", "mentalModel": "Price the options you give up."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. The giant says exclusivity is the only deal on the table.", "prompt": "What's your best move?", "options": ["Accept at once to avoid any risk", "Give the platform away for free", "Seek other partners to test the market"], "correctIndex": 2, "consequences": ["You may sell the power for less than it is worth.", "That gives away the asset entirely.", "Competing interest shows what the platform is worth."], "explanation": "Other bidders reveal what your platform is really worth."}, "proReasoning": "Founders test the market before giving away their key asset. Other bidders reveal its real value.", "commonMistake": "Accepting the first exclusive offer without alternatives.", "mentalModel": "Test the market."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a small company might turn down a giant's big offer.", "prompt": "What's a good reason?", "options": ["Its platform could earn from many partners", "Small companies simply dislike money", "It has no technology worth selling"], "correctIndex": 0, "consequences": ["Owning the way in lets it deal with several companies.", "It wants more money over time, not less.", "It owns a shuttle."], "explanation": "When you own something many need, control can be worth more than one cheque."}, "proReasoning": "Explain that keeping control can be worth more than a big cheque when you own something many need.", "commonMistake": "Assuming the biggest offer is always the best.", "mentalModel": "Control can beat cash."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:deb8e82373fe$ml$]::text[]),
($ml$a3ab87c5-4865-5057-8682-bc3b3944434b$ml$::uuid, $ml$neuroscience$ml$, 28, 1, $ml${"id": "neuroscience-d28-c1", "title": "Japan's first shuttle drug", "lessonTitle": "The numbers behind a brain shuttle", "slot": 1, "type": "apply", "brief": {"headline": "Five years before the FDA approved Avlayah, Japan approved Izcargo, a Hunter syndrome enzyme fused to a transferrin receptor antibody. In its trial, all 28 patients had lower spinal fluid heparan sulfate at 52 weeks.", "kicker": "Apply the numbers: what a shuttle trial measured, and what it did not.", "fullText": "JCR Pharmaceuticals announced Japan's approval of Izcargo, pabinafusp alfa, on March 23, 2021, for MPS II, Hunter syndrome. It fuses idursulfase, the missing enzyme, to an antibody against the human transferrin receptor, using JCR's J-Brain Cargo technology to carry it across the blood-brain barrier. JCR called it the first approved enzyme replacement therapy that penetrates the barrier when given intravenously.\n\nIn the Japanese phase 2/3 trial of 28 patients, all 28 showed significant reductions in cerebrospinal fluid heparan sulfate after 52 weeks, meeting the primary endpoint. Neurocognitive development was maintained or improved in 21 of the 28. JCR was preparing phase 3 trials in the US, Brazil, the UK, Germany and France.\n\nThe same receptor, the same disease and the same marker as Avlayah, approved in the US in March 2026.", "sources": [{"url": "https://www.businesswire.com/news/home/20210323005577/en/JCR-Pharmaceuticals-Announces-Approval-of-IZCARGO%C2%AE-Pabinafusp-Alfa-for-Treatment-of-MPS-II-Hunter-Syndrome-in-Japan", "label": "JCR Pharmaceuticals via Business Wire, Approval of Izcargo in Japan, Mar 2021"}, {"url": "https://www.neurologylive.com/view/fda-grants-accelerated-approval-to-tividenofusp-alfa-for-neurologic-hunter-syndrome", "label": "NeurologyLive, FDA grants accelerated approval to tividenofusp alfa for neurologic Hunter syndrome, Mar 2026"}]}, "evidence": {"kind": "sortSignal", "prompt": "Did the Japanese trial show each of these?", "buckets": ["Shown in the trial", "Not shown yet"], "items": [{"text": "Lower spinal fluid heparan sulfate in all 28", "bucket": 0}, {"text": "Neurocognition held or improved in 21 of 28", "bucket": 0}, {"text": "Results from an IV infusion, not a spinal shot", "bucket": 0}, {"text": "Results from a large global trial", "bucket": 1}, {"text": "Neurocognitive gains in every patient", "bucket": 1}], "explanation": "A small trial showed the marker fell in everyone and neurocognition held in most. Larger trials were still to come."}, "numbers": {"kind": "numberSense", "prompt": "Neurocognitive development was maintained or improved in 21 of 28 patients. What share is that?", "min": 0, "max": 100, "value": 75, "unit": "%", "explanation": "21 of 28 is 75%, against 100% on the marker. The two numbers tell different stories."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a company developing shuttle enzymes. They ask about Izcargo's data.", "prompt": "Which summary is most accurate?", "options": ["It cured every one of the 28 patients", "It failed to meet its primary endpoint", "Marker fell in all 28; cognition held in 21"], "correctIndex": 2, "consequences": ["The trial showed marker drops, not cures.", "It met its primary endpoint.", "That separates the marker from the clinical picture."], "explanation": "Quote the marker and the clinical number separately."}, "proReasoning": "Quote marker and clinical numbers separately. All 28 on the marker and 21 of 28 on neurocognition tell different stories.", "commonMistake": "Blending a marker result into a clinical claim.", "mentalModel": "Marker and outcome, separately."}, "invest": {"call": {"kind": "theCall", "situation": "A shuttle enzyme shows a marker drop in all 28 trial patients.", "prompt": "What's the main caution?", "options": ["28 patients is a small trial", "The marker went up, not down", "Shuttles never cross the barrier"], "correctIndex": 0, "consequences": ["Larger global trials were still being prepared.", "The marker fell in all 28.", "JCR says it crosses the barrier when given by vein."], "explanation": "Small trials can look cleaner than larger ones."}, "proReasoning": "Investors weigh strong early numbers by trial size. Small trials can look cleaner than larger ones.", "commonMistake": "Treating a perfect small result as certain.", "mentalModel": "Strong numbers, small sample."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're planning a shuttle drug for a rare brain disease.", "prompt": "What does Izcargo suggest about your first trial?", "options": ["Markers are useless in rare disease", "A clear marker can anchor a small trial", "You need 10,000 patients first"], "correctIndex": 1, "consequences": ["A marker was the primary endpoint here.", "Izcargo met its primary endpoint on a spinal fluid marker in 28.", "Rare diseases have few patients; markers help."], "explanation": "A measurable marker lets a small trial show the drug reaches its target."}, "proReasoning": "Founders in rare disease pick a measurable marker for small trials. It can show the drug reaches its target.", "commonMistake": "Designing a rare disease trial as if patients were plentiful.", "mentalModel": "Markers fit small trials."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how doctors could tell the drug was acting in the brain.", "prompt": "What's the answer?", "options": ["Patients said they could feel it", "Doctors saw it in a photograph", "A disease marker fell in spinal fluid"], "correctIndex": 2, "consequences": ["Feelings cannot show a drug reached the brain.", "The evidence was a lab marker.", "Heparan sulfate in spinal fluid fell in all 28."], "explanation": "A marker in the fluid around the brain and spinal cord shows the drug is acting there."}, "proReasoning": "Explain how delivery is measured: a marker in the fluid around the brain shows the drug is acting there.", "commonMistake": "Assuming you can see a drug reach the brain directly.", "mentalModel": "Markers show reach."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:83b2575eca9f$ml$]::text[]),
($ml$7345cfa5-ce14-5f6b-9d0a-8065a5583e55$ml$::uuid, $ml$neuroscience$ml$, 28, 2, $ml${"id": "neuroscience-d28-c2", "title": "Less swelling to watch for?", "lessonTitle": "The numbers behind a brain shuttle", "slot": 2, "type": "connect", "brief": {"headline": "Brain swelling hit 4 of 149 people on trontinemab, under 5%, against reported rates of 13% for lecanemab and 24% for donanemab. Those rates drive the MRI schedules clinics run.", "kicker": "Connect day 17 and day 28: delivery, swelling and the scan schedule.", "fullText": "On day 17 you saw why patients on anti-amyloid drugs get repeated MRIs: ARIA-E, brain swelling that MRI detects, led the FDA to add a scan before the third Leqembi infusion after identifying six fatal cases and 101 serious ones.\n\nOn day 28 you saw what a brain shuttle may change. In Roche's Phase 1b/2a study of trontinemab, 91% of patients on the higher dose fell below the amyloid threshold within 28 weeks, and ARIA-E occurred in fewer than 5%, 4 of 149, across two dose groups. NeurologyLive compared that with reported rates of 13% for lecanemab and 24% for donanemab. Phase 3 will test whether this holds, and whether patients benefit.", "sources": [{"url": "https://www.fda.gov/drugs/drug-safety-and-availability/fda-recommend-additional-earlier-mri-monitoring-patients-alzheimers-disease-taking-leqembi-lecanemab", "label": "FDA, FDA to recommend additional, earlier MRI monitoring for patients taking Leqembi, Aug 2025"}, {"url": "https://www.roche.com/media/releases/med-cor-2025-07-28.htm", "label": "Roche, New insights in Alzheimer's disease research at AAIC, Jul 2025"}, {"url": "https://www.neurologylive.com/view/roche-unveils-preventron-phase-3-prevention-trial-trontinemab-cognitively-unimpaired-individuals-high-risk-alzheimers", "label": "NeurologyLive, Roche unveils PrevenTRON phase 3 prevention trial of trontinemab, Jul 2026"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["ARIA-E hit 4 of 149 people on trontinemab.", "Trontinemab had a higher ARIA-E rate than donanemab.", "91% on the higher dose fell below the threshold."], "fakeIndex": 1, "explanation": "Under 5% for trontinemab, against a reported 24% for donanemab."}, "numbers": {"kind": "numberSense", "prompt": "4 of 149 participants had ARIA-E. About what percent is that?", "min": 0, "max": 15, "value": 2.7, "unit": "%", "explanation": "About 2.7%, well under the 13% and 24% reported for older antibodies. Phase 3 must confirm it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You run imaging at a memory clinic. A colleague says shuttle drugs will end safety MRIs.", "prompt": "What's the accurate view?", "options": ["Early data only; scans still matter", "MRIs are now totally unnecessary", "Shuttles raise the swelling rates"], "correctIndex": 0, "consequences": ["Under 5% comes from an early study; Phase 3 decides.", "ARIA-E still occurred in 4 of 149.", "Early data showed lower rates, not higher."], "explanation": "Early low rates may ease the burden later, if Phase 3 confirms them."}, "proReasoning": "Operations leads plan on evidence, not hopes. Early low rates may ease the burden later, if Phase 3 confirms them.", "commonMistake": "Cutting safety capacity on early data.", "mentalModel": "Plan on confirmed data."}, "invest": {"call": {"kind": "theCall", "situation": "You compare trontinemab's early ARIA-E rate with lecanemab's and donanemab's.", "prompt": "Why could it matter commercially?", "options": ["Higher rates boost demand", "Less swelling may ease monitoring", "Swelling rates do not affect uptake"], "correctIndex": 1, "consequences": ["Risk does not raise demand.", "Day 17 showed MRI burden can limit uptake.", "Monitoring burden shapes how fast drugs spread."], "explanation": "If lower swelling holds up, the monitoring burden could fall."}, "proReasoning": "Investors link safety numbers to workload. If lower swelling holds up, monitoring burden could fall.", "commonMistake": "Comparing efficacy alone across drugs.", "mentalModel": "Safety shapes uptake."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup reads safety MRIs for anti-amyloid clinics.", "prompt": "How should early shuttle data shape your plans?", "options": ["Shut down now, since scans are over", "Ignore it entirely", "Watch Phase 3 before changing course"], "correctIndex": 2, "consequences": ["Scans are still required for approved drugs.", "A large shift could change your market.", "Early rates may shift workload if confirmed."], "explanation": "Track the threat early, and act on confirmed data."}, "proReasoning": "Founders track threats early but act on confirmed data. Phase 3 will show whether swelling rates really fall.", "commonMistake": "Overreacting or underreacting to early data.", "mentalModel": "Watch, then act."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a new Alzheimer's drug might cause less brain swelling.", "prompt": "What's the idea?", "options": ["Better delivery may need lower doses", "The new drug is just water", "Swelling was never a real risk"], "correctIndex": 0, "consequences": ["More drug across the barrier may clear plaque at lower doses.", "It is an antibody with a shuttle.", "Six fatal ARIA-E cases were identified with Leqembi."], "explanation": "If more drug gets in, less may be needed, which could mean fewer side effects."}, "proReasoning": "Explain the shuttle idea: if more drug gets in, less may be needed, which could mean fewer side effects.", "commonMistake": "Assuming every new drug has the same risks.", "mentalModel": "Better delivery, lower dose."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:75dbd4187576$ml$]::text[]),
($ml$355893ad-45f1-50c4-9fc8-2462e0b61440$ml$::uuid, $ml$neuroscience$ml$, 28, 3, $ml${"id": "neuroscience-d28-c3", "title": "Betting on early numbers", "lessonTitle": "The numbers behind a brain shuttle", "slot": 3, "type": "decide", "brief": {"headline": "You run a fund. A brain shuttle antibody brought 91% of higher-dose patients below the amyloid threshold in 28 weeks, with swelling under 5%. Phase 3 has not reported.", "kicker": "Decide how much early numbers should move you.", "fullText": "You run a healthcare fund looking at brain shuttle companies. Roche's trontinemab is the benchmark: in the Phase 1b/2a Brainshuttle AD study, 49 of 54 participants, or 91%, on the 3.6 mg per kg dose fell below the 24-centiloid amyloid threshold after 28 weeks, and 72% reached deep clearance below 11 centiloids. Brain swelling occurred in fewer than 5%, 4 of 149, across two dose cohorts.\n\nThese come from a small early study. Phase 3 trials will test whether clearing plaque faster translates into slower decline. Better delivery can mean more effect with fewer side effects, but early data are not proof.", "sources": [{"url": "https://www.roche.com/media/releases/med-cor-2025-07-28.htm", "label": "Roche, New insights in Alzheimer's disease research at AAIC, Jul 2025"}, {"url": "https://www.neurologylive.com/view/roche-unveils-preventron-phase-3-prevention-trial-trontinemab-cognitively-unimpaired-individuals-high-risk-alzheimers", "label": "NeurologyLive, Roche unveils PrevenTRON phase 3 prevention trial of trontinemab, Jul 2026"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each shown by the early study, or still to be shown?", "buckets": ["Shown early", "Still to show"], "items": [{"text": "91% below the amyloid threshold at 28 weeks", "bucket": 0}, {"text": "Swelling in 4 of 149", "bucket": 0}, {"text": "Deep clearance in 72%", "bucket": 0}, {"text": "Slower decline in patients", "bucket": 1}, {"text": "Results in about 1,600 patients", "bucket": 1}], "explanation": "The early study showed plaque clearance and low swelling. Benefit at scale is what Phase 3 must show."}, "numbers": {"kind": "numberSense", "prompt": "49 of 54 participants fell below the threshold. What percent is that?", "min": 0, "max": 100, "value": 91, "unit": "%", "explanation": "49 of 54 is about 91%, from a small group. Impressive, and still early."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the fund's analyst. Your partner wants to call the shuttle a sure thing.", "prompt": "What's your reply?", "options": ["Worthless, since the study was small", "Strong early data; Phase 3 decides", "A sure thing, since 91% cleared"], "correctIndex": 1, "consequences": ["Small early data still carry information.", "Plaque clearance must still become slower decline.", "Clearing plaque is not yet proof of benefit."], "explanation": "Plaque clearance is a marker. Slower decline is the goal."}, "proReasoning": "Analysts say what early data prove and what they do not. Plaque clearance is a marker; slower decline is the goal.", "commonMistake": "Calling early marker data a sure thing.", "mentalModel": "Early data, not proof."}, "invest": {"call": {"kind": "theCall", "situation": "You can invest now or after Phase 3 reads out.", "prompt": "What's the trade-off?", "options": ["Now: no risk at all", "Later: more upside and more risk", "Now: more upside and more risk"], "correctIndex": 2, "consequences": ["Phase 3 could still fail.", "Waiting lowers both risk and upside.", "Early bets pay more if right and lose more if wrong."], "explanation": "Strong early numbers raise the odds without guaranteeing the result."}, "proReasoning": "Investors size early bets for the risk. Strong early numbers raise the odds without guaranteeing the result.", "commonMistake": "Sizing an early bet as if Phase 3 had already succeeded.", "mentalModel": "Size for the risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has a shuttle with early data less striking than trontinemab's.", "prompt": "How should you pitch?", "options": ["Show your data and path to proof", "Claim you beat Roche outright", "Hide your data until Phase 3"], "correctIndex": 0, "consequences": ["Honest data with a clear plan builds trust.", "Claims beyond your data backfire.", "Investors need data to fund you."], "explanation": "Pitch your own numbers next to the benchmark, with a plan to prove more."}, "proReasoning": "Founders pitch their own numbers honestly next to the benchmark, with a clear plan to prove more.", "commonMistake": "Overclaiming against a stronger benchmark.", "mentalModel": "Honest numbers, clear plan."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads that a drug cleared plaque in 91% of patients and asks if Alzheimer's is solved.", "prompt": "What's a fair answer?", "options": ["No, the drug clearly failed", "Not yet; Phase 3 must show benefit", "Yes, the disease is now solved"], "correctIndex": 1, "consequences": ["Early results were strong.", "Phase 3 will test whether patients benefit.", "A small early study cannot settle that."], "explanation": "Clearing plaque is promising. Slowing decline is what patients need."}, "proReasoning": "Separate a marker from a cure: clearing plaque is promising, slowing decline is what patients need.", "commonMistake": "Reading marker success as a cure.", "mentalModel": "Marker first, benefit later."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4ba1925e9fd7$ml$]::text[]),
($ml$7d91fdf6-c369-5c0b-97d2-511fc24faede$ml$::uuid, $ml$neuroscience$ml$, 29, 1, $ml${"id": "neuroscience-d29-c1", "title": "Approved on a nerve-damage marker", "lessonTitle": "Approved on a marker, judged on benefit", "slot": 1, "type": "apply", "brief": {"headline": "In April 2023, the FDA granted accelerated approval to Biogen's ALS drug Qalsody because it lowered a blood marker of nerve damage. Its Phase 3 trial had missed its main goal.", "kicker": "Apply the lesson: a marker opens the door; benefit must keep it open.", "fullText": "Qalsody, tofersen, from Biogen and Ionis, is an antisense drug that reduces production of the SOD1 protein in people with ALS caused by SOD1 mutations. Biogen estimated fewer than 500 such patients in the US, about 2% of the roughly 168,000 people with ALS worldwide.\n\nIn the VALOR Phase 3 trial, Qalsody did not significantly improve function in patients who already had ALS-related weakness. But it reduced plasma neurofilament light, a biomarker of nerve injury, which the FDA and its advisers judged reasonably likely to predict benefit. In March 2023, nine advisers agreed the marker data supported approval; the panel did not back full approval.\n\nTo keep its approval, Biogen must confirm benefit. The ATLAS trial tests whether Qalsody delays symptoms in people with the mutation who have no symptoms yet.", "sources": [{"url": "https://www.fiercepharma.com/pharma/sign-biogens-als-drug-qalsody-fda-follows-experts-advice-accelerated-approval", "label": "Fierce Pharma, FDA awards Biogen's ALS drug Qalsody an accelerated approval, Apr 2023"}, {"url": "https://www.neurologylive.com/view/fda-grants-accelerated-approval-to-tividenofusp-alfa-for-neurologic-hunter-syndrome", "label": "NeurologyLive, FDA grants accelerated approval to tividenofusp alfa for neurologic Hunter syndrome, Mar 2026"}]}, "evidence": {"kind": "buildChain", "prompt": "Put Qalsody's path to approval in order.", "steps": ["VALOR misses its main functional goal", "Neurofilament light falls in the blood", "Advisers say the marker likely predicts benefit", "The FDA grants accelerated approval", "ATLAS must confirm benefit to keep it"], "explanation": "A marker opened the door after the main goal was missed. Confirmation decides whether it stays open."}, "numbers": {"kind": "numberSense", "prompt": "SOD1-ALS is about what share of the roughly 168,000 people with ALS worldwide?", "min": 0, "max": 10, "value": 2, "unit": "%", "explanation": "About 2%, fewer than 500 patients in the US. Small groups make markers valuable."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Biogen's ALS team in 2023. A friend asks if Qalsody is proven to work.", "prompt": "What's the accurate answer?", "options": ["It lowers a marker; benefit is pending", "Yes, VALOR proved it improves function", "No, the FDA rejected it"], "correctIndex": 0, "consequences": ["Approval rests on neurofilament light; ATLAS must confirm.", "VALOR missed its primary endpoint.", "It won accelerated approval."], "explanation": "Approved on a marker, with benefit still to confirm."}, "proReasoning": "Describe accelerated approvals precisely: approved on a marker, with benefit still to confirm.", "commonMistake": "Calling an accelerated approval proof of benefit.", "mentalModel": "Marker now, benefit later."}, "invest": {"call": {"kind": "theCall", "situation": "You hold Biogen shares after Qalsody's accelerated approval.", "prompt": "What's the key risk to track?", "options": ["Whether ALS really exists", "Whether ATLAS confirms benefit", "Whether the marker can be measured"], "correctIndex": 1, "consequences": ["The disease is real; the question is benefit.", "Continued approval depends on confirming benefit.", "It was measured; that is how it was approved."], "explanation": "The confirmatory trial decides whether the approval stays."}, "proReasoning": "Investors price confirmation risk into marker-based approvals. The confirmatory trial decides whether approval stays.", "commonMistake": "Valuing an accelerated approval like a full one.", "mentalModel": "Price the confirmation."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup develops a drug for a rare form of ALS, with few patients for big trials.", "prompt": "What does Qalsody suggest?", "options": ["Rare diseases never get approved", "Markers replace all trials forever", "A marker can support early approval"], "correctIndex": 2, "consequences": ["Qalsody was approved for a rare form.", "Confirmatory evidence is still required.", "Neurofilament light supported accelerated approval."], "explanation": "Plan around a marker regulators may accept, and still plan the confirmatory trial."}, "proReasoning": "Founders in rare disease plan around markers regulators may accept, and still plan the confirmatory trial.", "commonMistake": "Assuming a marker approval ends the need for proof.", "mentalModel": "Marker in, proof after."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a drug can be approved if its main trial missed.", "prompt": "What's the explanation?", "options": ["A marker suggested likely benefit", "The FDA simply ignored the trial", "The trial secretly succeeded"], "correctIndex": 0, "consequences": ["Accelerated approval can rest on a reasonably likely marker.", "The FDA weighed the marker and the trial together.", "It missed its primary endpoint."], "explanation": "A marker reasonably likely to predict benefit can open the door, with proof required later."}, "proReasoning": "Explain accelerated approval: a marker reasonably likely to predict benefit can open the door, with proof required later.", "commonMistake": "Assuming approval always means a trial hit its main goal.", "mentalModel": "Approval comes in kinds."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c3a00d2cb36d$ml$]::text[]),
($ml$9eb3065f-b248-50b9-9529-6b0aa8eb61b6$ml$::uuid, $ml$neuroscience$ml$, 29, 2, $ml${"id": "neuroscience-d29-c2", "title": "Marker approval, benefit coverage", "lessonTitle": "Approved on a marker, judged on benefit", "slot": 2, "type": "connect", "brief": {"headline": "Avlayah won accelerated approval in March 2026 on a spinal fluid marker. For Alzheimer's antibodies, Medicare tied coverage to traditional approval, not accelerated approval.", "kicker": "Connect day 21 and day 29: what a marker buys, and what it does not.", "fullText": "On day 29 you saw the FDA grant accelerated approval to Denali's Avlayah on March 25, 2026, based on reduced cerebrospinal fluid heparan sulfate, a surrogate endpoint reasonably likely to predict benefit. It fell about 91% at 24 weeks. Continued approval depends on COMPASS, a 96-week trial against the older enzyme therapy idursulfase.\n\nOn day 21 you saw how one payer treated the same distinction. In June 2023, CMS said Medicare would cover Alzheimer's antibody drugs that receive traditional FDA approval, through a registry. Coverage required traditional approval, not just accelerated approval. A marker can open the FDA's door before a payer opens its own.", "sources": [{"url": "https://www.neurologylive.com/view/fda-grants-accelerated-approval-to-tividenofusp-alfa-for-neurologic-hunter-syndrome", "label": "NeurologyLive, FDA grants accelerated approval to tividenofusp alfa for neurologic Hunter syndrome, Mar 2026"}, {"url": "https://www.auntminnie.com/clinical-news/molecular-imaging/article/15633540/cms-to-cover-alzheimers-drugs-for-patients-enrolled-in-registry", "label": "AuntMinnie, CMS to cover Alzheimer's drugs for patients enrolled in registry, May 2023"}]}, "evidence": {"kind": "faceOff", "prompt": "Which approval did Medicare require before covering Alzheimer's antibodies?", "left": {"name": "Accelerated approval", "note": "Based on a marker likely to predict benefit"}, "right": {"name": "Traditional approval", "note": "Based on shown clinical benefit"}, "correctIndex": 1, "explanation": "CMS tied coverage to traditional approval. A marker alone was not enough for Medicare."}, "numbers": {"kind": "numberSense", "prompt": "Avlayah's confirmatory trial, COMPASS, runs for how many weeks?", "min": 0, "max": 250, "value": 96, "unit": "weeks", "explanation": "Almost two years. Until it reads out, the approval rests on the marker."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a rare disease company after an accelerated approval. Payers ask about evidence.", "prompt": "What should your team prepare?", "options": ["A plan to skip confirmation", "Progress on the confirmatory trial", "Proof the marker was measured"], "correctIndex": 1, "consequences": ["Continued approval depends on confirmation.", "Payers and regulators want benefit confirmed.", "The marker was the basis; benefit is next."], "explanation": "Confirmatory progress is what payers want to see."}, "proReasoning": "Market access teams know payers may treat accelerated approval differently. Confirmatory progress is the answer.", "commonMistake": "Assuming payers treat every approval the same.", "mentalModel": "Payers watch the confirmation."}, "invest": {"call": {"kind": "theCall", "situation": "A company wins accelerated approval on a marker.", "prompt": "What might limit early revenue?", "options": ["The FDA will withdraw it at once", "Markers always mean full coverage", "Payers may wait for confirmed benefit"], "correctIndex": 2, "consequences": ["Withdrawal depends on the confirmatory trial.", "Coverage can require more than a marker.", "Medicare tied Alzheimer's antibody coverage to traditional approval."], "explanation": "Coverage can lag until benefit is confirmed."}, "proReasoning": "Investors check how payers treat accelerated approvals. Coverage can lag until benefit is confirmed.", "commonMistake": "Assuming approval and payment arrive together.", "mentalModel": "Approval is not payment."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's drug may win approval on a marker.", "prompt": "What should your plan include from day one?", "options": ["A confirmatory trial and payer plan", "A marketing launch and nothing else", "Nothing more beyond the marker"], "correctIndex": 0, "consequences": ["Both regulators and payers look for confirmed benefit.", "Marketing cannot replace confirmation.", "Continued approval depends on more evidence."], "explanation": "A marker opens the door; benefit keeps it open and gets you paid."}, "proReasoning": "Founders plan confirmation and coverage together. A marker opens the door; benefit keeps it open and gets you paid.", "commonMistake": "Planning only for the approval moment.", "mentalModel": "Plan past the approval."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a drug can be FDA approved but not broadly covered.", "prompt": "What's one reason?", "options": ["The FDA sets insurance rules", "It was approved on a marker", "Insurers never cover new drugs"], "correctIndex": 1, "consequences": ["Payers set their own rules.", "Payers may wait for confirmed benefit.", "Insurers cover many new drugs."], "explanation": "Approvals and coverage can use different evidence bars."}, "proReasoning": "Explain that approvals and coverage use different evidence bars. A marker may be enough for one, not the other.", "commonMistake": "Assuming approval guarantees coverage.", "mentalModel": "Different bars."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:dd3d318cc072$ml$]::text[]),
($ml$36e4ab68-cd77-5fde-88bc-6e9dac52b723$ml$::uuid, $ml$neuroscience$ml$, 29, 3, $ml${"id": "neuroscience-d29-c3", "title": "Covering a drug approved on a marker", "lessonTitle": "Approved on a marker, judged on benefit", "slot": 3, "type": "decide", "brief": {"headline": "You run a health plan's rare disease program. Avlayah won accelerated approval after cutting a spinal fluid marker by about 91%, but its 96-week confirmatory trial is still running.", "kicker": "Decide how to cover a marker-based approval.", "fullText": "You manage rare disease drugs for a health plan. On March 25, 2026, the FDA granted accelerated approval to Denali's Avlayah for neurologic Hunter syndrome, based on reduced cerebrospinal fluid heparan sulfate, a surrogate endpoint considered reasonably likely to predict benefit. In a phase 1/2 study of 47 patients, heparan sulfate fell about 91% at 24 weeks, and 93% of treated patients reached normal levels.\n\nContinued approval depends on COMPASS, a 96-week global phase 2/3 trial comparing Avlayah with idursulfase, an existing enzyme therapy that does not cross the barrier. If the confirmatory trial fails, approval can be withdrawn.", "sources": [{"url": "https://www.neurologylive.com/view/fda-grants-accelerated-approval-to-tividenofusp-alfa-for-neurologic-hunter-syndrome", "label": "NeurologyLive, FDA grants accelerated approval to tividenofusp alfa for neurologic Hunter syndrome, Mar 2026"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Approval rested on a spinal fluid marker.", "COMPASS has already confirmed the benefit.", "The marker fell about 91% at 24 weeks."], "fakeIndex": 1, "explanation": "COMPASS is still running. Continued approval depends on it."}, "numbers": {"kind": "numberSense", "prompt": "In the phase 1/2 study, what share of treated patients reached normal heparan sulfate levels?", "min": 0, "max": 100, "value": 93, "unit": "%", "explanation": "93% reached normal levels on the marker. Whether that becomes clinical benefit is what COMPASS tests."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the plan's clinical pharmacist. A doctor requests Avlayah for a child with Hunter syndrome.", "prompt": "What's the sound approach?", "options": ["Deny it until COMPASS reads out", "Cover it with no criteria at all", "Cover per label; track COMPASS"], "correctIndex": 2, "consequences": ["The drug is approved for this use now.", "Coverage criteria should follow the label.", "It is FDA approved; confirmation will update the picture."], "explanation": "Accelerated approval is real approval, with evidence still due."}, "proReasoning": "Pharmacists cover approved drugs by their label and watch the evidence. Accelerated approval is real approval, with homework due.", "commonMistake": "Treating an accelerated approval as no approval.", "mentalModel": "Real approval, homework due."}, "invest": {"call": {"kind": "theCall", "situation": "You're an investor in Denali after the approval.", "prompt": "What should you model?", "options": ["Sales, with risk tied to COMPASS", "Guaranteed sales forever", "Zero sales until COMPASS ends"], "correctIndex": 0, "consequences": ["Continued approval depends on the confirmatory trial.", "Approval can be withdrawn if COMPASS fails.", "The drug can be sold now."], "explanation": "Value the approval with confirmation risk built in."}, "proReasoning": "Investors value accelerated approvals with confirmation risk built in.", "commonMistake": "Ignoring the confirmatory trial in the forecast.", "mentalModel": "Price in confirmation risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers outcomes tracking for rare disease drugs.", "prompt": "Which service fits Avlayah's situation?", "options": ["Replacing the confirmatory trial", "Tracking real-world benefit", "Marketing the drug to families"], "correctIndex": 1, "consequences": ["Continued approval depends on COMPASS itself.", "Payers want evidence of benefit beyond the marker.", "Marketing is the maker's job."], "explanation": "Real-world tracking helps payers while confirmation runs."}, "proReasoning": "Founders serve the evidence gap an accelerated approval leaves. Real-world tracking helps payers while confirmation runs.", "commonMistake": "Trying to replace a required trial.", "mentalModel": "Fill the evidence gap."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend's nephew with Hunter syndrome may get Avlayah. They ask what accelerated approval means.", "prompt": "What's a fair explanation?", "options": ["Approved without any data", "Approved for good, no conditions", "Approved on a marker; proof is pending"], "correctIndex": 2, "consequences": ["It was approved on marker data from 47 patients.", "Continued approval depends on COMPASS.", "Heparan sulfate fell about 91%; COMPASS tests benefit."], "explanation": "A strong marker result now, with proof of benefit required later."}, "proReasoning": "Explain accelerated approval plainly: a strong marker result now, with proof of benefit required later.", "commonMistake": "Thinking accelerated means rushed or unproven.", "mentalModel": "Marker now, proof later."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b4f3313fba41$ml$]::text[]),
($ml$24ac675c-04c1-5436-b638-556424304bf9$ml$::uuid, $ml$neuroscience$ml$, 30, 1, $ml${"id": "neuroscience-d30-c1", "title": "The capsules that delivered too little", "lessonTitle": "When too little drug reached the brain", "slot": 1, "type": "apply", "brief": {"headline": "In December 2024, CervoMed's Lewy body dementia drug missed its main goal; target drug levels had not been reached. When patients moved to new capsules with higher levels, they did better.", "kicker": "Apply the lesson: if too little drug arrives, the target was never tested.", "fullText": "RewinD-LB was a 16-week, placebo-controlled Phase 2b trial of neflamapimod in 159 people with early dementia with Lewy bodies. On December 10, 2024, CervoMed said it missed its primary endpoint, the CDR-SB, and that target plasma drug concentrations were not achieved, which may have hurt the results. It paused Phase 3 planning.\n\nIn March 2025, CervoMed reported its working hypothesis: the capsules used had delivered lower drug levels than expected, because of age-related changes in how they dissolved. In the open-label extension, mean trough levels were 5.1 ng/mL on new capsules against 4.0 on old ones. From the start of the extension to week 16, patients on new capsules did better on the CDR-SB by 0.73 points than those still on old capsules. The analyses were exploratory.\n\nDay 30 was about drug failing to reach the brain. Here the shortfall started even earlier, in the blood.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1053691/000143774924037053/ex_755525.htm", "label": "CervoMed via SEC, RewinD-LB Phase 2b topline results, Dec 2024"}, {"url": "https://drug-dev.com/cervomed-announces-positive-results-from-the-extension-phase-of-its-phase-2b-clinical-study-of-neflamapimod-in-patients-with-dementia-with-lewy-bodies/", "label": "Drug Development & Delivery, CervoMed extension phase results for neflamapimod, Mar 2025"}, {"url": "https://www.alzheimer-europe.org/news/roche-discontinues-clinical-trials-gantenerumab-after-graduate-studies-fail-meet-their-primary", "label": "Alzheimer Europe, Roche discontinues gantenerumab trials after GRADUATE studies fail, Nov 2022"}]}, "evidence": {"kind": "faceOff", "prompt": "Which capsules reached the higher drug levels?", "left": {"name": "Old capsules", "note": "Used in the double-blind phase"}, "right": {"name": "New capsules", "note": "Introduced during the extension"}, "correctIndex": 1, "explanation": "New capsules gave mean trough levels of 5.1 ng/mL, against 4.0 for the old ones."}, "numbers": {"kind": "numberSense", "prompt": "New capsules gave 5.1 ng/mL against 4.0 for old ones. About what percent higher is that?", "min": 0, "max": 100, "value": 28, "unit": "%", "explanation": "About 28% more drug in the blood, and a better result on the CDR-SB."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a clinical pharmacologist at CervoMed after the December 2024 miss.", "prompt": "What's the first question to answer?", "options": ["Should we drop the program now?", "Did patients get enough drug?", "Is the target the wrong one?"], "correctIndex": 1, "consequences": ["Not before checking exposure.", "Target drug levels were not reached, so exposure comes first.", "Too early: low exposure can hide a good target."], "explanation": "A drug that never reached its target levels was never fairly tested."}, "proReasoning": "Pharmacologists check exposure before judging the target. A drug that never reached its levels was never fairly tested.", "commonMistake": "Blaming the target before checking the dose that arrived.", "mentalModel": "Check exposure first."}, "invest": {"call": {"kind": "theCall", "situation": "CervoMed's stock falls after the miss. Later, new-capsule data look better.", "prompt": "How should you read the new data?", "options": ["Proof that the drug clearly works", "Meaningless, since the trial failed", "Encouraging, but a new trial must confirm"], "correctIndex": 2, "consequences": ["Open-label, exploratory data cannot prove it.", "Exposure differences can explain a miss.", "The extension analyses were described as exploratory."], "explanation": "Rescue analyses can justify a new trial. They cannot replace one."}, "proReasoning": "Investors treat rescue analyses as hypotheses. They can justify a new trial, not replace one.", "commonMistake": "Treating exploratory subgroup data as proof.", "mentalModel": "Rescue data needs a new trial."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is about to run its first brain drug trial.", "prompt": "What does CervoMed's story tell you to check?", "options": ["That each batch hits target levels", "Only the final efficacy results", "Nothing about the capsules"], "correctIndex": 0, "consequences": ["Old capsules lost bioavailability as they aged.", "By then, an exposure problem has already cost you.", "The capsules turned out to matter a lot."], "explanation": "Measure drug levels throughout, not just at the end."}, "proReasoning": "Founders measure drug levels throughout a trial. Exposure problems found late can cost years.", "commonMistake": "Assuming the formulation will behave the same over time.", "mentalModel": "Measure exposure throughout."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a drug can fail and then look promising in the same study.", "prompt": "What happened here?", "options": ["Researchers changed the scoring", "Patients first got too little drug", "The patients changed diseases"], "correctIndex": 1, "consequences": ["The same scale, the CDR-SB, was used.", "New capsules raised drug levels, and results improved.", "The same patients continued in the extension."], "explanation": "A test with too little drug is not a fair test of the drug."}, "proReasoning": "Explain with the dose that arrived: a test with too little drug is not a fair test of the drug.", "commonMistake": "Assuming a failed trial means the drug never works.", "mentalModel": "No dose, no fair test."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4847286cc877$ml$]::text[]),
($ml$e723d666-9f64-55b9-a763-5725571947dd$ml$::uuid, $ml$neuroscience$ml$, 30, 2, $ml${"id": "neuroscience-d30-c2", "title": "Same company, better delivery", "lessonTitle": "When too little drug reached the brain", "slot": 2, "type": "connect", "brief": {"headline": "Roche's gantenerumab failed in 2022 after removing less amyloid than expected. Its brain shuttle successor, trontinemab, brought 91% of higher-dose patients below the amyloid threshold.", "kicker": "Connect day 28 and day 30: the delivery fix after the failure.", "fullText": "On day 30 you saw the failure. In November 2022, Roche reported that neither GRADUATE I nor GRADUATE II, Phase 3 trials of gantenerumab in 1,965 people with early Alzheimer's, met its goal: decline slowed by 8% and 6%, neither statistically significant, and amyloid removal was lower than expected. Roche said it was exploring new technologies to deliver more gantenerumab into the brain.\n\nOn day 28 you saw what followed. Trontinemab, which uses Roche's Brainshuttle, brought 91% of higher-dose patients below the amyloid threshold within 28 weeks, with brain swelling under 5%. Phase 3 will test whether better delivery means slower decline.", "sources": [{"url": "https://www.alzheimer-europe.org/news/roche-discontinues-clinical-trials-gantenerumab-after-graduate-studies-fail-meet-their-primary", "label": "Alzheimer Europe, Roche discontinues gantenerumab trials after GRADUATE studies fail, Nov 2022"}, {"url": "https://www.roche.com/media/releases/med-cor-2025-07-28.htm", "label": "Roche, New insights in Alzheimer's disease research at AAIC, Jul 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did Roche do after gantenerumab removed too little amyloid?", "options": ["Raised the price of gantenerumab", "Stopped all its Alzheimer's research", "Turned to a way to get more drug in"], "correctIndex": 2, "explanation": "Roche explored new delivery technology, and its Brainshuttle drug trontinemab entered Phase 3."}, "numbers": {"kind": "numberSense", "prompt": "The GRADUATE trials enrolled about how many thousand people?", "min": 0, "max": 5, "value": 2, "unit": "K", "explanation": "1,965 people, about 2,000. A large, costly test of a drug that could not get enough into the brain."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Roche's neuroscience unit. They ask what links gantenerumab and trontinemab.", "prompt": "What's the best answer?", "options": ["They target two different diseases", "Trontinemab is just a cheaper copy", "A delivery fix after a delivery failure"], "correctIndex": 2, "consequences": ["Both target amyloid in Alzheimer's.", "It adds a shuttle to cross the barrier.", "Low amyloid removal led Roche to the Brainshuttle."], "explanation": "Too little drug got in, so Roche built a way to get more in."}, "proReasoning": "Tell the story as cause and response: too little drug got in, so Roche built a way to get more in.", "commonMistake": "Treating the two drugs as unrelated.", "mentalModel": "Failure taught delivery."}, "invest": {"call": {"kind": "theCall", "situation": "You're judging Roche's Alzheimer's pipeline after gantenerumab.", "prompt": "What's the strongest reason for renewed interest?", "options": ["Better delivery and high early clearance", "Gantenerumab succeeded after all", "Phase 3 has already proven benefit"], "correctIndex": 0, "consequences": ["91% fell below the threshold early, with low swelling.", "Its GRADUATE trials failed.", "Phase 3 results are still to come."], "explanation": "Better delivery addresses why gantenerumab fell short."}, "proReasoning": "Investors look for a failure's root cause being fixed. Better delivery addresses why gantenerumab fell short.", "commonMistake": "Writing off a company after one failure without asking why it failed.", "mentalModel": "Fix the root cause."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your antibody failed after removing less of its target than expected.", "prompt": "What does Roche's path suggest?", "options": ["Repeat the same trial unchanged", "Fix delivery, keep the target", "Abandon the target at once"], "correctIndex": 1, "consequences": ["Same drug, same delivery, likely same result.", "Roche kept the target and improved delivery.", "The target may be fine if too little drug reached it."], "explanation": "If too little got in, delivery is the fix, not a new target."}, "proReasoning": "Founders diagnose why a drug failed. If too little got in, delivery is the fix, not a new target.", "commonMistake": "Changing targets when the problem was delivery.", "mentalModel": "Diagnose before you pivot."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Roche tried again after its Alzheimer's drug failed.", "prompt": "What's the answer?", "options": ["It ignored the failure", "The first drug was quietly approved", "Too little got in, so it fixed delivery"], "correctIndex": 2, "consequences": ["It responded with a new approach.", "Gantenerumab trials were discontinued.", "Trontinemab uses a shuttle to carry more drug across."], "explanation": "Roche found the weak link, delivery, and rebuilt it."}, "proReasoning": "Explain persistence through diagnosis: Roche found the weak link and rebuilt it.", "commonMistake": "Assuming a failed drug means a dead end.", "mentalModel": "Find the weak link."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:401f0e3740d9$ml$]::text[]),
($ml$0e168ee9-8a2d-5efb-94c6-2b38369cc377$ml$::uuid, $ml$neuroscience$ml$, 30, 3, $ml${"id": "neuroscience-d30-c3", "title": "Raise the dose, add a shuttle, or quit?", "lessonTitle": "When too little drug reached the brain", "slot": 3, "type": "decide", "brief": {"headline": "You run a biotech whose anti-amyloid antibody just failed in Phase 3, removing less amyloid than expected. Your board wants a decision.", "kicker": "Decide what to do when too little drug reached the brain.", "fullText": "You run a biotech whose antibody targets amyloid. Its Phase 3 trials just missed their goal, and amyloid removal was lower than expected.\n\nDay 30 offers a precedent. In November 2022, Roche's gantenerumab failed GRADUATE I and II in 1,965 people, slowing decline by just 8% and 6%, neither statistically significant, with amyloid removal lower than expected. Roche discontinued most gantenerumab trials and said it was exploring new technologies to deliver more of the drug into the brain. Its Brainshuttle drug, trontinemab, later entered Phase 3. Leqembi, aimed at the same target, had slowed decline by 27%. If too little drug reaches the brain, even the right target can fail.", "sources": [{"url": "https://www.alzheimer-europe.org/news/roche-discontinues-clinical-trials-gantenerumab-after-graduate-studies-fail-meet-their-primary", "label": "Alzheimer Europe, Roche discontinues gantenerumab trials after GRADUATE studies fail, Nov 2022"}, {"url": "https://www.roche.com/media/releases/med-cor-2025-07-28.htm", "label": "Roche, New insights in Alzheimer's disease research at AAIC, Jul 2025"}, {"url": "https://www.biospace.com/fda-grants-traditional-approval-for-leqembi-lecanemab-irmb-for-the-treatment-of-alzheimer-s-disease", "label": "Eisai and Biogen via BioSpace, Leqembi traditional approval"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the diagnosis in order.", "steps": ["The trial misses its main goal", "Check how much amyloid was removed", "Find that removal was lower than expected", "Ask whether enough drug reached the brain", "Choose a delivery fix or a new target"], "explanation": "Low target removal points to delivery before it points to a bad target."}, "numbers": {"kind": "numberSense", "prompt": "Gantenerumab slowed decline by 8% in GRADUATE I; Leqembi by about 27%. How many percentage points apart?", "min": 0, "max": 50, "value": 19, "unit": "points", "explanation": "About 19 points between two drugs aimed at the same target. Delivery and dose can make that gap."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the biotech's head of translational science. The board asks whether to drop the target.", "prompt": "What's your view?", "options": ["Not until we know if enough drug got in", "Yes, the target is clearly wrong", "No; rerun the same trial unchanged"], "correctIndex": 0, "consequences": ["Low removal can mean low delivery, not a bad target.", "Leqembi slowed decline by acting on the same target.", "Same drug and delivery would likely repeat the result."], "explanation": "Separate target failure from delivery failure before deciding."}, "proReasoning": "Translational leads separate target failure from delivery failure. The answer decides whether to fix or pivot.", "commonMistake": "Dropping a validated target before checking delivery.", "mentalModel": "Target or delivery?"}, "invest": {"call": {"kind": "theCall", "situation": "The biotech asks investors to fund a shuttle version of its antibody.", "prompt": "What makes that bet more reasonable?", "options": ["The original trial succeeded", "Roche took this path before", "Shuttles guarantee success"], "correctIndex": 1, "consequences": ["It missed its goal.", "Trontinemab followed gantenerumab and entered Phase 3.", "Shuttle drugs still need Phase 3 proof."], "explanation": "Roche's move from gantenerumab to trontinemab is a precedent, not a promise."}, "proReasoning": "Investors look for precedents that lower the risk of a pivot. Roche's move from gantenerumab to trontinemab is one.", "commonMistake": "Treating a precedent as a guarantee.", "mentalModel": "Precedent, not promise."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Building a shuttle would take years; licensing one is faster.", "prompt": "What's the sound move?", "options": ["Build one alone from scratch", "Skip delivery and rerun the trial", "License a shuttle from an owner"], "correctIndex": 2, "consequences": ["Possible, but slow and costly.", "The same delivery likely gives the same result.", "Owners license platforms, which saves years."], "explanation": "Platform owners exist for companies in exactly this spot."}, "proReasoning": "Founders buy time by licensing delivery. Platform owners exist for companies in exactly this spot.", "commonMistake": "Rebuilding what others already license.", "mentalModel": "License the fix."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a drug aimed at the right target can still fail.", "prompt": "What's the explanation?", "options": ["Too little of it reached the brain", "The target moved to another organ", "Targets do not matter at all"], "correctIndex": 0, "consequences": ["Gantenerumab removed less amyloid than expected.", "Amyloid is in the brain; the drug must get there.", "Targets matter, and so does delivery."], "explanation": "The right target is not enough if the drug does not get there in force."}, "proReasoning": "Explain with gantenerumab: the right target is not enough if the drug does not get there in force.", "commonMistake": "Assuming a good target guarantees a good drug.", "mentalModel": "Target plus delivery."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d6eca27e9ba5$ml$]::text[])
